UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თევზში შემავალი ცხიმები ბავშვის ჯანმრთელობის შენარჩუნებისთვის მეტად სასარგებლოა. თევზის ქონი ცნობილია ანთების საწინააღმდეგო, ანტიოქსიდანტური და სიმსივნის საწინააღმდეგო მოქმედებით. ის ასევე ხელს უწყობს სისხლძარღვების გამკვრივებისა და დახშობის თავიდან აცილებას. სპეციალისტების უმეტესობის აზრით, ბავშვისთვის უფრო სასარგებლოა ამ ცხიმების მიღება უშუალოდ თევზის ჭამით და არა საკვები დანამატის სახით. თუმცა ბევრ ბავშვს ცხიმიანი თევზი არ უყვარს. არსებობს მოსაზრება, რომ ბავშვებს, რომლებიც კვირაში ორჯერ მიირთმევენ თევზს, დამატებით თევზის ქონის მიღება არ სჭირდებათ. ზოგიერთი სპეციალისტი კი აღნიშნავს, რომ ჩვენს რეგიონში გავრცელებული თევზები ძირითადად თბილი ზღვის სახეობებია და მათში Omega-3 ცხიმოვანი მჟავების (DHA და EPA) შემცველობა ძალიან დაბალია. ამიტომ ისინი თევზის ქონის დანამატის მნიშვნელობას უსვამენ ხაზს. შესაბამისად, ექიმთან კონსულტაციის შემდეგ ბავშვისთვის თევზის ქონის ყოველდღიურად მიცემა შეიძლება კარგი გადაწყვეტილება იყოს.') WHERE id = 'fbb69386-c7e5-4fbb-97e9-982d14f4b94e';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი ყოველდღიურად იზრდება და მოკლე დროში განვითარების დიდი გზა გაიარა. ახლა თქვენი ამოცანაა, აგრძნობინოთ, რომ ის უკვე დიდია. იმის საჩვენებლად, რომ თქვენი შვილი ოჯახის სრულფასოვანი წევრია, პირადი ნივთების გარდა შეგიძლიათ მისთვის საკუთარი თეფში და ჩანგალიც შეიძინოთ, რომლებსაც ჭამის დროს გამოიყენებს. განსაკუთრებით მისთვის საყვარელი პერსონაჟებით გაფორმებული ასეთი ნივთები ბავშვის ჭამისკენ წახალისების საყვარელი და სახალისო საშუალება იქნება. ასევე შეგიძლიათ სთხოვოთ, რომ გახდილი ტანსაცმელი ჭუჭყიანი სარეცხის კალათაში ჩააგდოს. ასეთი ჩვევების ჩამოყალიბება ერთი შეხედვით შეიძლება უმნიშვნელოდ მოგეჩვენოთ, თუმცა პასუხისმგებლობის გრძნობა სწორედ ამ ასაკში ვითარდება. ეს მცირე დავალებები მომავალში დაეხმარება მას, უფრო მოწესრიგებულ და პასუხისმგებლიან ზრდასრულად ჩამოყალიბდეს.') WHERE id = '3101c4cb-3b48-4335-a262-39fa7a1322ad';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი უკვე შეიძლება ინტერესდებოდეს იმ საქმეებით, რომლებსაც აკეთებთ. ამ პერიოდში ის შესაძლოა უკან დაგყვებოდეთ და თქვენი მიბაძვა, მაგალითად, სხვადასხვა ზედაპირის გაწმენდით სცადოს. ბევრ მშობელს არ სურს, ბავშვი საქმეში ჩაერთოს და ხელს უშლის მას. თუმცა იმის ნაცვლად, რომ საქმის გართულების შიშით შეაჩეროთ, მიეცით საშუალება, ჩაერთოს და ცოტა თავისუფლად იმოქმედოს. ამასთანავე, შეგიძლიათ ეს მომენტები სასწავლო შესაძლებლობად აქციოთ და ყოველდღიური ურთიერთობისას მას მცირე ცოდნა გაუზიაროთ. მაგალითად, ფერებისა და რიცხვების სწავლა უფრო მარტივია, როცა ის თამაშის სახით მიმდინარეობს. ბავშვისთვის საყვარელი საყოფაცხოვრებო ნივთების ფერების მიხედვით დაჯგუფება ან იატაკის წმენდისას ფილების დათვლა მის განვითარებაში დიდ წვლილს შეიტანს. ამგვარად, შეგიძლიათ ერთდროულად გაერთოთ, შვილთან ხარისხიანად გაატაროთ დრო და ხელი შეუწყოთ მის განათლებას.') WHERE id = '62a7c96c-d9da-4a1b-918e-e957e6e835d1';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, '27-ე თვეში თქვენი ბავშვის კითხვების წვიმა კვლავ ინტენსიურად გაგრძელდება. შესაძლოა, მუდმივად მოგიწიოთ ერთმანეთთან დაკავშირებულ თუ სრულიად განსხვავებულ უამრავ კითხვაზე პასუხის გაცემა და ბავშვი თქვენგან აუცილებლად დაელოდება განმარტებას. ძალიან მნიშვნელოვანია, უპასუხოთ რაც შეიძლება მარტივად და გასაგებად და აგრძნობინოთ, რომ მის მოსაზრებებს მნიშვნელობას ანიჭებთ. ამ პროცესში ბავშვი ზოგჯერ შეიძლება გაბრაზდეს ან უკმაყოფილება გამოხატოს, თუმცა თუ მოთმინებით ეცდებით ახსნას, ეს მის განვითარებაზე აუცილებლად დადებითად იმოქმედებს. კიდევ ერთი მნიშვნელოვანი საკითხია, შეაქოთ ბავშვი იმისთვის, რაც გამოსდის და არ განსაჯოთ იმის გამო, რაც ჯერ არ შეუძლია. ასეთმა მიდგომამ მასში შეიძლება ფსიქოლოგიური დაძაბულობა გამოიწვიოს. მოთმინებით მოეკიდეთ მას, რადგან თითოეული დასმული კითხვითა და ყოველი ცელქობით ბავშვი სამყაროს უფრო ახლოს ეცნობა.') WHERE id = '8617b177-02ab-46b0-bf53-616ceb20767c';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვობაში ჩამოყალიბებულ კვებით ჩვევებს დიდი მნიშვნელობა აქვს, რადგან ბავშვების დაავადებებისგან დაცვა და მათი გონებრივი თუ ფიზიკური უნარების განვითარება უშუალოდ ჯანსაღ კვებას უკავშირდება. სწორი კვება ყველა ასაკში მნიშვნელოვანია, თუმცა განვითარების ეტაპზე მყოფი ბავშვებისთვის მას სასიცოცხლო მნიშვნელობა აქვს. არასაკმარისი და დაუბალანსებელი კვება მრავალი დაავადების გამომწვევი ძირითადი მიზეზია. არაჯანსაღი საკვების არჩევამ შეიძლება განვითარების დარღვევები და ჯანმრთელობის სხვადასხვა პრობლემა გამოიწვიოს. 2 წლის შემდეგ ხშირად იწყება არასწორი კვებითი ჩვევების ჩამოყალიბება, რადგან ამ პერიოდში ბავშვები პირველად ეცნობიან მზა შეფუთულ პროდუქტებსა და საკვები ღირებულების არმქონე ტკბილეულს. ეს კი ჯანსაღი ზრდის ერთ-ერთი უდიდესი დაბრკოლებაა. სპეციალისტები გირჩევენ, ბავშვები ასეთ მავნე პროდუქტებს, სულ მცირე, სასკოლო ასაკამდე მოარიდოთ.') WHERE id = 'b67098ba-523c-4deb-8d75-c6e4c04c833c';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'შეიძლება ითქვას, რომ განვითარების ამ ეტაპზე თქვენი 27 თვის ბავშვი აქტიურად ეძებს საკუთარ იდენტობას. ამ პერიოდში ძალიან მნიშვნელოვანია, მის გვერდით ყურადღება მიაქციოთ თქვენს ქცევასა და სიტყვებს. მიუხედავად იმისა, რომ ბევრი მშობლისთვის ეს არასასურველია, ბავშვებმა ამ ასაკში შეიძლება ყველა გაგონილი სიტყვის გამოყენება დაიწყონ. ამიტომ კარგი იქნება, თუ გააფრთხილებთ ადამიანებს, რომლებიც თქვენი ბავშვის გარემოცვაში უსიამოვნო ან შეუსაბამო სიტყვებს ამბობენ. ასევე ეცადეთ, ბავშვის თანდასწრებით არ იკამათოთ, არ გამოიყენოთ ცუდი სიტყვები და აკონტროლოთ ხმის ტონი. თქვენი ბავშვი თითქმის ყველაფრის მიბაძვას დაიწყებს, რასაც თქვენგან ხედავს. ამიტომ შეეცადეთ, მისთვის კარგი მაგალითი იყოთ. ამ პერიოდში ბავშვს უნდა დაეხმაროთ როგორც მოტორული უნარების განვითარებაში, ისე საკუთარ თავზე ზრუნვის ჩვევების გამომუშავებაში. მაგალითად, ბავშვს უკვე უნდა შეეძლოს თქვენი დახმარების გარეშე კბილების გახეხვა და ხელების დაბანა.') WHERE id = '5abe92b5-f52e-400b-a5f6-cabd63afd859';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ფტორი თქვენი ბავშვის ჯანმრთელობისთვის ერთ-ერთი ძალიან მნიშვნელოვანი მინერალია. მიუხედავად ამისა, საჭიროა მისი რაოდენობის კონტროლი. ფტორი განსაკუთრებით ეფექტურად იცავს კბილებს კარიესისგან და ორგანიზმში შესაძლოა სასმელი წყლიდან მოხვდეს. თუ თქვენს სასმელ წყალში ფტორის რაოდენობა საკმარისია, დამატებით მიღება საჭირო არ არის. თუმცა, თუ ფტორის შემცველობა დაბალია და თქვენს ბავშვს კბილების კარიესის განვითარების რისკი აქვს, ექიმის თანხმობით შეგიძლიათ ფტორის დანამატი მისცეთ. ჩვენი ქვეყნის ზოგიერთ რეგიონში წყალი ფტორით ძალიან მდიდარია.  ფტორის სიჭარბემ შესაძლოა გამოიწვიოს კბილებზე ლაქების გაჩენა, ანუ ფლუოროზი. ფტორი კბილის პასტების შემადგენლობაშიც შედის. თუმცა, რადგან ამ პროდუქტებს ხელოვნურად დამატებული ფტორი აქვს, მათი გამოყენებისას განსაკუთრებული სიფრთხილეა საჭირო. ამიტომ, როდესაც თქვენი ბავშვი კბილის პასტის გამოყენებას პირველად იწყებს, მას ფტორის დამატებითი მიღება არ სჭირდება.') WHERE id = '6748d69e-868b-4bd5-8a5b-784f97c40a36';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ პერიოდში თქვენს ბავშვს შეუძლია გააზრებულად თქვას 50-ზე მეტი სიტყვა. ამ სიტყვების გამოყენებით მას წინადადებების შედგენაც შეუძლია, თუმცა ჯერ ძალიან რთულ და გამართულ წინადადებებს ნუ დაელოდებით. მას შეუძლია საკუთარი სურვილების გამოხატვა ისეთი წინადადებებით, როგორებიცაა: „ბურთი ისროლე“, „დედა, მოდი“, „მამა, შეხედე“, „თოჯინა მომეცი“, „სამზარეულოში წავიდეთ“. ამასთანავე, ამ ასაკში ზოგიერთი ბავშვი საკუთარ თავზე მესამე პირში საუბრობს. რადგან სხვები მას სახელით მიმართავენ, საკუთარ თავზე საუბრისას შესაძლოა „მე“-ს ნაცვლად თავისი სახელი თქვას. თუ ბავშვს ადრე გააცანით ისეთი ცხოველები, როგორებიცაა კატა, ძაღლი და ფრინველი, მათი ხმის გაგონებისას მას შეუძლია მიხვდეს, რომელ ცხოველს ეკუთვნის ეს ხმა. ნუ მოელით, რომ თქვენი ბავშვი ამ ხმებს ყოველთვის სწორად დააკავშირებს ცხოველებთან და განაგრძეთ მისი განვითარების ხელშეწყობა. ამ მიზნით ძალიან სასარგებლოა ცხოველების ხმებთან დაკავშირებული პროგრამები ან თამაშები ბარათებით, რომლებზეც ცხოველებია გამოსახული.') WHERE id = '0b2efb81-ea8f-4a69-a8e4-bfa0406f23c0';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ვიცით, რომ ბავშვის კვების საკითხი თქვენთვის დიდ გამოწვევად იქცა. ნუ ინერვიულებთ, რადგან უამრავი დედა ზუსტად იმავეს გრძნობს! :) ამ პროცესში გახსოვდეთ, რომ თქვენს ბავშვს აქვს საყვარელი და არასასურველი საკვები და ჭამა არ უნდა აიძულოთ. რეალისტური მოლოდინები და ის, რომ არც საკუთარ თავსა და არც ბავშვს არ შეუქმნით ზედმეტ სირთულეებს, მნიშვნელოვნად შეგიმსუბუქებთ მდგომარეობას. როცა მშობლები თავს უძლურად გრძნობენ, ყველაზე ხშირად ტელეფონსა და ტელევიზორს მიმართავენ. თუმცა, ამ მოწყობილობებით ბავშვის ყურადღების გაფანტვა და ამ დროს მისთვის საკვების მიცემა უარყოფითად მოქმედებს სწავლისა და აღქმის უნარების განვითარებაზე. უმჯობესია, ამ ასაკიდანვე შეაჩვიოთ ბავშვი სუფრასთან და სასადილო მაგიდასთან ჭამას. ამ ასაკში გამომუშავებული ჩვევა მომავალში მას უფრო სწრაფად ადაპტირებასა და კვების რეგულარული რეჟიმის ჩამოყალიბებაში დაეხმარება.') WHERE id = '28fd7c5d-9fca-4359-bc66-b636a21a6247';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'კვლევების თანახმად, გოგონები ტუალეტის ჩვევის გამომუშავებით ინტერესს, როგორც წესი, 23 თვის ასაკში იჩენენ, ხოლო ბიჭები — დაახლოებით 25 თვის ასაკში. ინტერესთან ერთად მნიშვნელოვანია, რომ ბავშვი ფიზიოლოგიურადაც მზად იყოს. გოგონებს ტუალეტის ჩვევა, ჩვეულებრივ, 33 თვის ასაკისთვის აქვთ სრულად ათვისებული, ბიჭებს კი — 37 თვისთვის. მოსალოდნელია, რომ ბავშვები ამ ასაკამდე ამ ჩვევას გამოიმუშავებენ, თუმცა უნდა გახსოვდეთ, რომ თითოეული ბავშვის განვითარების ტემპი განსხვავებულია. 27 თვის ასაკში თქვენს ბავშვს შესაძლოა ტუალეტის ჩვევა უკვე სრულად ჰქონდეს გამომუშავებული ან ჯერ კიდევ სწავლების ეტაპზე იყოს. მაშინაც კი, თუ პროცესი სრულად დაასრულეთ, გარკვეული პერიოდის განმავლობაში შეიძლება კვლავ მოხდეს მცირე „შემთხვევები“. ეს სრულიად ნორმალურია და ასეთ დროს საუკეთესო მიდგომაა, მკაცრად არ გამოეხმაუროთ და მდგომარეობას გაგებით მოეკიდოთ.') WHERE id = 'a2e641a4-c0c5-4079-b4c0-664fe147cd24';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბოჭკოვანი სტრუქტურის წყალობით მარცვლეული თქვენი ბავშვის საჭმლის მონელებას უწყობს ხელს და ხელს უშლის ისეთი ჩივილების განვითარებას, როგორიცაა მუცლის ტკივილი. მარცვლეული ასევე B ჯგუფის ვიტამინებით მდიდარი საკვებია. B ჯგუფის ვიტამინები მნიშვნელოვან როლს ასრულებს ნერვული სისტემის განვითარებაში და ორგანიზმში ენერგიის გამომუშავებაზეც მოქმედებს. გარდა ამისა, მარცვლეულის პროდუქტები მდიდარია ძვლებისა და კუნთებისთვის სასარგებლო მინერალებით, როგორებიცაა რკინა, სელენი და მაგნიუმი. თუ გსურთ, რომ თქვენმა ბავშვმა მარცვლეულისგან მაქსიმალური სარგებელი მიიღოს, მაგალითად, მაკარონის ნახარში წყალი არ უნდა გადაწუროთ, რადგან მასში შემავალი საკვები ნივთიერებები მომზადების დროს წყალში გადადის. ამიტომ ბავშვისთვის მაკარონის მომზადებისას უმჯობესია, ის მცირე რაოდენობის წყალში მოხარშოთ ისე, რომ წყალი მთლიანად შეიწოვოს. ბრინჯის მომზადებამდე წყალში დიდხანს დატოვება ან ზეთში ხანგრძლივად მოშუშვა კი მის კვებით ღირებულებას ამცირებს. თუ ფუნთუშების მსგავს ცომეულს ამზადებთ და მას თქვენი ბავშვიც შეჭამს, უპირატესობა მიანიჭეთ საფუარს და არა გამაფხვიერებელს.') WHERE id = 'e7b4691f-ceeb-4bdc-b7b7-f707d0e7fa17';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი შვილი უკვე დამოუკიდებლობის მწვერვალზეა. ამის გამო მან შესაძლოა ზოგიერთ ბოსტნეულზე უარი თქვას. ზოგიერთი მშობელი ამბობს, რომ ბავშვები ყველაფერს, რაც მწვანეა, ბოსტნეულად აღიქვამენ და ფიქრობენ, რომ ცუდი გემო ექნება. თუ თქვენც ასეთ სიტუაციაში აღმოჩნდით, ეცადეთ, გარკვეული ხნით ამ აზრს გადაატანინოთ ყურადღება. ამისთვის შეგიძლიათ უფრო ფერადი ბოსტნეული გამოიყენოთ! მაგალითად, წითელი და ყვითელი ბულგარული წიწაკით, სტაფილოთი, პომიდვრით, ჭარხლითა და გოგრით მომზადებული კერძები თქვენს შვილში მეტ ინტერესს გამოიწვევს. ეს ბოსტნეული ასევე მდიდარია A და C ვიტამინებით. შეგიძლიათ ბავშვის საყვარელი საკვებიც შეუთავსოთ იმას, რაც არ უყვარს. მაგალითად, თუ თქვენს შვილს ხორცის ბურთულები უყვარს, გვერდით ყვავილოვანი კომბოსტოს ან ბროკოლის რამდენიმე ნაჭერი დაუდეთ. ქათმის ნაჭრები მწვანე ბარდას შეურიეთ და კერძის გაფორმების ნაწილად გამოიყენეთ.') WHERE id = 'e19f528f-be1a-4590-a1ad-08cb799868f7';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ თვეებში, როდესაც თქვენი შვილი ყველაზე აქტიურია, შესაძლოა ფიქრობდეთ, რომელი აქტივობები იქნება მასთან ერთად გასაკეთებლად უფრო სასარგებლო. სინამდვილეში, როგორც სახლში, ისე გარეთ, უამრავი არჩევანი გაქვთ. კუნთების განვითარებისა და ფიზიკური აქტივობის ჩვევის ჩამოსაყალიბებლად საბავშვო სპორტული ცენტრები კარგი იდეაა. სასარგებლოა სათამაშო ჯგუფები და სახელოსნოებიც, რომლებიც ავითარებს როგორც ემოციურ, ისე მოტორულ უნარებს. საოჯახო საქმეების ერთად კეთება კი იდეალურია როგორც დროის ერთად გასატარებლად, ისე ბავშვისთვის წესრიგისა და დისციპლინის სასწავლებლად. მაგალითად, როცა თქვენ იატაკს წმენდთ, თქვენი შვილი შეიძლება თავისი სათამაშო დასუფთავების ნაკრებით შემოგიერთდეთ. სარეცხ მანქანაში ჭუჭყიანი ტანსაცმლის ჩაყრისას შეგიძლიათ დახმარება სთხოვოთ. მოკლედ, შეგიძლიათ თქვენი შვილი ყოველდღიურ ცხოვრებაში შესრულებულ ნებისმიერ საქმეში ჩართოთ.') WHERE id = 'c3a4f4bb-ac8b-4cd2-b729-634f2ef8e015';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'დიარეა ბავშვებში ერთ-ერთი ყველაზე გავრცელებული ჩივილია. თუ თქვენს შვილს დროდადრო დიარეა აქვს, კვებასთან დაკავშირებით გარკვეული ინფორმაცია დაგჭირდებათ. უნდა იცოდეთ, რომ ყაბზობისგან განსხვავებით, დიარეის დროს ბავშვს დაბალბოჭკოვანი საკვები უნდა მისცეთ. დიარეის დროს ერთ-ერთი ყველაზე სასარგებლო საკვები იოგურტია, რადგან ის ძლიერი პრობიოტიკია. დიარეის დროს ორგანიზმის მიერ დაკარგული ერთ-ერთი უმნიშვნელოვანესი მინერალი თუთიაა. თუთიით მდიდარი ხორბლის ჩანასახი ამ პერიოდში ერთ-ერთი საუკეთესო საკვებია. საკვებში მცირე რაოდენობით დამატებული სუმახიც დადებითად მოქმედებს დიარეაზე. თუ სისუსტის გამო თქვენს შვილს ჭამა არ სურს, შეგიძლიათ ბანანი და ატამი მისცეთ. მიუხედავად იმისა, რომ ატამს ზრდასრულებში ნაწლავების მოქმედების გამაძლიერებელი ეფექტი აქვს, ბავშვებში მას დიარეის შემცირების თვისება ახასიათებს.') WHERE id = 'a3da791d-47b3-44f0-b6db-2186758922d6';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ თვეებში თქვენს ბავშვს შესაძლოა ჰყავდეს წარმოსახვითი მეგობარი, რომელთან ერთადაც თამაშობს და ჭამს. ბევრი მშობელი შვილში ასეთი ქცევის შემჩნევისას ღელავს და ჩარევას ცდილობს. სინამდვილეში, სანერვიულო არაფერია. სკოლამდელ ასაკში წარმოსახვა და რეალობა ჯერ კიდევ მკვეთრად არ არის ერთმანეთისგან გამიჯნული. ამ ასაკში ბავშვებმა შესაძლოა უსულო საგნები ცოცხალ არსებებად აღიქვან. ზოგჯერ თქვენს ბავშვს შეიძლება მისი საყვარელი სათამაშო დათუნია ან თოჯინაც უწევდეს მეგობრობას. ზოგ შემთხვევაში კი, მიუხედავად იმისა, რომ მის გვერდით არანაირი საგანი არ არის, შეიძლება შეამჩნიოთ, რომ თქვენი ბავშვი ვიღაცას ესაუბრება... ყველა ასეთი მეგობრობა თქვენი ბავშვის განვითარების ნორმალურ პროცესად მიიჩნევა. თუმცა, თუ ეს მდგომარეობა ძალიან დიდხანს გაგრძელდება და სერიოზულად შეგაწუხებთ, შეგიძლიათ ექიმს მიმართოთ.') WHERE id = '43ebcc3b-a67c-42aa-91cf-6698742da655';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ნაყინი ერთ-ერთი იმ საკვებია, რომელსაც თქვენი ბავშვი ზაფხულშიც და ზამთარშიც ყოველთვის მოისურვებს. ნაყინის პირდაპირ სწრაფი კვების ან უსარგებლო საკვების კატეგორიაში მოქცევა ცოტა უსამართლო იქნება. ნაყინი შეიცავს B12, B6, D, C და E ვიტამინებს. ის ასევე მდიდარია ცხიმებით, ცილებითა და ნახშირწყლებით. ნაყინი შეიძლება ენერგიის შესანიშნავ წყაროდ ჩაითვალოს და ზომიერი რაოდენობით მიღებისას ჭარბ წონას არ იწვევს. თუმცა, ზოგიერთი ნაყინი შესაძლოა ხელოვნურ დამატკბობლებს შეიცავდეს. ამიტომ, თუ დრო გაქვთ, შეგიძლიათ თქვენს შვილს სახლში ჯანსაღი ნაყინი მოუმზადოთ. საჭირო ინგრედიენტებია: 100 გრამი შოკოლადი, 100 ml რძე და 1 შეფუთვა ნაღები. მომზადება ძალიან მარტივია: შოკოლადი ორთქლის აბაზანაზე გაადნეთ, რძე დაუმატეთ და კარგად აურიეთ. ცალკე ჭურჭელში ნაღები მიქსერით ქაფის წარმოქმნამდე ათქვიფეთ. შემდეგ ყველა ინგრედიენტი ერთმანეთში აურიეთ და საყინულეში 2 საათით მოათავსეთ. თქვენი ნაყინი მზადაა! :)') WHERE id = 'd4f84a64-6da8-4928-8a62-9c2d85080c7a';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენმა ბავშვმა შესაძლოა უკვე დაიწყოს თითების გამოყენება თავისი ასაკის საჩვენებლად. მეტყველების განვითარებაც სწრაფად გრძელდება. მაგალითად, მას შეუძლია სხეულის ნაწილების დასახელება, 1-2 ფერის ცნობა და კითხვაზე თავისი სქესის მარტივად თქმა. თქვენი პატარა, რომელიც აქამდე სიტყვებს მხოლოდ მხოლობით რიცხვში იყენებდა, შესაძლოა უკვე მრავლობითი რიცხვის ფორმებსაც იყენებდეს. ანუ რამდენიმე წიგნის დანახვისას უკვე მხოლოდ „წიგნს“ კი არა, „წიგნებს“ იტყვის. ამასთანავე, ის იწყებს წარსული დროის ფორმების სწორად გამოყენებასაც (მაგალითად, წავიდა, მოვიდა). კითხვებს „ეს რა არის?“ და „ის რა არის?“ კვლავაც ხშირად დაგისვამთ. ძალიან მნიშვნელოვანია, მის შეკითხვებს ყოველ ჯერზე მოთმინებით და მისთვის გასაგებ ენაზე უპასუხოთ. კითხვებისთვის თავის არიდება არასწორია, რადგან თქვენი ბავშვი სწორედ კითხვების დასმით შეიცნობს სამყაროსა და ცხოვრებას.') WHERE id = '623efdbe-b7f0-42be-97e8-fdfbef54b271';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ალბათ უკვე რამდენიმე თვეა ამჩნევთ, რომ თქვენმა ბავშვმა საკუთარი დამოუკიდებლობის გამოვლენა დაიწყო. თქვენი მოთხოვნების გაპროტესტებასა და კითხვების — „რატომ?“, „რისთვის?“ — დასმას რომ აგრძელებს, პატარამ ზოგჯერ შეიძლება ისეთ საკითხებზეც გკითხოთ, რომლებიც უხერხულ მდგომარეობაში ჩაგაყენებთ. მაგალითად, ამ ასაკის ბავშვებს ხშირად აინტერესებთ, როგორ გაჩნდნენ. მოკლედ, ბავშვი შეიძლება მოვიდეს თქვენთან და გკითხოთ: „როგორ გავჩნდი, როგორ მოვევლინე ქვეყანას?“ ბევრი მშობელი ფიქრობს, რომ ეს კითხვა უშუალოდ სექსუალობას უკავშირდება, ამიტომ პასუხის გაცემას თავს არიდებს და საუბარი სხვა თემაზე გადააქვს. თუმცა ასეთი მიდგომა ბავშვის ცნობისმოყვარეობას უფრო მეტად აღვივებს და კითხვებიც არ წყდება. ასეთ შემთხვევებში საჭირო არ არის, ბავშვს ყველა დეტალი აუხსნათ. ამის ნაცვლად, უმჯობესია მისთვის გასაგებ ენაზე უპასუხოთ: „შენ ჩემს მუცელში იზრდებოდი“.') WHERE id = '63361e0d-5fd3-4108-803f-7f7fd698945d';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'D ვიტამინი თქვენი ბავშვის ჯანმრთელობისთვის ერთ-ერთი უმნიშვნელოვანესი კომპონენტია. D ვიტამინის ნაკლებობისას, რომელიც განსაკუთრებით დიდ გავლენას ახდენს ძვლების განვითარებასა და კბილების ჯანმრთელობაზე, ბავშვებში შეიძლება განვითარდეს რაქიტი — დაავადება, რომელიც ძვლების დეფორმაციას იწვევს. ისეთი პრობლემების მიზეზი, როგორებიცაა ბავშვის სისუსტე, მოუსვენრობა, ხშირი ავადმყოფობა და უმადობა, შესაძლოა სწორედ D ვიტამინის დეფიციტი იყოს. ამიტომ სასარგებლოა, რომ ბავშვმა D ვიტამინი რეგულარულად მიიღოს. სხვა ვიტამინებისგან განსხვავებით, D ვიტამინს ორგანიზმი არა მხოლოდ საკვებიდან, არამედ მზის სხივების მეშვეობითაც იღებს. D ვიტამინის ბუნებრივად შემცველი პროდუქტები ცოტაა და მათ შორის პირველ ადგილზე თევზია. განსაკუთრებით მდიდარია D ვიტამინით ისეთი ცხიმიანი თევზი, როგორიცაა სარდინი, ორაგული (სალმონი) და სკუმბრია. მცირე რაოდენობით ის კვერცხში, სოკოში, რძესა და ყველშიც გვხვდება. გახსოვდეთ, რომ D ვიტამინის სინთეზისთვის მხოლოდ მზეზე ყოფნა ან მხოლოდ შესაბამისი საკვების მიღება შეიძლება საკმარისი არ იყოს — ორივეს კომბინაცია უფრო ეფექტურია.') WHERE id = '54b7999d-3552-4ccb-ad57-5e50a6a6a619';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ ფიქრობთ, რომ თქვენი ბავშვი სიმაღლეში საკმარისად სწრაფად არ იზრდება ან ზრდის ცხრილის (პერცენტილის) მიხედვით ჩამორჩება, თქვენი შეშფოთება სრულიად ბუნებრივია. სპეციალისტები აღნიშნავენ, რომ ბავშვების ზრდის უმნიშვნელოვანესი მაჩვენებლებია სიმაღლისა და წონის მატება. სიმაღლეში ზრდა ხდება ძვლების ბოლოებში არსებული ხრტილოვანი ქსოვილის, ე.წ. ზრდის ზონების, განვითარების ხარჯზე. მოზარდობის პერიოდის ბოლოს ეს ზონები იხურება და სიმაღლეში ზრდა წყდება. ზრდაზე ორი ძირითადი ფაქტორი მოქმედებს. პირველი გენეტიკური ფაქტორებია — თითოეული ბავშვის სიმაღლეზე გავლენას ახდენს მშობლებისგან გადაცემული გენები. მეორე ფაქტორი კი კვებაა. გენეტიკურად განსაზღვრული სიმაღლის პოტენციალის მაქსიმალურად გამოსაყენებლად ძალიან მნიშვნელოვანია, რომ ბავშვმა ასაკის შესაბამისი რაოდენობის კალორიები მიიღოს და დაბალანსებულად იკვებოს. განსაკუთრებით განვითარების სწრაფი ტემპით გამორჩეულ პირველ ორ წელიწადში კვების დარღვევა, ქრონიკული ღებინება, ქრონიკული დიარეა ან არასწორი კვება ზრდის შეფერხების გამომწვევ ძირითად ფაქტორებს შორისაა.') WHERE id = 'e4cccfa5-92e6-4cfb-b6af-32b8c84e3a41';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ გარეთ გასვლისას ბავშვს საფენს უკეთებთ, სახლში დაბრუნების შემდეგ კი მხოლოდ საცვლებით ტოვებთ, ეს მას დააბნევს. ამიტომ როგორც სახლში, ისე გარეთ და საბავშვო ბაღშიც, თუ ბავშვი იქ დადის, ერთი და იგივე წესი უნდა დაიცვათ და დაეხმაროთ, გაიგოს, რას ელით მისგან. ტუალეტის ჩვევის გამომუშავების პერიოდში დროდადრო უსიამოვნო შემთხვევები სრულიად ბუნებრივია. ასეთ დროს თქვენი ან ბავშვის მომვლელის რეაქცია ძალიან მნიშვნელოვანია. აუცილებლად მოერიდეთ მკაცრ და განმსჯელ ფრაზებს. ნუ ეტყვით ბავშვს ისეთ სიტყვებს, რომლებმაც შეიძლება შეაშინოს ან ააღელვოს, მაგალითად: „ხომ გითხარი“, „უკვე დიდი ხარ, მაგრამ პატარასავით შარვალში ისველებ“. ამის ნაცვლად, უპირატესობა მიანიჭეთ გამამხნევებელ ფრაზებს: „არაუშავს, ასეთი რამ შეიძლება მოხდეს“ ან „დღეს ასე გამოვიდა, მაგრამ ხვალ უფრო ყურადღებით ვიქნებით, ხომ?“ ტუალეტის ჩვევის გამომუშავებისას ბავშვის წახალისება ძალიან მნიშვნელოვანია. შეცდომის დაშვება ბუნებრივია და შეცდომა ყველას მოსდის. გახსოვდეთ, რომ სწავლის პროცესი შეცდომების გარეშე შეუძლებელია.') WHERE id = '74cbe601-3405-4913-b913-ad225051c0de';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვის კვება ძალიან მნიშვნელოვანია როგორც მისი ჯანსაღი განვითარებისთვის, ისე დღის განმავლობაში საჭირო ენერგიის მისაღებად. ამ პერიოდში ბევრი მშობელი ჩივის, რომ ბავშვები ჯიუტობენ და სასარგებლო საკვებს არ ჭამენ. კვერცხი ამის მხოლოდ ერთი მაგალითია. ზოგჯერ საკვების განსხვავებულად მირთმევა ან ახალი სანელებლის დამატება საკმარისია, რომ ბავშვმა კვერცხი მიირთვას. ამისთვის შესანიშნავი რეცეპტი გვაქვს! :) ჩვენი რეცეპტის სახელია: კარტოფილი კვერცხით. საჭირო ინგრედიენტები: 1 ცალი კარტოფილი, გემოვნებით თეთრი ყველი, 1 ცალი კვერცხი, 2-3 ჩაის კოვზი მთლიანი მარცვლის ხორბლის ფქვილი, ცოტა ოხრახუში, ერთი მწიკვი მარილი, პიტნა, ბეგქონდარა და შესაწვავად 2 სუფრის კოვზი ზეითუნის ზეთი. მომზადება ძალიან მარტივია: კარტოფილი გახეხეთ და დაუმატეთ კვერცხი, ფქვილი, ოხრახუში, ყველი და სანელებლები. კარგად აურიეთ, შემდეგ მიღებული მასა კოვზით ნაწილ-ნაწილ გადაიტანეთ ტაფაზე და ზეითუნის ზეთში ორივე მხრიდან შეწვით. გემრიელად მიირთვით! 😊') WHERE id = 'a528e9be-0130-4c5b-8b4a-8c91b4559506';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'გენეტიკური ფაქტორებისა და კვების შემდეგ თქვენი ბავშვის ზრდაზე მოქმედი უმნიშვნელოვანესი ფაქტორი ჰორმონებია. ადამიანის ორგანიზმში არსებული ჯირკვლები გამოყოფენ ჰორმონებს, რომლებიც ზრდას, განვითარებასა და სხვა სასიცოცხლო ფუნქციებს არეგულირებენ. მათ შორის უმთავრესია ტვინში მდებარე ჰიპოფიზის მიერ გამოყოფილი ზრდის ჰორმონი (Growth hormone). ზრდის ჰორმონი და ორგანიზმში წარმოქმნილი ზოგიერთი ფაქტორი ძვლების ბოლოებში ხრტილოვანი უჯრედების დაყოფას უწყობს ხელს და ამგვარად სიმაღლეში ზრდას უზრუნველყოფს. ფარისებრი ჯირკვლის ჰორმონებიც არეგულირებენ ნივთიერებათა ცვლას და ზრდას უწყობენ ხელს. გოგონებში ესტროგენი, ხოლო ბიჭებში ტესტოსტერონი მნიშვნელოვან როლს ასრულებს სიმაღლეში ზრდასა და განვითარებაში. ამ ჰორმონების დეფიციტმა შეიძლება ზრდის შეფერხება ან დაბალი სიმაღლე გამოიწვიოს. თუ ამასთან დაკავშირებით ეჭვი გაქვთ, აუცილებლად გაიარეთ კონსულტაცია ექიმთან.') WHERE id = '9f60c03d-388c-4852-aae7-a31ffa00fa8f';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ტუალეტის ჩვევის სრულად ათვისება თქვენი ბავშვისთვის საკმაოდ დიდი ნაბიჯი და რთული ამოცანაა. თუ ჯერ კიდევ ამ პროცესში ხართ, რამდენიმე საკითხს უნდა მიაქციოთ ყურადღება. მაგალითად, საბავშვო ბაღში სიარულის დაწყების, ძუძუსგან მოშორების ან საცხოვრებლად გადასვლის მსგავსი მნიშვნელოვანი ცვლილებების წინ ტუალეტის სწავლის დაწყება მიზანშეწონილი არ არის. ამისთვის აუცილებელია, რომ ბავშვიც მზად იყოს და პერიოდიც შესაფერისი იყოს. ამასთანავე, ამისთვის თქვენც ისევე მზად უნდა იყოთ, როგორც თქვენი ბავშვი. ზოგიერთ ბავშვს ამ ჩვევის ათვისება შეიძლება უფრო გაუჭირდეს. ამ პერიოდში მნიშვნელოვანია, იყოთ თანმიმდევრული და მომთმენი. თუ ბავშვს არ დაადანაშაულებთ, პროცესს ბუნებრივად მიუდგებით და უხვად გამოხატავთ მის მიმართ სიყვარულს, ყველაფერი გაცილებით გაგიადვილდებათ.') WHERE id = '2add9cbb-bed9-4a33-8609-e9090d87a0b2';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენს ბავშვთან ერთად კიდევ ერთი თვე გაატარეთ. კეთილი იყოს თქვენი მობრძანება 28-ე თვეში! :) თქვენი პატარას პიროვნება უკვე აქტიურად იწყებს ჩამოყალიბებას. თუმცა გახსოვდეთ, რომ მას შეიძლება თქვენგან განსხვავებული ხასიათი ჰქონდეს. როდესაც ის თავის ბუნებრივ თვისებებს ავლენს, გაკიცხვის ნაცვლად, საჭიროა, მიიღოთ ისეთი, როგორიც არის. მოკლედ, ნუ აიძულებთ, აუცილებლად ისეთ ადამიანად ჩამოყალიბდეს, როგორიც თქვენ გსურთ. თუ მხარს დაუჭერთ, რომ სამყარო მისთვის დამახასიათებელი გზით აღიქვას, ეს დაეხმარება, ჯანსაღ პიროვნებად გაიზარდოს. ამ პერიოდში ბავშვმა შეიძლება საკუთარი სხეულის, განსაკუთრებით კი სასქესო ორგანოების გაცნობა და მათ მიმართ ინტერესის გამოხატვა დაიწყოს. ამის გამო მასზე გაბრაზება ნამდვილად არ ღირს. საჭიროების შემთხვევაში შეგიძლიათ სპეციალისტთან გაიაროთ კონსულტაცია და გაიგოთ, როგორ მიუდგეთ ბავშვს ამ საკითხთან დაკავშირებით.') WHERE id = '6e1b9324-94a1-40b9-be8a-0189cd97ec29';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ თვეებში თქვენს ბავშვს ჯერ კიდევ ძლიერად აქვს გამოხატული ეგოცენტრული (საკუთარ თავზე ორიენტირებული) მიდრეკილებები. ამიტომ ზოგჯერ ის შეიძლება ეგოისტურად მოიქცეს. თუმცა გახსოვდეთ, რომ ეს დროებითი ეტაპია და დროთა განმავლობაში გაივლის. ასეთი ქცევის მიზეზებია ბავშვის ლოგიკური აზროვნების ჯერ კიდევ არასაკმარისი განვითარება, სხვა ადამიანის ცნების სრულად გაუცნობიერებლობა, გაზიარების უნარის ჩამოუყალიბებლობა და აბსტრაქტული მნიშვნელობების აღქმის სირთულე. ამასთანავე, მას ჯერ სრულად არ აქვს განვითარებული მოვლენების კლასიფიცირების, თანმიმდევრობით დალაგებისა და დაჯგუფების უნარი. ყოველივე ამის გამო თქვენი ბავშვი ხშირად არ ითვალისწინებს სხვა ადამიანების, მათ შორის თქვენს მოსაზრებებსა და აზრებს. ეს იმიტომ ხდება, რომ მას ჯერ არ მიუღწევია შემეცნებითი განვითარების შესაბამისი დონისთვის. ამიტომ შეშფოთების საფუძველი არ გაქვთ. თუმცა, თუ ეს მდგომარეობა ძალიან გაღელვებთ, შესაძლოა სასარგებლო იყოს სპეციალისტთან კონსულტაცია.') WHERE id = 'e03558fa-2b62-46f8-8b8d-62974309090d';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'მართალია, რძე ცილის შესანიშნავი წყაროა, მაგრამ ზოგიერთმა ბავშვმა შეიძლება მის მიღებაზე უარი თქვას. თუ თქვენს ბავშვსაც არ უყვარს რძე, იცოდეთ, რომ მარტო არ ხართ. :) თუმცა, იმისთვის, რომ ბავშვს ეს მნიშვნელოვანი საკვები არ მოაკლოთ, შეგიძლიათ პატარა ხრიკებს მიმართოთ და რძე სხვა კერძებში შეურიოთ. მაგალითად, თუ თქვენს ბავშვს კვერცხში ამოვლებული პური უყვარს, ნოყიერი საუზმისთვის კვერცხი და რძე ერთად ათქვიფეთ. ამ ნარევში ჩააწეთ სრულმარცვლოვანი პური და ცოტაოდენ კარაქში შეწვით. თუ თქვენს ბავშვს სასმელები უყვარს, შეგიძლიათ გემრიელი სმუზი (smoothie) მოუმზადოთ. ამისთვის რძე და ბანანი ბლენდერში დააბლენდერეთ და სურვილისამებრ სახლში არსებული სხვა ხილიც დაუმატეთ. შინ მომზადებული პუდინგიც ისეთი გემრიელი დესერტია, რომელზეც უარის თქმა თითქმის არცერთ ბავშვს არ შეუძლია! ამასთანავე, ეს რძის შესაყვარებლად ერთ-ერთი საუკეთესო გზაა. :) უშაქრო კაკაოს ფხვნილისა და რძის მომზადებითა და სხვადასხვა ინგრედიენტით გემოს დამატებით შეგიძლიათ განსხვავებული გემოები შექმნათ.') WHERE id = 'd764e4e1-1fd6-421c-bf7e-324e9264d8bd';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ თვეში თქვენი ბავშვი ცდისა და შეცდომის გზით ინტენსიურად სწავლას იწყებს. ის უკვე უფრო გააზრებულად და მიზანმიმართულად სვამს კითხვებს: რატომ? და რისთვის? მაგალითად, შეიძლება პატარა ნივთების შეფუთვის გახსნა სცადოს და გკითხოთ, რისთვის გამოიყენება ის. ამ პერიოდში თქვენი ბავშვი ახალ უნარებსაც იძენს: უფრო მაღალი კოშკების აშენება მხოლოდ ერთ-ერთი მათგანია. თქვენი მიბაძვით მას შეუძლია ქაღალდი მარტივად გადაკეცოს შუაზე, ელვა-შესაკრავი შეკრას ან ტანსაცმლის დამოუკიდებლად ჩაცმა სცადოს. ამ თვეებში, როდესაც სწრაფი განვითარება გრძელდება, შეგიძლიათ ბავშვთან ერთად სახლში ან გარეთ სხვადასხვა აქტივობით დაკავდეთ და სასიამოვნოდ გაატაროთ დრო. მაგალითად, ცალ ფეხზე დგომის თამაში ერთდროულად სახალისოც იქნება და მის ფიზიკურ განვითარებასაც შეუწყობს ხელს! :)') WHERE id = '1c1e64d8-d06f-466f-9b34-33f9ed75a828';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თევზი ბავშვის კვებაში ცილის, შესაძლოა, ყველაზე მნიშვნელოვანი წყაროა. რადგან ახალი თევზის პოვნა, მომზადება და ფხებისგან გასუფთავება რთულია, ბევრი მშობელი კონსერვს ანიჭებს უპირატესობას. თუმცა დაკონსერვებულ თევზთან დაკავშირებით სიფრთხილე უნდა გამოიჩინოთ. დაკონსერვებული ტუნა სხვადასხვა სახეობის თევზისგან მზადდება და ზოგიერთი მათგანი შეიძლება შეიცავდეს ვერცხლისწყალს, რომელსაც მცირე დოზითაც კი ტოქსიკური ზემოქმედება აქვს. თეთრი ტუნა light ტუნასთან შედარებით უფრო მეტ ვერცხლისწყალს შეიცავს. მიუხედავად იმისა, რომ ზრდასრულებისთვის თეთრი ტუნის მიღება კვირაში მაქსიმუმ 170 გრამით იზღუდება, ეს რაოდენობა ბავშვისთვის შეიძლება სახიფათო იყოს. ამ ასაკში ბავშვისთვის თვეში სულ 85 გრამი თევზიც საკმარისია. ამიტომ, მიუხედავად იმისა, რომ ეს მეტ ძალისხმევას მოითხოვს, კონსერვის ნაცვლად ახალი ზღვის პროდუქტების არჩევა ბავშვის ჯანმრთელობისთვის გაცილებით სასარგებლოა.') WHERE id = '42d066ad-b938-4b87-8fff-39d96cc2a17e';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვის კვების უნარები უკვე უკეთ არის განვითარებული. მას შეუძლია აქტიურად დაიჭიროს კოვზი, ერთი ხელით დალიოს წყალი ჭიქიდან და მიირთვას მრავალი ისეთი საკვები, რომლის ხელით ჭამაც შეიძლება. მიუხედავად იმისა, რომ ბავშვმა რეგულარულად ჭამა დაიწყო, ის ჯერ კიდევ სწავლობს ღეჭვასა და ყლაპვას; ზოგჯერ თამაშზე ეჩქარება და საკვებს სრულად დაუღეჭავად ყლაპავს. ამიტომ გადაცდენისა და სასუნთქი გზების დახშობის რისკი კვლავ არსებობს. უნდა მოერიდოთ ისეთ საკვებს, რომელმაც შესაძლოა სასუნთქი გზები დახშოს. მაგალითად, ამის მიზეზი შეიძლება გახდეს ერთი კოვზი არაქისის კარაქი, თხილეული, ლოქუმი, ყურძენი, უმი სტაფილო, უმი ნიახური, კურკიანი ბალი და ალუბალი. ძალიან მნიშვნელოვანია, ყურადღებით იყოთ, როდესაც თქვენი ბავშვი ამ საკვებს მიირთმევს. თუ ბავშვი ასეთ საკვებს ჭამს, შეეცადეთ, მარტო არ დატოვოთ. რაიმე სირთულის შემთხვევაში პანიკაში ნუ ჩავარდებით, დააკვირდით ბავშვს, ხოლო სასუნთქი გზების სრული დახშობისას, როდესაც შეამჩნევთ, რომ ის ვერ სუნთქავს, დაუყოვნებლივ დარეკეთ 112-ზე და დაიწყეთ პირველადი დახმარების გაწევა.') WHERE id = '43766e9c-9331-414f-9fe4-c87c7161371c';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ პერიოდში თქვენმა ბავშვმა სამ ძირითად კვებასთან ერთად 1-2 წახემსებაც უნდა მიიღოს. მას უკვე შეუძლია ოჯახის სხვა წევრების მსგავსი საკვების ჭამა. სხვა სიტყვებით რომ ვთქვათ, მისთვის ცალკე კერძის მომზადება აღარ არის საჭირო. ბავშვის მეტყველებისა და სოციალური უნარების განვითარებასთან ერთად, ყველასთან ერთ სუფრასთან ჯდომა მას საშუალებას მისცემს, აქტიურად ჩაერთოს კვების პროცესში. ამ დროს მნიშვნელოვანია, ზედმეტად არ გაამახვილოთ ყურადღება ბავშვის მიერ შეჭმული საკვების რაოდენობაზე, კვების დრო ბრძოლად არ აქციოთ და ერთად სასიამოვნოდ გაატაროთ დრო. რაც უფრო მეტს შეეკამათებით საკვების არჩევანის გამო, მით უფრო მტკიცედ მოინდომებს ბავშვი თავისის გატანას. თუმცა ოჯახში უნდა ეცადოთ, დაიცვათ ჯანსაღი კვების ჩვევები და ერთად გააკეთოთ ჯანსაღი არჩევანი. კვების დროს მთელი ოჯახით სუფრასთან შეკრება შესანიშნავი ჩვევის დასაწყისია.') WHERE id = '690fc0a4-31a8-41bb-8387-afbb9a513803';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ზრდასთან ერთად თქვენი ბავშვი ისწავლის მრავალი საქმის დამოუკიდებლად გაკეთებას — დაწყებული პერანგის ჩაცმა-გახდით და დამთავრებული თეფშზე საკვების გადაღებით. თქვენი ბავშვის დამოუკიდებლობის განვითარებაზე დაკვირვება ემოციურიცაა და სიამაყის მომგვრელიც. ეს მისი პიროვნული და სოციალური განვითარების მნიშვნელოვანი ნაწილია. მიუხედავად იმისა, რომ თავისუფალი ტანსაცმლის დამოუკიდებლად ჩაცმა უკვე გარკვეული ხანია შეუძლია, მაისურის მსგავსი მომდგარი სამოსის დაუხმარებლად ჩასაცმელად შესაძლოა კიდევ რამდენიმე თვე დასჭირდეს. სრულიად დამოუკიდებლად ჩაცმას კი შეიძლება ერთი-ორი წელი დასჭირდეს. ამიტომ რეალისტური მოლოდინები გქონდეთ და ნუ ინერვიულებთ. ასევე, ზედმეტად ნუ ჩაერევით. მაგალითად, თქვენს ბავშვს უკვე უნდა შეეძლოს ფეხსაცმლის დახმარების გარეშე გახდა და ჩაცმისას სასურველი ფერის თავად არჩევა.') WHERE id = 'd7f6ffc6-8357-4c5b-94b8-550d90fdcbed';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი უკვე კვებასთან დაკავშირებითაც საკუთარ გადაწყვეტილებებს იღებს და უფრო დამოუკიდებელი ხდება, ამიტომ კვების დრო შეიძლება ცოტა რთულად წარიმართოს. როგორც მშობელს, მნიშვნელოვანი როლი გაქვთ ბავშვისთვის ჯანსაღი კვების ჩვევებისა და დისციპლინის ჩამოყალიბებაში. ჭამის დაძალება და ჯილდოს ან დასჯის მეთოდების გამოყენება ბავშვის კვების ჩვევებზე უარყოფითად მოქმედებს. თქვენ პატივი უნდა სცეთ ბავშვის მადას. ჯანსაღი კვების მთავარი პირობაა, არ გამოტოვოთ ძირითადი კვება და წახემსება და ბავშვი არ მიაჩვიოთ არაჯანსაღ საკვებს. ამ პერიოდში განსაკუთრებით მნიშვნელოვანია რძე და რძის პროდუქტები, კვერცხი, ყველი, ახალი სეზონური ბოსტნეული და ხილი, მარცვლეული, წითელი ხორცი, ფრინველის ხორცი, თევზი და პარკოსნები. ეს პროდუქტები დაბალანსებულად უნდა შეიტანოთ თქვენი ბავშვის კვების რაციონში. გახსოვდეთ, რომ თითოეული ჯანსაღი საკვები, რომელსაც ბავშვი დღეს იღებს, მის მომავალში ჩადებული უდიდესი ინვესტიციაა.') WHERE id = '7ace9092-3ee2-47b6-b891-840cce162d3e';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი ამჟამად კოგნიტიური (შემეცნებითი) განვითარების მეორე ეტაპზე, „ოპერაციამდელ პერიოდში“ იმყოფება. ეს პერიოდი აზროვნების დასაწყისადაც მიიჩნევა. მარტივად რომ ვთქვათ, თქვენი ბავშვი უკვე იწყებს გონებრივი შესაძლებლობების საკუთარი მიზნებისთვის გამოყენებას. ცდისა და შეცდომის პირველი გამოცდილებიდან დასკვნების გამოტანა სწავლის პროცესში მისი უდიდესი დამხმარეა. ამ პერიოდში ბავშვი მეხსიერების აქტიურად გამოყენებას იწყებს და უყალიბდება საგნის მუდმივობისა და იდენტობის გაგება. ის უკვე შინაგანი რეაქციებიდან გარეგან რეაქციებზე გადადის. მიბაძვის უნარი კიდევ უფრო ვითარდება, ამიტომ ძალიან მნიშვნელოვანია, რომ მის გარშემო მყოფმა ადამიანებმა კარგი მაგალითი მისცენ და მისთვის მისაბაძი პიროვნებები იყვნენ.') WHERE id = '694eaa85-119e-4aa0-b132-331a3944017a';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ ეტაპზე თქვენი ბავშვის მიერ მიღებული თითოეული ჯანსაღი საკვები შეგიძლიათ მის მომავალში ჩადებულ ინვესტიციად მიიჩნიოთ. მაგალითად, სასარგებლოა, ბავშვის რაციონში სეზონურ ბოსტნეულსა და ხილთან ერთად იმუნური სისტემის გამაძლიერებელი ძვლის ბულიონიც შეიტანოთ. ძვლის ბულიონი მრავალ ვიტამინსა და მინერალს, ასევე დიდი რაოდენობით ცილას შეიცავს. ამიტომ მას ბავშვის კვებაში მნიშვნელოვანი ადგილი უკავია. ძვლის ბულიონში შემავალი კოლაგენი, ქონდროიტინი და გლუკოზამინი ხრტილოვან ქსოვილს აძლიერებს და ბავშვის ძვლების ჯანსაღ განვითარებას უწყობს ხელს. გარდა ამისა, ძვლის ბულიონი მდიდარია ორგანიზმის მომადუნებელი ამინომჟავა გლიცინით, რაც ბავშვს უფრო მშვიდად დაძინებაში ეხმარება. თქვენი ბავშვის საჭმლის მომნელებელი სისტემა ჯერ კიდევ განვითარების პროცესშია, ამიტომ ნორმალურია, თუ მას თქვენ მიერ მიღებული ზოგიერთი მძიმე საკვების მონელება უჭირს. ძვლის ბულიონი კი ადვილად შეთვისების უნარის წყალობით ბავშვისთვის მარტივად მოსანელებელი საკვებია.') WHERE id = 'a406b692-65b5-470a-8764-73b3f8d9ec30';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ ეტაპზე ბავშვის როგორც ნატიფი, ისე მსხვილი მოტორული უნარები მნიშვნელოვნად არის განვითარებული. ის უკვე თავისუფლად დარბის, სურვილისამებრ ჩერდება და დაბრკოლებებს ადვილად გადალახავს. იატაკიდან ნივთის ასაღებად თავისუფლად ჩაიმუხლება და ხელების დაუხმარებლად დგება. შეუძლია ავეჯზე აძვრეს და ხშირად დახმარების გარეშე ჩამოვიდეს. შესაძლოა, ის ფეხის წვერებზეც მდგარი დაინახოთ. მოაჯირზე ხელის მოკიდებით კიბეზე დამოუკიდებლად ადის და ჩამოდის, თუმცა წონასწორობის შესანარჩუნებლად თითოეულ საფეხურზე ჯერ კიდევ ორივე ფეხს დგამს. ამ ასაკში ბავშვები ცდილობენ, წინ მდებარე ბურთს ფეხი დაარტყან, თუმცა ხშირად მიზანს ვერ ხვდებიან. სრულიად ნორმალურია, თუ ბავშვი ფანქარს მთელი მტევნით იჭერს და ქაღალდზე ჯღაბნის. მას წიგნის ფურცლების გადაფურცვლაც ძალიან მოსწონს. ეს ნიშნავს, რომ უკვე დროა, თქვენმა ბავშვმა ხატვა დაიწყოს! თუმცა კვლავ ყურადღება მიაქციეთ, რომ კედლები არ მოხატოს! :)') WHERE id = 'b039724d-e5f7-45e9-8fc4-95a761a5df3b';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენმა ბავშვმა როგორც ფიზიკური, ისე გონებრივი განვითარების მხრივ დიდ პროგრესს მიაღწია. თუმცა ამ პერიოდში მას ღამით კვლავ 11-12 საათი ძილი სჭირდება. ამიტომ საღამოს დაძინების დრო ბავშვის დილით გაღვიძების დროს უნდა შეუსაბამოთ. მაგალითად, თუ ბავშვი დილის 07:00-ზე იღვიძებს, 11-საათიანი ძილის საჭიროების დასაკმაყოფილებლად ის დაახლოებით 20:00-ზე უნდა დააძინოთ. ძილის ჯანსაღი რეჟიმის ჩამოსაყალიბებლად ყურადღება მიაქციეთ, რომ დაძინების დრო არაუგვიანეს 21:00-ისა იყოს. თუ თქვენმა ბავშვმა დღის ძილზე უკვე უარი თქვა, დაძინების დროის ოდნავ ადრე გადმოწევით თავიდან აიცილებთ მის მეტისმეტად დაღლილ მდგომარეობაში ჩაძინებას და ღამით გაღვიძებებსაც შეამცირებთ. ძილისწინა რიტუალების მეშვეობით ბავშვს აგრძნობინებთ, რომ დაძინების დრო მოვიდა. კბილების გახეხვა, წიგნის კითხვა, დღის განმავლობაში ყველაზე სასიამოვნო მოვლენის გაზიარება, შუქის ჩაქრობა და ძილის წინ კოცნა ამ ასაკისთვის შესაფერისი აქტივობებია.') WHERE id = 'aa2b7696-4c81-4ab5-b66f-36eb3f265c8f';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'პერცენტილის ცხრილის მიხედვით, 28 თვის ბიჭების საშუალო წონა 13.200 გრამია, ხოლო გოგოების — 12.700 გრამი. ბავშვის წონა შეიძლება ამ მაჩვენებლებზე ოდნავ ნაკლები ან მეტი იყოს, რადგან თითოეული ბავშვის სხეულის ჯანსაღი პარამეტრები მრავალ სხვადასხვა ფაქტორზეა დამოკიდებული. ამ ფაქტორებს შორის უმთავრესია ბავშვის გენეტიკა და მისთვის დამახასიათებელი ჰორმონული ბალანსი. ამასთანავე, წონაზე პირდაპირ გავლენას ახდენს კვების რეჟიმი, დღის განმავლობაში ფიზიკური აქტივობის დონე და საცხოვრებელი გარემოს პირობები. მნიშვნელოვანია გვახსოვდეს, რომ ბავშვის განვითარების მაჩვენებლები ერთმანეთთან არის დაკავშირებული. მაგალითად, თუ ბავშვი საშუალოზე მაღალია, მისი ჯანსაღი წონაც საშუალოზე მეტი იქნება. ამიტომ ყველაზე ზუსტ შეფასებას ექიმი გააკეთებს, რომელიც თქვენს ბავშვს რეგულარულად აკვირდება.') WHERE id = '5a3ba4d7-afcf-4bb0-aad2-6d8e229cd0e1';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'მეტყველების პრობლემები ამ პერიოდში მშობლებისთვის ერთ-ერთი ყველაზე შემაშფოთებელი საკითხია. ხშირად ბავშვებში ენის განვითარებისა და მეტყველების შეფერხებას ერთსა და იმავე ცნებად მიიჩნევენ, თუმცა ისინი ერთმანეთისგან განსხვავდება. თუ თქვენს ბავშვს ნათქვამის გაგება და საკუთარი აზრის გამოხატვა უჭირს, შესაძლოა, საქმე ენობრივ დარღვევასთან გვქონდეს. ასეთ შემთხვევაში ბავშვი თანატოლებთან შედარებით უფრო მოკლე წინადადებებს ადგენს, სუფიქსებს არასწორად ან არასრულად იყენებს და შეზღუდული ლექსიკური მარაგი აქვს. თუ ბავშვი ბგერებს სწორად და გამართულად ვერ წარმოთქვამს, ეს უკვე მეტყველების დარღვევაა. მეტყველების დარღვევა შეიძლება გამოვლინდეს ცალკეული ბგერების წარმოთქმის სირთულით (არტიკულაციის დარღვევა), ენის ბორძიკით ან ენის განვითარების შეფერხებით. თუმცა ამ დიაგნოზის დასმა მხოლოდ ექიმს შეუძლია. განსაკუთრებით იმის გათვალისწინებით, რომ ბავშვი სიტყვებსა და სუფიქსებს ახლა სწავლობს, მნიშვნელოვანია, რეალისტური მოლოდინები გქონდეთ.') WHERE id = 'adac34a3-0b40-4281-8ff2-1c451c990897';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის ზრდისა და განვითარების შეუფერხებლად გასაგრძელებლად ჯანსაღი და დაბალანსებული კვება ძალიან მნიშვნელოვანია. ამ პროცესში ცილებს (პროტეინებს) დიდი როლი აკისრიათ. ცილები, რომლებიც ორგანიზმის ძირითადი საშენი მასალაა, აუცილებელია კუნთებისა და უჯრედების აღდგენისთვის. 1 წლამდე ამ საჭიროებას დედის რძე აკმაყოფილებს. 1 წლის შემდეგ კი ყოველდღიურად მიღებული ცილის 20% ცხოველური, ხოლო 80% მცენარეული წარმოშობის უნდა იყოს. ამ პერიოდში საკმარისია, ბავშვმა სხეულის წონის ყოველ კილოგრამზე დღეში 2 გრამი ცილა მიიღოს. ეს საშუალოდ დღეში 16 გრამ ცილას შეადგენს. მაგალითად, 2 ჯამი იოგურტი ან ერთი თეფში მაკარონი ყველით ბავშვის ცილის დღიურ საჭიროებას სრულად დააკმაყოფილებს. რძე, კვერცხი, ხორცი, ქათამი და თევზი სრულფასოვანი ცილის წყაროა და ორგანიზმისთვის საჭირო ყველა ამინომჟავას შეიცავს. ამასთანავე, ცილის საჭიროების სრულად დასაკმაყოფილებლად სასარგებლოა, ბავშვს მარცვლეული, პარკოსნები და ბოსტნეული ერთად მისცეთ.') WHERE id = '5d36b2bf-f065-4e27-b7dc-33f78f228aae';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ ფიქრობთ, რომ ბავშვისთვის ტუალეტის ჩვევის გამომუშავების პროცესში ჯერ საკმარის პროგრესს ვერ მიაღწიეთ, სასარგებლო იქნება რამდენიმე მნიშვნელოვანი საკითხის ცოდნა. მიუხედავად იმისა, რომ ბავშვს ჯერ სრულად ჩამოყალიბებულ ადამიანად არ აღიქვამთ, მისი აღქმის უნარი ზრდასრულების მსგავსად საკმაოდ განვითარებულია. ამიტომ ტუალეტის ჩვევის გამომუშავების პერიოდში ის ადვილად ამჩნევს თქვენს სახეზე უკმაყოფილებას, დადანაშაულებას ან დაღლილობას და საკუთარ რეაქციებს ამის მიხედვით არეგულირებს. ბავშვს რეგულარულად უნდა შეახსენოთ, რომ ტუალეტში წასვლის საჭიროებისას შეგატყობინოთ. თუმცა ამ დროს ეცადეთ, ჩვეულებრივზე მეტად მომთმენი და მოსიყვარულე იყოთ. ამასთანავე, მაშინაც კი, თუ ბავშვი თავად არ გეტყვით, შეგიძლიათ, გარკვეული ინტერვალებით ტუალეტზე დასვათ და წაახალისოთ. დაახლოებით 1-2 დღის განმავლობაში შეგიძლიათ, ის ყოველ საათში ერთხელ ტუალეტში წაიყვანოთ და შემდეგ ეს ინტერვალი თანდათან გაზარდოთ. ასე ბავშვი მოკლე დროში დაიწყებს იმის თქმას, რომ ტუალეტში წასვლა სჭირდება.') WHERE id = '115cbd6b-06db-4566-8c7c-e6c251edd677';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'მიუხედავად იმისა, რომ თქვენმა ბავშვმა ტუალეტით სარგებლობის ჩვევა სწორად აითვისა, გარკვეული პერიოდის შემდეგ შესაძლოა კვლავ შარვალში მოსაქმება დაიწყოს. ეს ზოგიერთ ბავშვს ემართება და პანიკის ნაცვლად ძალიან მნიშვნელოვანია, იცოდეთ, როგორ მოიქცეთ. თუ ტუალეტით სარგებლობის ჩვევის გამომუშავების შემდეგ ბავშვმა მოულოდნელად შარვალში მოსაქმება დაიწყო, უნდა ეცადოთ მიზეზის დადგენას და გააანალიზოთ, რა ხდება სახლში. ტუალეტით სარგებლობა 2–3 წლის ბავშვების მიერ შეძენილი განვითარების ერთ-ერთი ბოლო უნარია და რაიმე პრობლემის წარმოქმნისას უკუსვლა ყველაზე სწრაფად სწორედ ამ სფეროში ვლინდება. უკუსვლაში იგულისხმება, როდესაც დიდი ხნის წინ ძუძუს მოშორებული ბავშვი კვლავ ითხოვს დედის რძეს, საწოვარას გადაჩვეული ბავშვი ისევ მასთან ერთად დაძინებას მოითხოვს ან ტუალეტით სარგებლობას მიჩვეული ბავშვი შარვალში მოსაქმებას იწყებს. უნდა დააკვირდეთ მიზეზებს, რომლებმაც შესაძლოა ბავშვის ყოველდღიური ცხოვრება დაარღვიოს და მას წარსული პერიოდის უსაფრთხო გარემოში დაბრუნებისკენ უბიძგოს. მაგალითად, საბავშვო ბაღში თანატოლების მხრიდან ზეწოლამ, ოჯახის წევრების უარყოფითმა დამოკიდებულებამ ან ახალი და-ძმის დაბადებამ შეიძლება მსგავსი რეაქცია გამოიწვიოს.') WHERE id = '618a4bda-826f-4f95-b833-9fc6f643980b';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ყოველდღიურ ცხოვრებაში, განსაკუთრებით სტრესულ მომენტებში, თქვენმა ბავშვმა შესაძლოა ტიკის მსგავსი ქცევები გამოავლინოს. ამის მაგალითებია თმის მოქაჩვა, ფეხის ქნევა, თავის რაიმეზე დარტყმა ან თითის წოვა. უპირველეს ყოვლისა, უნდა დაადგინოთ მიზეზები, რომლებიც ბავშვს ამ მოქმედებებისკენ უბიძგებს. მაგალითად, თუ ამჩნევთ, რომ ბავშვი შფოთვისა და დაძაბულობის დროს თითს წოვს, უნდა ეცადოთ, დაიცვათ იგი ამ დაძაბულობისგან. ცვლილებებამდე, რომლებმაც შეიძლება სტრესი გამოიწვიოს, ეცადეთ ბავშვი ფსიქოლოგიურად მოამზადოთ. ასევე, ნუ მისცემთ ბავშვს მისი ასაკისთვის შეუფერებელი გამოსახულებებისა და მასალის ნახვის უფლებას. თუ გრძნობთ, რომ ამ მდგომარეობასთან დამოუკიდებლად გამკლავებას ვერ შეძლებთ, ბავშვზე ზეწოლის ნაცვლად უმჯობესია სპეციალისტს მიმართოთ.') WHERE id = '45fb1590-a84e-4747-9499-1dc671d7ac73';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ პერიოდში თქვენმა ბავშვმა შესაძლოა წარმოსახვაში სრულიად უცნობი პიროვნება წარმოსახვით მეგობრად შექმნას. ეს მდგომარეობა, რომელიც დაახლოებით 2,5 წლის ასაკში ჩნდება, ბავშვის აბსტრაქტული აზროვნების განვითარების ნაწილია და სრულიად ნორმალურია. ზოგჯერ შეიძლება შეამჩნიოთ, რომ ბავშვი საკუთარ აზრებს ამ წარმოსახვით მეგობარს ადასტურებინებს ან დაშვებულ შეცდომას მას აბრალებს. მაგალითად, თუ რაიმე გატეხა, შეიძლება თქვას, რომ ეს მას არ გაუკეთებია. სინამდვილეში ეს სრული მნიშვნელობით ტყუილი არ არის, რადგან ბავშვს ამ ნივთის გატეხვა განზრახული არ ჰქონია. ამიტომ გაბრაზების ნაცვლად უნდა წაახალისოთ, რომ მომხდარის შესახებ მოგიყვეთ. წარმოსახვითი მეგობრები, ჩვეულებრივ, 6 წლამდე ქრებიან. ამის მიზეზი ისაა, რომ ბავშვს ჯერ კიდევ ბოლომდე არ ესმის განსხვავება რეალობასა და წარმოსახვას შორის. ამ პროცესში თქვენმა ჩარევამ შეიძლება ბავშვის პიროვნულ განვითარებაზე უარყოფითად იმოქმედოს.') WHERE id = 'f133f827-1aea-4a05-8919-15682019fac0';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვობიდან ჩამოყალიბებული გმო-ს შემცველი საკვების, არომატიზატორებისა და სწრაფი კვების პროდუქტებში დამატებული გემოს გამაძლიერებლებისადმი დამოკიდებულებისგან გათავისუფლება მომავალში ძალიან რთულია. არასწორი კვებით გამოწვეული ჭარბი წონის დაკლება და დარღვეული ჰორმონული ჯანმრთელობის აღდგენა ზოგჯერ შეუძლებელია. სწორედ ამიტომ, ბავშვი შეფუთულ საკვებსა და სწრაფ კვებას არ უნდა მიაჩვიოთ. ბავშვისთვის ჯანსაღი კვების ჩვევის ჩამოსაყალიბებლად ძალიან მნიშვნელოვანია სახლში მომზადებული საკვები, კვების რეგულარული დრო და მთელი ოჯახის ერთად ჭამა. მაგალითად, ბატიბუტი შესაძლოა ძალიან ჯანსაღ საკვებად მოგეჩვენოთ, თუმცა სიმინდი ერთ-ერთი კულტურაა, რომლის გენეტიკურად მოდიფიცირებული სახეობებიც ყველაზე ფართოდ გამოიყენება. თუ ამას მიკროტალღურ ღუმელში მომზადებაც ემატება, პროდუქტი თქვენი ბავშვისთვის კიდევ უფრო საზიანო ხდება. ნაგეტები, კარტოფილი ფრი, ჰამბურგერები, ჩიფსები და ნიტრატების მაღალი შემცველობის მქონე გადამუშავებული ხორცის პროდუქტები, როგორიცაა ძეხვი და სოსისი, ასევე იმ საკვებს მიეკუთვნება, რომელსაც ბავშვი უნდა მოარიდოთ.') WHERE id = 'f814e388-56b0-4495-929d-571e82ff8364';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ პერიოდში თქვენი ბავშვის ძილის რეჟიმი შეიძლება ისე აირიოს, როგორც არასდროს. ოჯახებისთვის, რომლებიც ბავშვის ძილის პრობლემებს ადრეც აწყდებოდნენ, იმის დანახვა, რომ ეს სირთულეები 2 წლის შემდეგაც გრძელდება, შესაძლოა გარკვეულ იმედგაცრუებას იწვევდეს. მიუხედავად იმისა, რომ ფართოდ არის გავრცელებული მოსაზრება, თითქოს ბავშვის ზრდასთან ერთად ძილის პრობლემები თავისთავად მოგვარდება, სინამდვილეში ყოველთვის ასე არ ხდება. თუ თქვენც გაწუხებთ ბავშვის ძილის პრობლემები, რამდენიმე საკითხს უნდა მიაქციოთ ყურადღება. მაგალითად, კვლევების თანახმად, ბავშვის გარემოში ტელევიზორისა და ინტერნეტის არსებობა ძილისადმი მის პირდაპირ წინააღმდეგობას იწვევს. ამის მთავარი მიზეზი ჭარბი სტიმულაციაა. მოკლედ რომ ვთქვათ, როგორც შაქარი და შოკოლადი ახდენს ორგანიზმზე მასტიმულირებელ გავლენას, ისეთივე ეფექტი აქვს ტელევიზორის მსგავს მოწყობილობებსაც. ამიტომ ბავშვის დაძინებამდე მინიმუმ 2 საათით ადრე ტელევიზორის, პლანშეტისა და ტელეფონის მსგავსი მოწყობილობების გამორთვა ამ დაძაბულობას მნიშვნელოვნად შეამცირებს.') WHERE id = '27bc15ff-de70-4213-99e8-421c8ec7be89';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ფუტკრის რძე, რომელსაც ფუტკრები მატლების გამოსაკვებად საკუთარი ორგანიზმიდან გამოყოფენ, ღირებული პროდუქტია და მნიშვნელოვანი ადგილი უკავია თქვენი ბავშვის ჯანმრთელობასა და კვებაში. მაღალი კვებითი ღირებულების მქონე ფუტკრის რძე 1 კვირის ფუტკრების მიერ გამოყოფილი გელისებრი ნივთიერებაა. ცნობილია, რომ ფუტკრის რძე იმუნურ სისტემას აძლიერებს, ხოლო ყოველ დილით 1 ჩაის კოვზ თაფლთან ერთად მიღება მის ეფექტს კიდევ უფრო ზრდის. ფუტკრის რძის 100 გრამში დაახლოებით 15 გრამი ცილაა. ის ასევე მდიდარია B ჯგუფის ვიტამინებით, ფოლიუმის მჟავით, მაგნიუმით, თუთიითა და რკინით. ფუტკრის რძე შეიცავს განსაკუთრებულ ცილას, სახელად როიალაქტინი, რომელიც არცერთ სხვა საკვებში არ გვხვდება, და ძვირფას ცხიმოვან მჟავას, სახელად 10-HDA. ყველა ამ თვისების წყალობით ფუტკრის რძე ბუნებრივი პროდუქტია, რომლის გამოყენებაც შესაძლებელია ბავშვის ზრდისა და განვითარების მხარდასაჭერად. რეგულარული გამოყენებისას შეამჩნევთ, რომ ის ბავშვის იმუნიტეტს აძლიერებს, ფიზიკურ და გონებრივ განვითარებას ხელს უწყობს და მადას არეგულირებს.') WHERE id = 'a10c3d04-e569-47ea-bad2-70a751db07a2';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ საქმე უსაფრთხოებასა და მნიშვნელოვან ზნეობრივ წესებს არ ეხება, ეცადეთ, ბავშვის მიმართ ხშირად არ გამოიყენოთ ისეთი აკრძალვები, როგორიცაა „არა“ და „ნუ გააკეთებ“. ეს სიტყვები შეიძლება მის სწავლისთვის გახსნილ გონებაში გადაულახავ დაბრკოლებებად იქცეს. სურვილების შესრულების შეუძლებლობამ შეიძლება მისი წარმოსახვის სამყარო დააზიანოს და თავდაჯერება შეუმციროს. ამიტომ ეცადეთ, ურთიერთობისას უარყოფითის ნაცვლად დადებითად ჩამოყალიბებული ფრაზები გამოიყენოთ. „არას“ თქმის ნაცვლად შეგიძლიათ ორივესთვის უფრო საინტერესო და სასარგებლო ალტერნატივები შესთავაზოთ. როდესაც ბავშვი რაიმეს არასწორად აკეთებს, მან შესაძლოა ისედაც თავი დამნაშავედ და ცუდად იგრძნოს. თქვენ და თქვენი მეუღლე, როგორც მისთვის ყველაზე სანდო ადამიანები, განსჯის გარეშე უნდა იყოთ მის გვერდით. ერთი მხრივ, სწორ ქცევისკენ უნდა უბიძგოთ, მეორე მხრივ კი დაიცვათ შეცდომების გამო დანაშაულის ღრმა განცდისგან.') WHERE id = 'adaca540-c013-4a03-bbd7-74d6af6f0d5a';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'იწყება ახალი პერიოდი, რომელსაც თქვენს ბავშვთან ერთად სრულფასოვნად გაატარებთ. ამ ეტაპზე, ბავშვის კუნთების გაძლიერებასთან ერთად, მისი მოძრაობების კოორდინაცია და წონასწორობაც უმჯობესდება. თქვენი საკმაოდ ენერგიული ბავშვი მუდმივად მოძრაობს და ბევრ მშობელს უჭირს მის ენერგიას აუწყოს ფეხი. ფიზიკური განვითარების პარალელურად მისი გონებრივი განვითარებაც სწრაფად გრძელდება. ამიტომ ამ პერიოდში მნიშვნელოვანია, ბავშვი ჩართოთ ისეთ აქტივობებში, რომლებიც მის კუნთოვან ძალას, შემოქმედებით უნარებსა და ფიზიკურ გამძლეობას განავითარებს. 29 თვის ბავშვისთვის ბურთზე ფეხის დარტყმა, სირბილი, ველოსიპედით სეირნობა და სხვადასხვა ადგილას აძრომა შესანიშნავი აქტივობებია. ყველა ეს ფიზიკური მოძრაობა მის გონებრივ განვითარებაშიც მნიშვნელოვან წვლილს შეიტანს.') WHERE id = '1aab8015-59a1-447d-9108-ce75d06b5eba';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, '1 წლის ასაკიდან ბავშვები ყოველწლიურად საშუალოდ 5-7 santimetr-ით იზრდებიან და დაახლოებით 2-3 kiloqram-ს იმატებენ. თუმცა ფიზიკური განვითარების ეს მაჩვენებლები მრავალი სხვადასხვა ფაქტორის მიხედვით შეიძლება შეიცვალოს. ამ პერიოდში გენეტიკური თავისებურებების გავლენა უფრო მეტად იწყებს გამოვლენას. ამიტომ, ბავშვის კვების ჩვევები რომც არ შეიცვალოს, სიმაღლისა და წონის მატების მხრივ შესაძლოა თანატოლებისგან განსხვავებული წინსვლა ან ჩამორჩენა შეამჩნიოთ. მაგალითად, გამხდარი და მცირე აღნაგობის მშობლების შვილები, დაბალანსებული კვების მიუხედავად, თანატოლებთან შედარებით შეიძლება უფრო პატარები ჩანდნენ. ამიტომ ფიზიკური განვითარების შეფასებისას თქვენთვის ერთადერთი კრიტერიუმი ექიმის მოსაზრება უნდა იყოს. ამ მხრივ ორიენტირებაში პერცენტილის (განვითარების) ცხრილიც დაგეხმარებათ. ცხრილის მიხედვით, 29 თვის გოგონების წონის ქვედა ზღვარი 10.000 qram, ხოლო ზედა ზღვარი 16.000 qram-ია. 29 თვის ბიჭების წონის ქვედა ზღვარი 10.500 qram, ზედა ზღვარი კი 16.400 qram-ია. რაც შეეხება სიმაღლეს, 29 თვის გოგონებისთვის ქვედა ზღვარი 83,4 sm, ზედა ზღვარი 96,4 sm-ია; ბიჭებისთვის კი ქვედა ზღვარი 84,9 sm, ხოლო ზედა ზღვარი 97,5 sm-ია.') WHERE id = 'db8346fb-9273-49d5-bf2c-a86e6c17b290';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'როგორც ზრდასრულების შემთხვევაში, ბავშვისთვის დღის განმავლობაში საჭირო ენერგიის დიდი ნაწილი ნახშირწყლებიდან მიიღება. ამ მიზანს, პირველ რიგში, პური და ნახშირწყლების სხვა წყაროები ემსახურება. თუმცა ჯანსაღი ნახშირწყლების შერჩევა თქვენი პასუხისმგებლობაა. თეთრი პურის ნაცვლად არა მხოლოდ თქვენ, არამედ თქვენმა ბავშვმაც უპირატესობა უნდა მიანიჭოს მთლიანი ხორბლისგან (მთლიანი მარცვლეულისგან) დამზადებულ პურს. მთლიანი ხორბლის ფქვილი ნაკლებად დამუშავებულია, ამიტომ კვებითი ღირებულებით უფრო მდიდარია. ბრინჯის ნაცვლად ბულგურის გამოყენებაც კარგი ალტერნატივაა. თუ თქვენს ბავშვს წონის მომატებისკენ აქვს მიდრეკილება, ამ პროდუქტების სრულად ამოღების ნაცვლად შეგიძლიათ ულუფები შეამციროთ. ამასთანავე, ჯანსაღი ნახშირწყლების ჯგუფში შემავალი პარკოსნები, როგორიცაა ლობიო, მუხუდო და ოსპი, შეგიძლიათ ბავშვის მენიუში კვირაში 2-3-ჯერ შეიტანოთ.') WHERE id = '1c27be1f-dfab-44ba-8a0e-90b8852c1426';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ ასაკში თქვენს ბავშვს ძალიან მოსწონს ისეთი თამაშები, როგორიცაა დაჭერობანა და დამალობანა. მისთვის თქვენთან ერთად თამაში ძალიან მნიშვნელოვანია, რადგან ამ გზით გრძნობს, რომ სასურველია და მას ეძებენ. დამალობანას თამაშისას პოვნის მომენტი ბავშვს ობიექტის მუდმივობის აღქმაც უმტკიცებს. ამ პერიოდში საკუთრების განცდა ჯერ სრულად ჩამოყალიბებული არ არის. მიუხედავად იმისა, რომ ბავშვი საკუთარ ნივთებს ნაწილობრივ აზიარებს, შესაძლოა შეამჩნიოთ, რომ სხვა ბავშვებთან უშუალო, ერთობლივ თამაშში არ ერთვება. როგორც წესი, სხვა ბავშვის გვერდით თამაშისას შეიძლება აკვირდებოდეს მას, თუმცა ისე იქცეოდეს, თითქოს ის იქ არ არის. ამასთანავე, თქვენმა ბავშვმა შეიძლება სხვა ბავშვის სიცილს სიცილით უპასუხოს ან მისმა ტირილმა შეაშინოს. თუ თავად გახდა სხვისი ტირილის მიზეზი, შესაძლოა ისიც შეამჩნიოთ, რომ დაიძაბა.') WHERE id = '48eeead7-4aaf-4261-980b-2417b364eaf1';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ახლა, როცა თქვენი ბავშვი 2.5 წლის ასაკს უახლოვდება, სრულიად ნორმალურია, თუ მას ულუფების შემცირება სურს და ხშირად ამბობს: „დავნაყრდი“. ეს აუცილებლად არ ნიშნავს, რომ ბავშვს მადა დაეკარგა, ამიტომ ნუ ინერვიულებთ. ამის მთავარი მიზეზი ზრდის ტემპის მნიშვნელოვნად შენელებაა. როდესაც ბავშვი ნაკლების ჭამას იწყებს, საუკეთესო არჩევანია, საკვები მცირე ულუფებით, თუმცა უფრო ნოყიერი სახით შესთავაზოთ. ამ პერიოდში ბავშვს ზრდასრულის მიერ მიღებული საკვების მაქსიმუმ ნახევრის მიღება შეუძლია. ამიტომ ძალიან მნიშვნელოვანია, არ აიძულოთ, მეტი ჭამოს. იზრუნეთ, რომ საკვები, რომელსაც მცირე რაოდენობით მიირთმევს, ჯანსაღი იყოს. ბავშვს ნებისმიერ დროს მარტივად უნდა მიუწვდებოდეს ხელი ჯანსაღ წასახემსებელზე, არაჯანსაღი საკვები კი მისთვის მიუწვდომელ ადგილას უნდა შეინახოთ.') WHERE id = '3870e199-6a66-48e6-9897-cabfbe66081e';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვის ამჟამინდელ ასაკში საზღვრები ძალიან მნიშვნელოვანია. მშობლები საზღვრებს აწესებენ, ბავშვებს კი მათი გამოცდა უყვართ. აქ მთავარი თანმიმდევრულობაა. თუ საზღვრებს ხან დაიცავთ, ხან კი არა, ბავშვი უფრო მეტად დაიბნევა. ძილის წინ ისეთ თხოვნებს, როგორებიცაა „კიდევ ერთი ჭიქა წყალი“, „მამას კიდევ ერთხელ ვაკოცებ“ ან „ბოლოს კიდევ ერთხელ წავალ ტუალეტში“, გარკვეული ზღვარი უნდა დაუწესოთ. მაგალითად, თუ ბავშვი დაძინების თავიდან ასაცილებლად სხვადასხვა მიზეზს იგონებს, მკაფიო საზღვრები უნდა განსაზღვროთ და აუცილებლად დაიცვათ. სიჯიუტის დროს არ უნდა დაგავიწყდეთ, რომ თქვენ ამ სიტუაციაში უფრო ზრდასრული მხარე ხართ. მეორე მხრივ, გაჯიუტებასაც აზრი არ აქვს, რადგან ამ ბრძოლაში ვერ გაიმარჯვებთ. :) ეს მხოლოდ იმ არასასურველი ქცევის გაგრძელებას შეუწყობს ხელს. ამის ნაცვლად მოდუნდით, ჩამოჯექით და ეცადეთ, თქვენი სიმშვიდით ბავშვს მაგალითი მისცეთ.') WHERE id = 'bc1477cb-0848-495f-b85f-1500cde5812a';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ პერიოდში, როდესაც ტუალეტის ჩვევის გამომუშავება უკვე დაასრულეთ ან ჯერ კიდევ აგრძელებთ, შეიძლება შეამჩნიოთ, რომ ზოგიერთ დღეს ბავშვს შარდვა უჭირს. შესაძლოა გამოვლინდეს ისეთი ნიშნები, როგორებიცაა შარდვის დროს ტირილი ან უმიზეზო ტირილის შეტევები. ეს მდგომარეობა შეიძლება 2 წლის ასაკისთვის დამახასიათებელი კრიზისის ნიშანი იყოს, თუმცა ინფექციაზეც მიუთითებდეს. საშარდე გზების ინფექცია, რომელიც განსაკუთრებით ხშირად გვხვდება გოგონებში, საშარდე გზების ანთების შედეგად ვითარდება. გოგონებში მისი სიხშირის მიზეზი სხეულის ანატომიური აგებულებაა, რის გამოც ბაქტერიები საშარდე გზებში უფრო ადვილად ხვდება. თუ ბავშვს აქვს ისეთი ნიშნები, როგორებიცაა მუცლის ტკივილი, შარდის უსიამოვნო სუნი, ღებინება, გულისრევა, უმადობა, შარდის შეუკავებლობა და ხშირი, მაგრამ მცირე რაოდენობით შარდვა, ექიმს უნდა მიმართოთ. თუ ანალიზით ანთება გამოვლინდა, ექიმი შესაბამის ანტიბიოტიკოთერაპიას დანიშნავს.') WHERE id = 'da48700f-d847-4b96-8c98-118ee88f992c';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვთა სიმსუქნე ბოლო წლებში როგორც მთელ მსოფლიოში, ისე ჩვენს ქვეყანაშიც გავრცელებულ პრობლემად იქცა. სიმსუქნის ერთ-ერთი მთავარი მიზეზია ბავშვების მიერ განსაკუთრებით შაქრის, სხვადასხვა ტკბილეულისა და დაბალი კვებითი ღირებულების, თუმცა მაღალკალორიული პროდუქტების მიღება. თეთრი შაქარი სისხლში გლუკოზის დონის სწრაფ მატებას, შემდეგ კი მკვეთრ ვარდნას იწვევს, რაც ბავშვებში ტკბილეულის მიღების დაუსრულებელ სურვილს აჩენს. ასევე მნიშვნელოვანია საუზმის ნაცვლად მიცემული ფუნთუშებისა და მსგავსი ცომეულის შეზღუდვა. მაღალი გლიკემიური ინდექსის მქონე ეს პროდუქტებიც, შაქრის მსგავსად, მუდმივი შიმშილის შეგრძნებას იწვევს. ფერად შეფუთვებში მოთავსებული რბილი ჟელეს კანფეტები კი ყველა ბავშვის ყურადღებას იქცევს. ამგვარი პროდუქტები, ჩვეულებრივ, მსხვილფეხა რქოსანი პირუტყვის ძვლოვანი ნაწილების მოხარშვით მიღებული ჟელატინით მზადდება. მოკლედ, ბავშვი აუცილებლად უნდა მოარიდოთ პროდუქტებს, რომელთა ზუსტი შემადგენლობაც უცნობია.') WHERE id = 'd02c7a47-3078-410b-a75a-b2f0b0e780c9';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'აუტიზმი, რომლის გავრცელებაც ბოლო პერიოდში საგრძნობლად გაიზარდა, ბევრი მშობლის მსგავსად, შესაძლოა თქვენც გაღელვებდეთ. აუტიზმის შემთხვევაში ადრეულ დიაგნოსტიკას გადამწყვეტი მნიშვნელობა აქვს, ამიტომ მისი ნიშნების ცოდნა ძალიან მნიშვნელოვანია. აუტიზმი ნეირობიოლოგიური დარღვევაა, რომელიც ადრეული ბავშვობიდან ვლინდება და, მიჩნეულია, რომ თავის ტვინისა და ნერვული სისტემის განსხვავებული აგებულებით ან ფუნქციონირებითაა განპირობებული. აუტიზმი, რომელიც სხვებთან ურთიერთობას ართულებს და ბავშვის საკუთარ შინაგან სამყაროში ჩაკეტვას იწვევს, ჩვეულებრივ, 3 წლამდე ვლინდება. ეს მდგომარეობა უარყოფითად მოქმედებს ბავშვის სოციალურ კომუნიკაციაზე, ურთიერთქმედებასა და ქცევაზე. აუტიზმისა და აუტისტური სპექტრის სხვა დარღვევების დიაგნოსტიკა შეიძლება რთული იყოს, რადგან ნიშნების სიმძიმე ყველა ბავშვში განსხვავებულია. ყველაზე ცნობილი ნიშნებია კომუნიკაციის სირთულეები, თვალით კონტაქტის თავიდან არიდება, განმეორებადი ქცევები — მაგალითად, ხელების ქნევა, თავის დარტყმა ან რაიმე საგნის მრავალჯერ დატრიალება — და ცვლილებებთან შეგუების სირთულე. გარდა ამისა, ინტერესების შეზღუდული სფერო და ჩახუტების ან შეხების სურვილის არქონაც შეიძლება აუტიზმის ნიშანი იყოს.') WHERE id = '47c104cd-1ceb-4881-829f-8f78f639b9f1';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვმა შეიძლება თითის წოვა ჯერ კიდევ დედის მუცელში დაიწყოს. დაახლოებით 18-24 თვის ასაკში პირის მიდამო სიამოვნების მთავარი წყაროა, ამიტომ თითის წოვა შეიძლება მუდმივ ჩვევად იქცეს. ამასთან, ბავშვი ყოველდღიური რუტინის დროს თითის წოვით თავს იმშვიდებს და დუნდება. ჩვეულებრივ, 2 წლის შემდეგ, მეტყველების განვითარებასთან ერთად, ბავშვი საკუთარი თავის გამოსახატავად ახალ უნარებს იძენს და თითის წოვაც იკლებს. თუმცა ზოგი ბავშვი ასაკის მატების მიუხედავად ამ ჩვევას აგრძელებს; შესაძლოა თითი შიშის, დაღლილობის, მოწყენილობის დროს ან დასაძინებლად მოწოვოს. თუ თქვენი ბავშვიც აგრძელებს ამ ქცევას, მნიშვნელოვანია, სწორი მეთოდებითა და დროულად გადააჩვიოთ. არასწორმა მიდგომამ შეიძლება ბავშვს თავი დასჯილად და დამნაშავედ აგრძნობინოს. მაგალითად, შეგიძლიათ ყურადღება იმ მომენტებზე გაამახვილოთ, როდესაც ბავშვი თითს არ წოვს. ასეთ დროს მისი შექება დადებითი მოტივაცია იქნება და ამ ჩვევის დაძლევას წაახალისებს.') WHERE id = '0ce7f0c6-55c7-478c-bbc2-e2aef384f568';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'შესაძლოა, ბავშვს მეორე სარძევე დიდი ძირითადი კბილები უკვე სრულად ამოუვიდა. თუ ჯერ არ ამოსულა, შეგახსენებთ, რომ სავარაუდოდ მომდევნო 2 თვის განმავლობაში ამოვა! :) სარძევე კბილების სრულად ამოსვლა შეიძლება 2-ნახევარ, ზოგჯერ კი 3 წლამდეც გაგრძელდეს, ხოლო 6-თვიანი სხვაობა ნორმად ითვლება. დიდი ძირითადი კბილები ყველაზე რთულად ამოსდის, ამიტომ პირველ კბილებთან შედარებით შესაძლოა უფრო დაძაბული პროცესი გაიაროთ. ამ პერიოდში კბილის ამოსვლის ადგილას შეიძლება იისფერი შეშუპება წარმოიქმნას, რასაც მედიცინაში ამოჭრის კისტა ეწოდება. ამ პრობლემის დროს სამედიცინო ჩარევა, როგორც წესი, საჭირო არ არის; შესაძლოა დაგეხმაროთ ამ უბნის მასაჟი ან მაცივარში გაგრილებული კბილის ამოსაჭრელი სათამაშოს ბავშვისთვის მიცემა. იშვიათ შემთხვევებში კბილი კისტიდან ვერ ამოდის; ასეთ დროს ექიმს მცირე განაკვეთის გაკეთებით შეუძლია კბილის ამოსვლას ხელი შეუწყოს.') WHERE id = '5201e9e6-1a37-48d8-b089-cbbfefcfd807';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, '1-დან 3 წლამდე პერიოდი, როდესაც ბავშვები სიარულს იწყებენ, დამოუკიდებლობის ეტაპია. გახსოვდეთ, რომ თქვენი ბავშვი ჯერ კიდევ განვითარების ამ ეტაპზეა. ის უკვე სწავლობს, რომ დამოუკიდებელი პიროვნებაა და ბევრი რამის თავისით გაკეთება შეუძლია. მიუხედავად იმისა, რომ ყოველი სიახლე და გამოცდილება მას სიხარულს ანიჭებს, ზოგჯერ უცნობმა გარემოებებმა შეიძლება შეაშფოთოს. უცხო სიტუაციებთან გამკლავება ადვილი არ არის, ამიტომ მას ჯერ კიდევ სჭირდება იმ ადამიანის მხარდაჭერა და თანხმობა, ვისაც ენდობა. მხოლოდ თქვენი თანხმობის მიღების შემდეგ შეძლებს გარემოს შესწავლის გაგრძელებას. აღმოჩენების ამ პროცესში ზოგჯერ აკრძალული ქმედებების ჩადენაც გარდაუვალია. ამიტომ საზღვრებსა და წესებთან შეჯახებისას მან ხშირად შეიძლება პროტესტი გამოხატოს. დაბრკოლების შეგრძნებამ კი ზოგჯერ შეიძლება გააბრაზოს. თუმცა ასეთი დაპირისპირება ბავშვს „არას“ თქმის უნარს უვითარებს, რაც საკუთარი არჩევანისა და ემოციების გაცნობიერებისკენ გადადგმული მნიშვნელოვანი ნაბიჯია.') WHERE id = 'd9130ed0-2f5f-4d02-851c-ceed9e0bc359';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ზოგიერთი მშობელი ჩივის, რომ მისი ბავშვი ცოტას ჭამს, ზოგი კი შვილის ჭარბი კვების გამო ღელავს. თუ თქვენც მსგავსი პრობლემა გაქვთ, უპირველესად უნდა დაფიქრდეთ, რის საფუძველზე განსაზღვრავთ, რა არის „ბევრი“. გახსოვდეთ, რომ ყველა ბავშვი განსხვავებულია და თითოეულ მათგანს დანაყრების საკუთარი ზღვარი აქვს. ყველაზე სწორი მიდგომაა იმის გარკვევა, თუ რატომ ჭამს ბავშვი ბევრს. თუ მიზეზი ფიზიოლოგიურია, ძალიან მნიშვნელოვანია პედიატრთან კონსულტაცია, ხოლო თუ ფსიქოლოგიურია — პედაგოგთან ან ფსიქოლოგთან. ზოგჯერ ბავშვები ბევრს მხოლოდ ყურადღების მისაქცევადაც ჭამენ. ნებისმიერ შემთხვევაში, ექიმის რეკომენდაციის გარეშე არ უნდა ჩაერიოთ ბავშვის კვებაში და არ უნდა დაიცვათ მას დიეტა. ამან ზრდისა და განვითარების ეტაპზე მყოფი ბავშვისთვის შესაძლოა სახიფათო შედეგები გამოიწვიოს.') WHERE id = 'b0d1338b-df42-42bb-9eec-8ea39482f47d';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ ეტაპზე ბავშვის ტვინის უჯრედები წარმოუდგენელი სისწრაფით განაგრძობს ახალი ინფორმაციის შეგროვებას! ის თავისი ცხოვრების ყველა გამოცდილებას მეხსიერებაში ინახავს, რათა მომავალში გამოიყენოს. უკვე ცნობს საკუთარ თავს სარკეში და ინტერესით ხშირადაც კი აკვირდება თავის გამოსახულებას. განსაკუთრებით თქვენი მარტივი საოჯახო საქმეების გამეორებით სწავლობს, როგორ მოიქცეს გარშემომყოფების მსგავსად. როდესაც მამა სახლში რაიმეს აკეთებს ან არემონტებს, ბავშვმა შეიძლება ისე იმოქმედოს, თითქოს მსოფლიოში ყველაზე საინტერესო მოვლენას უყურებს. შემდეგ კი იმავე მოქმედებების სათამაშოებზე გამეორებას შეეცდება. თქვენი შვილის დაკვირვებები, მიბაძვა და მეხსიერებაში შენახული გამოცდილება მასში თანაგრძნობის საფუძვლებსაც აყალიბებს.') WHERE id = 'af02d5b9-9b5a-44a3-8a27-d35bbbd65550';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი შვილის კვებისას ერთ-ერთი მნიშვნელოვანი საკითხი, რომელსაც ყურადღება უნდა მიაქციოთ, საკვების მომზადების მეთოდია. ორთქლზე მომზადებისა და მოშუშვის მსგავსი მეთოდები საკვების სტრუქტურას არ აზიანებს, რის შედეგადაც მისი კვებითი ღირებულება არ იკარგება. ამიტომ ბავშვისთვის ბოსტნეულის სასარგებლოდ მომზადების საუკეთესო გზა მისი ორთქლზე მოხარშვაა. თევზი კი შეგიძლიათ ღუმელში, გრილზე ან ორთქლზე მოამზადოთ. როგორც ბოსტნეულის, ისე თევზის შეწვა საკმაოდ მავნებელია. შესაძლებლობის შემთხვევაში, შემწვარ საკვებზე სრულად უარის თქმა თქვენი შვილის მომავალ ჯანმრთელობაში შეტანილი საუკეთესო წვლილი იქნება.') WHERE id = 'b026868b-14a9-4e91-9d7c-64f2335b71be';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'დაახლოებით 36 თვის ასაკამდე თქვენს ბავშვს ღამით 11 საათი, ხოლო დღისით 1,5-2 საათი ძილი სჭირდება. ამ ასაკის ბავშვების უმეტესობა საღამოს 19.00-21.00 საათებს შორის იძინებს და დილით 06.30-08.00 საათებს შორის იღვიძებს. ეს საათები მიუთითებს, რომ მათი ძილის რეჟიმი უკვე უფროსებისას უახლოვდება. თქვენი შვილი თქვენზე უფრო ფხიზლად იძინებს და ეს მდგომარეობა შესაძლოა დაახლოებით 4 წლამდე გაგრძელდეს. თუ დილით თქვენზე ადრე იღვიძებს, სასარგებლო იქნება, ასწავლოთ მას ხელახლა ჩაძინება. ამ პერიოდში ბავშვის დაძინებისადმი წინააღმდეგობა საკმაოდ გავრცელებული მოვლენაა. საწოლში დაწოლის სურვილის არქონა შეიძლება სიბნელის ან წარმოსახვითი შიშების გამო იყოს. შიშის განცდა ბავშვის ნორმალური განვითარების ნაწილია, ამიტომ მას გაგებითა და თანაგრძნობით უნდა მოეკიდოთ.') WHERE id = 'd4569b71-1c50-4817-b555-f4e1a27ff451';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, '2-6 წლის ასაკი ის პერიოდია, როდესაც ბავშვებს საკმარისი და დაბალანსებული კვების შესახებ ცნობიერება უყალიბდებათ. თუმცა დღის განმავლობაში სოციალური აქტივობები და ბავშვის ზედმეტი მოძრავობა ამ პროცესს შეიძლება ართულებდეს. კიდევ ერთი სირთულე ამ ასაკის ბავშვებისთვის დამახასიათებელი სიჯიუტეა. თქვენი მთავარი მიზანი უნდა იყოს, სკოლაში შესვლამდე ბავშვს სწორი კვების ჩვევები ჩამოუყალიბოთ. ამ ასაკში ჩამოყალიბებული გემოვნური არჩევანი და ჩვევები ბავშვის მთელ მომავალ ცხოვრებაზე ახდენს გავლენას. მშობლების ყველაზე დიდი შეცდომაა ბავშვზე ზეწოლა იმის შიშით, რომ ის მშიერი დარჩება. პირიქით, ბავშვმა კვება არა ტანჯვად, არამედ სასიამოვნო საქმიანობად უნდა აღიქვას.') WHERE id = 'cca7e654-d2f4-435d-ac1b-7bc12c892a08';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი უკვე იმ ეტაპზეა, როცა სახლში ნებისმიერი ნივთი მისთვის შეიძლება სათამაშოდ იქცეს. ეს თქვენს პირად ნივთებსაც ეხება. ნივთები, რომლებსაც სათამაშოებად აღიქვამს, მან შეიძლება სახლის სხვადასხვა ადგილას გადაიტანოს, მიმოფანტოს ან ადგილები შეუცვალოს. მიუხედავად იმისა, რომ ამან სახლში შეიძლება დიდი არეულობა გამოიწვიოს, მისთვის ხელის შეშლის მცდელობა ჯანსაღი რეაქცია არ არის. ბავშვი სამყაროს თამაშით იკვლევს, ეცნობა და სწავლობს. მუდმივმა შეზღუდვამ შეიძლება სწავლის სურვილი დაუკარგოს. უმჯობესია, საზღვრები დააწესოთ: მაგალითად, სამზარეულოში შეგიძლიათ აუკრძალოთ ბასრი და მჩხვლეტავი ხელსაწყოებით თამაში, ხოლო ქვაბებით თამაშის უფლება მისცეთ. თამაშის დასრულების შემდეგ კი ნივთები ერთად დაალაგეთ და ამ გზით პასუხისმგებლობის გრძნობა ასწავლეთ.') WHERE id = '368b3b11-1e1f-4a83-bc4e-453fba29a7a6';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'მიუხედავად იმისა, რომ თქვენმა ბავშვმა ტუალეტის გამოყენება უკვე ისწავლა, ღამით შესაძლოა კვლავ ჩაისველოს. მედიცინაში ამას „ენურეზი“ ეწოდება. ჩვეულებრივ, ბავშვების უმეტესობა ტუალეტის გამოყენების სწავლებისა და შარდის ბუშტის განვითარების შედეგად, დაახლოებით 2 წლის ასაკში, შარდის შეკავებას როგორც დღისით, ისე ღამით ახერხებს. ღამით ჩასველების პრობლემა ხშირად შარდის ბუშტის განვითარების შეფერხებით არის გამოწვეული და ასაკის მატებასთან ერთად გაივლის. თუ ასეთ შემთხვევას შეამჩნევთ, პირველ რიგში მიმართეთ ექიმს, რათა გამოირიცხოს საშარდე გზების ინფექცია ან სხვა პრობლემა. თუ მიზეზი დაავადება არ არის, შეგიძლიათ რამდენიმე გარემოებას მიაქციოთ ყურადღება: დაძინებამდე 2 საათით ადრე შეუმცირეთ სითხის მიღება და მოარიდეთ კოფეინის შემცველ სასმელებს. რაც მთავარია, სისუფთავის შესანარჩუნებლად ბავშვს ღამით საფენს ნუ ჩააცვამთ — ეს ღამით გაღვიძების მოტივაციას შეუმცირებს.') WHERE id = '8d79c984-59c4-461b-b19e-f63da9c3b917';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ პერიოდში შეიძლება შეამჩნიოთ, რომ თქვენი ბავშვი სინამდვილესთან შეუსაბამო ამბებს გიყვებათ. თუმცა ეს, ამ სიტყვის პირდაპირი მნიშვნელობით, „ტყუილი“ არ არის. 5-7 წლამდე ბავშვებს წარმოსახვითი სამყაროსა და რეალობის ერთმანეთისგან სრულად გარჩევა უჭირთ. განსაკუთრებით 2.5-3 წლის ბავშვებმა ყურადღების მისაქცევად შეიძლება სხვადასხვა ამბავი მოიგონონ. მაგალითად, თუ ბავშვი ამბობს, რომ მისი სათამაშო დათუნია გაიქცა და დაიმალა, ეს ტყუილი კი არა, ფანტაზიის ნაყოფია. თქვენს ბავშვს ძალიან მდიდარი წარმოსახვა აქვს, ამიტომ ასეთი ქცევა „ტყუილის თქმად“ არ უნდა შეაფასოთ და ბავშვი არ უნდა დაადანაშაულოთ. ეს ქცევა თანდათან შემცირდება და, ჩვეულებრივ, 7 წლის ასაკამდე სრულიად გაქრება.') WHERE id = '312018ab-f646-4975-9148-a5d080d99b50';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენ კვლავაც ყველაზე დიდი მაგალითი ხართ თქვენი ბავშვისთვის. ეს ნიშნავს, რომ მას მოუნდება ყველაფრის გასინჯვა, რასაც თქვენ ჭამთ ან სვამთ. ჩაი, ყავა და გაზიანი სასმელები ბავშვებში დიდ ინტერესს იწვევს. მშობლები ზოგჯერ ბავშვის დაჟინებულ თხოვნას ვერ უძლებენ და ამ მავნე სასმელების ცოტაოდენი რაოდენობით გასინჯვის უფლებას აძლევენ. თუმცა ისეთი ნივთიერებები, როგორებიცაა ჩაიში შემავალი თეინი და ყავაში არსებული კოფეინი, მასტიმულირებელი მოქმედებით ხასიათდება და შეიძლება დამოკიდებულება გამოიწვიოს. ამასთანავე, ჩაი და მსგავსი სასმელები ორგანიზმში რკინის ათვისებას ამცირებს. გაზიანი და ფერადი სასმელები კი ბავშვებში გაღიზიანებას იწვევს და ჯანმრთელობისთვის საზიანოა. უმჯობესია, ბავშვმა ასეთი სასმელების გემო საერთოდ არ იცოდეს.') WHERE id = 'd3f39e2d-95d5-4448-a3ee-5735bd480f16';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'რაც უნდა ეცადოთ მის დაცვას, თქვენი ბავშვი დროდადრო მაინც შეიძლება ავად გახდეს. დაავადებების სიმძიმის შესამცირებლად მნიშვნელოვანია მისი იმუნური სისტემის გაძლიერება. ამის ყველაზე ბუნებრივი გზაა ბავშვის „კარგ“ ბაქტერიებთან კონტაქტი. ბუნებაში, მიწასთან თამაშისას, ბავშვების იმუნიტეტი უფრო ძლიერად ვითარდება. თანამედროვე ცხოვრებაში ქუჩაში თამაში შემცირდა, ამიტომ ეცადეთ, ბავშვთან ერთად ბუნებაში მეტი დრო გაატაროთ. ასევე, ავად გახდომის შიშით ნუ მოარიდებთ მას სხვა ბავშვებს. კვლევები აჩვენებს, რომ იმ ბავშვების იმუნური სისტემა, რომლებიც ხშირად ურთიერთობენ თანატოლებთან და სათამაშო ჯგუფებში მონაწილეობენ, უფრო მდგრადია.') WHERE id = 'f9d7a8b1-31bd-4aa3-ada9-e3738e8a0231';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ პერიოდში თქვენი ბავშვი იწყებს იმის გაცნობიერებას, რომ საკვებს მხოლოდ დანაყრების ფუნქცია არ აქვს და მას სხვა დანიშნულებაც შეიძლება ჰქონდეს. მაგალითად, ის ამ პერიოდში ეცნობა საკვების ქრთამის, ჯილდოს ან საჩუქრის სახით შეთავაზებას და ასევე საკვებზე უარის თქმის ძალას. შეიძლება შეამჩნიოთ, რომ ჭამის დროს თქვენი ბავშვი უფრო მცირე ულუფებით დანაყრებას გეუბნებათ. ამის ერთ-ერთი მიზეზი ისაა, რომ ჩვილობის პერიოდთან შედარებით ზრდის ტემპი მნიშვნელოვნად შენელდა და შესაბამისად კალორიების საჭიროებაც შემცირდა. მთავარია, უზრუნველყოთ, რომ ბავშვმა საჭირო კალორიები ჯანსაღი საკვებიდან მიიღოს. თუ ბავშვი ვახშმამდე კუჭს ხილის წვენითა და კრეკერებით გაივსებს, ნუ მოელით, რომ ვახშამზე ბოსტნეულის კერძს მადიანად შეჭამს. დასაწყისისთვის შეგიძლიათ წასახემსებელი ულუფები შეამციროთ და უპირატესობა ნაკლებად ტკბილ პროდუქტებს მიანიჭოთ. ძირითად კვებაზე კი, თუ საკვებს თანმიმდევრულად შესთავაზებთ — ჯერ ბოსტნეულს, შემდეგ ცილოვან პროდუქტებს და ბოლოს ნახშირწყლების ჯგუფს — დაინახავთ, რომ ყველაზე მეტად მოშივებულ ბავშვს ბოსტნეულის ჭამის მეტი სურვილი ექნება.') WHERE id = '644f27a1-772e-4290-a4c7-b64545b7ca56';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, '2,5 წლის ასაკში თქვენი ბავშვის განვითარების თავისებურებებს შორისაა ფერების ცნობა, სიტყვების სწორად გამოყენება და თვლის დაწყება. ამ უნარების განვითარება შეიძლება იმის მიხედვით განსხვავდებოდეს, თუ როგორ ეხმარებით და მიმართულებას აძლევთ მას, როგორც მშობელი. ამ პერიოდში თქვენს შვილს დამოუკიდებლობის განცდასთან ერთად უყალიბდება გარემოს გაკონტროლების სურვილიც. 2,5 წლის ასაკი ბავშვის განვითარების ერთ-ერთ ყველაზე რთულ კრიზისულ პერიოდად მიიჩნევა. ამ ეტაპზე, რომელსაც სიჯიუტის პერიოდსაც უწოდებენ, ბავშვმა შეიძლება ხშირად გამოავლინოს ნეგატიური, მეამბოხე და მერყევი ქცევა. გარემოზე საკუთარი გავლენის დამყარების სურვილი ეჯახება გარშემომყოფებისა და მშობლების მიერ დაწესებულ შეზღუდვებს. ამ პერიოდში ბავშვის გაღიზიანებული და დაუფიქრებელი ქცევა სრულიად ბუნებრივია და განვითარების ნორმალურ ნაწილს წარმოადგენს. ამიტომ, ემოციური და სოციალური განვითარების ხელშესაწყობად კარგი იქნება, თუ ამ პერიოდში ბავშვს უფრო ხშირად ჩართავთ სოციალურ გარემოში.') WHERE id = 'fd9715f6-ed39-43d1-a0a5-6696d68a16b2';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ პერიოდში შეიძლება შეამჩნიოთ, რომ თქვენს შვილს ძალიან მოსწონს ხატვა და თავის ნახატებს სახელებს არქმევს. რადგან ბავშვმა უკვე კარგად იცის საკუთარი სახელი, შესაძლოა, სხვებისთვის მისი თქმაც დაიწყოს. გონებრივი განვითარების დაჩქარებასთან ერთად ის კიდევ უფრო სრულყოფს უკვე ათვისებულ ძირითად ცნებებს. მაგალითად, შეიძლება შეამჩნიოთ, რომ უფრო მეტი ფერი იცის, რამდენიმე სიმღერა ისწავლა და მღერის, ასევე დაიწყო რიცხვების ჩამოთვლა, თუნდაც ჯერ შეცდომებით. ამ პერიოდში თქვენს შვილს 200-ზე მეტი განსხვავებული სიტყვის გამოყენება შეუძლია. ამასთანავე, მას შეუძლია მკაფიოდ თქვას პირის ნაცვალსახელები, როგორიცაა „მე, ჩემი, ჩემთვის“. თუმცა არ უნდა შეგაშფოთოთ, თუ ენობრივი უნარების ეს მნიშვნელოვანი ცვლილებები ჯერ არ ვლინდება დროის ფორმების გამოყენებაში. ბავშვს ჯერ კიდევ სჭირდება დრო, რომ გაიაზროს და გამოიყენოს ისეთი დროითი ფორმები, როგორიცაა „მოვიდა, მოდის, მოვა“.') WHERE id = '0ce06f10-94aa-437c-be3f-bceab8e03d9c';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ პერიოდში თქვენს ბავშვს სხვადასხვა საგნისა და მოვლენის მიმართ შეიძლება გარკვეული ჩვევები ან განმეორებადი ინტერესები ჩამოუყალიბდეს. ერთი და იმავე მულტფილმის მრავალჯერ ყურება, ერთი და იმავე ზღაპრის მოსმენა, საყვარელი სათამაშოს ან საბნის ყველგან თან ტარება 2-5 წლის ბავშვებში ხშირად გვხვდება. ამ ასაკში განმეორებადი ქცევები და ჩვევები განვითარების ნორმალური პროცესის ნაწილია. მაგალითად, ბავშვს შეიძლება ყოველთვის ერთი და იმავე ჭიქიდან სურდეს წყლის დალევა, რადგან მასზე საყვარელი მულტფილმის პერსონაჟია გამოსახული ან ის მის საყვარელ ფერშია. ასეთი ქცევის გამეორებისას მშობლები ზოგჯერ ღელავენ, თუმცა განვითარების ამ ეტაპისთვის დამახასიათებელი ქცევები, როგორც წესი, 5 წლის შემდეგ თანდათან მცირდება.') WHERE id = '2a252a94-6183-4f26-b967-1e55f04f7793';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ პერიოდში, როდესაც უმადობა და საკვების არჩევითობა პიკს აღწევს, ზოგიერთი მშობელი შეიძლება ბავშვის ჭარბი წონის გამო შეშფოთდეს. თუ ბავშვის წონა მართლაც კრიტიკულ ზღვარზე არ არის, სპეციალისტები ამ ასაკში წონის დასაკლებად მკაცრ დიეტებსა და პროგრამებს არ გირჩევენ. ზედმეტად შემზღუდველმა დიეტამ, სათანადო მეთვალყურეობის გარეშე, შეიძლება შეაფერხოს მოზარდი ბავშვის განვითარება და ჯანმრთელობის სხვა პრობლემები გამოიწვიოს. ჭარბი წონის მქონე ბავშვებისთვის სპეციალისტები, როგორც წესი, კვებითი ჩვევების გაუმჯობესებასა და ფიზიკური აქტივობის გაზრდას გვირჩევენ. მიზანია ცხიმოვანი ქსოვილის შემცირება ისე, რომ სიმაღლეში ზრდა, ძვლებისა და კუნთების განვითარება გაგრძელდეს. ეს პროცესი აუცილებლად სპეციალისტის მეთვალყურეობით უნდა წარიმართოს. მშობლებმა არ უნდა დაუშვან შეცდომა და საკუთარი დიეტა ბავშვს არ უნდა მოარგონ. მიზნები ბავშვის ასაკისა და განვითარების შესაბამისად ექიმმა უნდა განსაზღვროს.') WHERE id = '12d89f35-8555-4479-a974-3feb5d64d6dc';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თამაში თითოეული ბავშვის განვითარებისთვის მნიშვნელოვანი საშუალებაა. თამაშებსა და სათამაშოებს დიდი მნიშვნელობა აქვს თქვენი ბავშვის როგორც ფიზიკური, ისე გონებრივი განვითარებისთვის, რადგან მას დაგროვილი ენერგიის დახარჯვა სჭირდება. სახლობანა, რომელიც გოგონებსაც და ბიჭებსაც ერთნაირად უყვართ, ამ ასაკში სახლში გასართობად ერთ-ერთი ყველაზე სასარგებლო აქტივობაა. სახლობანას თამაშისას სხვადასხვა როლის მორგება და ამ როლის შესაბამისად მოქცევა ხელს უწყობს ბავშვის ინტელექტუალურ განვითარებას და ემოციურ განტვირთვაში ეხმარება. ეს თამაში ბავშვს საკუთარი თავის უკეთ შეცნობასა და სამომავლო, ზრდასრული როლებისთვის მომზადებაში ეხმარება. თამაშისას ბავშვი იყენებს როგორც ყოველდღიურ ცხოვრებაში მიღებულ გამოცდილებას, ისე თამაშში გადააქვს თავისი წარმოსახვა და ემოციები. ამგვარად, ის სწავლობს საკუთარი თავის სხვის ადგილას წარმოდგენას, პასუხისმგებლობის აღებას, გრძნობების გამოხატვას და ოჯახთან დაკავშირებული წუხილის გაზიარებით ემოციურ განტვირთვას. როლების შესრულებისას ვითარდება თვითგამოხატვისა და გამართულად მეტყველების უნარი, ხოლო ლექსიკური მარაგი იზრდება. ამიტომ სახლობანას თამაში ერთ-ერთი საუკეთესო აქტივობაა, რომელიც შეგიძლიათ ბავშვთან ერთად შეასრულოთ.') WHERE id = '7052912b-8ae5-42fd-9ebb-4b3f1ca4c1a8';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ ამჩნევთ, რომ თქვენი ბავშვი გარშემო მყოფ სხვა ბავშვებს ურტყამს, კბენს ან სათამაშოებს ამტვრევს, ამ საკითხში მტკიცე პოზიცია უნდა დაიკავოთ. მნიშვნელოვანია, მკაფიოდ უთხრათ: „საკუთარი თავისა და სხვებისთვის ზიანის მიყენება დაუშვებელია!“ და ეს წესი თანმიმდევრულად დაიცვათ. სხვა საკითხებში ბავშვს თავისუფლებასაც რომ აძლევდეთ, ძალადობრივ ქცევასთან დაკავშირებით შეზღუდვების დაწესებას ნუ მოერიდებით. მხოლოდ ასე გაიგებს ბავშვი, რომ საჭიროა სხვების პატივისცემა, რომ არსებობს სოციალური წესები და მათი დაცვა მნიშვნელოვანია. ყველაზე მთავარი კი ეს არის: როგორი არასწორიც უნდა იყოს ბავშვის საქციელი, ამის გამო ის არასდროს უნდა დასაჯოთ. მაგალითად, არასწორი მიდგომაა, თქვენც უკბინოთ, რათა აჩვენოთ, რამდენად გტკივათ, როცა ის გკბენთ. პირიქით, ამან შეიძლება ბავშვის ქცევა კიდევ უფრო გააუარესოს. უმჯობესია, სიტყვიერად აუხსნათ, რომ დარტყმა ან კბენა ძალიან მტკივნეულია და მისცეთ შესაძლებლობა, თავად გააცნობიეროს თავისი შეცდომა.') WHERE id = '1d14becf-2063-41bf-9be0-72a1734a9d5c';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ თქვენს ბავშვს თევზი არ უყვარს, ამის მთავარი მიზეზი, სხვა ბავშვების მსგავსად, ხშირად მისი სუნია. ბავშვები საკვების გემოს აღქმისას გემოს, სუნსა და გარეგნობას ერთობლივად აფასებენ. ამასთანავე, თევზის ჭამის შემდეგ წარმოქმნილმა ზოგიერთმა დისკომფორტმაც შეიძლება ბავშვს მასზე უარი ათქმევინოს. მიუხედავად იმისა, რომ თევზზე ალერგია საშუალოდ ყოველი 200 ადამიანიდან ერთს აღენიშნება, ბავშვებში ეს მაჩვენებელი საკმაოდ მაღალია. თევზზე ალერგიის ნიშნებია გულისრევა, ღებინება, დიარეა, კუჭის სპაზმები, მსტვენავი სუნთქვა, ცხვირიდან გამონადენი, კანის გაწითლება და შეშუპება. ალერგიის გამომწვევ ზღვის პროდუქტებს მიეკუთვნება სკუმბრია, თინუსი, ლობსტერი, სარდინი, კრევეტი, კიბორჩხალა, ლოკოკინა და მიდია. გარდა ამისა, თევზის მომზადებისას ცილის წვრილი ნაწილაკები ორთქლთან ერთად ჰაერში ხვდება, ამიტომ ასეთმა ორთქლმაც კი შეიძლება ალერგიის მქონე ბავშვებში რეაქცია გამოიწვიოს.') WHERE id = 'ac158c46-bbd5-4329-8d4c-0e71f3f20b42';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ცეკვა თქვენი ბავშვის განვითარების ამჟამინდელი ეტაპისთვის შესანიშნავი აქტივობაა. ცეკვა არა მხოლოდ სპორტი, არამედ ხელოვნებაცაა. ის ბავშვს ჰარმონიის, რიტმისა და წონასწორობის შეგრძნებას უვითარებს. ამასთანავე, ცეკვა თქვენს ბავშვს ემოციების გამოხატვას ასწავლის, დაძაბულობის მოხსნაში ეხმარება და სტრესთან გამკლავების უნარს აძლიერებს. ცეკვის ერთ-ერთი უმნიშვნელოვანესი სარგებელი ფიზიკურ განვითარებაზე მისი დადებითი გავლენაა. მოცეკვავე ბავშვის სხეული უფრო მოქნილი, ძლიერი და გრაციოზული გახდება. რადგან საცეკვაო მოძრაობები კუნთების გაჭიმვით სრულდება, ისინი ხელს უწყობს ძვალ-კუნთოვანი სისტემისა და სხეულის კონტურების უფრო სწორად და დახვეწილად ჩამოყალიბებას. ცეკვას დიდი როლი აქვს მომავალში შესაძლო არასწორი ტანადობის პრევენციაში. ის ასევე ძალიან სასარგებლოა ბრტყელტერფიანობის, სიარულისას ტერფების შიგნით შეტრიალებისა და ხერხემლის გამრუდების თავიდან ასაცილებლად. ყოველივე ამის გათვალისწინებით, შეგიძლიათ დღის განმავლობაში შესაფერისი მუსიკის თანხლებით ბავშვს ცეკვისკენ უბიძგოთ.') WHERE id = '068ebdad-194f-4a1d-9270-77ef045bd6c5';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'განვითარების ამჟამინდელ ეტაპზე თქვენს ბავშვს შესაძლოა ჯანსაღი საკვების მიმართ ნაკლები მადა ჰქონდეს, ხოლო ტკბილეული და მზა შეფუთული პროდუქტები განსაკუთრებით იზიდავდეს. თითქმის ყველა ბავშვს ძალიან უყვარს ასეთი საკვები და თუ შეზღუდვებს არ დაუწესებთ, შესაძლოა ის ჭარბად მიირთვას. გახსოვდეთ, რომ სკოლამდელი ასაკის ბავშვებში საკვების მიმართ ჭირვეულობა ძალიან გავრცელებული და ბუნებრივი მოვლენაა. ამ მხრივ მარტო არ ხართ — უამრავი მშობელი იზიარებს თქვენს განცდებს. ამიტომ ამ პერიოდში ბავშვის ჯანსაღი და დაბალანსებული კვება თქვენგან გარკვეულ მოთმინებასა და ძალისხმევას მოითხოვს. თუ ამ ასაკში ბავშვის კვებით ჭირვეულობას ყოველთვის დაჰყვებით, ის ამ პრობლემის დაძლევას ვერ შეძლებს და ზრდასრულ ასაკში კვებასთან დაკავშირებულ სირთულეებს საფუძველი ჩაეყრება. ამ პერიოდში მას რაც შეიძლება მრავალფეროვანი საკვები უნდა შესთავაზოთ და ახალი გემოებისთვის გასინჯვისკენ წაახალისოთ.') WHERE id = '57a840ed-dc9e-4918-86ea-a8434bde9387';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'რეგულარული მოძრაობა ძალიან მნიშვნელოვანია არა მხოლოდ ზრდასრულებისთვის, არამედ ბავშვებისთვისაც. კვლევები აჩვენებს, რომ დღის განმავლობაში აქტიური და სპორტით დაკავებული ბავშვების ავად გახდომის რისკი 57%-ით მცირდება. ამასთანავე, რეგულარულად მოძრავ ბავშვებს ზედა სასუნთქი გზების ინფექციები ნაკლებად ემართებათ, გაციების შემთხვევაში კი უფრო სწრაფად გამოჯანმრთელდებიან. ამიტომ დიდი მნიშვნელობა აქვს აქტივობებს, რომელთა შესრულებაც თქვენს ბავშვთან ერთად შეგიძლიათ. ფიზიკური აქტივობა ასევე აუმჯობესებს თქვენი ბავშვის ძილის ხარისხს. მაგალითად, სეზონის მიუხედავად, ამინდის შესაბამისად ჩაცმულ ბავშვს პარკში თამაში შეუძლია — ეს ერთდროულად სახალისო და სასარგებლო ფიზიკური აქტივობაა. ოჯახური სეირნობა, დაჭერობანა, ფრენბურთი, ფეხბურთი და ცურვა თქვენი ბავშვისთვის ძალიან სასარგებლოა.') WHERE id = 'b3c41e3b-28a4-4d9f-a7f2-3d2269ca1f16';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, '2-3 წლის ბავშვების კვების გეგმის შედგენისას სპეციალისტები ამერიკის დიეტოლოგთა ასოციაციის კვების პირამიდას იყენებენ. ამ პირამიდის მიხედვით, ბავშვმა საკვები 5 ძირითადი ჯგუფიდან უნდა მიიღოს. 1-ლი ჯგუფი: მარცვლეული და პური; მე-2 ჯგუფი: ბოსტნეული და ხილი; მე-3 ჯგუფი: რძე და იოგურტი; მე-4 ჯგუფი: ხორცი, კვერცხი და პარკოსნები; მე-5 ჯგუფი კი შაქარი და ცხიმებია. თქვენი ბავშვის დღიური ნორმა ასეთი უნდა იყოს: 1-ლი ჯგუფიდან 6 პორცია (ნახევარი ნაჭერი პური, ერთი პატარა ჯამი ფლავი ან მაკარონი); მე-2 ჯგუფიდან 5 პორცია (ბოსტნეულის წვენი, ახალი ხილი); მე-3 ჯგუფიდან 3 პორცია (ნახევარი ჯამი იოგურტი ან რძე, ასანთის კოლოფის ზომის ყველი); მე-4 ჯგუფიდან 2 პორცია (1 სუფრის კოვზი ქათამი, თევზი ან ხორცი, 1 ცალი კვერცხი); მე-5 ჯგუფიდან კი 3-4 პორცია (დღის განმავლობაში 1 ჩაის კოვზი მცენარეული ზეთი ან კარაქი).') WHERE id = '962b4a12-0b09-4183-b941-3cfed8499be2';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, '„რა თავაზიანი შვილი გყავთ!“ — ამ სიტყვების მოსმენა ყველა მშობლისთვის სასიამოვნოა. პატივისცემის მქონე ბავშვის აღზრდა მოთმინებას, პირადი მაგალითის მიცემასა და შექებას მოითხოვს. თუ გსურთ, რომ თქვენი შვილი სხვებს პატივისცემით მოეპყროს, უპირველესად თავად უნდა მისცეთ ამის მაგალითი. ბავშვი თავაზიანობას ჩვილობიდანვე გარშემომყოფებისგან სწავლობს. მაგალითად, თუ ბავშვი ხელიდან რაიმეს გამოგგლეჯთ, უთხარით „გთხოვ“, ხოლო თუ თმას გქაჩავთ, უთხარით „მტკივა“ და ხელი ფრთხილად გააშვებინეთ — ამით მას კეთილგანწყობას ასწავლით. ბავშვმა უნდა იგრძნოს, რომ მას პატივს სცემენ. ამის საუკეთესო მაგალითებია მისი მოსმენა სიტყვის შეწყვეტის გარეშე და თვალებში ყურებით, მის ოთახში კარზე დაკაკუნების შემდეგ შესვლა და გადაწყვეტილებების მიღებისას მისი აზრის კითხვაც. იყავით თანმიმდევრული თქვენს ქცევაში; ერთსა და იმავე მოვლენაზე ხან მკაცრმა და ხან რბილმა რეაქციამ შესაძლოა შეარყიოს თქვენი შვილის ნდობა და პატივისცემა თქვენ მიმართ.') WHERE id = 'faf2efdc-0dd3-4966-8ab3-9c85e83a2de6';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ პერიოდში შეიძლება შეამჩნიოთ, რომ თქვენს ბავშვს ხშირად ესიზმრება კოშმარები და ზოგჯერ ყვირილითაც კი იღვიძებს. ასეთ შემთხვევაში დაუყოვნებლივ მიდით მასთან, დაამშვიდეთ და მის შიშებზე ესაუბრეთ. თუ მსგავსი შემთხვევები ძალიან ხშირად არ მეორდება, სერიოზული შეშფოთების საფუძველი არ არსებობს. თუმცა, თუ ეს რეგულარულად გაგრძელდება, უნდა გამოიკვლიოთ დღის განმავლობაში ამის გამომწვევი შესაძლო ფაქტორები (მაგალითად, ძალადობრივი შემთხვევის თვითმხილველობა, დაცემით გამოწვეული ტრავმა ან ტელევიზორში ნანახი საშიში პერსონაჟები) და საჭიროების შემთხვევაში სპეციალისტს მიმართოთ. ყურადღებით დაკვირვება, თუ ვისთან ურთიერთობს თქვენი შვილი დღის განმავლობაში და რას უყურებს, პრობლემის გადაჭრაში დაგეხმარებათ. მიზეზის აღმოჩენის შემდეგ დაინახავთ, რომ კოშმარები თანდათან გაქრება.') WHERE id = 'b61f296a-4531-4652-8575-c61cd39dfd62';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენს ბავშვთან ერთად უკვე 2.5 წელი განვლეთ, გილოცავთ! თუმცა, 2.5 წლის ასაკი შესაძლოა ახალი ეტაპის — „3 წლის ასაკის სინდრომის“ დასაწყისიც გახდეს. ახლა მას უკვე ყველაფერზე საკუთარი აზრი აქვს და სურს, თავი გამოიჩინოს და შექება დაიმსახუროს. ეს განვითარების ბუნებრივი ეტაპია, ამიტომ მას სიჯიუტეში ნუ აჰყვებით. ამის გამარჯვებისთვის ბრძოლად აღქმა აზრს მოკლებულია. რთულ მომენტებში შეეცადეთ, ბავშვს ყურადღება სხვა რამეზე გადაატანინოთ და მოთმინებით დაელოდეთ, სანამ გაბრაზება გადაუვლის. მოერიდეთ მკაცრ დასჯას, რადგან ამ ასაკში ემოციები ძალიან ცვალებადია — ბავშვმა შეიძლება ერთ წამს იტიროს, მეორე წამს კი გაჩუმდეს. მის დასამშვიდებლად ყურადღების სხვა საინტერესო საქმიანობაზე გადატანა ახლა უფრო ადვილია, ვიდრე ადრე.') WHERE id = '639bc96b-c7fc-4373-a80d-f5910cdd0c67';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'მიუხედავად იმისა, რომ ამ პერიოდში თქვენი შვილის განვითარების თავისებურებები და ცვლილებები შეიძლება სხვა ბავშვებისგან განსხვავდებოდეს, ზოგადად ისინი პროგნოზირებად გზას მიჰყვება. მნიშვნელოვანია, რომ თქვენ, როგორც ზრდასრულმა, იცოდეთ ამ ცვლილებების შესახებ — ეს თქვენს შფოთვასაც შეამცირებს და ბავშვის მხარდაჭერაშიც დაგეხმარებათ. 2.5 წლის ასაკში ბავშვს შესაძლოა მკვეთრად გამოუვლინდეს უცხო ადამიანების შიში და მიტოვების შიში. იმის შიშით, რომ თქვენ მიატოვებთ, მას შეიძლება გვერდიდან მოშორება არ უნდოდეს, თუმცა ამავე დროს თანატოლებთან დროის გატარებაც სურდეს. რადგან ახლა უკვე აცნობიერებს, რომელი თანატოლები უყვარს და ვისთან სურს სიახლოვე. თუმცა, ასეთ მერყეობაში ყოფნისას შეიძლება უჩვეულოდ ჯიუტად მოიქცეს. ასეთ შემთხვევებში ძალიან მნიშვნელოვანია, შეძლებისდაგვარად სიმშვიდე შეინარჩუნოთ, გახსოვდეთ, რომ ეს პერიოდი დროებითია და ბავშვს აგრძნობინოთ, რომ ყოველთვის მის გვერდით ხართ.') WHERE id = '68cb6aa4-e74d-46fc-9a61-c95e7e0181e6';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის ორგანიზმის ზრდასრულის ორგანიზმისგან განმასხვავებელი მთავარი თავისებურება ისაა, რომ ის მუდმივად იზრდება და ვითარდება. თუმცა, ეს განვითარება ყველა ბავშვში სხვადასხვაგვარად მიმდინარეობს. მაგალითად, 1-2 წლის ასაკში ზრდის ტემპი რამდენადმე ნელდება, ხოლო 2-10 წლის ასაკში სტაბილურად გრძელდება. მოზარდობის პერიოდში კი კვლავ იწყება სწრაფი ზრდის ნახტომი. მოკლედ რომ ვთქვათ, თქვენი შვილის ამჟამინდელ ასაკში სიმაღლეში ზრდისა და წონის მატების ტემპი შედარებით სტაბილურდება. გარემოსა და გენეტიკური ფაქტორების გათვალისწინებით, ამ ასაკის ბავშვების წონისა და სიმაღლის მაჩვენებლები შეიძლება ერთმანეთისგან მნიშვნელოვნად განსხვავდებოდეს. მაგალითად, 2.5 წლის ბავშვის წონა შეიძლება იყოს როგორც 9.900 გრამი, ისე 16.500 გრამი. თქვენი შვილისთვის მთავარია, რომ მისი წონა ამ ნორმების ფარგლებში, ე.წ. უსაფრთხო დიაპაზონში იყოს.') WHERE id = '02cec2db-f46a-42b8-bf27-568e1890c0f7';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'შესაძლოა, ამ თვეში თქვენს ბავშვს A ჰეპატიტის საწინააღმდეგო ვაქცინის განმეორებითი დოზის მიღება დასჭირდეს. A ჰეპატიტი არის ღვიძლის ინფექცია, რომელსაც ამავე სახელწოდების ვირუსით დაინფიცირება იწვევს. მიუხედავად იმისა, რომ დაავადების გავრცელება სოციალურ-ეკონომიკური მდგომარეობისა და საცხოვრებელი რეგიონის მიხედვით განსხვავდება, ის მთელ მსოფლიოში ფართოდ არის გავრცელებული. დაავადება უფრო ხშირად გვხვდება შემოდგომასა და ზამთრის პირველ თვეებში. A ჰეპატიტის საწინააღმდეგო ვაქცინაცია ამ დაავადების პრევენციის ყველაზე ეფექტური გზაა. სამედიცინო კვლევები აჩვენებს, რომ მასობრივი ვაქცინაციის წყალობით ინფიცირების ყოველწლიური შემთხვევების რაოდენობა მკვეთრად შემცირდა. ამ მხრივ ვაქცინა ძალიან მნიშვნელოვან დამცავ როლს ასრულებს, რათა თქვენი შვილი A ჰეპატიტით არ დაავადდეს.') WHERE id = 'df299f90-e498-4bad-8aac-c9ce133896e2';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი შვილის კვების მთავარი მიზანი ორგანიზმისთვის საჭირო ვიტამინების, მინერალების, ცილების, ნახშირწყლებისა და ცხიმების მოთხოვნილების დაკმაყოფილება უნდა იყოს. 2-6 წლის ასაკი ის ეტაპია, როდესაც ბავშვს სრულფასოვანი და დაბალანსებული კვების შესახებ წარმოდგენა უყალიბდება. თუმცა, სოციალურმა აქტივობებმა და ბავშვის ზედმეტმა მოძრავობამ შესაძლოა კვების პროცესი ოდნავ გაართულოს. ამ ასაკში ბავშვის სიჯიუტეც ერთ-ერთი სირთულეა, რომელსაც შეიძლება შეხვდეთ. მნიშვნელოვანია, რომ ბავშვს სკოლაში შესვლამდე ჩამოუყალიბდეს სწორი კვების ჩვევები. ამ ასაკში ჩამოყალიბებული გემოვნური არჩევანი და ჩვევები მის მთელ შემდგომ ცხოვრებაზე მოახდენს გავლენას. მოგვიანებით ამ ჩვევების შეცვლა ძალიან რთულია. გახსოვდეთ, რომ ზრდასრულ ასაკში წონასა და ჯანმრთელობასთან დაკავშირებული პრობლემების მქონე მრავალი ადამიანის პრობლემების სათავე ბავშვობაში ჩამოყალიბებული არასწორი კვების ჩვევებია.') WHERE id = 'fe0a2002-9184-44fe-a34f-37af62aa35fd';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი ამჟამად იმ პერიოდშია, როდესაც ზრდისა და განვითარების ტემპი შედარებით ნელდება. ამიტომ ზოგ დღეებში შეიძლება ნაკლები ჭამოს, ზოგ დღეებში კი — მეტი. ძალიან მნიშვნელოვანია, არ აიძულოთ, რომ ყოველდღე აუცილებლად განსაზღვრული რაოდენობის საკვები მიიღოს. როგორც ყოველთვის, ამ ასაკშიც პატივი უნდა სცეთ ბავშვის მადას. განსაზღვრულ დროს კვება და არაჯანსაღი საკვებისადმი ინტერესის არწახალისება მნიშვნელოვანია, რათა ბავშვს კარგი ჩვევები ჩამოუყალიბდეს. ჯანსაღი კვების ჩვევების ჩამოყალიბებისთვის უმთავრესია, თქვენ, როგორც მშობელმა, თანმიმდევრულად იმოქმედოთ და კარგი მაგალითი მისცეთ. მოკლედ რომ ვთქვათ, თუ თავად შოკოლადს მიირთმევთ, ბავშვს კი საუზმეზე კვერცხის ჭამას აიძულებთ, ამას არავითარი სარგებელი არ ექნება. ამასთანავე, ჭამის მუდმივი დაძალება და საკვების ჯილდოდ ან სასჯელად გამოყენება მომავალში ბავშვის კვებით ქცევაზე უარყოფითად იმოქმედებს.') WHERE id = '0ff6de72-1685-4d41-9fb9-6bad83bfb59a';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'შემოქმედებითობა საკუთარი თავის გამოხატვის ყველაზე თავისუფალი ფორმაა. თქვენი ბავშვისთვისაც არაფერია იმაზე სასიამოვნო, ვიდრე საკუთარი თავის თავისუფლად და ღიად გამოხატვა. ალბათ შეგიმჩნევიათ, რომ დაბადების მომენტიდან თქვენი შვილი მუდმივად აკვირდება გარემოს, უსმენს და სხვადასხვა რამეს ცდის. ამ პერიოდში კი ყოველი ახალი გამოცდილება და აღმოჩენა მას კიდევ უფრო აღაფრთოვანებს. სწორი მიდგომით ამ თანდაყოლილი უნარის მხარდაჭერა გადამწყვეტ როლს შეასრულებს იმაში, რომ თქვენმა შვილმა მთელი ცხოვრების განმავლობაში შემოქმედებითად იაზროვნოს. ამისთვის მის ყველა მცდელობას მხარი უნდა დაუჭიროთ. სრულყოფილი შედეგის მიღწევას შესაძლოა დრო დასჭირდეს, თუმცა მთავარია, დააფასოთ მისი ძალისხმევა და შეაქოთ. ეს ბავშვს თავდაჯერებას გაუძლიერებს და საკუთარი ნიჭის გამოვლენაში დაეხმარება.') WHERE id = '4508e3d7-7e76-4f2d-8b22-fd23d4a47309';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'კვლევები აჩვენებს, რომ თითოეულ ბავშვს სწავლის მისთვის დამახასიათებელი მეთოდი და პოტენციალი აქვს. ზრდასთან ერთად, თქვენი მხარდაჭერით, ბავშვს ახალი ინფორმაციის უფრო სწრაფად ათვისება შეუძლია. თუმცა ყველაზე მნიშვნელოვანია, ბავშვს სწავლის სურვილი და ინტერესი გაუღვივოთ. მაგალითად, შეგიძლიათ მისცეთ საშუალება, თქვენ მიერ შეთავაზებული ვარიანტებიდან არჩევანი თავად გააკეთოს. უნდა შეაქოთ არა მიღწეული შედეგებისთვის, არამედ გაწეული ძალისხმევისთვის. ერთ-ერთი ყველაზე მნიშვნელოვანი საკითხია, მის შეკითხვებს მოუბეზრებლად უპასუხოთ და არ უთხრათ, რომ ამისთვის ჯერ პატარაა. ამ პროცესში ბავშვს უნდა მისცეთ საშუალება, დაეცეს, ტანსაცმელი დაისვაროს ან სათამაშოები დაშალოს და ხელახლა ააწყოს. მის ქცევაზე მაშინ უნდა ისაუბროთ, როდესაც ორივე მშვიდად ხართ. და რაც მთავარია, ბავშვი არასდროს შეადაროთ თანატოლებს.') WHERE id = 'cb11e36c-39a0-4aef-be34-9d54b22af192';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ ბევრი დედის მსგავსად თქვენც ბავშვის უმადობას უჩივით, ნუ ღელავთ, მარტო არ ხართ! :) ბევრ მშობელს ჰგონია, რომ ბავშვს მადა არ აქვს, თუმცა სინამდვილეში მათი მოლოდინი რეალობას არ შეესაბამება და ბავშვისგან იმაზე მეტის ჭამას მოითხოვენ, ვიდრე მას შეუძლია. მაგრამ თუ ნამდვილად ფიქრობთ, რომ ბავშვს მადა არ აქვს, რამდენიმე მნიშვნელოვან ნიუანსს უნდა მიაქციოთ ყურადღება. გახსოვდეთ, რომ ბავშვებისთვის საკვების გარეგნული სახე ხშირად მის გემოზე უფრო მნიშვნელოვანია. ბავშვის მადაზე საკვების სუნიც მოქმედებს. მან შესაძლოა უარი თქვას ერთმანეთში არეულ გემოებსა და არაერთგვაროვანი იერის მქონე კერძებზე. ამიტომ საკვების მირთმევისას ეცადეთ, შემოქმედებითად მიუდგეთ. მაგალითად, საუზმეზე სტაფილოს ნაჭრები უბრალოდ თეფშზე დალაგების ნაცვლად, თუ მათგან საინტერესო ფიგურებს შექმნით, დარწმუნებული ვართ, რომ პატარას ყურადღებას მიიპყრობთ! 😊') WHERE id = 'fac64036-a219-4703-b872-665eb449d5b6';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ თქვენს ბავშვს ტუალეტის გამოყენების ჩვევა ჯერ კიდევ სრულად არ აქვს გამომუშავებული, ძალიან მნიშვნელოვანია, გამოიჩინოთ მოთმინება, არ შეადაროთ სხვებს და არ დასაჯოთ. სპეციალისტების თქმით, ტუალეტის ჩვევის სწავლებისთვის ყველაზე შესაფერისი პერიოდია ზაფხულის თვეები და 1.5 - 3 წლის ასაკი. მოკლედ, თუ ეს ჩვევა ჯერ ვერ გამოუმუშავეთ, დაგვიანებულად არ ითვლება. თუ წარმატებას ვერ აღწევთ, ამის მიზეზი შესაძლოა როგორც თქვენი მიდგომა, ისე ბავშვის მზადყოფნა იყოს. ზოგი ბავშვი რამდენიმე დღეში ეჩვევა, ზოგმა კი შეიძლება ძლიერი წინააღმდეგობა გამოავლინოს. მშობლის არასწორმა მიდგომამ მომავალში ბავშვს სერიოზული პრობლემები შეიძლება შეუქმნას. გახსოვდეთ, რომ ყველა ჯანმრთელი ბავშვის მსგავსად, თქვენი პატარაც ადრე თუ გვიან ისწავლის ტუალეტის გამოყენებას. თუმცა სწავლების არასწორმა მეთოდებმა შესაძლოა ბავშვს თავდაჯერებასთან, პიროვნულ განვითარებასა და მიჯაჭვულობასთან დაკავშირებული პრობლემები შეუქმნას.') WHERE id = 'feaefa5c-467b-473d-8593-ed69b32fa642';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბოლო დროს ცივი, ყინულიანი ჩაი ბავშვების ერთ-ერთ საყვარელ სასმელად იქცა. თუ თქვენს ბავშვსაც უყვარს ცივი ჩაი და მისი დალევა მუდმივად სურს, იცოდეთ, რომ მარტო არ ხართ. 😊 თუმცა მნიშვნელოვანია, ბავშვის სითხის მოთხოვნილება შეძლებისდაგვარად წყლით დააკმაყოფილოთ. ცივი ჩაის მიცემისას ყურადღება უნდა მიაქციოთ მასში კოფეინისა და შაქრის შემცველობას. ასეთმა სასმელებმა შესაძლოა ბავშვი ზედმეტად აღაგზნოს და წონის სწრაფად მატება გამოიწვიოს. კოფეინის გარკვეულ რაოდენობაზე მეტის მიღება მოზრდილებშიც კი გადაჭარბებულ სიფხიზლეს იწვევს. ბავშვებში კი ამან შესაძლოა ნერვული აფეთქებები, ზედმეტი აქტიურობა და დაძინებისთვის წინააღმდეგობის გაწევა გამოიწვიოს.') WHERE id = '0d16f898-6bee-46b7-810a-0ae08cd779d7';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი თამაშის საშუალებით ბუნებრივად, დამოუკიდებლად და ხალისით იძენს ახალ ცოდნას. 2.5 წლის ბავშვი უკვე იწყებს მიზანმიმართული ქცევის გამოვლენას და წინა წლებთან შედარებით უფრო დიდხანს შეუძლია ყურადღების კონცენტრირება. მასთან აქტიური კომუნიკაცია ერთად გატარებულ დროს უფრო ხარისხიანს გახდის. მაგალითად, ამ პერიოდში ბავშვს ერთ აქტივობაზე ყურადღების დაახლოებით 10 წუთის განმავლობაში გამახვილება შეუძლია. 2.5 წლის ბავშვებს გარშემო მყოფ ადამიანებთან ერთად სხვადასხვა აქტივობაში მონაწილეობა მოსწონთ. თუმცა არ უნდა დაგავიწყდეთ, რომ ეს პარალელური თამაშის ეტაპია. პარალელური თამაშის პერიოდში ბავშვს სიამოვნებს თანატოლებთან ან უფროსებთან ერთ სივრცეში, ერთნაირი სათამაშოებით დროის გატარება, თუმცა ჯერ კიდევ არ ერთვება მათთან ინტერაქციულ, ერთობლივ თამაშში. ამიტომ, განსაკუთრებით თანატოლებისთვის სათამაშოების გაზიარებისას, შესაძლოა სირთულეები წარმოიშვას.') WHERE id = 'ba0dbae3-755a-40e2-a8cd-2a1d2c900c58';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ პერიოდში შეიძლება კითხვები გაგიჩნდეთ, რა რაოდენობისა და მრავალფეროვნების საკვები შესთავაზოთ თქვენს ბავშვს. მაგალითად, საუზმეზე შეგიძლიათ მისცეთ თეთრი ყველით წასმული პური და მოხარშული კვერცხი, ან 1 ნაჭერი სრულმარცვლოვანი ხორბლის პური ბექმეზითა და ტაჰინით, თეთრ ყველთან ერთად. საუზმიდან დაახლოებით 1-1.5 საათის შემდეგ შეგიძლიათ დაალევინოთ ახლად გამოწურული, უშაქრო ხილის წვენი ან 1 ჭიქა რძე. ბავშვის განვითარებისთვის ძალიან მნიშვნელოვანია, სადილამდე დაახლოებით 1 საათით ადრე ან სადილიდან 1 საათის შემდეგ აუცილებლად მისცეთ ხილი ან იოგურტი. სადილად კარგი არჩევანი შეიძლება იყოს 1 ჯამ ბოსტნეულის კერძთან ერთად ნახევარი ჯამი ფლავი ან სრულმარცვლოვანი ხორბლის ფქვილისგან მომზადებული მაკარონი. ვახშამზე ბავშვს შეგიძლიათ მისცეთ თითქმის ყველა ხორციანი ბოსტნეულის კერძი, რომელსაც საკუთარი თავისთვის ამზადებთ. თუ სადილზე ან ვახშამზე ბავშვს არ მიუღია ცილის ისეთი წყაროები, როგორიცაა ხორცი, ქათამი ან თევზი, ძალიან მნიშვნელოვანია, რომ ვახშამზე მირთმეული ბოსტნეულის კერძი მცენარეული ცილით იყოს მდიდარი.') WHERE id = 'a05e1296-3724-4f4f-b2bb-e078e101f1c5';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ პერიოდში, როდესაც თქვენი ბავშვი 2.5 წლისაა, მისი კომუნიკაციის უნარი კვლავ სწრაფად იწყებს განვითარებას. ამ ეტაპზე ენის განვითარების პროცესში ბავშვს სჭირდება კომუნიკაცია, სხვების ყურადღების მიპყრობა და საკუთარი სურვილების, ემოციებისა და აზრების გაზიარება. ამ პერიოდში მოსალოდნელია, რომ ბავშვი დაახლოებით 200-250 სიტყვას ამბობდეს და სიტყვების ერთმანეთთან დაკავშირებას იწყებდეს. განსაკუთრებით მომდევნო 1-2 თვის განმავლობაში, 3 წლის ასაკის მოახლოებასთან ერთად, მისი ლექსიკური მარაგი მნიშვნელოვნად უნდა გაიზარდოს და 3-4 სიტყვისგან შემდგარი წინადადებების აგება უნდა დაიწყოს. ამასთან, მისთვის გასაგები სიტყვების რაოდენობა ბევრად მეტი იქნება, ვიდრე იმ სიტყვებისა, რომელთა თქმაც შეუძლია. ამ ასაკის ბავშვებმა შეიძლება გამოიყენონ მეტყველების სტილი, რომელსაც ტელეგრაფიულ მეტყველებას უწოდებენ — ანუ მოკლე წინადადებები, რომლებიც მხოლოდ ძირითად აზრს გამოხატავს, მაგალითად: „მამა, ბურთი ითამაშე“. ამიტომ, ბავშვის მეტყველების გასავითარებელი აქტივობების გაგრძელებისას სასურველია, ჯერ მისგან იმაზე მეტს არ ელოდოთ, ვიდრე კოგნიტიურად შეუძლია.') WHERE id = 'e211eecc-39db-4566-ab98-8e17bb940902';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ პერიოდში ბავშვები ხშირად ეცნობიან არაჯანსაღ საკვებსა და სწრაფ კვებას. უმადობის მქონე ბავშვებში ამან შეიძლება განვითარების შეფერხება გამოიწვიოს, კარგი მადის მქონე ბავშვებში კი — სიმსუქნე. თუ თქვენი ბავშვი ინტერესდება შეფუთული მზა პროდუქტებით და მუდმივად ითხოვს მათ, ძალიან მნიშვნელოვანია, უფრო ჯანსაღი და გემრიელი ალტერნატივები შესთავაზოთ. მაგალითად, თუ ბავშვს ჩიფსები უყვარს, შეგიძლიათ კარტოფილი თხლად დაჭრათ, სანელებლებით შეაზავოთ და ღუმელში გამოაცხოთ. ამასთან, თუ ბავშვი საკმარისი რაოდენობით მარცვლეულსა და ხილს მიიღებს, ასეთი არაჯანსაღი საკვებისადმი სურვილი შეუმცირდება. მაგალითად, მარცვლეულის პროდუქტები შეგიძლიათ წვნიანში დაამატოთ ან რძესა თუ იოგურტთან ერთად მისცეთ. მათთან ერთად შესაძლებელია მცირე რაოდენობით სრულმარცვლოვანი ხორბლისგან მომზადებული ფლავის ან მაკარონის მირთმევაც. ეს საკვები არა მხოლოდ შეამცირებს თქვენი ბავშვის ინტერესს არაჯანსაღი პროდუქტებისადმი, არამედ მნიშვნელოვანია მისი ჯანსაღი ზრდისა და დაავადებებისგან დაცვისთვისაც.') WHERE id = 'dea526e3-269a-402d-8089-37a01ca0586f';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'უფროსებისა და ბავშვების სამყაროს შორის ერთ-ერთი მთავარი განსხვავება ემოციების აღქმისა და შეფასების ფორმაა. სკოლამდელი ასაკის თქვენს ბავშვს თქვენი და გარშემო მყოფი ადამიანების სახის გამომეტყველებიდან და არავერბალური ნიშნებიდან ემოციების ამოცნობის საკმაოდ კარგად განვითარებული უნარი აქვს. იმისათვის, რომ ბავშვს სხვადასხვა ემოციის უკეთ შესწავლაში დაეხმაროთ, შეგიძლიათ სახლში შესანიშნავი Montessori აქტივობა ჩაატაროთ. ამისთვის დაგჭირდებათ: მუყაო, მაკრატელი და ფერადი ფლომასტერები. :) კვერცხის, კვადრატის ან სამკუთხედის ფორმით გამოჭრილ, დაახლოებით 10 sm ზომის მუყაოებზე ფერადი ფლომასტერებით უნდა დახატოთ პირი და ამ გამომეტყველების შესაბამისი წარბები. მაგალითად, კბილებდაჭერილ და გაბრაზებულ პირს შეჭმუხნილი წარბები უნდა შეუხამოთ, გაოცებულ პირს კი — ზემოთ აწეული წარბები. შემდეგ მუყაო მაკრატლით ისე უნდა გაჭრათ, რომ პირი და წარბები ზუსტად შუაზე გაიყოს. ამის შემდეგ აურიეთ მუყაოს ყველა ნაწილი და აღტაცებით უყურეთ, როგორ შეუხამებს თქვენი ბავშვი ერთმანეთს შესაბამის წარბებსა და პირებს! :)') WHERE id = 'a9c58f85-ffb9-43bd-bd02-2e1899f70507';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'არსებობს რამდენიმე რეკომენდაცია, რომლებიც დაგეხმარებათ აღმოაჩინოთ, ინტელექტის რომელი სფეროები აქვს თქვენს ბავშვს მეტად განვითარებული, და ხელი შეუწყოთ მათ გაუმჯობესებას. მათ შორის ყველაზე პოპულარულია ინტელექტის სხვადასხვა სფეროს განვითარებაზე ორიენტირებული თამაშები და სათამაშოები. 2.5 წლის ასაკში ბავშვთან ერთად სხვადასხვა აქტივობის შესრულებით შეგიძლიათ განსაზღვროთ, რომელი სფერო უფრო აინტერესებს და რომელშია მეტად წარმატებული. მაგალითად, დიდი დეტალებისგან შემდგარი ფაზლების აწყობა, ერთმანეთში ჩასაწყობი ყუთებით თამაში, ქუჩაში სირბილი და გზად შემხვედრ მცირე დაბრკოლებებზე გადახტომა ძალიან სახალისო იქნება. ბურთის სროლა და დაჭერა, ქვიშისგან ფიგურების გაკეთება ან ქვიშაში დამალული ნივთების პოვნა ასევე ბავშვის ინტელექტის განმავითარებელი აქტივობებია. უდავოა, რომ ქვიშით თამაში თითქმის ყველა ბავშვს უყვარს. ამასთან, ქვიშით სათამაშოდ ზაფხულის თვეების ლოდინი საჭირო არ არის. ბავშვის სიმაღლის შესაბამის მაგიდაზე შეგიძლიათ დადგათ მაღალგვერდებიანი ჭურჭელი, ჩაყაროთ მასში სუფთა ქვიშა და ბავშვს სახლშიც მისცეთ თამაშისა და თითების კუნთების გაძლიერების შესაძლებლობა.') WHERE id = '27c1de50-2c42-464a-b6bf-b96b6763bf44';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ძალიან მნიშვნელოვანია, ბავშვს ასწავლოთ ემოციების ამოცნობა, რაც მისი სოციალურ-ემოციური განვითარების მნიშვნელოვანი ნაწილია. ბავშვებს, რომლებსაც შეუძლიათ თავიანთი ემოციების სოციალური გარემოს შესაბამისად გამოხატვა, ქცევითი პრობლემები ნაკლებად აღენიშნებათ. თუ თქვენი ბავშვი გაბრაზებისას შეძლებს თქვას: „ძალიან გავბრაზდი“, ნაკლები იქნება ალბათობა, რომ მას ბრაზის ან ტირილის ძლიერი შეტევა დაეწყოს. როდესაც ბავშვს ემოციების ამოცნობასა და გამოხატვაში ეხმარებით, ამავდროულად ასწავლით, როგორ გაუმკლავდეს უარყოფით განცდებს ჯანსაღად. გარდა ამისა, ემოციურ განვითარებასთან ერთად ბავშვი ემპათიის უნარსაც იძენს. ამგვარად, ადრეული ასაკიდანვე ხვდება, რომ მის გარშემო მყოფ ადამიანებს სხვადასხვა სიტუაციაში განსხვავებული ემოციები შეიძლება ჰქონდეთ. მაგალითად, თუ თქვენმა ბავშვმა იცის, რომ მეგობარს ეწყინება, როცა სათამაშოს წაართმევს, ნაკლებია ალბათობა, რომ ასე მოიქცეს.') WHERE id = '6f6fea86-044b-4ad1-8721-a20a4d184e96';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ყველა ბავშვს აქვს უფლება, თავისუფლად გამოხატოს საკუთარი აზრი, როდესაც მასთან დაკავშირებული გადაწყვეტილება მიიღება. ბავშვის მონაწილეობა გადაწყვეტილებების მიღებაში არა მხოლოდ მისი უფლება, არამედ განვითარების მნიშვნელოვანი ნაწილიცაა. გადაწყვეტილებების მიღებაში მონაწილეობა ხელს უწყობს ბავშვის გონებრივ და სოციალურ განვითარებას, ასევე პასუხისმგებლობის აღებისა და პრობლემების გადაჭრის უნარების ჩამოყალიბებას. ბავშვი, რომელსაც დამოუკიდებელ პიროვნებად აღიქვამენ, აზრს ეკითხებიან და აგრძნობინებენ, რომ ღირებულია, უკეთ შეძლებს თავის დაცვას და ნაკლები იქნება უყურადღებობისა თუ ძალადობის მსხვერპლად ქცევის ალბათობა. თუ აქამდე არ დაგიწყიათ, მნიშვნელოვანია, ბავშვს გადაწყვეტილებების მიღებაში მონაწილეობის პასუხისმგებლობა ჩაუნერგოთ. დასაწყისისთვის შეგიძლიათ, წაახალისოთ, თავად მიიღოს საკუთარ სხეულთან დაკავშირებული გადაწყვეტილებები. მაგალითად, შეგიძლიათ იმით დაიწყოთ, რომ ბავშვს თავად გადააწყვეტინოთ, სურს თუ არა ნათესავებმა ან ნაცნობებმა აკოცონ და ჩაეხუტონ.') WHERE id = '20007018-c312-42f8-9d7c-bba3d4a8dc28';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ის, რომ ბავშვი წინანდელთან შედარებით ნაკლებ საკვებს იღებს, განვითარების ბუნებრივი ნაწილია. თქვენი ამოცანაა, მისთვის უფრო ხარისხიანი საკვები შეარჩიოთ. მაგალითად, ცილებისა და ნახშირწყლების წყაროები, რომლებსაც ბავშვს სთავაზობთ, მაღალი ხარისხის უნდა იყოს. მაღალი ხარისხის ცილის წყაროებს მიეკუთვნება კვერცხი, რძე, იოგურტი, ხორცის ბურთულები და პარკოსნები. ბავშვმა ამ პროდუქტებიდან დღეში 2–3 პორცია უნდა მიიღოს. განსაკუთრებული ყურადღება უნდა მიაქციოთ რძის რაოდენობას. თუ ბავშვს რძე ძალიან უყვარს, მისი ჭარბად მიცემა შეიძლება სასარგებლოზე მეტად საზიანო აღმოჩნდეს. რძისა და იოგურტის დღიური რაოდენობა 500 ml-ს არ უნდა აღემატებოდეს; ამ პროდუქტების ჭარბად მიღებამ შეიძლება გამოიწვიოს ყაბზობა და რკინის შეწოვის დარღვევის გამო სისხლნაკლებობა (ანემია).') WHERE id = 'a35dfbb5-f5f6-479e-a555-e5d0082e7b04';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ყველა ბავშვი განსხვავებულია. და-ძმებიცა და ტყუპებიც კი, მიუხედავად იმისა, რომ ერთ სახლში იზრდებიან, შეიძლება ერთმანეთს სრულად არ ჰგავდნენ. ამის ერთ-ერთი მთავარი მიზეზი ტემპერამენტია. ტემპერამენტი ბავშვის თანდაყოლილი თვისებების ერთობლიობაა, რომელიც მომავალში მისი პიროვნების ჩამოყალიბებას უდევს საფუძვლად. მაგალითად, ზოგი ბავშვი უფრო მშვიდია, ზოგი კი — უფრო აქტიური და მგრძნობიარე. სიტყვები „ადვილი“ და „რთული“, რომლებსაც განსაკუთრებით ჩვილებზე საუბრისას იყენებენ, სინამდვილეში ბავშვის ტემპერამენტს აღწერს. მთლიანობაში ტემპერამენტის ცხრა ძირითადი მახასიათებელია განსაზღვრული, რომელთა შორის განსაკუთრებით გამოირჩევა აქტიურობის, სოციალურობისა და ადაპტაციის დონეები. მაგალითად, ადაპტაციის დონე გვიჩვენებს, რამდენად შეუძლია ბავშვს ახალ გარემოებებსა და ცვლილებებთან შეგუება. სწორედ ამ თვისებაზეა დამოკიდებული, რამდენად სწრაფად შეეგუება ბავშვი ოთახის, სახლის ან სკოლის შეცვლას.') WHERE id = 'd7b7b77e-5570-44db-89ff-93dc046edc75';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ პერიოდში თქვენს ბავშვს შეიძლება უკვე ჰქონდეს ტუალეტის გამოყენების ჩვევა გამომუშავებული ან ჯერ კიდევ სწავლების ეტაპზე იყოთ. თუმცა ამ პროცესს აქვს ერთი საერთო პრობლემა, რომელიც თითქმის ყველა ბავშვს ეხება: ყაბზობა! ტუალეტის გამოყენების სწავლების პერიოდში ბავშვებს ყაბზობა ხშირად აწუხებთ. ბავშვმა, რომელსაც საფენი ახლახან მოხსენით, შეიძლება განზრახ შეიკავოს დეფეკაცია, რაც განავლის გამკვრივებასა და მტკივნეულ დეფეკაციას იწვევს. ტკივილისა და შიშის მანკიერი წრის დაწყების შემდეგ მდგომარეობის მოსაწესრიგებლად ბავშვი ზედმეტად არ უნდა აიძულოთ. ამ პერიოდში ასევე არ არის სწორი ბავშვის განავალზე უარყოფითი კომენტარების გაკეთება. ამ ასაკის ბავშვისთვის განავალი ძალიან მნიშვნელოვანია და მას საკუთარი სხეულის ნაწილად აღიქვამს. დეფეკაციისას შეიძლება ისეთი განცდა ჰქონდეს, თითქოს მის სხეულს ნაწილი სცილდება.') WHERE id = '8cd65094-234a-43ba-9216-79ad31e952d9';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'კვების რეგულარული განრიგი ერთ-ერთი ყველაზე მნიშვნელოვანი ჩვევაა, რომელიც შეგიძლიათ თქვენს ბავშვს გამოუმუშაოთ. თუმცა რეჟიმთან ერთად მნიშვნელოვანია პორციების ზომაც. ამ პერიოდში ბავშვს უნდა შესთავაზოთ მცირე პორციები, რომელთა ჭამასაც შეძლებს, და არ მისცეთ იმაზე მეტი საკვები, ვიდრე შეუძლია დაასრულოს. თუ თქვენს ბავშვს ძალიან ცუდი მადა აქვს, მაგრამ მისი ზრდა და განვითარება ნორმალურად მიმდინარეობს, მიეცით საშუალება, თავად განსაზღვროს, რამდენს შეჭამს. ძალიან მნიშვნელოვანია საკვების მომზადება ჯანსაღი მეთოდებით. მოერიდეთ ცხარე და სანელებლებით ჭარბად შეზავებულ საკვებს, ასევე საკვების ზედმეტად ცხლად ან ცივად მიცემას. სოციალიზაციის პროცესში თქვენი ბავშვი ზოგჯერ შეიძლება არაჯანსაღ საკვებსაც გაეცნოს. თქვენი მთავარი მიზანი უნდა იყოს, შეძლებისდაგვარად მოარიდოთ ბავშვი ასეთ საკვებს და შეეცადოთ, ჯანსაღი რეჟიმი შეინარჩუნოთ.') WHERE id = '16c8ff33-deb6-4f40-89a3-c531e7b4cb9c';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ძილი ყველა ასაკში სასიცოცხლოდ მნიშვნელოვანია თქვენი ბავშვის ჯანსაღი განვითარებისთვის, რადგან ზრდის ჰორმონი ძილის დროს გამოიყოფა. 2 წლის შემდეგ, მიუხედავად იმისა, რომ დღის ძილის ხანგრძლივობა მცირდება, ღამის ძილის საჭიროება იზრდება. ამ ეტაპზე საკმარისია ღამით 11 საათი უწყვეტი ძილი, ხოლო დღისით — 1-1,5 საათი. სწორედ მაშინ, როდესაც ფიქრობთ, რომ 2 წლის ასაკის კრიზისმა ჩაიარა, შეიძლება 3 წლის ასაკის კრიზისი დაიწყოს, რის გამოც თქვენი შვილი შეიძლება ცოტა ჯიუტი გახდეს და დაძინებას შეეწინააღმდეგოს. თუ ის დაძინების დროის გადადებას შეეცდება, აგრძნობინეთ, რომ მტკიცედ დგახართ თქვენს გადაწყვეტილებაზე, თუმცა ზედმეტი სიმკაცრის გარეშე მცირე გამონაკლისებიც შეგიძლიათ დაუშვათ.') WHERE id = '4051aaec-c1ae-4638-bc35-ce5ea1cf068b';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'მნიშვნელოვანია, მოუსმინოთ თქვენს ბავშვს, რომელსაც მეტყველების უნარები უვითარდება, და დაეხმაროთ საკუთარი აზრების გამოხატვაში. ბავშვები, რომლებსაც არ ესმით, რას და რატომ აკეთებენ, გადაწყვეტილებების მიღებაში მონაწილეობას ვერ შეძლებენ. ძალიან მნიშვნელოვანია, უმცირესი გადაწყვეტილებებიც კი აუხსნათ, მათი მიზეზები განუმარტოთ და გულწრფელად ჰკითხოთ, რას გრძნობს. როდესაც ბავშვს უსმენენ, ის თავს დაფასებულად გრძნობს და თავდაჯერებულობა ემატება. მაშინაც კი, თუ მისი ყველა სურვილის შესრულება შეუძლებელია, აუხსენით ამის მიზეზი. გახსოვდეთ, რაც უფრო მეტად მოუსმენთ თქვენს შვილს და ხელს შეუწყობთ გადაწყვეტილებების მიღებაში მის მონაწილეობას, მით უფრო დამოუკიდებელ პიროვნებად ჩამოყალიბდება.') WHERE id = '0ce591a9-3ab7-4fd5-aaf6-d14c88201ae3';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, '24 თვიდან ბავშვები თანდათან უფრო დამოუკიდებლები ხდებიან. 2,5 წლის ასაკში თქვენს ბავშვს სურს, ოჯახში თავი მეტად დამოუკიდებელ პიროვნებად წარმოაჩინოს. დამოუკიდებლობის ეს განცდა მის კვებით ჩვევებზეც მოქმედებს. ამ პერიოდში თქვენმა შვილმა შეიძლება ჯიუტად უარი თქვას იმ საკვებზე, რომლის გემოც არ მოსწონს, ან განსაკუთრებულად მიეჯაჭვოს რომელიმე კონკრეტულ საკვებს. თუ საკვები, რომლის მიღებასაც თქვენი შვილი დაჟინებით ითხოვს, საზიანოა, შესთავაზეთ არჩევანი. მაგალითად, ისეთი ფრაზით, როგორიცაა: ბოსტნეულის კერძის დასრულების შემდეგ კარტოფილი ფრი შეგიძლია მიირთვა, შეგიძლიათ მისი სურვილიც გაითვალისწინოთ და ჯანსაღად კვებაც უზრუნველყოთ.') WHERE id = '158b48bc-de87-4a18-8590-049c1345f651';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ პერიოდში ბავშვს უნდა ასწავლოთ ისეთი ძირითადი ემოციების დასახელება, როგორიცაა ბედნიერება, სევდა, ბრაზი და შიში. შემდეგ შეგიძლიათ დაუსვათ კითხვები: რას გრძნობ, როცა ბედნიერი ხარ? ან რას გრძნობ, როცა ბრაზდები? იმის გასაგებად, თუ რას უკავშირებს ის ამ სიტყვებს, შეგიძლიათ სთხოვოთ, დახატოს ან მოგიყვეთ ამის შესახებ. შეგიძლიათ შვილს ყოველდღე ჰკითხოთ: დღეს თავს როგორ გრძნობ? ან დღეს როგორ გრძნობდი თავს? ასევე ძალიან მნიშვნელოვანია, მასთან მის მიერ დასახელებულ ემოციაზე ისაუბროთ. მაგალითად, შეგიძლიათ ჰკითხოთ: რამ გაგაბედნიერა?, რამ დაგამწუხრა? ან რა რომ ყოფილიყო სხვაგვარად, თავს უკეთ იგრძნობდი? ამ დროს შეგიძლიათ დაეხმაროთ და თითოეული ემოციის შესახებ საკუთარი მაგალითი მოუყვანოთ. თუმცა გახსოვდეთ, რომ რთულ სიტუაციებთან გამკლავების თქვენი სტრატეგიები და ჩვევები შვილისთვის მისაბაძი მაგალითი იქნება. თუ გაბრაზებისას ხმამაღლა ყვირით, საკუთარ ემოციას არ გამოხატავთ ან რაიმე ნივთს იატაკზე აგდებთ, სწორი არ იქნება, ბავშვისგან მოელოდეთ, რომ ემოციებს სიტყვიერად გამოხატავს და უარყოფით განცდებს ჯანსაღად გაუმკლავდება.') WHERE id = '0daa42c4-6bd6-49b7-8345-003a12087e4e';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ტექნოლოგიების ეპოქაში ბავშვის ტექნოლოგიებისგან სრულად იზოლირება არარეალურია. თუმცა უნდა ისწავლოთ, რომ გარკვეული დროის განმავლობაში ტექნოლოგიური მოწყობილობების გამოყენებაში შესვენება გააკეთოთ, საჭიროების შემთხვევაში კი — მთელმა ოჯახმა. ტელევიზორი, მობილური ტელეფონები და კომპიუტერები ძალიან სახალისოა, თუმცა ბავშვის შემოქმედებითობისთვის ძალიან მცირე სივრცეს ტოვებს. იმისთვის, რომ თქვენს შვილს შემოქმედებითი საქმიანობისა და წარმოსახვისთვის დრო ჰქონდეს, გარკვეული პერიოდით ეს მოწყობილობები უნდა გამორთოთ. მაგალითად, შეგიძლიათ ბავშვს დაუსვათ წარმოსახვის გამომწვევი კითხვები, როგორიცაა: "რას ჰგავს ცაში ღრუბელი ან კედელზე დაცემული ჩრდილი?" თამაშის დროს შეგიძლიათ წაახალისოთ, რომ სათამაშოები ან სხვა ნივთები მათი ჩვეული დანიშნულებისგან განსხვავებულად გამოიყენოს. მცირე შემოქმედებითობის წყალობით ერთი სათამაშო შეიძლება სრულიად სხვა რამედ იქცეს. ისტორიების მოყოლაც ძალიან სასარგებლოა ბავშვის შემოქმედებითი უნარების გასავითარებლად. შეგიძლიათ მისთვის ნაცნობი ამბავი შეცვლილი სახით მოუყვეთ, შემდეგ კი თავადაც წაახალისოთ, რომ ისტორიები შეცვალოს და ისე მოგიყვეთ.') WHERE id = '8115dfc9-eb92-4e72-a543-4ea919c775ac';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'როდესაც საქმე თქვენს შვილს ეხება, ბუნებრივია, რომ მის საკვებთან დაკავშირებით მუდმივად კითხვები გიჩნდებათ. ერთ-ერთი ასეთი საკითხია პური და ფქვილის ნაწარმი, რომლის შესახებაც ექიმებსაც კი არ აქვთ ერთიანი აზრი. ამ საკვებ ჯგუფს პურთან ერთად ნახშირწყლების სხვა წყაროებიც მიეკუთვნება. პურის არჩევისას არა მხოლოდ ზრდასრულებმა, არამედ ბავშვებმაც თეთრი პურის ნაცვლად მთლიანი ხორბლისგან დამზადებული, სრულმარცვლოვანი პური უნდა მიირთვან. სრულმარცვლოვანი ფქვილი ნაკლებად დამუშავებულია, ამიტომ საკვები ნივთიერებებით უფრო მდიდარია. ბრინჯის ნაცვლად ბულგურის გამოყენებაც შეიძლება უფრო ჯანსაღი და კარგი ალტერნატივა იყოს. თუ თქვენს ბავშვს წონის მომატებისკენ აქვს მიდრეკილება, ამ პროდუქტების რაციონიდან სრულად ამოღების ნაცვლად, უფრო გონივრულია, ისინი მცირე ულუფებით მისცეთ.') WHERE id = 'bb018208-0884-4d7b-917a-81edc759ffd2';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვობაში ჩამოყალიბებული ჰიგიენური ჩვევები, ყოველდღიური რუტინა და კვების ჩვევები მთელი ცხოვრების განმავლობაში ნარჩუნდება. ამიტომ სწორი კვების საფუძვლების სწავლება, პირადი ჰიგიენის დაცვა და ზოგიერთი ძირითადი რუტინის ჩვევად ქცევა თქვენს შვილს გრძელვადიან პერსპექტივაში დაავადებებისგან დაიცავს. ამგვარი ჩვევები არა მხოლოდ დაავადებებისგან დასაცავად, არამედ თქვენი ბავშვის განვითარებისთვისაც ძალიან მნიშვნელოვანია. გახსოვდეთ, რომ შვილისთვის გაწეული ძალისხმევა მის მომავალში ჩადებული ყველაზე დიდი ინვესტიციაა. ამ მხრივ მნიშვნელოვანია, უზრუნველყოთ, რომ ბავშვმა ჭამამდე და ჭამის შემდეგ ხელები დაიბანოს, საღამოს, დაძინებამდე, კბილების გახეხვა ჩვევად აქციოს და გარედან დაბრუნებისას ტანსაცმელი გამოიცვალოს. ამ პერიოდში, როდესაც თქვენი შვილი ნებისმიერი ჩვევის ათვისებისკენაა მიდრეკილი, მავნე ჩვევების მიმართაც ყურადღებით უნდა იყოთ. მაგალითად, ახლობელთა წრეში ნანახმა ყვირილით ურთიერთობამ, გაბრაზებისას გარშემო არსებული ნივთების დაზიანებამ ან ცუდი სიტყვების მოსმენამ შეიძლება გამოიწვიოს, რომ მანაც ადვილად აითვისოს ეს ჩვევები.') WHERE id = 'fa462e53-99cc-4df3-9374-bf4b0433f122';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი შვილი, რომელსაც 31-ე თვე შეუსრულდა, ამ პერიოდში უკვე საკმაოდ კარგად ფლობს ფიზიკურ და ნატიფ მოტორულ უნარებს. მას შეუძლია, თქვენი მიბაძვით ადვილად ისწავლოს ფანქრის დაჭერა და ხატვა. მართალია, ჯერ სრულყოფილად ვერ დახატავს, თუმცა შეუძლია ფერები უწესრიგოდ გამოიყენოს. შეგიძლიათ, ბავშვს თითის საღებავები უყიდოთ და ხატვისკენ წაახალისოთ, ერთად ხატვით კი მხიარულადაც გაატარებთ დროს. ხატვისას, მისი შემოქმედებითი უნარების განსავითარებლად, ყველა ფერის გამოყენების საშუალება უნდა მისცეთ. ზოგადად, რადგან შავი დომინანტური ფერია, შეიძლება ის სხვა ფერებზე მეტად მოეწონოს, თუმცა მის მიერ არჩეულ ფერებში არ უნდა ჩაერიოთ. თითის საღებავები შეიძლება ფუნჯზე უფრო სასარგებლო აღმოჩნდეს, რადგან ბავშვი ხაზებს თითებით უფრო ადვილად ავლებს. რამდენიც უნდა ეცადოთ მის შეჩერებას, ბავშვმა ხატვა შეიძლება არა მხოლოდ ქაღალდზე, არამედ სახლის კედლებზეც მოსინჯოს. დასუფთავებისთვის ახლავე მოემზადეთ! თუ სახლის კედლებს ადვილად გასაწმენდი საღებავით შეღებავთ, მათი გაწმენდა უფრო მარტივი იქნება. ‐ Anacan-ის ოჯახი.') WHERE id = 'f361492b-3d92-4ce0-97da-c8386dbad563';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ პერიოდში თქვენს ბავშვს საშუალოდ 11-13 საათი უნდა ეძინოს. ძილის საერთო ხანგრძლივობა ღამესა და დღეს შორის ასე უნდა განაწილდეს: 10-11 საათი ღამის ძილი და 1-2 საათი — ერთი დღის ძილი. ზოგიერთი მშობელი ამ პერიოდში ბავშვს დღისით აღარ აძინებს. თუმცა ბავშვის განვითარებისთვის დღის ძილი საშუალოდ 4 წლამდე კვლავ მნიშვნელოვანია. იმისთვის, რომ ბავშვმა ახალი რამ ისწავლოს, დღის დარჩენილი ნაწილისთვის საჭირო ენერგია აღიდგინოს, ზედმეტად არ გადაიღალოს და ღამით დაძინებაზე უარი არ თქვას, მის დღის ძილს კვლავ სათანადო ყურადღება უნდა მიაქციოთ. თქვენი ბავშვი უკვე იმ ასაკშია, როდესაც ყველაფერს იგებს. ამიტომ მის ძილზე შეიძლება დღის განმავლობაში მომხდარმა ნებისმიერმა უსიამოვნო მოვლენამ იმოქმედოს. რადგან თქვენი პატარა გაიზარდა და უფრო მოძრავი გახდა, მისი გისოსებიან საწოლში დატოვება შეიძლება უკვე რთული იყოს. ჩვილის საწოლიდან ბავშვის საწოლზე გადასასვლელად ეს პერიოდი, როგორც წესი, ყველაზე შესაფერისია. სასარგებლო იქნება, თუ ამ პროცესს სახალისოს გახდით. ამგვარად, ბავშვს ახალი საწოლი შეუყვარდება. წინააღმდეგ შემთხვევაში, შესაძლოა, ძილის პრობლემები წარმოიშვას.') WHERE id = 'a72583c0-5214-45e6-a7f3-7cad2b42e3ee';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'როდესაც თქვენი ბავშვი უკვე იმავე საკვებს ჭამს, რომელსაც საკუთარი თავისთვის ამზადებთ, სრულიად ბუნებრივია, თუ კერძებში დამატებული მარილის რაოდენობასთან დაკავშირებით კითხვები გაგიჩნდებათ. მართალია, მშობლები, როგორც წესი, ცდილობენ კერძებს ზედმეტი მარილი არ დაუმატონ, თუმცა მაგიდაზე მდგარი სამარილე ხშირად ბავშვების ინტერესსაც იწვევს. ამ ასაკში ბავშვის ორგანიზმს ბევრი მარილი არ სჭირდება. რადგან საკვები ბუნებრივადაც შეიცავს მარილს, კერძში მისი მცირე რაოდენობით დამატება საკმარისია. მთავარი, რასაც ყურადღება უნდა მიაქციოთ, ისაა, რომ გამოყენებული მარილი იოდირებული იყოს. თუ თქვენი ბავშვი ზედმეტად მარილიან საკვებს მიეჩვევა, მომავალში მას მაღალი არტერიული წნევის განვითარების რისკი ექნება. ამიტომ, თუ თქვენს პატარას მარილიანი საკვები უყვარს, შესაძლოა, გარკვეული პერიოდით მთელმა ოჯახმა რაციონიდან კერძებში დამატებული ზედმეტი მარილი ამოიღოთ.') WHERE id = '190574b9-2d94-41ec-8775-1a8e11808369';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ყველა ბავშვის სოციალიზაციის დონე განსხვავებულია. მიუხედავად იმისა, მაღალია თუ დაბალი სოციალიზაციის დონე, თქვენ, როგორც მშობელს, ამ პროცესში მრავალი პასუხისმგებლობა გაკისრიათ. სოციალიზაციის დონე ასახავს ბავშვის რეაქციას სოციალურ გარემოსა და ახალ ადამიანებზე — მათთან მიახლოების ან მათგან დისტანცირებისკენ მიდრეკილებას. ზოგიერთი ბავშვი ახალ გარემოში თავს ძალიან თავისუფლად გრძნობს და სხვებს სწრაფად უახლოვდება, ზოგი კი მორცხვობს და არავისთან მიახლოება არ სურს. თუ თქვენი ბავშვის სოციალიზაციის დონე დაბალია, არ უნდა აიძულოთ, ახალ გარემოში ადამიანებთან დაუყოვნებლივ დაამყაროს ურთიერთობა. ასეთ შემთხვევაში საუკეთესო არჩევანი იქნება, დაელოდოთ, სანამ ბავშვი გარემოს შეეჩვევა. ხოლო თუ სოციალიზაციის დონე მაღალია, ბავშვს უფრო ყურადღებით უნდა დააკვირდეთ და ზედამხედველობა გაუწიოთ. თუ მისი სოციალიზაციის თავისებურებები ძალიან გაწუხებთ, შეგიძლიათ სპეციალისტ ექიმს მიმართოთ რჩევისთვის.') WHERE id = '3818caec-41c6-4171-b3ce-2ce4abd11b1e';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ თვიდან ბავშვის წონა საშუალოდ 13.250 გრამია. გოგონებისთვის ეს მაჩვენებელი საშუალოდ 12.900 გრამია, ხოლო ბიჭებისთვის — დაახლოებით 13.600 გრამი. 31 თვის ბავშვების სიმაღლე კი საშუალოდ 92 სმ-ია. გოგონებისთვის ეს მაჩვენებელი საშუალოდ 91,4 სმ-ია, ხოლო ბიჭებისთვის — 92,7 სმ. თუმცა გახსოვდეთ, რომ ეს რიცხვები მხოლოდ საშუალო მაჩვენებლებია. მაშინაც კი, თუ ბავშვის სიმაღლე და წონა საშუალო მნიშვნელობებს არ შეესაბამება, პრობლემა არ არის, თუ ისინი უსაფრთხო დიაპაზონშია. პერცენტილის ცხრილის მიხედვით, 31 თვის ბავშვების სიმაღლისა და წონის დიაპაზონი ასეთია: 31 თვის გოგონებისთვის წონის ქვედა ზღვარია 10.300 გრამი, ზედა ზღვარი — 16.500 გრამი; 31 თვის ბიჭებისთვის წონის ქვედა ზღვარია 10.800 გრამი, ზედა ზღვარი კი — 16.900 გრამი. სიმაღლის მაჩვენებელი 31 თვის გოგონებისთვის: ქვედა ზღვარი — 84,7 სმ, ზედა ზღვარი — 98,2 სმ; ბიჭებისთვის კი ქვედა ზღვარი — 86,2 სმ, ხოლო ზედა ზღვარი — 99,2 სმ.') WHERE id = '3842dedf-9bba-4a59-b233-533a1cd51008';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ პერიოდში მშობლების ერთ-ერთი ყველაზე დიდი საზრუნავი ბავშვის წარმოსახვითი მეგობრების გაჩენაა. თუ თქვენც ამგვარ რამეს შეამჩნევთ, უპირველეს ყოვლისა, სიმშვიდე უნდა შეინარჩუნოთ და იცოდეთ, რომ ეს განვითარების ბუნებრივი ნაწილია. წარმოსახვით მეგობართან ერთად, ბავშვმა შეიძლება ცხოველთან ან სათამაშოსთანაც დაამყაროს ურთიერთობა, რომელსაც მითითებებს აძლევს და სხვადასხვა როლს ასრულებინებს. მან შეიძლება სათამაშოს წესრიგისკენ მოუწოდოს, გაუბრაზდეს და დაუყვიროს კიდეც. თუ ამას შეესწრებით, ნუ გაგიკვირდებათ. ეს იმით არის განპირობებული, რომ ბავშვი თქვენ გბაძავთ და საკუთარ თავს დიდ ადამიანად აღიქვამს. ამ პერიოდში ბავშვის ფიზიკური და გონებრივი განვითარების ხელშესაწყობად შეგიძლიათ ასაკის შესაბამისი რბილი სათამაშოები შეუძინოთ, რომლებიც როლური თამაშის შესაძლებლობას მისცემს. ყურადღება მიაქციეთ, რომ თქვენ მიერ შერჩეული სათამაშოები ბავშვს როგორც გონებრივი, ისე ფიზიკური აქტივობისკენ უბიძგებდეს და მის განვითარებად წარმოსახვას ასტიმულირებდეს. სათამაშოების სწორად შერჩევა თქვენს პრიორიტეტებს შორის უნდა იყოს, რათა მზარდმა ბავშვმა თავისი ენერგია ჯანსაღად მიმართოს.') WHERE id = 'f8ae4ada-7f41-4498-b68a-fecd1f544ae2';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'არსებული სტატისტიკური მონაცემების თანახმად, სამწუხაროდ, დღეს ყოველი 5 ბავშვიდან ერთს სიმსუქნე აწუხებს. ჭარბი წონის მქონე ბავშვებზე დაკვირვება აჩვენებს, რომ ისინი ცოტას მოძრაობენ, დიდ დროს ატარებენ ტელევიზორთან ან კომპიუტერთან და ხშირად ჭამის დროსაც კი ამგვარი აქტივობებით არიან დაკავებული. ამასთანავე, ფიზიკური აქტივობის ნაკლებობა და, რაც მთავარია, ბავშვის მუდმივად სხვების მიერ კვება სიმსუქნის გამომწვევ მნიშვნელოვან ფაქტორებს მიეკუთვნება. ბავშვებს, რომლებსაც დამოუკიდებლად ჭამის ჩვევა არ აქვთ, ხშირად არაჯანსაღი კვების ჩვევები უყალიბდებათ. კიდევ ერთი მიზეზი დანამატების შემცველ საკვებთან ბავშვების მიჩვევაა. სპეციალისტები გვირჩევენ, ბავშვები მოვარიდოთ სწრაფ კვებას, მზა საკვებს, ჩიფსებს, კოლასა და გაზიან სასმელებს, ასევე ხელოვნური დანამატების შემცველ პროდუქტებს. თუ გავითვალისწინებთ, რომ თქვენი 2.5 წლის ბავშვი ახლო მომავალში სკოლაში დაიწყებს სიარულს და შესაძლოა უფრო ხშირად გახდეს ავად, არ უნდა დაგავიწყდეთ, რამდენად მნიშვნელოვანია ჯანსაღი კვება ძლიერი იმუნიტეტის ჩამოსაყალიბებლად.') WHERE id = '58502d60-f8e0-4b8e-a1fb-c17d973d4ff1';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ ეტაპზე თქვენი ბავშვი უკვე საკმაოდ სოციალიზებულია, მუდმივად ურთიერთობს გარშემომყოფებთან და ადამიანების მიმართ სხვადასხვაგვარი გრძნობები უჩნდება. შეიძლება შეამჩნიოთ, რომ სკოლამდელი ასაკის ბავშვი ხშირად გამოხატავს უეცარ სიყვარულს ან სიძულვილს. ბავშვობაში ემოციები სწრაფად იცვლება იმის მიხედვით, სრულდება თუ არა ბავშვის იმწუთიერი სურვილები. ამიტომ აზრი არ აქვს, ბავშვს უთხრათ, ვინმე უყვარდეს ან არ უყვარდეს. მის მიმართ გრძნობები ამ ადამიანთან ჩამოყალიბებული ურთიერთობის საფუძველზე უჩნდება. ანუ ბავშვის გრძნობები დამოკიდებულია იმაზე, რამდენად საინტერესოა მისთვის ეს ურთიერთობა და რას უზიარებენ ისინი ერთმანეთს. ამიტომ ისეთი ფრაზები, როგორებიცაა „ნახე, რა კარგი მეგობარია, მოდი, შეიყვარე“ ან „ბებია უნდა გიყვარდეს“, ბავშვისთვის დიდად აზრიანი არ არის. მოკლედ, ბავშვის გრძნობებიც იმის მიხედვით ჩამოყალიბდება, თუ როგორ განვითარდება ურთიერთობა. იძულებამ კი შეიძლება ამ ადამიანის მიმართ კიდევ უფრო უარყოფითი გრძნობები გაუჩინოს.') WHERE id = '24346579-f274-43ec-b861-363147af3e6c';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'შეიძლება შეამჩნიოთ, რომ ბოლო დროს თქვენი 31 თვის ბავშვის ცნობიერება გაიზარდა. ამის ყველაზე თვალსაჩინო მაგალითი დროის აღქმას უკავშირდება. ამ პერიოდში ბავშვს დროის ცნება თანდათან უყალიბდება. მაგალითად, როდესაც ეუბნებით „3 საათის შემდეგ“, მას უკვე ესმის, რას ნიშნავს სიტყვა „შემდეგ“ ამ წინადადებაში. თუმცა დროის ხანგრძლივობა მისთვის ჯერ კიდევ ბოლომდე გასაგები არ არის. ამის გასააზრებლად, მაგალითად, თუ სადმე 2 დღის შემდეგ მიდიხართ, შეგიძლიათ ასე აუხსნათ: „დავიძინებთ, გავიღვიძებთ, ისევ დავიძინებთ და გავიღვიძებთ“. ამგვარი მაგალითები თქვენს ბავშვს დროის უკეთ აღქმაში დაეხმარება და შესაძლო გაუგებრობებს თავიდან აგაცილებთ.') WHERE id = '12b0c10e-3144-4c46-a3b6-1700a0248288';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ თქვენი ბავშვი კვლავ ეწინააღმდეგება დაძინებას, იცოდეთ, რომ მარტო არ ხართ და ბევრ დედას აქვს იგივე პრობლემა! ამ ასაკში სრულიად ნორმალურია, რომ დაძინების ნაცვლად თამაშს, კითხვების დასმასა და თქვენთან მეტი დროის გატარებას ამჯობინებდეს. ბუნებრივია ისიც, თუ დაძინებიდან გარკვეული ხნის შემდეგ გაიღვიძებს და თამაში მოუნდება. ამ ეტაპზე ძილის რეჟიმისა და ძილისთვის მომზადების თანმიმდევრული პროცესის ჩამოყალიბება ძალიან სასარგებლო იქნება. მაგალითად, თუ ბავშვს ჯერ კიდევ თქვენთან ერთად სურს დაძინება, ამ საკითხში დათმობაზე არ უნდა წახვიდეთ. თუ შესაძლებელია, საკუთარი ოთახი უნდა ჰქონდეს, ხოლო თუ ეს შეუძლებელია — აუცილებლად საკუთარი საწოლი, რაც საქმეს გაგიადვილებთ. ძილის დროის მოახლოებისას ოთახში ფარდები ჩამოაფარეთ, შუქი ჩააქრეთ და მშვიდი, ბნელი გარემო შექმენით. როდესაც პიჟამას ჩააცმევთ და დასაძინებლად მოამზადებთ, ბავშვი მიხვდება, რომ ძილის დრო მოვიდა.') WHERE id = 'fcf11140-2354-4af3-8445-6e3473639648';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ყურადღება მიაქციეთ, რომ ბავშვისთვის მომზადებულ 3 ძირითად კვებას — საუზმეს, სადილსა და ვახშამს — შორის სულ მცირე 4-საათიანი შუალედი იყოს. კვების სიხშირეს ბავშვის მადასა და ჩვევებზე დიდი გავლენა აქვს. საუზმესა და სადილს, ასევე სადილსა და ვახშამს შორის შეგიძლიათ მცირე წახემსება შესთავაზოთ. თუმცა სხვა დროს, წყლის გარდა, ბავშვს არაფერი უნდა მისცეთ საჭმელად ან დასალევად. ერთმა უმნიშვნელო ორცხობილამ ან კრეკერმაც კი შეიძლება ბავშვს შემდეგი კვებისთვის მადა დაუკარგოს. ამგვარი წასახემსებელი ასევე ანაცვლებს ძირითად საკვებს, რომელიც ბავშვმა უნდა მიიღოს. ამიტომ, ძირითად კვებაზე ბავშვმა ცოტაც რომ ჭამოს, რეკომენდებულია, მომდევნო წახემსების ან კვების დროს დაელოდოთ და შუალედში მხოლოდ იმისთვის არ აჭამოთ, რომ აუცილებლად რამე შეჭამოს.') WHERE id = '03e2d49c-fc1b-4405-8b1e-dc104530e959';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ დღეებში შეიძლება შეამჩნიოთ, რომ თქვენს შვილს დანაშაულის განცდა უვითარდება. მას უკვე შეუძლია თანატოლებთან თამაშისას თანამშრომლობა, საყვარელი ადამიანებისადმი სითბოს გამოხატვა და სათამაშოების გაზიარება. დანაშაულის განცდის გამო, თუ შემთხვევით მეგობარს აწყენინებს ან ზიანს მიაყენებს, შეიძლება ინერვიულოს. კომუნიკაციის უნარების გაუმჯობესებასთან ერთად, თქვენი შვილის ქცევა უფრო მოწესრიგებული ხდება, აგრესიული ქცევა კი დროთა განმავლობაში რბილდება. თუმცა, არც 3 წლის ასაკის კრიზისის გავლენა უნდა დაგავიწყდეთ. ამ პერიოდში ბავშვი ერთ მომენტში შეიძლება ძალიან დამყოლი და მორჩილი იყოს, ცოტა ხანში კი კვლავ გაჯიუტდეს და აგრესიული გახდეს. მასთან მაქსიმალურად მჭიდრო კომუნიკაციის შენარჩუნება ამ არასტაბილურ პერიოდში ძალიან დაგეხმარებათ.') WHERE id = 'a43e3be1-81c8-45fd-98c2-ea9d64a44b8b';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენს შვილს, რომელსაც უკვე თითქმის ყველაფრის ჭამა შეუძლია, წინა წლებთან შედარებით საკვებისმიერი ალერგიის ნაკლები რისკი აქვს. თუმცა, რაციონში ღვიძლის, ბადრიჯნის, ფსკერული ზღვის თევზისა და ცერცვის მსგავსი პროდუქტების შეტანამდე მაინც სასურველია ექიმთან კონსულტაცია. 3 წლამდე ბავშვისთვის მისაცემი საკვები 4 ძირითად ჯგუფად იყოფა: 1-ლი ჯგუფი: B ჯგუფის ვიტამინების, ცილების, სისხლის წარმოქმნისთვის საჭირო მინერალებისა და ენერგიის წყაროები — კვერცხი, წითელი ხორცი, თევზი, ქათამი, ლობიო, ოსპი, მუხუდო და მათგან მომზადებული კერძები. მე-2 ჯგუფი: კალციუმით, A და B ვიტამინებით მდიდარი პროდუქტები, როგორიცაა რძე, ყველი და იოგურტი. მე-3 ჯგუფი: ენერგიის მომცემი მარცვლეული და მისგან მომზადებული ყველა საკვები. მე-4 ჯგუფი: C ვიტამინის წყარო ხილი და ბოსტნეული. განსაკუთრებით მნიშვნელოვანია A, B და C ვიტამინებით მდიდარი მწვანე ფოთლოვანი ბოსტნეული. უნდა უზრუნველყოთ, რომ თქვენი შვილი დღის 3 ძირითადი კვების დროს თითოეული ამ ჯგუფიდან საკმარისი და დაბალანსებული რაოდენობის საკვებს იღებდეს.') WHERE id = 'f972da56-9345-45fd-af4a-8733021b3193';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ პერიოდში თქვენი შვილის შიშები შეიძლება საკმაოდ გაძლიერდეს. განსაკუთრებით შეიძლება გაგრძელდეს სიბნელის შიში. მიუხედავად თქვენდამი ნდობისა და სიყვარულისა, მისთვის ახალი შიშები ბავშვს შეიძლება ძალიან აშფოთებდეს. მაშინაც კი, თუ აქამდე ცალ-ცალკე საწოლებში გეძინათ, ბავშვმა შეიძლება ღამით ხშირად გაიღვიძოს და თქვენთან ერთად დაძინება მოინდომოს. მის საჭიროებებზე სიყვარულით რეაგირება და უსაფრთხო გარემოს შექმნა თავდაჯერებული და ოპტიმისტი ბავშვის აღზრდაში დაგეხმარებათ. ძილის წინ დამამშვიდებელი მუსიკის ჩართვა ან მისთვის «ძილის მეგობრის» (რბილი სათამაშოს) შეძენა შეიძლება სასარგებლო იყოს. გარდა ამისა, დაძინებამდე სულ მცირე ორი საათით ადრე უნდა გამორთოთ ტელევიზორი, ტელეფონი და სხვა მსგავსი მოწყობილობები. ეკრანზე ნანახმა წამიერმა კადრებმა შეიძლება ქვეცნობიერად გააძლიეროს შიში და ძილის ხარისხი გააუარესოს.') WHERE id = 'd586b6dd-dba7-499f-a5f6-07d3a6c2087c';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ პერიოდში თქვენი შვილის ენერგიისა და საკვები ნივთიერებების ყოველდღიური მოთხოვნილება მაღალია. ეს დაკავშირებულია არა მხოლოდ ზრდასთან, არამედ იმასთანაც, რომ ის მთელი დღის განმავლობაში ძალიან აქტიურია. თუმცა, ბავშვებს ერთ ჯერზე დიდი ულუფების მიღება არ შეუძლიათ. ამ ასაკში გარკვეულ საკვებზე უარის თქმა, მეტისმეტი პრეტენზიულობა და მხოლოდ რამდენიმე სახეობის საკვების ჭამის სურვილი საკმაოდ გავრცელებული და დროებითი პრობლემაა. მიუხედავად იმისა, რომ თქვენს შვილს შეიძლება მადა ნაკლებად ჰქონდეს, ჩვეულებრივ, ერთ-ერთ კვებაზე კარგად ჭამს, საჭირო ენერგიას კი კვებებს შორის წახემსებით ივსებს. თუმცა, ძირითად კვებებს შორის ბავშვს არ უნდა მისცეთ ისეთი მაღალკალორიული პროდუქტები, როგორებიცაა ორცხობილა, კრეკერი, ტკბილეული, გაზიანი სასმელები და შოკოლადი. ამან შეიძლება სასარგებლო საკვების მიმართ უმადობა, ჭარბი წონა და მხოლოდ ცარიელი კალორიების მიღება გამოიწვიოს.') WHERE id = 'df828bef-6a35-4e81-bf54-f27cccf0eaf6';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ორი წლის შემდეგ ბავშვები, როგორც წესი, დღისით დაძინებას ეწინააღმდეგებიან. თუ თქვენც ამ პრობლემას აწყდებით, უპირველეს ყოვლისა, მას გაგებით უნდა მოეკიდოთ. ეს 2-3 წლის ბავშვებში გავრცელებული მდგომარეობაა, რომელსაც «ძილის რეგრესი» ეწოდება და განვითარების ნაწილია. ასეთ დროს ბავშვთან გაჯიუტება შედეგს არ გამოიღებს — პირიქით, მას უფრო მეტად გააჯიუტებს. ეცადეთ, ბავშვი ძილის წინ ზედმეტად არ გადაიღალოს. გავრცელებულია მოსაზრება, რომ დაღლილი ბავშვი უფრო სწრაფად დაიძინებს, თუმცა სინამდვილეში გადაჭარბებული დაღლილობა ბავშვებში დაძაბულობასა და ტირილს იწვევს, რაც ჩაძინებას ართულებს. გახსოვდეთ, რომ ზედმეტ დაღლილობას ძილი არ მოაქვს — პირიქით, ის უძილობასა და მოუსვენრობას იწვევს.') WHERE id = '8f507486-74e1-4930-a39d-bd0f1f3a9dd1';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ თვეებში თქვენი ბავშვი ცნებებისა და საგნების გონებაში აბსტრაქტულად წარმოდგენას იწყებს. დროის აღქმის ჩამოყალიბებასთან ერთად, ის გარკვეული მოვლენების დამახსოვრებასაც უკეთ ახერხებს და მისი კონცენტრაციის უნარიც გაზრდილია. შეიძლება შეამჩნიოთ, რომ მისთვის საინტერესო ამბავს ან საგანს რამდენიმე დღის ან თუნდაც კვირის შემდეგ გიყვებათ, ან მსგავსი მოვლენის დროს გახსენებთ. ამ პერიოდში თქვენი შვილისთვის შეგიძლიათ შეიძინოთ სამთვლიანი ველოსიპედი, ბავშვებისთვის განკუთვნილი საღებავები, მუსიკალური ინსტრუმენტები, როგორიცაა დოლი, დაფდაფი და სალამური, ასევე ბურთები. ამასთანავე, საოჯახო საქმეების მიბაძვისთვის შესაფერისია სათამაშო სამზარეულოს ნაკრები, სათამაშო ხელსაწყოების ნაკრები, ისეთი ზომის ასაწყობი სურათები (ფაზლები) და ლეგოს დეტალები, რომლებსაც ვერ გადაყლაპავს, ავტომობილები, ინტერაქტიული და ფერადი წიგნები და გეომეტრიული ფიგურები. ისინი აჩქარებს როგორც ფიზიკურ, ისე გონებრივ განვითარებას. აუცილებლად უნდა შეამოწმოთ, რომ შეძენილი სათამაშოები და შემოქმედებითი მასალები თქვენი ბავშვისთვის უსაფრთხოა.') WHERE id = '64a38c2b-47fb-49f6-b66e-e941b4f59ce1';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'შეიძლება შეამჩნიოთ, რომ თქვენს შვილს ტირილის შეტევები და უცხო ადამიანების მიმართ სიფრთხილე უკვე ნაკლებად ახასიათებს. ამ პერიოდში თქვენი სათვალე ან ჩანთა მისთვის ზრდასრულობის სიმბოლოა და ძალიან მოსწონს. ასეთი თამაშები მას ცხოვრების შეცნობაში ეხმარება. სათამაშოებით თქვენსა და საოჯახო საქმიანობებს ბაძავს და როლური თამაშები უყვარს. ამისთვის შეგიძლიათ დროებით თქვენი ნივთებიც მისცეთ. რადგან საოჯახო საქმეების მიბაძვა მისი ერთ-ერთი საყვარელი როლია, მას ზრდასრულივით საჭმლის მომზადება და სახლის დალაგება მოუნდება. ზრდასრულების მიბაძვით საკუთარი თავის სხვის ადგილას წარმოდგენა თქვენი შვილისთვის ერთ-ერთი ყველაზე მნიშვნელოვანი თამაშია. ის შეეცდება, თითქმის ყველა იმ ადამიანის როლი მოირგოს, ვისაც აკვირდება. თუმცა ჯერჯერობით ისეთი კონკრეტული პროფესიებით, როგორიცაა ჯარისკაცი ან ბორტგამცილებელი, არ დაინტერესდება. ამის ნაცვლად შეგიძლიათ თქვენი ძველი ჩანთა, სათვალე ან ფეხსაცმელი მისცეთ. ასეთი როლური თამაშები მას სამყაროს აღმოჩენაში ეხმარება და მისი წარმოსახვის სწორად განვითარებას უწყობს ხელს.') WHERE id = 'df956a39-da9f-4532-82ec-209edcca5b25';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ კვირებში თქვენმა ბავშვმა შესაძლოა უკვე დაიწყოს მრავლობითი რიცხვის ნიშნებისა და სიტყვების სწორად გამოყენება. საშუალოდ მას შეუძლია დაახლოებით 300 სხვადასხვა სიტყვის თქმა, საკუთარი სქესის, ასაკისა და სახელის დასახელება და მოვლენების თანმიმდევრულად გადმოცემა. თუმცა ეს მაჩვენებლები შეიძლება იმის მიხედვით შეიცვალოს, თუ რამდენად აქტიურად ხართ ჩართული თქვენი შვილის მეტყველების განვითარებაში. ბავშვის მეტყველების უნარები, რომელიც დროის დიდ ნაწილს ტელევიზორთან ან პლანშეტთან ატარებს, განსხვავდება იმ ბავშვის უნარებისგან, რომელიც ამ მიმართულებით ხშირად არის ჩართული სხვადასხვა აქტივობაში. თქვენი შვილის მეტყველების გასავითარებლად შეგიძლიათ მასთან ერთად იცეკვოთ, იმღეროთ და მუსიკას მოუსმინოთ. დააკვირდით, როგორ გრძნობს რიტმს, რადგან რიტმის შეგრძნება თანდაყოლილია. სიმღერის ტექსტის წარმოთქმასა და მუსიკის დამოუკიდებლად შექმნას კი დროთა განმავლობაში ისწავლის.') WHERE id = '4c057f5d-1f83-4813-a64a-8ad2927711c6';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი შვილის ჯანმრთელობისთვის ერთფეროვანი კვება საკმარისი არ არის. ყოველდღე ოთხივე ძირითადი საკვები ჯგუფიდან სხვადასხვა პროდუქტი შესთავაზეთ — მაშინაც კი, თუ თავდაპირველად მათ მიღებაზე უარს იტყვის. დროთა განმავლობაში შეეჩვევა და მისი კვებაც დაბალანსებული გახდება. ყურადღება მიაქციეთ, რომ კვების საათები რეგულარული იყოს და უპირატესობა მაღალი კვებითი ღირებულების პროდუქტებს მიანიჭეთ. თქვენი შვილისთვის, რომელმაც ცოტ-ცოტა და ხშირად უნდა ჭამოს, უმჯობესია პატარა თეფშებზე მცირე ულუფები მოამზადოთ. ასევე განსაკუთრებით მნიშვნელოვანია მასთან ერთად სუფრასთან დაჯდომა, სამზარეულოში საქმეების ერთად კეთება და სუფრის ერთობლივად გაწყობა. თუ თქვენი შვილი რომელიმე მნიშვნელოვან საკვებზე უარს ამბობს, შეგიძლიათ ის სხვა, მსგავსი კვებითი ღირებულების პროდუქტით ჩაანაცვლოთ. მაგალითად, კალციუმი ძალიან მნიშვნელოვანია ძვლებისა და კბილების ჯანმრთელობისთვის. თუ თქვენს შვილს რძის დალევა არ უყვარს, მის ნაცვლად შეგიძლიათ აირანი, ყველი, იოგურტი ან რძიანი მარცვლეულის ფაფა შესთავაზოთ.') WHERE id = 'f14350f9-b48d-4bfb-88a6-d4e850319819';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი როლი ბავშვის სოციალურ ცხოვრებასთან შეგუებაში ძალიან დიდია. მხარი დაუჭირეთ იმ საქმიანობაში, რომელსაც ენთუზიაზმით ასრულებს და ნუ ეტყვით ისეთ გულგამტეხ სიტყვებს, როგორიცაა „ამას ვერ შეძლებ“. ამან მომავალში შეიძლება თავდაჯერების ნაკლებობა გამოიწვიოს. ეცადეთ, თქვენი შვილი უფრო ხშირად იყოს თანატოლების გარემოცვაში და განუმტკიცეთ გაზიარების, ურთიერთდახმარებისა და ერთიანობის მნიშვნელობა. როცა გისმენთ და ამას ქცევითაც გამოხატავს, მადლობა გადაუხადეთ და უთხარით, რომ ეს კარგი საქციელია. რამდენი სათამაშოც არ უნდა ჰქონდეს, ის ყოველთვის თქვენთან ერთად თამაშს მიანიჭებს უპირატესობას. სახლში თქვენი მოქმედებების მიბაძვაც კი იმაზე მიუთითებს, რომ თავს უკვე დიდად გრძნობს. ამიტომ, სანამ რამეს გააკეთებთ, კიდევ ერთხელ დაფიქრდით, რადგან ახლა ის თქვენი ანარეკლია.') WHERE id = 'e8b1c2b9-b8f2-4e27-b070-1a99713d7661';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ პერიოდში თქვენმა ბავშვმა უკვე ძალიან კარგად იცის, როგორ უბიძგოს გარშემომყოფებს, მათ შორის თქვენც, სასურველი მოქმედებისკენ. შეიძლება შეამჩნიოთ, რომ ის სხვა ადამიანების განწყობით ინტერესდება და სურს გაიგოს, რატომ არის მეზობელი გაბრაზებული ან მამა მოწყენილი. მისთვის გასაგები ენით ახსნა დაეხმარება ბავშვს გააცნობიეროს, რომ ემოციები ბუნებრივია და მათზე საუბარი სწორია. ამ პერიოდში თქვენი პატარა ისეთი ფუნდამენტური ემოციური მოდელების ჩამოყალიბებას იწყებს, როგორებიცაა სიყვარული და ნდობა. მან იცის, რომ თქვენ და ოჯახის სხვა წევრები იცავთ და მის მხარეს ხართ. ეს მნიშვნელოვანი წარმოდგენები სწორედ ამ გაცნობიერების საფუძველზე, ცხოვრების პირველი ორი წლის განმავლობაში მის მიმართ თქვენი დამოკიდებულების წყალობით შეიძინა. მისთვის სიყვარულის გამოხატვა, საჭიროებებზე დროულად რეაგირება და უსაფრთხო გარემოს შექმნა ის უმთავრესი ფაქტორებია, რომლებიც ემოციების სწორად გააზრებაში ეხმარება.') WHERE id = 'e0588130-112a-43d1-a91a-610ac0b19398';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'მრავალმხრივი ინტელექტის თეორიის თანახმად, ადამიანს აქვს არა ერთი ტიპის ინტელექტი (IQ), არამედ ინტელექტის მრავალი სფეროსა და უნარის ერთობლიობა. ამ პერიოდში უკვე შეგიძლიათ დააკვირდეთ, ინტელექტის რომელი სფეროსკენ აქვს თქვენს ბავშვს უფრო ძლიერი მიდრეკილება. მაგალითად, თუ განვითარებული აქვს მიზეზშედეგობრივი კავშირების დამყარების, კითხვების დასმისა და აბსტრაქტული აზროვნების უნარი, მასში მათემატიკურ-ლოგიკური შესაძლებლობები უფრო მეტადაა გამოკვეთილი. თუ ვიზუალური კვლევის, განსხვავებების შემჩნევისა და წარმოსახვითი მსგავსებების პოვნისკენაა მიდრეკილი, მისი ვიზუალურ-სივრცითი შესაძლებლობები უფრო ძლიერია. თუ მუსიკალურ ფორმებს აღიქვამს, ერთმანეთისგან განასხვავებს და საკუთარ თავს მუსიკით გამოხატავს, მისი მუსიკალურ-რიტმული ანუ სმენითი ინტელექტი უფრო განვითარებულად მიიჩნევა. გარდა ამისა, თუ ბავშვი გრძნობებისა და აზრების გამოსახატავად სხეულსა და ხელებს ხშირად იყენებს, შეგვიძლია ვთქვათ, რომ სხეულებრივ-კინესთეტიკური ინტელექტი გამოირჩევა. ეს უნარი შეიძლება გამოვლინდეს ხელების მუდმივად აქტიურად გამოყენებით რაიმე ახლის შექმნის, მოდელის აწყობის ან სათამაშო ცომისთვის სხვადასხვა ფორმის მიცემის სურვილში.') WHERE id = '9eabf6e3-daca-46d0-9e1c-7b73da5a85a6';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ისეთი საკვები, როგორიცაა ხორცი, ქათამი, თევზი, კვერცხი და პარკოსნები, მდიდარია ცილებით (პროტეინით). ისინი აუცილებელია კუნთების გაძლიერებისთვის, სისხლის წარმოქმნისთვის, ორგანიზმის ჯანსაღი ზრდისა და ჯანმრთელი ცხოვრებისთვის. კვებაში ცილების მნიშვნელობა ძალიან დიდია. თუმცა ზოგიერთი მშობელი ჩივის, რომ მათი ბავშვი ხორცს არ ჭამს. თუ თქვენს ბავშვს ხორცის ნაჭრების ჭამა არ სურს, შეგიძლიათ შესთავაზოთ კატლეტი, ქათამი, თევზი ან ფარშით მომზადებული პარკოსნების კერძები. თუ მას რომელიმე საკვები არ მოსწონს, ეს არ ნიშნავს, რომ განსხვავებული სახით მიწოდების ან მომზადების შემთხვევაში მას მაინც არ შეჭამს. მაგალითად, თუ თქვენი ბავშვი უმ პომიდორს არ ჭამს, მისი კვებითი საჭიროება შეგიძლიათ კერძებში მომზადებული პომიდვრის დამატებით დააკმაყოფილოთ. ამასთან, რძე, იოგურტი და ყველი კალციუმის, A ვიტამინისა და მაღალი ხარისხის ცილის წყაროა, რომლებიც აუცილებელია ძვლებისა და კბილების განვითარებისთვის, ასევე ნერვებისა და კუნთების გამართული მუშაობისთვის.') WHERE id = '00d733e5-f424-4abb-bd54-db1b13f18fb2';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვებში ხშირად გვხვდება ფუნქციური შეკრულობა. ეს არის მდგომარეობა, რომლის საფუძველშიც სერიოზული სამედიცინო მიზეზი არ დგას და რომელიც სხვადასხვა ფსიქოსოციალური ფაქტორითაა გამოწვეული. შეკრულობის გამომწვევი 5 ძირითადი ფაქტორია: ფსიქოსოციალური მიზეზები, კვებითი შეცდომები, საჭმლის მომნელებელი სისტემის სტრუქტურული პრობლემები, მედიკამენტების ზემოქმედება და ენდოკრინული დარღვევები. ფსიქოსოციალურ მიზეზებს მიეკუთვნება განავლის შეგნებულად შეკავება დეფეკაციის დროს ტკივილის გამო და ამის ჩვევად ქცევა. კვებით შეცდომებს მიეკუთვნება არასაკმარისი კვება, დღეში ნახევარ ლიტრზე მეტი ძროხის რძის მიღება, ბოჭკოვანი საკვებით (ბოსტნეულითა და ხილით) ღარიბი რაციონი და დამატებით კვებაზე გადასვლისას დაშვებული შეცდომები. საჭმლის მომნელებელი სისტემის სტრუქტურულ პრობლემებში იგულისხმება ანალური ნაპრალი (ნახეთქი), აბსცესი ან ანუსის თანდაყოლილი ატიპური მდებარეობა. შეკრულობა ასევე შეიძლება ზოგიერთი ანტიდეპრესანტის ან ანტიქოლინერგული მედიკამენტის ზემოქმედებამ გამოიწვიოს. ენდოკრინულ დარღვევებს შორის ყველაზე ხშირად ჰიპოთირეოზი გვხვდება. ამიტომ, თუ თქვენს ბავშვს ხშირად აქვს შეკრულობა, მნიშვნელოვანია, ექიმს მიმართოთ.') WHERE id = 'a1fca9a1-a5b5-4cd3-9585-094e87558f67';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვის მხედველობითი მეხსიერება უკვე იმდენად გაძლიერდა, რომ როდესაც რომელიმე ნივთს სადმე დებთ, ის თვალს გადევნებთ. თუ შემდეგ ამ ნივთს ვეღარ იპოვით, ბავშვმა შეიძლება მისი ადგილიც კი მიგითითოთ და დაგეხმაროთ. ეს მისი განვითარებისთვის ძალიან კარგი მაჩვენებელია. მან შეიძლება სცადოს, ქაღალდზე დახატოს ნანახი სურათი ან გარეთ დანახული რაიმე სცენა. ზოგჯერ ამას სრულყოფილად ვერ ახერხებს, თუმცა ეს აქტივობა ეხმარება, ისწავლოს ფანქრის სწორად დაჭერა და ფერების გარჩევა. ამასთან, ბავშვს მოუნდება, მისი ყურადღების მიმქცევი ობიექტი დაუყოვნებლივ გაგიზიაროთ. მაგალითად, როდესაც პეპელას დაინახავს, სურს, რომ თქვენც გაიზიაროთ მისი აღფრთოვანება, ამიტომ დაჟინებით გიჩვენებთ მას. დეტალები, პატარა ნივთები და განსაკუთრებით ის ნივთები, რომელთა აღების უფლებასაც არ აძლევთ, მის დიდ ინტერესს იწვევს. ის მათ მაშინვე იმახსოვრებს და პირველივე შესაძლებლობისას ცდილობს სასურველ ნივთამდე მისვლას.') WHERE id = 'f14124df-63d7-46de-a1b0-fb1bc90ef99c';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ პერიოდში თქვენი ბავშვის ენობრივი და მეტყველების უნარები განვითარების ახალ ეტაპზე გადადის. შესაძლოა, უკვე გარკვეული ხანია ამჩნევთ, რომ ბავშვი გრამატიკული პირის აღმნიშვნელი დაბოლოებების გარჩევით საუბრობს. ისეთი ნათესაობის აღმნიშვნელი სიტყვების გამოყენებით, როგორიცაა "დეიდა" და "ბიძა", ის აცნობიერებს, რომ ეს ადამიანები მისი ოჯახის წევრები არიან. გარდა ამისა, შესაძლოა, სიტყვები "დედა" და "მამა" უფრო სახალისოდ წარმოთქვას, რათა თქვენი ყურადღება მიიქციოს და თქვენთან მეტი ურთიერთობა ჰქონდეს. მას ესმის სიტყვების უარყოფითი ფორმა და იმის აღსანიშნავად, რომ რაიმე ნივთი მას ეკუთვნის, იყენებს ისეთ გამოთქმებს, როგორიცაა "ჩემია" ან "მამასია". თუმცა ამ თვეებში შესაძლოა ჯერ კიდევ აერიოს სიტყვები "შენი აზრით" და "ჩემი აზრით". ყველა ეს სიახლე მიუთითებს, რომ მეტყველების განვითარებაში მან საკმაოდ დიდი გზა გაიარა.') WHERE id = 'c55bb7ad-082f-45d6-afd3-b0c6f31390a4';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვის ჯანსაღი კვება ძალიან მნიშვნელოვანია ისეთი საჭმლის მომნელებელი პრობლემების თავიდან ასაცილებლად, როგორიცაა შეკრულობა და დიარეა, ასევე რკინის დეფიციტით გამოწვეული ანემიის პრევენციისთვის. ამ პერიოდში შეკრულობის თავიდან ასაცილებლად ბავშვს უნდა მისცეთ ბოსტნეულითა და ხილით მდიდარი, ბოჭკოვანი საკვები. ამასთან, ყურადღებით უნდა უზრუნველყოთ მისი მოთხოვნილება ცილებზე, ვიტამინებსა და მინერალებზე. თუ თქვენს ბავშვს ხორცი არ უყვარს, შეგიძლიათ შესაფერისი სახეობის ხორცი კატლეტის სახით, მოხარშული ან ბოსტნეულის კერძებსა და წვნიანებში დამატებული შესთავაზოთ. თქვენს ყოველკვირეულ მენიუში თევზი სულ მცირე ერთხელ უნდა იყოს. ბავშვმა ამ ჯგუფის საკვები დღეში 2-3 ულუფის ოდენობით უნდა მიიღოს. მთლიანობაში, დღის განმავლობაში 2 ჭიქა რძე (400-500 გრამი) და ასანთის კოლოფის ზომის ყველის ნაჭერი მის საჭიროებას დააკმაყოფილებს. კალციუმის ამაზე მეტი რაოდენობით მიღებამ შეიძლება ორგანიზმში სხვა მინერალების შეწოვაზე უარყოფითად იმოქმედოს.') WHERE id = 'e18a2773-f5ca-428b-953b-bdd7310cbd6f';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'პერიოდი, რომელსაც ახლა გადიხართ, თქვენი ბავშვისთვის ნამდვილ რევოლუციას ჰგავს. შესაძლოა, 2 წლის ასაკის კრიზისის ნიშნები ჯერ სრულად არ დასრულებულა, როცა 3 წლის ასაკის კრიზისის ნიშნები უკვე იწყება. ამ ახალ ეტაპზე მცირე სიახლეების შემოტანით შეგიძლიათ აჩვენოთ, რომ მისი გესმით, ან ყოველდღიური რეჟიმი ოდნავ შეცვალოთ. მაგალითად, თუ აქამდე ძილის მეგობარი (სათამაშო) არ შეგირჩევიათ, ახლა სწორედ ამის დროა! ძილის მეგობრად შეგიძლიათ აირჩიოთ რბილი სათამაშო, რომელსაც ბეწვი პირისა და ცხვირისკენ არ სცვივა და არ აქვს ღილები ან ჯაჭვები. ყურადღება მიაქციეთ, რომ სათამაშო ირეცხებოდეს და ჰქონდეს ისეთი მოსაკიდებელი ნაწილები, როგორიცაა ხელი, ყური ან კუდი. ძალიან მნიშვნელოვანია, ეს სათამაშო სხვა სათამაშოებთან ერთად არ შეინახოთ. ბავშვმა უნდა იგრძნოს, რომ ის ჩვეულებრივი სათამაშო კი არა, განსაკუთრებული მეგობარია, რომელიც მხოლოდ ძილის დროს არის მის გვერდით.') WHERE id = 'dad27d76-9b3f-4d94-805e-e4b144d944ca';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ტელევიზორი თქვენი ბავშვისთვის ვერასოდეს იქნება თქვენზე უკეთესი მომვლელი, მასწავლებელი ან თამაშის პარტნიორი. თუ ბავშვი ტელევიზორს უყურებს, საათობით მარტო კი არა, მცირე ხნით და თქვენთან ერთად უნდა უყუროს. მნიშვნელოვანია, რომ ეკრანთან გატარებული დრო დღეში ნახევარ საათს არ აღემატებოდეს. დარწმუნდით, რომ გადაცემები მის ასაკს შეესაბამება, შემეცნებითი და გასართობია. ტელევიზორის გადაჭარბებული ყურება ბავშვის სოციალურ აქტივობასა და უნარებს ზღუდავს. ბევრი მშობელი ენერგიული ბავშვის გასართობად ტელევიზორს რთავს. თუმცა ამ შემთხვევაში სათამაშოები უფრო სასარგებლოა. სათამაშოების შერჩევისას უმჯობესია უპირატესობა მიანიჭოთ ისეთ მოდელებს, რომლებიც ბავშვს ფიზიკური და გონებრივი აქტივობისკენ უბიძგებს და მის განვითარებად ინტელექტს ასტიმულირებს.') WHERE id = 'f2588707-ed76-4381-a46a-51f910d91358';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'კეთილი იყოს თქვენი და თქვენი ბავშვის მობრძანება 32-ე თვეში! 😊 32-ე თვეში გადასულ თქვენს ბავშვს უკვე მრავალი ახალი უნარი აქვს. მაგალითად, მას შეუძლია ფანქრით წრის დახატვა, თუმცა კვადრატისა და სამკუთხედის დასახატად ჯერ კიდევ დრო სჭირდება. მას შეუძლია პერანგი დამოუკიდებლად ჩაიცვას და გაიხადოს, თუმცა ხშირად უკუღმა იცვამს. ღილებიანი ტანსაცმლის შემთხვევაში კი შესაძლოა დახმარება დასჭირდეს. მას შეუძლია ცოტა ხნით ცალ ფეხზე დგომა და წინ თავისუფლად გადახტომა. შესაბამისი ზომის ბურთის როგორც სროლა, ისე დაჭერაც შეუძლია. რაც უფრო აქტიურია თქვენი ბავშვი, მით უფრო წარმატებით მოსინჯავს ახალ აქტივობებს, რომლებიც მის ფიზიკურ განვითარებას უწყობს ხელს. 32 თვის ბავშვი, ძილის დროის გარდა, 60 წუთზე მეტხანს უმოძრაოდ არ უნდა დარჩეს. დიდხანს ნუ დატოვებთ საბავშვო ეტლში ან მანქანის სავარძელში მჯდომარეს. თუ ხელში აყვანაზე ან ეტლში ჩაჯდომაზე უარს ამბობს, უსაფრთხო გარემოში დამოუკიდებლად სიარულის საშუალება მიეცით.') WHERE id = '70fac899-c576-4661-823a-c8e6d7ab1f20';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'მიუხედავად იმისა, რომ ამ ასაკის ბავშვების მშობლები ყველაზე ხშირად მათი განუწყვეტელი კითხვებითა და ლაპარაკით ჩივიან, ზოგი მშობელი იმასაც განიცდის, რომ მისი ბავშვი ჯერ კიდევ არ საუბრობს. თუ თქვენს ბავშვშიც ამჩნევთ მსგავს მდგომარეობას, ექიმთან მიმართვამდე რამდენიმე საკითხს უნდა მიაქციოთ ყურადღება. მათ შორის ყველაზე მნიშვნელოვანია მეტყველების განვითარების ოჯახური შეფერხება. თუ თქვენ ან თქვენმა მეუღლემ გვიან დაიწყეთ საუბარი, შესაძლოა ბავშვმაც გვიან დაიწყოს ლაპარაკი და ხშირად ამის უკან სერიოზული პრობლემა არ დგას. მეტყველების უნარების განვითარება შესაძლოა შეფერხდეს დღენაკლულ ან განვითარების შეფერხების მქონე ბავშვებშიც. სახლში ორ ენაზე საუბარმა, მარჯვენა და მარცხენა ხელის გამოყენებასთან დაკავშირებულმა გაურკვევლობამ, სმენის დაქვეითებამ, ენის მოკლე ლაგამმა, სასისა და ტუჩის ნაპრალმა და სხვა მსგავსმა პრობლემებმაც შეიძლება გამოიწვიოს ბავშვის თანატოლებთან შედარებით ჩამორჩენა. გარდა ამისა, ბავშვის გარემოში კომუნიკაციის ნაკლებობამ ან, პირიქით, მის მიმართ გადაჭარბებულმა მზრუნველობამაც შეიძლება საუბრის დაწყებას შეუშალოს ხელი. ხშირად ეს პრობლემა იმიტომ ჩნდება, რომ ბავშვს საუბრის შესაძლებლობა არ ეძლევა; შესაბამისი პირობების შექმნის შემდეგ კი პროგრესი მოკლე დროში ხდება შესამჩნევი.') WHERE id = '142a2085-8e97-430d-aa1a-76d048b9f3e3';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'რიტმის შეგრძნება, ისევე როგორც ყველა ბავშვს, თქვენს პატარასაც თანდაყოლილი აქვს. ამიტომ მასთან ერთად შეგიძლიათ მოუსმინოთ როგორც საბავშვო სიმღერებს, ისე თქვენთვის სასურველ ნებისმიერი ჟანრის მუსიკას. ენერგიის სწორად დასახარჯად შეგიძლიათ ერთად იცეკვოთ, იმღეროთ და რიტმს ტაში აჰყვეთ. თუ ბავშვს მელოდიის აწევისა და დაწევის შეგრძნებასა და სხეულის მოძრაობებით მის გამოხატვაში დაეხმარებით, ეს მის მუსიკალურ სმენას განავითარებს. როდესაც ნაცნობი სიმღერის ღიღინს დაიწყებს, შეგიძლიათ მიხვდეთ, რომ სხვა მუსიკალური ინსტრუმენტებისთვისაც მზადაა. სახლში არსებული ქვაბის ორი სახურავი ან უბრალო დოლი შეიძლება მუსიკალური ინსტრუმენტის როლში გამოიყენოთ. თუმცა ბავშვს შესაძლოა ისეთი ინსტრუმენტიც დასჭირდეს, რომლითაც ნამდვილ ბგერებს მოისმენს. ამ მხრივ, ბავშვებისთვის განკუთვნილი სასწავლო პიანინოს კლავიშებზე ან გიტარის სიმებზე შეხება და გამოცემული ბგერების გამეორება ორივესთვის ძალიან სახალისო იქნება.') WHERE id = '72d5321b-8667-4786-a0a9-55391cfc58eb';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ თქვენც ხშირად ამბობთ: „ჩემს ბავშვს ვერაფერს ვაჭმევ“ ან „საათობით მშიერი რომ იყოს, მაინც არ ადარდებს“, ნუ ინერვიულებთ. ამ ასაკში ბევრ დედას ერთი და იგივე პრობლემა აქვს: უმადობა ბავშვებში! მიუხედავად იმისა, რომ ბავშვის მადა ზრდის ტემპისა და ინდივიდუალური მდგომარეობის მიხედვით იცვლება, 1-3 წლის ასაკი განსაკუთრებით დაბალი მადის პერიოდია. ზოგ დღეს ბავშვის მიერ ცოტა, ზოგ დღეს კი ბევრი საკვების მიღება ამ ასაკისთვის ბუნებრივია. ამიტომ ზედმეტი ნერვიულობა საჭირო არ არის. გარდა ამისა, თუ ბავშვი მიჩვეულია მცირე ულუფებითა და ხშირად ჭამას, ამ გზით მიღებული საკვები ნივთიერებები შეიძლება ისეთივე სასარგებლო იყოს, როგორიც ძირითადი კვებისას მიღებული. თუმცა, თუ უმადობა დიდხანს გრძელდება და ბავშვი საკმარისად ვერ იმატებს წონას, მიზეზი შესაძლოა ნაწლავური პარაზიტები, ყაბზობა, ანემია ან საშარდე გზების ინფექცია იყოს. ასეთ შემთხვევებში აუცილებლად უნდა მიმართოთ ექიმს.') WHERE id = '8eb704da-d3e4-4f40-a1ec-24b231c52cba';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ თქვენს ბავშვს თანატოლებთან ერთად დააკვირდებით, ნახავთ, რომ ზოგი მარტო თამაშობს, ზოგი კი ჯგუფურად. მიუხედავად იმისა, რომ ამ პერიოდში ბავშვები უფრო ხშირად იწყებენ ერთად თამაშს, ზოგი მათგანი მარტო თამაშისას უფრო ბედნიერია. თუ თქვენს ბავშვს მარტო დროის გატარება მოსწონს, ნუ აიძულებთ სხვებთან თამაშს და ნუ ინერვიულებთ. მალე ისიც, სხვა ბავშვების მსგავსად, იპოვის თამაშის პარტნიორს და მეგობრობას ჩაუყრის საფუძველს. სოციალური განვითარების პროცესში ზოგ ბავშვს სხვებზე ბატონობისა და ზეწოლისკენ მიდრეკილება შეიძლება ჰქონდეს. დიქტატორული ქცევა ამ ასაკში საკმაოდ ხშირია. თუ თქვენს ბავშვს თანატოლების მიმართ მსგავს ქცევას ამჩნევთ, ძალიან მნიშვნელოვანია, მას ემპათიის — სხვის ადგილას საკუთარი თავის წარმოდგენის — უნარი განუვითაროთ.') WHERE id = '13173885-9e0a-4abe-ab99-a5202cd0d97c';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ თქვენი ბავშვი ამ პერიოდში თავს მზად გრძნობს და ბოლო დროს არ განუცდია ისეთი მკვეთრი ცვლილებები, როგორიცაა საცხოვრებლად გადასვლა, მშობლების განქორწინება ან ძუძუსგან მოშორება, შეგიძლიათ ტუალეტის ჩვევის სწავლებას შეუდგეთ. ამ პროცესის ყველაზე მგრძნობიარე მხარე ისაა, რომ იგი ემთხვევა ბავშვის „ეგოცენტრულ“ პერიოდს, როდესაც ის საკუთარ თავს ყველაფრის ცენტრად აღიქვამს. ამიტომ მისთვის რაიმე ახლის სწავლება შეიძლება რთული აღმოჩნდეს. ამავე პერიოდს ემთხვევა 3 წლის ასაკის კრიზისის ნიშნებიც, რის გამოც თქვენ შორის ავტორიტეტის საზღვრები შესაძლოა გამოცდის წინაშე დადგეს. ერთი მხრივ, წესების დაწესება, ხოლო მეორე მხრივ, მისი ტირილის ვერგაძლება ემოციურ სირთულეებს ქმნის. ამ პერიოდში გადაჭარბებულმა ზეწოლამ ბავშვში შეიძლება გამოიწვიოს თავდაჯერებულობის ნაკლებობა და ემოციების ჩახშობა. ამის თავიდან ასაცილებლად შეგიძლიათ ბავშვს მისცეთ ქვიშაში თამაშის, წყალთან შეხებისა და ბუნებაში ფეხშიშველი სირბილის შესაძლებლობა. ეს აქტივობები დაძაბულობას შეუმცირებს და მოდუნებაში დაეხმარება.') WHERE id = '56eba127-0922-4581-82f1-54a03ed676ef';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'რადგან თქვენი ბავშვის ხელით დაჭერის უნარი გაუმჯობესდა, მას უკვე უკეთ შეუძლია ფანქრის დაჭერა და ჩოგბურთის ბურთის მსგავსი პატარა ბურთებით თამაში. ამ მოქმედებების შესრულებისას ბავშვი თავისი კომფორტის მიხედვით აირჩევს, რომელ ხელს გამოიყენებს. ამ დროს ზოგიერთი მშობელი ცაცია ბავშვს შეიძლება მარჯვენა ხელით მოქმედება აიძულოს. თუმცა ეს სრულიად არასწორი მიდგომაა. რომელი ხელის გამოყენებას ანიჭებს ბავშვი უპირატესობას, ტვინის მუშაობის თავისებურებებით განისაზღვრება, ამიტომ ეს მისთვის ბუნებრივი და ჯანსაღი პროცესია. ამასთანავე, მოსალოდნელია, რომ ამ პერიოდში თქვენი ბავშვი სხვადასხვა ფიზიკურ უნარსაც განივითარებს. მაგალითად, შეიძლება სცადოს ერთ ფეხზე დგომა და ამას წარმატებითაც გაართვას თავი. მას უკვე მოუნდება ხელების დამოუკიდებლად დაბანა და ტანსაცმლის თავად ჩაცმა, რადგან საკუთარ ფიზიკურ განვითარებას გრძნობს. თუ ფართო და კომფორტულ ტანსაცმელს მისცემთ, ამ სურვილის განხორციელებისას წარმატების განცდასაც შეიგრძნობს.') WHERE id = 'b96b8dee-7314-45ef-8935-c7aceece6b06';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, '2 წლის ასაკიდან სკოლაში შესვლამდე დედების ერთ-ერთი ყველაზე ხშირი ჩივილი ისაა, რომ ბავშვები გამუდმებით ტკბილეულს ითხოვენ. შაქარი ერთ-ერთი ყველაზე კალორიული ნივთიერებაა, რომელსაც არანაირი კვებითი ღირებულება არ გააჩნია. ამ პერიოდში ასეთი საკვების მიღებამ თქვენს შვილს მომავალში სხვადასხვა დაავადებისადმი მიდრეკილება შეიძლება გაუზარდოს. ამიტომ სახლში რაც შეიძლება ნაკლები შაქრის შემცველი პროდუქტი უნდა გქონდეთ, რათა ბავშვმა ისინი ადვილად ვერ იპოვოს და ვერ შეჭამოს. ტკბილის სურვილის დასაკმაყოფილებლად შეგიძლიათ ხილი მისთვის ხელმისაწვდომ ადგილას დადოთ. როგორც ზოგიერთი მშობელი ხშირად იქცევა, შოკოლადი და კანფეტი ჯილდოდ არ უნდა გამოიყენოთ. ბავშვის ჯანმრთელობისთვის სახლში მომზადებულ კექსებსა და ორცხობილებში შაქრის ნაცვლად შეგიძლიათ ხილი დაამატოთ და ისინი უფრო სასარგებლო გახადოთ.') WHERE id = 'da4edbe5-0e9f-475e-b94c-678be057a584';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი შვილი უკვე უფრო სოციალურად იქცევა, უცნობი ადამიანების მიმართ მისი მორცხვობა და შიში კი მცირდება. მას შეუძლია მეგობრებს სათამაშოები გაუზიაროს და მათთან ერთად ითამაშოს. შეიძლება დივნის ბალიშებიც კი აიღოს, პატარა სახლი მოიწყოს, საკუთარი სივრცე შექმნას და იქ მხოლოდ თავისი მეგობრების მიწვევა მოინდომოს. ნორმალურია, თუ ამ პროცესში თქვენს ჩართვას არ ისურვებს, რადგან ამ სივრცის უფროსი თავადაა. ამ პერიოდში ბავშვს ფერადი ფანქრებისა და ხატვის მიმართ ინტერესიც უმძაფრდება. მიეცით სუფთა ფურცლები და საღებავები, რათა თავისი წარმოსახვა ქაღალდზე გადაიტანოს. ეს მის მსოფლმხედველობას გააფართოებს. თუმცა ყურადღებით იყავით, რადგან ამ ასაკში ბავშვების მიერ კედლებისა და ავეჯის მოხატვა მშობლების ერთ-ერთი ყველაზე დიდი საზრუნავია. 😊') WHERE id = 'b23ce050-0379-4aa6-b489-85355e97ec2f';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'შეიძლება შეამჩნიოთ, რომ თქვენი ბავშვი განსაკუთრებით ღამით, ჩაძინებიდან გარკვეული დროის შემდეგ, ყვირილით იღვიძებს. ღამის შიში, რომელსაც ძილის ტერორსაც უწოდებენ, ძილის დარღვევაა. ეს მდგომარეობა, როგორც წესი, ძილის nREM ფაზაში, ბავშვის ჩაძინებიდან დაახლოებით 90 წუთის შემდეგ ვითარდება. ის 2.5-3 წლის ასაკიდან მოზარდობის პერიოდამდე გვხვდება და მშობლებს ხშირად კოშმარებში ერევათ. თუ თქვენს შვილს ღამის შიშის ეპიზოდები აქვს, უპირველეს ყოვლისა, სიმშვიდე შეინარჩუნეთ. ეს ეპიზოდები შეიძლება რამდენიმე წუთიდან 20 წუთამდე გაგრძელდეს. დამშვიდების შემდეგ ბავშვი თანდათან კვლავ ჩვეულებრივ ძილს დაუბრუნდება.') WHERE id = '076a6ccb-3a8e-4030-a673-d4b097978807';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'გთავაზობთ სახალისო აქტივობას, რომელიც თქვენს შვილს საგნების ერთმანეთთან დაკავშირების, პრობლემების გადაჭრისა და შეხებით აღქმის უნარების განვითარებაში დაეხმარება! 😊 ჩვენი დღევანდელი თამაშია: რა არის ტომარაში? ამისთვის დაგჭირდებათ გაუმჭვირვალე ტომარა, ბავშვის სათამაშოები და სახლში არსებული რამდენიმე პატარა ნივთი. ნივთები ტომარაში მოათავსეთ და პირი მოუკარით. ძალიან მნიშვნელოვანია, რომ ტომარაში ჩახედვა შეუძლებელი იყოს. სთხოვეთ თქვენს შვილს, ხელი ტომარაში ჩაყოს და იქ მოთავსებული საგნების ფორმები შეხებით შეიგრძნოს. ჰკითხეთ, რას გრძნობს და რა ნივთი შეიძლება იყოს ეს. თუ გაუჭირდება, შეგიძლიათ მცირე მინიშნებები მისცეთ იმის შესახებ, თუ რისთვის გამოიყენება ეს ნივთი. Anacan-ის ოჯახი გაძლევთ გარანტიას, რომ ამ აქტივობის წყალობით შვილთან ერთად ხარისხიან დროსაც გაატარებთ და ძალიანაც გაერთობით! 😊') WHERE id = 'ebefcc6f-edb8-4dbf-a46a-4627d454ebec';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'იმისთვის, რომ თქვენს ბავშვს რეგულარული კვების ჩვევა ჩამოუყალიბდეს, რამდენიმე საკითხს უნდა მიაქციოთ ყურადღება. მათგან ყველაზე მნიშვნელოვანია, გაითვალისწინოთ ის დრო, როდესაც ბავშვი მეტისმეტად დაღლილი და ძილიანია. ასეთ მდგომარეობაში მას შეიძლება მადა არ ჰქონდეს და ჭამაზე უარი თქვას. სუფრასთან დაჯდომამდე ბავშვთან თამაშმა შესაძლოა განწყობა აუმაღლოს და საკვების მიმართ მისი წინააღმდეგობა შეამციროს. კვებებს შორის ბავშვს არავითარ შემთხვევაში არ უნდა მისცეთ შაქარი, შოკოლადი, ნამცხვარი, გაზიანი და სხვა მეტისმეტად ტკბილი სასმელები. მზა ხილის წვენის ნახევარი ჭიქაც კი შეიძლება მადის დაკარგვის მიზეზი გახდეს. ჭამის დროს კი არ უნდა დააძალოთ საკვები. გავრცელებული მოსაზრების საპირისპიროდ, დაჯილდოება ან დასჯა კვებით ჩვევებზე უარყოფითად მოქმედებს. გარდა ამისა, უფროსი და-ძმებისა და ოჯახის ზრდასრული წევრების სუფრასთან არდაჯდომამ ან საკვების არჩევით ჭამამ შესაძლოა თქვენს ბავშვს ცუდი მაგალითი მისცეს. ამიტომ ჭამის დროს, შეძლებისდაგვარად, ოჯახის ყველა წევრი სუფრასთან უნდა იჯდეს.') WHERE id = 'b0de3f60-3586-4525-93f5-131c4993a7dc';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ პერიოდში ბუნებრივი მოთხოვნილების დაკმაყოფილების შემდეგ თქვენმა ბავშვმა შეიძლება ძლიერი სევდა და შფოთვა იგრძნოს. სინამდვილეში, ეს სრულიად ნორმალური რეაქციაა. რადგან ბავშვი ჯერ საკმარისად დიდი არ არის, დეფეკაციისას შეიძლება იფიქროს, რომ მის სხეულს რაღაც ნაწილი მოსწყდა. შედეგად, ის შიშობს, რომ შესაძლოა სხეულის სხვა ნაწილებიც, მაგალითად, ხელი ან ფეხი დაკარგოს. ასეთ სიტუაციებში ბავშვს არავითარ შემთხვევაში არ უნდა მოექცეთ მკაცრად და დაჟინებით არ უნდა უმეოროთ: „არა!“ ან „ნუ გეშინია!“ ამის ნაცვლად, შეეცადეთ მისთვის გასაგები ენით აუხსნათ ამ პროცესის ფიზიოლოგია. შეგიძლიათ უთხრათ, რომ ეს მიღებული საკვების ნარჩენია, უნიტაზი კი ნაგვის ურნას შეადაროთ. შეგიძლიათ საშუალება მისცეთ, საფენში დარჩენილი განავალიც ნახოს. შემდეგ კი ერთად გადააგდოთ ის ნარჩენების ურნაში ან უნიტაზში.') WHERE id = '8c882e96-3609-47c5-bc42-d3ee39abdda4';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის განვითარების ამ ეტაპზე შეიძლება შეამჩნიოთ, რომ სქესის მიუხედავად, ის საოჯახო საქმეებში დახმარებას ცდილობს. ამ პერიოდში თქვენი და გარშემო მყოფი ადამიანების მიბაძვა ბავშვის განვითარების ბუნებრივი ნაწილია. ამ გზით ის გაუცნობიერებლად სწავლობს, სად და როგორ უნდა მოიქცეს. ამ მხრივ თქვენ და გარშემო მყოფ სხვა ადამიანებს მნიშვნელოვანი პასუხისმგებლობა გეკისრებათ. საკუთარ ქცევას ყურადღება უნდა მიაქციოთ; თუ ბავშვი ვინმესგან მისი ასაკისთვის შეუფერებელ ცუდ სიტყვას გაიგონებს, მაშინვე დაიწყებს მის გამეორებას. ამიტომ ჩვეულებრივზე მეტად ყურადღებით უნდა იყოთ. როდესაც ბავშვს საოჯახო საქმეებში თქვენი დახმარება სურს, ხელის შეშლის ნაცვლად დარწმუნდით, რომ საკუთარ თავს არ დაიზიანებს. მოკლედ, ნაცვლად იმისა, რომ უთხრათ: „თავს დაიზიანებ, ნუ აკეთებ!“, შეგიძლიათ გაამხნეოთ და უთხრათ: „თუ ფრთხილად იქნები, გამოგივა!“') WHERE id = 'a8b1ba6a-e9b7-4b18-8bee-81c98164dc1d';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'კვლევები აჩვენებს, რომ ბავშვები, რომლებსაც შაქრის გემო ჯერ არ გაუსინჯავთ, სკოლის ასაკამდე შეიძლება მოვარიდოთ ხელოვნურად დამატკბარ საკვებს, როგორიცაა ორცხობილა, შოკოლადი და ნამცხვარი. შაქარი მნიშვნელოვანია ბავშვის განვითარებისა და დღის განმავლობაში საჭირო ენერგიის მისაღებად. თუმცა, ნაცვლად იმისა, რომ ეს მოთხოვნილება არავითარი კვებითი ღირებულების მქონე მარტივი შაქრით დააკმაყოფილოთ, ბავშვის ნახშირწყლების საჭიროება შეგიძლიათ სახლში ბადაგით ან თაფლით მომზადებული კექსით, ორცხობილითა და მსგავსი საკვებით შეავსოთ. სკოლის წლებში, სხვა ბავშვებთან ურთიერთობისას, მას ასეთი საკვები უნებლიეთ მაინც შეხვდება. თუმცა მნიშვნელოვანია, რომ ამ ასაკამდე მისთვის უკვე გქონდეთ ჩამოყალიბებული სწორი კვების ჩვევები. რაც უფრო მეტად იქნება თქვენი ბავშვი მიდრეკილი ტკბილი საკვებისკენ, მით უფრო გაიზრდება მომავალში ჯანმრთელობის პრობლემების განვითარების რისკი. ამიტომ ძალიან მნიშვნელოვანია, ჩვევების ჩამოყალიბების ამ პერიოდში დათმობაზე არ წახვიდეთ.') WHERE id = '35e2d7ef-3499-43c9-ac1b-a5604e2b87d4';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ადრე მიიჩნეოდა, რომ ტვინის განვითარება მხოლოდ გენეტიკურ ფაქტორებზე იყო დამოკიდებული. თუმცა ბოლო დროს მეცნიერები მივიდნენ დასკვნამდე, რომ გარემო ფაქტორები ტვინის განვითარებაში მნიშვნელოვან როლს ასრულებს. თითოეული ბავშვი დაახლოებით 100 მილიარდი ნერვული უჯრედით იბადება. ცხოვრების შემდგომ ეტაპებზე ახალი ნერვული უჯრედები აღარ წარმოიქმნება. ამიტომ ბავშვთან ხარისხიანად გატარებული ყოველი წუთი მისი მომავალი წარმატებისთვის დათესილი თესლია. კვლევებით დადასტურებულია, რომ სიტყვიერი, ვიზუალური და სმენითი სტიმულები დადებითად მოქმედებს ბავშვის ტვინისა და ინტელექტის განვითარებაზე. რაც უფრო მრავალფეროვანია ეს სტიმულები, მით მეტია მათი სარგებელი. ამიტომ ბავშვი შეძლებისდაგვარად ხშირად უნდა წაიყვანოთ ბუნებაში სასეირნოდ, მისცეთ ფერადი და ილუსტრირებული წიგნების დათვალიერების შესაძლებლობა და მასთან ერთად შემეცნებითი აქტივობებით დაკავდეთ.') WHERE id = 'ea041f70-a712-4618-a072-ebd4e18f986e';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ პერიოდში ბავშვის მარილის ყოველდღიური საჭიროება დაახლოებით 1500 მილიგრამია. ეს რაოდენობა დღეში 1.5 გრამ მარილს შეესაბამება. ჯანმოს მიერ დადგენილი ნორმების თანახმად, იოდირებული მარილის მიღება მნიშვნელოვანია ფარისებრი ჯირკვლის ჰორმონების წარმოქმნისთვის. მარილის სრულად ამოღებამ შესაძლოა თქვენს ბავშვში ჰორმონული დარღვევები, მათ შორის ჰიპოთირეოზი გამოიწვიოს. ამასთანავე, ნორმაზე მეტი მარილის მიღებამაც შეიძლება საშიში გართულებები გამოიწვიოს. მაშინაც კი, თუ მის საკვებს დამატებით მარილს არ აყრით, მზა შეფუთული პროდუქტების მიღების შემთხვევაში ბავშვი მისთვის საჭირო რაოდენობაზე გაცილებით მეტ მარილს იღებს. ჭარბი მარილის მიღება ორგანიზმში წყლის რაოდენობის შემცირებას და შედეგად გაუწყლოებას (დეჰიდრატაციას) იწვევს. ამიტომ ძალიან მნიშვნელოვანია, ბავშვი შეფუთულ პროდუქტებს მოარიდოთ და შეძლებისდაგვარად უპირატესობა სახლში მომზადებულ საკვებს მიანიჭოთ.') WHERE id = 'f91b2ae4-510c-4199-8db1-8954345d3297';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვის სკოლამდელ ასაკში განვითარებისთვის შეგიძლიათ სხვადასხვა სახალისო მონტესორის აქტივობა გამოიყენოთ. მონტესორის მეთოდის, რომლის შესახებაც ბევრ დედას დედობამდე არაფერი სმენია, სახლში მარტივად გამოყენებაა შესაძლებელი. ამისთვის ძვირადღირებული მასალები არ გჭირდებათ. პირიქით, მონტესორის აქტივობებში გამოიყენება ნივთები, რომლებსაც გარშემო ადვილად იპოვით. ამ მეთოდით თამაშად გარდაიქმნება საგნები, რომლებსაც ბავშვი ზრდის პროცესში ყოველდღიურად ხვდება, ინტერესით აკვირდება და სურს გაიგოს, როგორ მუშაობს. ამ ნივთებით თამაშისას ბავშვი რეალურად ივითარებს საბაზისო უნარებს, რომლებიც მთელი ცხოვრების განმავლობაში დასჭირდება. მაგალითად, სამზარეულოში ყოველდღიური საქმეების შესრულებისას იატაკზე სუფთა ქსოვილი დააფინეთ და მასზე სხვადასხვა ზომის ჩაის, დესერტისა და სუფრის კოვზები დააწყვეთ. სთხოვეთ ბავშვს, კოვზები პატარიდან დიდისკენ, შემდეგ კი პირიქით დაალაგოს. აი, ასე მარტივად! 😊') WHERE id = 'da312752-586a-4921-9553-2181d873da6f';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ პერიოდში მოსალოდნელია, რომ ბავშვმა გაიგოს ისეთი კითხვები, როგორიცაა „ეს რა არის?“, „ბურთი სად არის?“, „მე ვინ ვარ?“ და მათ გააზრებული პასუხები გასცეს. ჯანმრთელობის პრობლემების არმქონე ყველა ბავშვმა არაუგვიანეს 36 თვის ასაკისა უნდა შეძლოს 2 ან 3 სიტყვისგან შემდგარი წინადადებების შედგენა. თუმცა, თუ თქვენს ბავშვს ეს უნარები ჯერ არ აქვს, ეს ყოველთვის სერიოზულ პრობლემაზე არ მიუთითებს. მეტყველების დაგვიანება ნიშნავს, რომ ბავშვს თანატოლების მსგავსი მეტყველების უნარები არ აქვს. თუ ბავშვი ასაკის შესაბამისად არ მეტყველებს, ეს შეიძლება იყოს „მეტყველების დარღვევა“ ან „განვითარების შეფერხება“. მეტყველების დაგვიანების ერთ-ერთი უმნიშვნელოვანესი მიზეზი სმენის დაქვეითებაა. ის შეიძლება თანდაყოლილი ან შეძენილი იყოს. ამიტომ, თუ რაიმე გაწუხებთ, რეკომენდებულია სპეციალისტ ექიმთან მიმართვა.') WHERE id = '8b57d158-736c-4f31-9161-27c88480c843';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ერთ-ერთი საკითხი, რომელიც მშობლებს ყველაზე მეტად აბნევს, კოშმარებისა და ღამის შიშის (ღამის ტერორის) ერთმანეთისგან გარჩევაა. ეს მდგომარეობა, რომელიც ძილის შიშის დარღვევად ხასიათდება, ჩვეულებრივი კოშმარებისგან განსხვავდება. ამ დროს ბავშვი ჩაძინებიდან დაახლოებით 90 წუთის შემდეგ მოულოდნელად იღვიძებს და ყვირილს იწყებს. ღამის ტერორი შემდეგი ნიშნებით შეგიძლიათ ამოიცნოთ: ბავშვი შეიძლება საწოლში წამოდგეს ან უმიზნოდ გაქცევა სცადოს. ის ძალიან შეშინებული და გაოგნებული ჩანს, ყვირის და გაურკვეველ ხმებს გამოსცემს. დამშვიდების მცდელობის მიუხედავად, ვერ გცნობთ, ნათქვამი არ ესმის და კითხვებს არ პასუხობს. შესაძლოა აღენიშნებოდეს გულისცემის გახშირება, სწრაფი სუნთქვა და ოფლიანობა. მიუხედავად იმისა, რომ ღამის ტერორი ბავშვს ფიზიკურ ზიანს არ აყენებს, თუ ის მუდმივ ხასიათს მიიღებს, შესაძლოა ფსიქოლოგიური გავლენა ჰქონდეს. ასეთ დროს თქვენი ამოცანაა, ბავშვს არ მისცეთ საკუთარი თავის ფიზიკურად დაზიანების საშუალება. მასთან შეხებამ ან ჩახუტებამ შესაძლოა შეტევა კიდევ უფრო გაამწვავოს.') WHERE id = '649c5984-28bb-41d3-857b-4e0043a7b040';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'შესაძლოა, თქვენს ბავშვს უკვე ამოსვლოდა ყველა სარძევე კბილი, რომელთა საერთო რაოდენობა 20-ია. თუ ჯერ ყველა არ ამოსულა, მომდევნო 1-2 თვის განმავლობაში მეორე სარძევე დიდი ძირითადი კბილებიც ამოვა. ამის შემდეგ პირველი მუდმივი კბილები იქნება პირველი დიდი ძირითადი კბილები, რომლებიც 6 წლიდან ამოდის. კბილების ამოსვლის პროცესში ბავშვს შესაძლოა აღენიშნებოდეს სხეულის ტემპერატურის მომატება, გულისრევა და დიარეა. ასევე ნორმალურია, თუ ამ პერიოდში ბავშვი უფრო მოუსვენარი გახდება და მადა შეუმცირდება. მეორე დიდი ძირითადი კბილის ამოსვლისას მოსალოდნელია ღრძილების გაწითლება და ნერწყვის გამოყოფის მატებაც. ამიტომ გარკვეული დროის განმავლობაში გაგებით უნდა მოეკიდოთ ბავშვის ჭამაზე უარსა და უმადობას.') WHERE id = '4caba1ee-fe4e-4f39-9676-eeb0deb3ad9f';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის ფიზიკური შესაძლებლობების ზრდამ ხელი შეუწყო მისი უნარების შემდგომ განვითარებას. ახლა ის უკვე საკმარისად ძლიერია, რომ კიბეზე თქვენი დახმარების გარეშე ავიდეს და ჩამოვიდეს. მისი ხელის მოძრაობები უფრო კოორდინირებულია და ხელებსაც უფრო ოსტატურად იყენებს. თუმცა, მიუხედავად იმისა, რომ თქვენს ბავშვს კიბეზე დამოუკიდებლად ასვლა შეუძლია, კვლავ სიფრთხილე გმართებთ. უსაფრთხოების მიზნით, აუცილებლობის გარდა, ის ზედამხედველობის გარეშე არ დატოვოთ. თქვენს ბავშვს, ისევე როგორც ყველა სხვა ბავშვს, საკუთარი შესაძლებლობების საზღვრების გასაგებად ზოგჯერ შეიძლება იმაზე მეტის გაკეთება მოუნდეს, ვიდრე შეუძლია. მაგალითად, შესაძლოა კიბეზე ორ-ორი საფეხურის გამოტოვებით ასვლა ან ჩამოხტომით ჩამოსვლა სცადოს.') WHERE id = '84c09dfd-750f-4d20-9c62-31f373486223';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'მსოფლიოსა და ჩვენს ქვეყანაში ყველაზე გავრცელებული საყოფაცხოვრებო უბედური შემთხვევების დაახლოებით 44% დაცემით არის გამოწვეული. თუ მრავალსართულიან სახლში ცხოვრობთ, არ დაგავიწყდეთ კიბის თავსა და ბოლოში შესაბამისი დამცავი ბარიერების ან უსაფრთხოების ჭიშკრების დამონტაჟება. ფანჯრიდან გადმოვარდნაც ბავშვებში ერთ-ერთი ხშირად გავრცელებული უბედური შემთხვევაა. მწერებისგან დამცავი ბადეები თქვენი ბავშვის დასაცავად საკმარისი არ არის. თუ განსაკუთრებით ამ პერიოდში ენერგიით სავსე ბავშვისთვის სრული უსაფრთხოების უზრუნველყოფა გსურთ, ფანჯრებზე სპეციალური დამცავი ეკრანები შეგიძლიათ დაამონტაჟოთ. ასევე შეეცადეთ, ავეჯი, რომელზეც ბავშვმა შეიძლება აძრომა შეძლოს, ფანჯრებისგან მოშორებით დადგათ. დაცემის კიდევ ერთი მიზეზი იატაკის სრიალა ზედაპირია. საფრთხის შესამცირებლად სახლში არსებულ ხალიჩებს ქვემოდან მოცურების საწინააღმდეგო საფენები დაუფინეთ. მაგიდებისა და თაროების კუთხეებზე დამცავების დამაგრებით შესაძლო დაზიანებების თავიდან აცილებასაც შეძლებთ.') WHERE id = '8d8068ce-d413-4155-9f05-19664d00e5b9';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'შეიძლება შეამჩნიოთ, რომ ამ პერიოდში თქვენი ბავშვის თანატოლებისადმი დამოკიდებულება იცვლება. მან შესაძლოა უკვე დაიწყოს თანატოლებთან ჯგუფურად თამაში, თუმცა ჯერ კიდევ არ სურდეს სათამაშოებისა და ნივთების სრულად გაზიარება. ეს სიძუნწედ კი არა, ამ ასაკისთვის დამახასიათებელ თავისებურებად უნდა აღიქვათ. დროთა განმავლობაში ის გაზიარებას უკეთ ისწავლის. მიეცით ცოტა დრო და ნუ აიძულებთ, რადგან თქვენი ბავშვი კიდევ გარკვეული ხნის განმავლობაში საკუთარ თავს სამყაროს ცენტრად აღიქვამს. ამ პერიოდში მას შესაძლოა ემოციებიც ხშირად ეცვლებოდეს. შეიძლება ძალიან ბედნიერი იყოს, მაგრამ თუ მისთვის არასასურველი რამის გაკეთება მოუწევს, უცებ გაბრაზდეს. მართალია, ძლიერი ბრაზის შეტევების პერიოდი მეტწილად უკვე უკან მოიტოვეთ, თუმცა ეს არ ნიშნავს, რომ ისინი მთლიანად დასრულდა — ზოგჯერ მსგავსი შემთხვევები კვლავ შეიძლება განმეორდეს.') WHERE id = 'a6115683-f3cb-4edb-9c84-9bf3b5c64952';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ ამჩნევთ, რომ თქვენს ვაჟს სათესლე ჯირკვლები ან თქვენს ქალიშვილს სარძევე ჯირკვლები ეზრდება, რამდენიმე საკითხს ყურადღება უნდა მიაქციოთ. სქესობრივი მომწიფება ბიოლოგიური ეტაპია, რომელიც ბავშვობიდან ზრდასრულ ასაკში გადასვლისას მიმდინარე ჰორმონულ და ფიზიკურ ცვლილებებს მოიცავს. სქესობრივი მომწიფების ნორმალური ასაკი გოგონებში 9-11, ხოლო ბიჭებში 10-12 წელია. თუ განვითარება გოგონებში 8, ხოლო ბიჭებში 9 წლამდე იწყება, ეს ნაადრევ სქესობრივ მომწიფებად ითვლება. მისი პირველი ნიშანი გოგონებში სარძევე ჯირკვლების ზრდა, ბიჭებში კი სათესლე ჯირკვლების გადიდებაა. ბოლო წლებში საკვებში GMO-ს მატებისა და ჰორმონული ცვლილებების გამო ბავშვებში ნაადრევი სქესობრივი მომწიფების შემთხვევებმა იმატა. ამაზე გავლენას ახდენს გენეტიკური ფაქტორები, გეოგრაფიული პირობები, კვება და ჯანმრთელობის ზოგადი მდგომარეობა. ეს პრობლემა მკურნალობას ექვემდებარება, თუმცა უყურადღებოდ დატოვების შემთხვევაში შესაძლოა სერიოზული გართულებები გამოიწვიოს. ამიტომ ძალიან მნიშვნელოვანია, ყურადღებით დააკვირდეთ თქვენს ბავშვს.') WHERE id = '96217fde-5713-4fe7-acb8-719f4d28185d';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ პერიოდში შეიძლება შეამჩნიოთ, რომ თქვენი ბავშვი ზოგჯერ აგრესიულად იქცევა. თუმცა ამ ასაკში გამოვლენილი აგრესია, ჩვეულებრივ, მოგვიანებით ათვისებული ქცევაა. თუ ადრე მსგავსი შემთხვევები არ ყოფილა, შეგიძლიათ მათი მიზეზი გამოიკვლიოთ. მაგალითად, თუ ოჯახში ვინმე აგრესიულად იქცევა, დიდია ალბათობა, რომ ეს თქვენს ბავშვზეც იმოქმედებს. სწავლისადმი ძალიან მიდრეკილმა ბავშვმა შესაძლოა პარკში ან მაღაზიაში ნანახი აგრესიული ქცევაც კი დაიმახსოვროს. ამ პერიოდში ძალიან მნიშვნელოვანია, ბავშვი მსგავსი უჩვეულო და უარყოფითი ქცევისგან დაიცვათ. ამიტომ უნდა დააკვირდეთ ფაქტორებს, რომლებიც მასში აგრესიას იწვევს, და საჭიროების შემთხვევაში სპეციალისტს მიმართოთ.') WHERE id = 'f6c4c1fb-2085-4620-b3dd-958a42acbbb4';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ვიცით, რომ ამ პერიოდში თქვენი ბავშვი ძალიან აქტიურია. შეგიძლიათ ეს შესაძლებლობად აქციოთ! მაგალითად, მისთვის ისეთი მცირე დავალებების მიცემით, რომელთა შესრულებაც შეუძლია, პასუხისმგებლობის გრძნობის განვითარებაში დაეხმარებით. ამ პერიოდში თქვენი ბავშვი უკვე იწყებს თქვენი და სხვა ადამიანების ემოციების გაგებას და ხვდება, სჭირდებათ თუ არა მათ დახმარება. ამასთანავე, ბავშვს უკვე უყალიბდება მისთვის დამახასიათებელი ფობიები და შიშები, ამიტომ ახალი და განსხვავებული რამეების გამოცდა შესაძლოა მისთვის საშიში იყოს. ამ ცვლილებისთვის მზად უნდა იყოთ და დაეხმაროთ მას შფოთვის შემცირებაში. ამ პერიოდში ბავშვისთვის სტრესის ერთ-ერთი მთავარი მიზეზი თქვენთან განშორების შიშია. ამიტომ, როცა სადმე მიდიხართ, აუცილებლად უთხარით, როდის დაბრუნდებით. თუ დარწმუნებული იქნება, რომ დაბრუნდებით, შეძლებს თქვენ გარეშე უფრო დიდხანს დარჩენას.') WHERE id = '333574d8-98a5-4257-9524-278228cb207c';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ ეტაპზე თქვენს ბავშვს უკვე შეუძლია თქვენი დახმარების გარეშე თავისუფლად დაიბანოს და შეიმშრალოს ხელები და სახე. მისი ტერფებისა და ფეხების კუნთები ადრინდელთან შედარებით კიდევ უფრო გაძლიერდა, რაც თავისუფლად ხტომის საშუალებას აძლევს. რა თქმა უნდა, ამ პერიოდში ყველა ბავშვის ფიზიკური განვითარების შესაძლებლობები ერთნაირი არ არის. თქვენი ბავშვის სხვა ბავშვებთან შედარება არაფერში დაგეხმარებათ. გახსოვდეთ, რომ თითოეულ ბავშვს ქცევის საკუთარი სტილი და განსხვავებული პიროვნება აქვს. ეს განსხვავებები განსაკუთრებით 2 წლის შემდეგ ხდება უფრო შესამჩნევი. 3 წლის ასაკი, რომელშიც ახლა შედიხართ, სწორედ ის ეტაპია, როცა ეს განსხვავებები სრულად ვლინდება. ამიტომ ბავშვს მხარი უნდა დაუჭიროთ იმის გამო, რაც შეუძლია, და არა მხოლოდ ყურადღება გაამახვილოთ იმაზე, რაც ჯერ არ გამოსდის. თქვენი გამხნევება მას თავდაჯერებულობისა და საკუთარი თავის პატივისცემის ჩამოყალიბებაში დაეხმარება.') WHERE id = '2736628c-47d5-4efe-8544-30f307dcafe3';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, '6 წლამდე პერიოდი, როცა თქვენი ბავშვი სკოლაში წავა, ის დროა, როდესაც მისი კვების ჩვევები თითქმის სრულად ყალიბდება. ამ ასაკში შეძენილი ჯანსაღი კვების ჩვევები საფუძველს უქმნის იმას, რომ მომავალში ის უფრო ჯანმრთელი ადამიანი იყოს. კვების არარეგულარული დრო, ტკბილეული და არაჯანსაღი საკვები (fast food) იმის მაჩვენებლად ითვლება, რომ მომავალში თქვენს ბავშვს შესაძლოა სიმსუქნე განუვითარდეს. ბოლო 20 წლის განმავლობაში ჩატარებული კვლევები აჩვენებს, რომ ჭარბი წონის მქონე მშობლების შვილების დიდი ნაწილი იმავე პრობლემას ბავშვობაშიც და ზრდასრულ ასაკშიც აწყდება. ეს ადასტურებს, რომ ბავშვები ოჯახის კვების ჩვევებს პირდაპირ იმეორებენ. ბავშვებისთვის, რომლებიც სკოლამდელ ასაკში მავნე საკვებს ერიდებიან, ასეთი პროდუქტები მთელი ცხოვრების განმავლობაში კვების რაციონის ძირითად ნაწილად არ იქცევა. ამიტომ, თუ გსურთ, რომ თქვენს ბავშვს ჯანსაღი წონა ჰქონდეს, უპირველეს ყოვლისა, თავად უნდა იკვებოთ ჯანსაღად.') WHERE id = '70039ed8-6ea5-4eb9-9e14-4db990b7a7b1';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვის კბილების მოვლა ძალიან მნიშვნელოვანი საკითხია და განსაკუთრებულ ყურადღებას მოითხოვს. მიდგომამ — „მაინც სარძევე კბილებია და მოსძვრება!“ — და პირის ღრუს მოვლის უგულებელყოფამ შეიძლება ისეთი გართულებები გამოიწვიოს, როგორიცაა ღრძილების ანთება და კბილის კარიესი. ამის თავიდან ასაცილებლად ერთ-ერთი საუკეთესო ჩვევა, რომელიც შეგიძლიათ თქვენს ბავშვს გამოუმუშაოთ, კბილების რეგულარულად გაწმენდაა. კბილების გაწმენდასთან დაკავშირებული პირველი საშუალება, რომელიც გვახსენდება, კბილის პასტაა, თუმცა საწყის ეტაპზე მისი გამოყენება ბავშვებისთვის რეკომენდებული არ არის. ამ პერიოდში თქვენს ბავშვს შეუძლია კბილები პასტის გარეშე გაიხეხოს. ზოგიერთი სპეციალისტი კბილის პასტის გამოყენებას დაახლოებით 3 წლამდე არ ურჩევს. ამ ასაკის შემდეგ კი შეიძლება ბარდის მარცვლის ოდენობის კბილის პასტის გამოყენება. თქვენი ამოცანაა, ბავშვს მაგალითი მისცეთ და ჭამის შემდეგ და ღამით, დაძინებამდე, მასთან ერთად გაიხეხოთ კბილები. გახსოვდეთ, რომ თქვენი ბავშვი ამ ჩვევას თქვენი მიბაძვით შეიძენს.') WHERE id = '8d37727a-164c-4cf0-b23a-460dee8cf99d';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენს ბავშვთან ერთად უკვე 33 თვე გაიარეთ, გილოცავთ! 😊 ამ თვიდან, სიტყვების მარაგის ზრდასთან ერთად, მას საკუთარი აზრის უფრო თავისუფლად გამოხატვა შეუძლია. მისი მეტყველება დღითი დღე უმჯობესდება. ამ პერიოდში თქვენი ბავშვი სწორად იყენებს ნაცვალსახელებსა და კავშირებს და ხშირად იწყებს ისეთი კითხვების დასმას, როგორიცაა ვინ, რა, რატომ და სად. კითხვებზე „რატომ?“ და „რისთვის?“ შესაბამის პასუხებს სცემს. სურათებზე ადამიანებს ცნობს, შეუძლია მათზე მიგითითოთ და მათი სახელები თქვას. საუბრისას ხმის ტონის შეცვლა შეუძლია, ხოლო შეკითხვისას ამბობს თავის სახელს, ასაკსა და სქესს. თუ ასწავლეთ, შეუძლია 10-მდე რიცხვები ზეპირად დაითვალოს. საყვარელი ისტორიების მრავალჯერ მოსმენა არ ბეზრდება. მიუხედავად იმისა, რომ სხვებთან მარტივი დიალოგის წარმართვა შეუძლია, ზოგიერთი ბგერის არასწორად წარმოთქმა სრულიად ნორმალურია.') WHERE id = '0ad387e8-b68f-42e3-a771-8b717ee81176';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი 33 თვის ბავშვის მოძრაობითი უნარები უკვე მნიშვნელოვნად განვითარდა. ის ხელებისა და თითების გამოყენებაში საკმაოდ დახელოვნდა. სხვა სიტყვებით რომ ვთქვათ, ახლა ხელებით უფრო რთული მოქმედებების შესრულება შეუძლია. მას შეუძლია 5-6 კუბი მარტივად დააწყოს ერთმანეთზე, ითამაშოს 6-12-ნაწილიანი ფაზლებით და ბურთი ჰაერში ააგდოს. წონასწორობაც კარგად აქვს განვითარებული, ამიტომ შეუძლია მარტივად იდგეს ერთ ფეხზე და ბურთით ითამაშოს. მას თითქმის ყველა ნივთის შესწავლა და მათით თამაში შეუძლია. ხელებს თქვენი ბავშვის ტვინის მოტორულ და სენსორულ ცენტრებში ფუნქციურად ყველაზე დიდი ადგილი უკავია. ბავშვის მიერ ხელების ოსტატურად გამოყენების უნარი მისი ნერვული სისტემის განვითარების დონეს პირდაპირ უკავშირდება. ამიტომ ძალიან მნიშვნელოვანია, ბავშვთან ერთად ხშირად შეასრულოთ ისეთი აქტივობები, რომლებიც ნატიფ მოტორულ უნარებს ავითარებს.') WHERE id = '3bca3dac-612d-48d3-8788-6c23c8d4b4e8';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ პერიოდში თქვენს 33 თვის ბავშვს შეიძლება განსაკუთრებით გაუჩნდეს დიდი ინტერესი ისეთი საკვების მიმართ, როგორიცაა ჩიფსები, შოკოლადი და ორცხობილა. განსაკუთრებით მაშინ, თუ თანატოლები ამ პროდუქტებს მიირთმევენ, მასაც მოუნდება მათი გასინჯვა. ასეთ შემთხვევაში შეგიძლიათ ბავშვს მსგავსი გემოს საკვები უფრო ბუნებრივი პროდუქტებით მოუმზადოთ. მაგალითად, თუ ბავშვს ჩიფსები სურს, შეგიძლიათ ღუმელში მცირე რაოდენობის ზეთით კარტოფილის ნაჭრები მოუმზადოთ. ასევე შეგიძლიათ მისი სურვილი ბუნებრივი და ჯანსაღი მეთოდით მომზადებული ორცხობილით დააკმაყოფილოთ. მთავარი მიზანია, ბავშვმა მაღაზიებში გაყიდული მზა პროდუქტები არ მიიღოს. გაყინულმა მზა საკვებმა, ზედმეტად ტკბილმა სასმელებმა და ცხიმიანმა თუ მარილიანმა ჩიფსებმა მომავალში შეიძლება სიმსუქნის განვითარებას შეუწყოს ხელი. თქვენი ბავშვის კვების ამჟამინდელი რეჟიმი მის მომავალ ცხოვრებაზე ახდენს გავლენას. ამიტომ ამ პერიოდში გაწეული ძალისხმევა შეგიძლიათ თქვენი ბავშვის მომავალში ჩადებულ ინვესტიციად მიიჩნიოთ.') WHERE id = 'e6a1b900-7219-4ca0-ae6e-83f3e11c466a';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი უკვე განვითარების ახალ ეტაპზე გადავიდა. ამ პერიოდიდან 7 წლამდე ის ცხოვრებისთვის აუცილებელი საბაზისო უნარების ათვისებას იწყებს. მათ შორისაა აქტიურად და დახმარების გარეშე სირბილი, ხტომა, ცალ ფეხზე ხტუნვა, დაჭერა, სროლა და ბურთისთვის ფეხის დარტყმა. ამ უნარებს საბაზისოს უწოდებენ, რადგან ისინი თითქმის ყველა ბავშვისთვის ერთნაირი და სასიცოცხლოდ მნიშვნელოვანია. ამ თვეებში აღნიშნული მოძრაობები ჯერ კიდევ შედარებით მოუქნელია, რადგან ბავშვი თავდაპირველად საკუთარი სხეულის მოძრაობით შესაძლებლობებს ეცნობა და მათ მოსინჯვას ცდილობს. მოგვიანებით, სხეულზე კონტროლის გაძლიერებასთან ერთად, მისი მოძრაობები უფრო კოორდინირებული და მართვადი ხდება. ამ ეტაპის ბოლოს კი ბავშვი ამ მოძრაობებს მექანიკურად უფრო ეფექტიანად შეასრულებს. 5-6 წლის ასაკში საბაზისო უნარები სრულად ჩამოყალიბებული იქნება.') WHERE id = '35b98740-6814-45cf-ad4b-cc3187b7b7a4';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ გსურთ, განუვითაროთ თქვენს ბავშვს თავდაჯერებულობა, წარმატების განცდა, მცირე კუნთები, ფერების ცოდნა და ნაწილსა და მთლიანს შორის კავშირის აღქმა, შესანიშნავი შემოთავაზება გვაქვს: მძივების აცმის აქტივობა! ამ აქტივობისთვის დაგჭირდებათ: ფერადი შალის ძაფები, მსხვილხვრელიანი მძივები და იატაკზე დასაფენი შესაფერისი საფარი. ბავშვს ყურადღებით დააკვირდით და საშუალება მიეცით, მძივები ძაფზე ააცვას. ამ აქტივობისას თქვენი ბავშვი დაინახავს, როგორ შეიძლება ცალკეული მძივების გაერთიანებით ერთი ნივთი შეიქმნას, და ნაწილსა და მთლიანს შორის კავშირს გაიაზრებს. ამავდროულად, ეს სახალისო აქტივობა ძალიან სასარგებლოა ბავშვის ყურადღებისა და კონცენტრაციის გასაძლიერებლად. ის ასევე ხელს უწყობს ხელისა და თვალის კოორდინაციასა და დაწყებული საქმის დასრულების უნარის გამომუშავებას, რაც ბავშვს თამაშით სწავლის შესაძლებლობას აძლევს. მძივების გადაყლაპვის რისკის გამო ძალიან მნიშვნელოვანია, ამ აქტივობის დროს ბავშვი მარტო არ დატოვოთ.') WHERE id = 'e89e203c-f03d-42bd-adfb-e246026e0afe';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ჩატარებული კვლევები აჩვენებს, რომ დედების დიდ ნაწილს ძილის მნიშვნელობის შესახებ საკმარისი ინფორმაცია არ აქვს. სრულფასოვანი ღამის ძილი ბავშვს ეხმარება, დღის განმავლობაში ნასწავლი ინფორმაცია დაალაგოს, ენერგიის მარაგი აღიდგინოს და ახალი დღე ბედნიერმა, მხნედ და, რაც მთავარია, სწავლისთვის მზად დაიწყოს, რაც მის გონებრივ განვითარებას აჩქარებს. თუ ბავშვს ძილის პრობლემები აქვს, ამან ხანგრძლივ პერსპექტივაში შესაძლოა ტვინის განვითარების შეფერხება გამოიწვიოს და მის ჯანსაღ ზრდას ხელი შეუშალოს. ამის მიზეზი ისაა, რომ ბავშვის ამჟამინდელი ასაკი გონებრივი განვითარებისა და ჯანსაღი ზრდისთვის განსაკუთრებით კრიტიკული პერიოდია. ამ დროს მისი ტვინი ინფორმაციას ღრუბელივით ისრუტავს. ტვინის განვითარების დაახლოებით 75-80% ამ პერიოდში სრულდება და მისი ზომა თითქმის ზრდასრული ადამიანის ტვინის ზომას აღწევს. ამ პერიოდში დაშვებული შეცდომებისა და უყურადღებობის შედეგების გამოსწორება მომავალში შესაძლოა შეუძლებელი აღმოჩნდეს. ამიტომ უწყვეტი ღამის ძილი, განსაკუთრებით კი REM ძილი, სასიცოცხლოდ მნიშვნელოვანია ბავშვის ტვინის განვითარების სრული პოტენციალის რეალიზებისთვის.') WHERE id = '295fa9e3-3754-4afa-a728-c53e7964be12';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი შვილი ახლა ემოციების ნამდვილი მკვლევარია. ის საკუთარ ინტელექტს გარემოს, ენისა და კულტურის ყოველმხრივი შესწავლის გზით აყალიბებს. ამ პერიოდში თქვენს შვილს განსაკუთრებული გონებრივი სტრუქტურა აქვს, რომელიც ზრდასრულებს აღარ გააჩნიათ. ის ზრდასრულთა აზროვნების გზას არ მიჰყვება. სამეცნიერო სამყაროში ამ ეტაპს „ქვეცნობიერი გონების ეტაპს“, მონტესორის მეთოდში კი „შთამნთქმელ გონებას“ უწოდებენ. ამის საუკეთესო მაგალითია ის, თუ როგორ სწავლობს თქვენი შვილი ენას. სხვა სიტყვებით რომ ვთქვათ, როდესაც გარშემომყოფები მისთვის უცნობ ენაზე საუბრობენ, ის ორი წლის განმავლობაში ჩუმად აკვირდება, შემდეგ კი მოულოდნელად ამ ენაზე გამართული გრამატიკითა და წარმოთქმით იწყებს ლაპარაკს — ეს „შთამნთქმელი გონების“ გამოვლინებაა. ამიტომ ძალიან მნიშვნელოვანია, ბავშვის ამ „მიმღებლობის“ პერიოდში მისი განვითარების შესაბამისი აქტივობები დაგეგმოთ. ყოველი ხარისხიანად გატარებული წუთი, რომელსაც ბავშვის განვითარებას დაუთმობთ, მის მომავალ წარმატებას ჩაუყრის საფუძველს.') WHERE id = 'd731faa5-02e6-48b2-9d1d-d0e589f45abc';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ დღეებში შესაძლოა შეამჩნიოთ, რომ თქვენს შვილს თქვენთან მეტი დროის გატარება და ხშირი ჩახუტება სურს. შეიძლება მაშინაც კი, როცა საქმით ხართ დაკავებული, მოულოდნელად მოვიდეს, მოგეხვიოთ ან თქვენს კალთაში ჩახტომა მოინდომოს. ასევე ნორმალურია, თუ გარეთ გასვლისას მალე დაიღლება და ხელში აყვანას მოგთხოვთ. ასეთ დროს ეცადეთ, შეძლებისდაგვარად უარი არ უთხრათ. მას გარე სამყაროდან მომდინარე შესაძლო საფრთხეების ეშინია და თავს უსაფრთხოდ მხოლოდ თქვენს მკლავებში გრძნობს. ხელში აყვანამდე შეგიძლიათ მასთან მცირე შეთანხმება დადოთ: აუხსენით, რომ დიდხანს ტარებისას შესაძლოა ზურგი აგტკივდეთ და როცა დასვენება დაგჭირდებათ, თავად უნდა იაროს. შიშის გაჩენა განვითარების ბუნებრივი ნაწილია, თუმცა ზოგჯერ ამან შეიძლება დაგღალოთ. დღის განმავლობაში უთხარით ბავშვს, რომ ძალიან გიყვართ და როცა იგრძნობთ, რომ სჭირდება, მის ჩახუტებას ნუ დაივიწყებთ.') WHERE id = '158d8d1e-7cf7-43eb-ab2b-077ae8698a3a';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'მიუხედავად იმისა, რომ საზოგადოებაში მშვიდ ბავშვებს, ჩვეულებრივ, უფრო „კარგად აღზრდილებად“ მიიჩნევენ, სინამდვილეში ამ პერიოდში თქვენი შვილი აქტიური და მოძრავი უნდა იყოს. ფიზიკური მოქნილობა ძალიან მნიშვნელოვანია ახალი უნარების შესაძენად და ტვინში მათი სწორად განსამტკიცებლად. იმისთვის, რომ ბავშვმა ენერგია სათანადოდ დახარჯოს, უპირატესობა წინასწარ დაგეგმილ აქტივობებს უნდა მიანიჭოთ. მოძრაობითი უნარების განვითარებაში გარემო, სათამაშოები და დროის ფაქტორი დიდ როლს ასრულებს. რაც უფრო გააზრებული და მრავალფეროვანი იქნება აქტივობები ამ პერიოდში, მით მეტად განვითარდება ბავშვის მოძრაობითი შესაძლებლობები. სპორტული აქტივობების სწორად დასაწყებად შესაბამისი სავარჯიშო გარემოა საჭირო. ამჟამინდელი მიზანი ძირითადი მოძრაობების სრულყოფილად ათვისებაა. ამ ინფორმაციის გათვალისწინებით, შეგიძლიათ ბავშვი ცურვის მსგავს მარტივ და სასარგებლო სპორტულ აქტივობებზე ატაროთ.') WHERE id = 'dfcc6d4e-9df3-4f70-83ad-b2044dc2b08d';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი შვილის კვება განვითარების ამჟამინდელ, აქტიური თამაშის პერიოდში უკვე ზრდასრულთა კვების რეჟიმს უახლოვდება. ამ ეტაპზე ცხიმების ისე ძლიერად შეზღუდვა აღარ არის საჭირო, როგორც ზრდასრულთა რაციონში. მცირე ზომის კუჭის გამო ბავშვს სჭირდება ცხიმები, რომლებიც მცირე რაოდენობით უფრო მეტ ენერგიას უზრუნველყოფს. 1 გრამი ცხიმი 9 კალორიას შეიცავს, რაც ბავშვისთვის დღის განმავლობაში საჭირო ენერგიის მნიშვნელოვან ნაწილს უზრუნველყოფს. თუმცა მისი რაოდენობის გადაჭარბებით გაზრდა არ შეიძლება — ცხიმის ჭარბმა მოხმარებამ მომავალში შესაძლოა გულ-სისხლძარღვთა ჯანმრთელობას საფრთხე შეუქმნას. ამიტომ, როგორც თქვენთვის, ისე თქვენი შვილისთვის ჯანსაღი კვების ჩვევების ჩამოსაყალიბებლად, უპირატესობა სასარგებლო ცხიმებს მიანიჭეთ. მაგალითად, საკვებში ზეითუნის ზეთის გამოყენება და ბავშვისთვის ავოკადოს, ნუშის, თხილისა და ნიგვზის მსგავსი ცხიმის შემცველი პროდუქტების მიცემა საუკეთესო არჩევანია.') WHERE id = '6a9442ee-d5d9-453f-a3b4-67e47e360e31';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბოლო წლებში მთელ მსოფლიოში ფართოდ გავრცელებული დრამატული აქტივობები განსაკუთრებით მნიშვნელოვანია სკოლამდელი ასაკის ბავშვების განვითარებისთვის. ამ აქტივობების დროს გამოიყენება თამაშები, როლური შესრულება და ამბების შეთხზვა. თამაში ბავშვის განათლების ყველაზე მნიშვნელოვანი საშუალებაა. თქვენი შვილი ყველაფერს მიბაძვით სწავლობს. მოდი, განვიხილოთ საინტერესო დრამატული აქტივობის მაგალითი, რომლის შესრულებაც მასთან ერთად შეგიძლიათ: 1. მე ბავშვი ვარ (ბავშვივით მოკუნტვა). 2. ჯერ ხოხვა დავიწყე (ხოხვის მოძრაობა). 3. შემდეგ გავიარე (სიარულის მოძრაობა). 4. შემდეგ ლაპარაკი დავიწყე (ლაპარაკის განსახიერება). 5. გავიზარდე, გავიზარდე, გავიზარდე (ფეხზე ადგომა და სიმაღლის ჩვენება). 6. სკოლაში შევედი, ახლა 3 წლის ვარ (3 თითის ჩვენება). ასეთი აქტივობები არა მხოლოდ სახალისოა, არამედ ხელს შეუწყობს თქვენი შვილის შემოქმედებითი უნარების განვითარებას და ახალი ცნებების ადვილად ათვისებაში დაეხმარება.') WHERE id = 'b977ef12-87df-48c3-93a8-39c832b155c7';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი, რომელიც უკვე 3 წლის ხდება, უკეთ აღიქვამს მის გარშემო არსებულ სამყაროს. მან უკვე სრულად აითვისა ყოველდღიური რეჟიმი და ცხოვრების შესახებ უფრო მეტი კითხვის დასმა დაიწყო. ამ პერიოდში შესაძლოა შეამჩნიოთ, რომ თქვენს შვილს თამაშის მოთხოვნილება გაეზარდა. თუ არ იცით, რა აქტივობებით დაკავდეთ მასთან ერთად, რამდენიმე შემოთავაზება გვაქვს: 😊 შეგიძლიათ მუსიკის ფონზე იცეკვოთ, ხოლო როცა მუსიკა შეწყდება, უეცრად გაჩერების ან მიმართულების შეცვლის თამაშები ითამაშოთ. ამ პერიოდში თქვენს ყოველდღიურ ცხოვრებაში აუცილებლად უნდა შეიტანოთ 3 წლის ბავშვის ინტელექტის განმავითარებელი თამაშებიც. შეგიძლიათ სხვადასხვა ნივთი ერთად დაალაგოთ დიდიდან პატარასკენ ან გრძელიდან მოკლესკენ. ამ ასაკში თქვენი ბავშვი მზად არის, ისწავლოს ისეთი საპირისპირო ცნებები, როგორებიცაა გრძელი-მოკლე და დიდი-პატარა. ასევე შეგიძლიათ ერთად ითამაშოთ ამბების მოყოლის თამაში. რიგრიგობით ერთმანეთისთვის თქვენ მიერ მოფიქრებული მოკლე ამბების მოყოლა ძალიან სახალისო შეიძლება იყოს! 😊') WHERE id = 'f3002e6d-b300-436f-b377-ff336ed0acaa';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენს 33 თვის ბავშვს უკვე შეუძლია ერთმანეთში ჩასაწყობი სათამაშოების დაშლა და ხელახლა აწყობა. ასევე შეუძლია ხრახნიანი სათამაშოების ხრახნების მოშვება. იგი თანდათან დამოუკიდებლად ჩაცმას იწყებს. შეუძლია სამთვლიანი ველოსიპედის ტარება და პედლების ტრიალით მისი მართვა. კიბეზე ასვლა უკვე უფროსების მსგავსად შეუძლია — ყოველ საფეხურზე მონაცვლეობით დგამს ფეხს; ასევე შეუძლია ცალ ფეხზე დგომა. გარდა ამისა, თქვენი შვილის ყურადღების კონცენტრირების ხანგრძლივობა იზრდება. მას შეუძლია უფრო დიდხანს ითამაშოს დამოუკიდებლად. თუმცა თამაშის დროს შესაძლოა კვლავ ამჯობინოს, რომ მის გვერდით იყოთ. თქვენი ბავშვი აგრძელებს ყოველდღიური ცხოვრების შესწავლას თქვენზე დაკვირვებით. ამ პერიოდში, როცა მიბაძვა და როლური თამაშები განსაკუთრებით ხშირდება, შეიძლება შეამჩნიოთ, როგორ ამოძრავებს ის სათამაშოებს და დავალებებს აძლევს მათ. ასეთი თამაშები მიუთითებს, რომ მისი წარმოსახვის სამყარო ღრმავდება და მნიშვნელოვან როლს ასრულებს ცხოვრების აღქმაში. თუ დროდადრო ყურადღებას მიაქცევთ შეტყობინებებს, რომლებსაც იგი სათამაშოების საშუალებით გადმოსცემს, ადვილად შეძლებთ მისი შიშების, წუხილისა და სურვილების გაგებას.') WHERE id = '312c2aaa-2210-4dfd-80d6-b0c1928bed26';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი შვილის ზრდისა და განვითარების ყველაზე სწრაფი პერიოდი უკვე დასრულდა. ამ ეტაპის შემდეგ, მოზარდობის ასაკამდე, განვითარება შედარებით ნელი ტემპით გაგრძელდება. თუმცა ეს არ ცვლის ცილის რაოდენობას, რომელიც მან ყოველდღიურად უნდა მიიღოს. დღის განმავლობაში ბავშვის მიერ მისაღები ხორცის რაოდენობა საშუალოდ 100 გრამი უნდა იყოს. ეს რაოდენობა შეიძლება მისი ასაკისა და წონის მიხედვით შეიცვალოს. თქვენს მენიუში შეგიძლიათ მონაცვლეობით შეიტანოთ ქათმის ხორცი, თევზი და წითელი ხორცი. ვიტამინების დაკარგვის თავიდან ასაცილებლად და იმისთვის, რომ ბავშვმა ცილისგან მაქსიმალური სარგებელი მიიღოს, ეცადეთ, ხორცი შეძლებისდაგვარად არ შეწვათ. სათანადოდ მომზადებისა და მიღების შემთხვევაში ეს პროდუქტები სრულად აკმაყოფილებს ბავშვის რკინისა და ცილის საჭიროებას. თევზის სეზონზე კი უნდა ეცადოთ, ბავშვმა შეძლებისდაგვარად უხვად მიირთვას თევზი. თევზი მდიდარია ბავშვის გონებრივი და ფიზიკური განვითარებისთვის საჭირო ყველა სასარგებლო ნივთიერებით.') WHERE id = '31476911-a7ea-4f5e-a49b-77486ebc31c9';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ეცადეთ, თქვენი შვილის მიმართ, განსაკუთრებით სხვების თანდასწრებით, არ გამოიყენოთ ისეთი სიტყვები, როგორებიცაა „მორცხვი“, „ცელქი“ ან „ჭირვეული“. მაშინაც კი, თუ ფიქრობთ, რომ ბავშვი არ გისმენთ ან თქვენს ნათქვამს მნიშვნელობას არ ანიჭებს, ამ სიტყვების წარმოთქმისას ის ყველაფერს თქვენი სხეულის ენით ხვდება. მისი პიროვნებისადმი ასეთი დამოკიდებულება უარყოფითად იმოქმედებს თვითაღქმის ჩამოყალიბებაზე. თუ თქვენს შვილს ასეთი ხასიათობრივი თვისებები აქვს, მისი საჭიროებების გათვალისწინებით უნდა იმოქმედოთ. მაგალითად, მორცხვი ბავშვის 10 ბავშვს შორის ჩაყენება და მისგან ლიდერობის მოლოდინი სწორი არ იქნება. შეგიძლიათ იგი სოციალურ ცხოვრებას თანდათან, მცირე ნაბიჯებით შეაჩვიოთ. გახსოვდეთ, რომ გარკვეული ხასიათით ვიბადებით, თუმცა გარემოს გავლენას ამ ხასიათის ჩამოყალიბება და შეცვლა შეუძლია.') WHERE id = '35e3ed0f-aad4-4c45-9de0-b5a3eebc1289';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვისთვის, რომელიც უკვე 3 წლის ასაკს უახლოვდება, შეგიძლიათ თავისუფლად გამოიყენოთ ფუტკრის ისეთი პროდუქტები, როგორიცაა ყვავილის მტვერი (პოლენი). ყვავილის მტვერი ბუნებრივი საკვებია, რომელიც შეიცავს 22 სახეობის ამინომჟავას, ნახშირწყლებს, კალციუმს, თუთიასა და მრავალ ვიტამინს. მის შემადგენლობაში არსებული ფლავონოიდები ასევე ძლიერი ანტიოქსიდანტური თვისებებით გამოირჩევა. ანტიოქსიდანტური მოქმედებით ის აძლიერებს იმუნიტეტს, იცავს დაავადებებისგან და ხელს უწყობს ორგანიზმის აღდგენას. მასში შემავალი ამინომჟავების, ნახშირწყლებისა და ვიტამინების წყალობით ხელს უწყობს ბავშვის ფიზიკურ და გონებრივ განვითარებას. ამ პერიოდში საკმარისია, ბავშვმა დღეში დაახლოებით 10-15 გრამი ყვავილის მტვერი მიიღოს. თუმცა, თუ თქვენს შვილს თაფლზე ან ფუტკრის პროდუქტებზე ალერგია აქვს, ასეთ პროდუქტებს უნდა მოერიდოთ. დაბოლოს, ძალიან მნიშვნელოვანია, ყვავილის მტვერი სანდო, ბუნებრივი და ორგანული წყაროებიდან შეიძინოთ.') WHERE id = 'e2dc9a31-e473-4137-a35c-bba202f969bf';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ პერიოდში შესაძლოა თქვენს შვილთან სიჯიუტით გამოწვეული სერიოზული დაპირისპირება გქონდეთ. მაგალითად, კარგი ამინდია და გარეთ გასვლა გსურთ, მაგრამ თქვენს ბავშვს იმ ტანსაცმლის ჩაცმა უნდა, რომელიც ამინდს არ შეეფერება. თუ ასეთ სიტუაციაში, როგორც ნებისმიერი მშობელი, შეეწინააღმდეგებით, ეს შეიძლება რამდენიმეწუთიან ტირილის შეტევაში გადაიზარდოს. სპეციალისტები ამ ჩაკეტილ წრეზე ამბობენ: "ჯიუტი ბავშვი არ არსებობს, არსებობს ჯიუტი მშობელი". რა თქმა უნდა, ეს არ ნიშნავს, რომ ბავშვს ყველა სურვილი უნდა შეუსრულდეს. თუ ყველა მის სურვილს შეასრულებთ, შესაძლოა უმართავ ძალასა და ქაოსს შეეჯახოთ. ასეთ მომენტებში ბავშვს "შეზღუდული თავისუფლების" პრინციპით უნდა მიუდგეთ. მოკლედ, თუ იმავე მაგალითს დავუბრუნდებით, ბავშვს, რომელსაც ტანსაცმლის თავად შერჩევა სურს, შეგიძლიათ ამინდის შესაბამისი რამდენიმე ვარიანტი შესთავაზოთ და მათ შორის არჩევის უფლება მისცეთ. ასეთი მიდგომა პრობლემას გამწვავებამდე მოაგვარებს.') WHERE id = '89f175d2-1f56-4a45-a902-ade3acc28e69';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ თქვენი ბავშვი ამ ეტაპზეც იყენებს საწოვარას და ამბობთ, რომ რაც უნდა სცადოთ, ვერ გადააჩვიეთ, თქვენთვის სპეციალისტის რეკომენდაცია გვაქვს! 😊 ასეთ სიტუაციებში ერთ-ერთი სპეციალისტი „გაფუჭების“ ცნების გამოყენებას გვთავაზობს. მისი აზრით, სამყარო არასრულყოფილი ადგილია, სადაც საწოვარებიც შეიძლება გაფუჭდნენ და „პენსიაზე გავიდნენ“. ამიტომ ბავშვთან საუბრისას შეგიძლიათ ახსენოთ, რომ ნებისმიერი ნივთი შეიძლება გაფუჭდეს. მაგალითად, როდესაც იპოვით სათამაშოს ან ფანქარს, რომელიც აღარ გამოდგება, შეგიძლიათ უთხრათ: „ეს გაფუჭდა და ვეღარ შევაკეთებთ, ამიტომ უნდა გადავაგდოთ“. დღის განმავლობაში განაგრძეთ საუბარი გაფუჭებულ ნივთებზე. როცა მზად იქნებით, შეგიძლიათ საწოვარასაც „დაასრულებინოთ მუშაობა“. აჩვენეთ ბავშვს საწოვარა, უთხარით: „ნახე, ეს გაფუჭდა“ და ერთად გადააგდეთ.') WHERE id = '77122e18-58c2-4599-aad9-dbc48d22e09c';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ვიცით, რომ თქვენი ბავშვის უმადობასთან გამკლავება გიწევთ. ამ პერიოდში დედები შვილებისთვის მადის გასაუმჯობესებლად სხვადასხვა მეთოდს მიმართავენ. კერატის სიროფი კი ერთ-ერთი ყველაზე ხშირად გამოყენებული დამატებითი საკვებია. მიუხედავად იმისა, რომ კერატის სიროფის მადის მომატების ეფექტის შესახებ საკმარისი სამეცნიერო კვლევა არ არსებობს, ის ჯანმრთელობისთვის მრავალი სასარგებლო ნივთიერების წყაროა. მაგალითად, მდიდარია რკინით, კალციუმით, კალიუმით, მაგნიუმით, ფოსფორით, თუთიითა და მრავალი ვიტამინით. მასში შემავალი გალის მჟავის წყალობით დადებითად მოქმედებს ასთმის, ალერგიისა და ბრონქიტის დროს და ხელს უწყობს იმუნური და საჭმლის მომნელებელი სისტემების მუშაობას. ხელს უწყობს ბავშვის გონებრივ განვითარებას, ხოლო ანტიოქსიდანტების შემცველობის გამო ზედა სასუნთქი გზების ინფექციების დროს ამოსახველებელი მოქმედება აქვს. მასში შემავალი ბეტა-კაროტინი ანეიტრალებს თავისუფალ რადიკალებს. ასევე აწესრიგებს საჭმლის მომნელებელი სისტემის მუშაობას და მიიჩნევა, რომ განსაკუთრებით სასარგებლოა დიარეის დროს.') WHERE id = '0f76d1dc-d8f6-44ec-b73b-3a61bf8f4885';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ გსურთ, 3 წლის ასაკის სინდრომის პერიოდი უფრო ჯანსაღად გაიაროთ, საკუთარი ქცევით უნდა დაიწყოთ. მაგალითად, წინადადება არასოდეს დაიწყოთ სიტყვებით „არა“, „მაგრამ“ ან „არ შეიძლება“. ამის ნაცვლად, ბავშვს სიყვარულით ესაუბრეთ და ამავდროულად მკაფიო საზღვრები დაუწესეთ. გამოგადგებათ ისეთი განმარტებები, როგორიცაა: „ამის ჭამას მას შემდეგ შეძლებ, რაც საჭმელს შეჭამ“, „იმ სათამაშოს მაშინ გიყიდი, როცა სათამაშოს ყიდვის დღე მოვა“, „ვიცი, რომ ეს ტანსაცმელი ძალიან გიყვარს და მესმის შენი. როცა დათბება, ისევ ჩაიცვამ“. თუ წინადადებას სიტყვით „არა“ დაიწყებთ, ურთიერთობა გართულდება, რადგან როცა თქვენ რამეს სთხოვთ, ბავშვიც მაშინვე „არას“ გიპასუხებთ. აუხსენით, რატომ ვერ შეუსრულებთ სურვილს და შესთავაზეთ ალტერნატივები. თუ მშვიდად საუბრის მიუხედავად მაინც გაბრაზებულია, თავად შეინარჩუნეთ სიმშვიდე და უთხარით: „კარგი, დაველოდები, სანამ დამშვიდდები. თუ შემოთავაზებული ვარიანტებიდან ერთ-ერთს აირჩევ, შეგვიძლია თამაში იქიდან გავაგრძელოთ, სადაც შევჩერდით“. თქვენი სიმშვიდე და თავშეკავება ბავშვსაც დაამშვიდებს.') WHERE id = '72c2f63f-5be1-4b2b-b6e5-eaccc64d9c5d';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'დედის რძის შემდეგ კვერცხი მეორე ყველაზე მნიშვნელოვანი საკვებია, რომელიც ყველა საჭირო მაკრო- და მიკროელემენტს აერთიანებს. ვიცით, რომ თქვენი ბავშვის კვებაში კვერცხს დიდ მნიშვნელობას ანიჭებთ. თუმცა ისეთი ცნებები, როგორიცაა ნატურალური, სოფლისა და ორგანული კვერცხი, ზოგჯერ დაბნეულობას იწვევს. ჩვეულებრივ, „თავისუფლად გაზრდილი ქათმის კვერცხის“ ხსენებისას ყველას სოფელში თავისუფლად მოსიარულე ქათმები წარმოუდგენია, თუმცა ყოველთვის ასე არ არის. ეს მხოლოდ წარმოების მეთოდია, რომლის დროსაც ქათმებს ვიწრო გალიის ნაცვლად განსაზღვრულ ღია სივრცეში გადაადგილება შეუძლიათ, ხოლო ასეთი კვერცხის კვებითი ღირებულება შეიძლება ჩვეულებრივი კვერცხისგან დიდად არ განსხვავდებოდეს. ორგანული კვერცხის წარმოებისას კი აუცილებელია, რომ საკვები არ შეიცავდეს გმო-ს და მიწაზე სულ მცირე სამი წლის განმავლობაში არ იყოს გამოყენებული ქიმიური სასუქი. ამ თვალსაზრისით, დამოუკიდებელი ორგანიზაციები უფრო მეტად ორგანული კვერცხის მოხმარებას უწევენ რეკომენდაციას.') WHERE id = '0d3c6f23-838a-4186-987c-62162e29d087';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ პერიოდში შეიძლება შეამჩნიოთ, რომ თქვენი ბავშვი საწოლს ასველებს. ეს ბავშვთა ჯანმრთელობის სფეროში ერთ-ერთი ყველაზე გავრცელებული ჩივილია. ზოგადად, ბავშვების მიერ ღამით საწოლის დასველებას შეიძლება 3 ძირითადი მიზეზი ჰქონდეს: შარდის ბუშტის კუნთების მუშაობის დარღვევა (შარდის გამოყოფის შემაკავებელი კუნთის სისუსტე), მცირე ზომის შარდის ბუშტი ან ორგანიზმის მიერ ნორმაზე მეტი შარდის გამომუშავება. ამიტომ ეცადეთ, დაძინებამდე 2 საათის განმავლობაში ბავშვს ზედმეტად ბევრი წყალი არ დაალევინოთ. ასევე უნდა დარწმუნდეთ, რომ მას საშარდე გზების ინფექცია არ აქვს. იმის დასადგენად, ხომ არ არის მიზეზი ჰორმონული დარღვევა, ძალიან მნიშვნელოვანია პედიატრთან ვიზიტის დაგეგმვა.') WHERE id = '706d264f-8089-480e-811b-db2ce4f82fa7';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'იატაკზე გაწოლა და თავის რტყმა, გაქცევა და კედელზე თავის მირტყმა, გაბრაზება და ყვირილი, ტირილის შეტევები (ჩვეულებრივ, ცრემლების გარეშე) და იმის არცოდნა, თუ რა სურს... ეს ქცევები თქვენთვისაც ნაცნობია? 😊 თუ თქვენს შვილს მსგავსი ქცევები ისევ დაეწყო, იცოდეთ, რომ მარტო არ ხართ. ამჟამად ათასობით ოჯახი თქვენთან ერთად ცდილობს ამ ერთი შეხედვით დაუსრულებელ სინდრომთან გამკლავებას. ამ პერიოდში 3 წლის ასაკის სინდრომის ნიშნები შეიძლება უფრო მკვეთრად გამოვლინდეს. რაც უფრო ძლიერი იქნება თქვენი ურთიერთობა შვილთან, მით უფრო მარტივად გაივლით ამ პერიოდს. ბავშვებთან, რომლებსაც საკუთარი თავის გამოხატვა უჭირთ, ეს პროცესი შეიძლება ოდნავ უფრო რთული იყოს, თუმცა გახსოვდეთ, რომ ეს მხოლოდ დროებითი ეტაპია. ძალიან მნიშვნელოვანია, გამოიჩინოთ მოთმინება და გააცნობიეროთ, რომ ეს მდგომარეობა გაივლის.') WHERE id = 'aad09a79-e81c-43b7-ab90-cbeb4244addf';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ პერიოდში შეგიძლიათ ბავშვის საუზმეში თამამად ჩართოთ თაფლი. თუ ყლაპვა უჭირს, კარგი ვარიანტია მისი პურზე წასმაც. თაფლი მასში შემავალი ვიტამინების, მინერალების, პრობიოტიკებისა და პრებიოტიკების წყალობით ბავშვებისთვის ნამდვილი სამკურნალო წყაროა. ცნობილია, რომ თაფლი ზრდის ორგანიზმის დამცველი უჯრედების — ლეიკოციტებისა და ლიმფოციტების — რაოდენობას, აძლიერებს იმუნიტეტს და იცავს დაავადებებისგან. ასევე, სისხლის წითელი უჯრედების რაოდენობის გაზრდით ხელს უშლის რკინის დეფიციტით გამოწვეულ ანემიას, რაც დადებითად მოქმედებს ფიზიკურ და ნევროლოგიურ განვითარებაზე, ასევე IQ-ის დონეზეც კი. თუმცა, რადგან ბაზარზე ბევრი ყალბი პროდუქტია, ყურადღება მიაქციეთ, რომ თაფლი ორგანული და ხარისხიანი ბრენდის იყოს. თუ თქვენი ბავშვი თაფლს პირველად გასინჯავს, ალერგიის რისკის გამო არ დაგავიწყდეთ 3 დღის წესის დაცვა.') WHERE id = '56e68160-3db6-4a51-9004-f5ed90328cb8';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ვიცით, რომ თქვენი ბავშვის კვებას დიდ მნიშვნელობას ანიჭებთ. თუმცა, არ დაგავიწყდეთ, რომ ჯანსაღი განვითარებისთვის უწყვეტი ღამის ძილი სულ მცირე ისეთივე მნიშვნელოვანია, როგორიც კვება. ბავშვები მართლაც ძილში იზრდებიან. ძილის დროს, განსაკუთრებით სიბნელეში, გამოიყოფა ჰორმონი მელატონინი. ეს ჰორმონი აძლიერებს იმუნიტეტს და ხელს უწყობს ჰიპოფიზის მიერ ზრდის ჰორმონის უფრო ინტენსიურად გამოყოფას. დღის განმავლობაში მიღებულ ინფორმაციას თქვენი ბავშვი ძილის დროს იმახსოვრებს, რაც ტვინის უჯრედებს შორის კავშირებს აძლიერებს. კარგად გამოძინებული და დასვენებული ბავშვი ახალ დღეს მეტი ენერგიით იწყებს, სწავლისადმი მეტი ინტერესი აქვს და თამაშითაც უფრო მეტად სიამოვნებს.') WHERE id = 'd38c5b0c-a2eb-49b2-9b6a-81efef827283';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ პერიოდში თქვენი ბავშვისთვის შეგიძლიათ შეიძინოთ პროფესიული სათამაშო ნაკრებები, მაგალითად, დურგლის, ექიმის ან მზარეულის ნაკრები. ამ ტიპის სათამაშოებს ბავშვის განვითარების სპეციალისტები უწევენ რეკომენდაციას და მათ ბავშვის განვითარებაში მნიშვნელოვანი წვლილი შეაქვთ. ასეთი სათამაშოები შეგიძლიათ შეურჩიოთ როგორც გოგოებს, ისე ბიჭებს. სპეციალისტები აღნიშნავენ, რომ ჯანსაღი გენდერული იდენტობის ჩამოყალიბებისთვის სასარგებლოა, ბავშვები სათამაშოების ერთმანეთისგან გამორჩევის გარეშე ყველა სახის თამაშს გაეცნონ. ბუნებრივია, ბავშვმა შესაძლოა თავისი ბუნებრივი მიდრეკილებების შესაბამისად გარკვეული სათამაშოები ამჯობინოს (მაგალითად, გოგოებს შეიძლება თოჯინები მოსწონდეთ, ბიჭებს კი მანქანები). თუმცა, არ უნდა დაგავიწყდეთ, რომ პროფესიებს სქესი არ აქვს და ამ საკითხში ბავშვი არ უნდა შეზღუდოთ.') WHERE id = 'b8d6b288-c63d-469e-a5b5-b302aabd5be2';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ პერიოდში შეიძლება შეამჩნიოთ, რომ თქვენი ბავშვი ემოციურად უფრო მგრძნობიარე გახდა. მაგალითად, როდესაც ვინმე ტირის, აინტერესებს, რატომ ტირის ის, თანაუგრძნობს მის სევდას და შესაძლოა თავადაც ძალიან დამწუხრდეს. თანაგრძნობის გაძლიერების გამო ბავშვი ცდილობს მტირალი ადამიანი დაამშვიდოს, ლოყაზე ეფერება და მანუგეშებელ ჟესტებს იყენებს. ბუნებრივია, ყველაფერს ამას ის თქვენგან სწავლობს. არ დაგავიწყდეთ, რომ თქვენ, როგორც მისი მთავარი მასწავლებელი, ბავშვისთვის მისაბაძი მაგალითი ხართ. ამ თვეებში ის თქვენს ემოციებსაც ამჩნევს; ანუ როდესაც ბედნიერი, დაძაბული ან მოწყენილი ხართ, ცდილობს თქვენ გვერდით იყოს. ის ხვდება, რომელი ქცევის შემდეგ გეუფლებათ ეს გრძნობები და მომავალში, როდესაც თავად აღმოჩნდება მსგავს სიტუაციაში, ზუსტად თქვენ მსგავსად მოიქცევა. ამავდროულად, თქვენც უნდა ეცადოთ თქვენი შვილის გაგებას, რადგან სწორედ თქვენ ხართ მთავარი ადამიანი, ვინც მას ზრდასრულ პიროვნებად აყალიბებს. იმისთვის, რომ ადამიანებთან სწორი ურთიერთობა შეძლოს, უნდა ასწავლოთ თანაგრძნობა და დაანახვოთ, რამდენად კარგია დახმარების საჭიროების მქონე ადამიანების მხარდაჭერა. გარდა ამისა, უნდა ასწავლოთ მადლობის თქმა, თავაზიანად მოქცევა და აჩვენოთ, რომ კეთილი სიტყვა ყველა კარს აღებს. ასევე, გაამხნევეთ ბავშვი, რათა ამ ასაკში შესაძლო მორცხვობა შეუმციროთ და თავდაჯერებულ პიროვნებად ჩამოყალიბებაში დაეხმაროთ.') WHERE id = '0ce0c599-580b-4527-aa93-807483cb4649';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'შესაძლოა, გქონდეთ კითხვები იმის შესახებ, თუ როგორ უნდა იკვებებოდეს თქვენი ბავშვი ამ პერიოდში. ამიტომ გთავაზობთ სანიმუშო მენიუს, რომელიც აჩვენებს, რა უნდა მიირთვას 33 თვის ბავშვმა ერთი დღის განმავლობაში! საუზმეზე: კარაქში მომზადებული ომლეტი მწვანილითა და ყველით + 2-3 ცალი ზეთისხილი + 1 ნაჭერი მთლიანი ხორბლის პური ბავშვს ყველა საკვები ჯგუფისგან სარგებლის მიღებაში დაეხმარება. წასახემსებლად: 1 პატარა ხილი + 2-3 ცალი ლეღვის ჩირი + 1 მთლიანი ნიგვზის ლებანი სრულად დააკმაყოფილებს მის ენერგეტიკულ მოთხოვნილებას. სადილად: ღუმელში გამომცხვარი ორაგული + 1 ნაჭერი მთლიანი ხორბლის პური; თუ თევზი არ გაქვთ, ალტერნატივის სახით შეგიძლიათ შესთავაზოთ პარკოსნების კერძი ქათმით ან ხორცით. შემდეგ წასახემსებლად: 2 ცალი სახლში მომზადებული უშაქრო შვრიის ორცხობილა + ნახევარი ჭიქა ხილის წვენი საკმარისია. ვახშამზე კი შეგიძლიათ შესთავაზოთ: ბოსტნეულის ფლავი + ნახევარი ჯამი იოგურტი. სურვილისამებრ, ღამით დაძინებამდე 1 ჭიქა რძეც შესაფერისი არჩევანია.') WHERE id = '549b2994-2980-4e78-85f4-a5477bf37526';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ ეტაპზე თქვენი ბავშვის გონებრივი განვითარება სწრაფად მიმდინარეობს, ამიტომ მნიშვნელოვანია, შეარჩიოთ განვითარებისა და ტვინის აქტივობის მასტიმულირებელი სათამაშოები. რადგან მისი მოძრაობის უნარი მნიშვნელოვნად გაუმჯობესებულია, შეგიძლიათ 3 ბორბლიანი ველოსიპედი უყიდოთ. უსაფრთხო გარემოში ველოსიპედით სეირნობის შესაძლებლობის მიცემით ხელს შეუწყობთ როგორც მის სოციალიზაციას, ისე ენერგიის სასარგებლოდ დახარჯვას. სახლში ყოფნის დღეებში ხელების მოტორული უნარების გასაუმჯობესებლად შეგიძლიათ უპირატესობა მიანიჭოთ მსხვილნაწილიან ასაწყობ სურათებსა და თავსატეხებს. ასევე, რადგან სახლში თქვენს ქცევებს ბაძავს, შეგიძლიათ უყიდოთ სათამაშო სამზარეულოს ნაკრები ან მცირე ზომის სათამაშო საყოფაცხოვრებო ნივთები. ამ პერიოდში ბავშვებს ხტუნვის, ახტომისა და დარტყმის ძლიერი სურვილი აქვთ, ამიტომ დოლი ან რიტმული ჩხირებიც ძალიან გამოგადგებათ. ყველა ეს სათამაშო შესანიშნავი საშუალებაა ბავშვის როგორც ნატიფი, ისე მსხვილი მოტორული უნარების განვითარებისთვის.') WHERE id = '369cc37b-2f9a-4abf-a1f2-8c6ddb44235b';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ დასაქმებული დედა ხართ და ფიქრობთ, რომ შვილთან საკმარის დროს ვერ ატარებთ, ნუ ინერვიულებთ. სპეციალისტები ხაზს უსვამენ, რომ ბავშვთან გატარებული დროის ხანგრძლივობაზე მეტად მისი ხარისხია მნიშვნელოვანი. სამსახურიდან სახლში დაბრუნების შემდეგ შვილთან ხარისხიანად გატარებული ნახევარი საათი ან ერთი საათი ზოგჯერ გაცილებით სასარგებლოა, ვიდრე მთელი დღის ერთად, მაგრამ უშედეგოდ გატარება. ამასთანავე, შაბათ-კვირაც თქვენ გეკუთვნით! შაბათ-კვირას შეგიძლიათ ოჯახთან ერთად ხანგრძლივად გაისეირნოთ, ველოსიპედით იაროთ ან ბურთით სხვადასხვა თამაში ითამაშოთ. ბავშვთა გასართობ ცენტრში წასვლა და იქ დროის ერთად სასიამოვნოდ გატარებაც შესანიშნავი არჩევანია. გახსოვდეთ, რომ თქვენი ბავშვისთვის ნებისმიერ ვითარებაში განსაკუთრებული და შეუცვლელი ხართ და ყოველთვის ასე იქნება. ამიტომ თავს ნუ დაიტანჯავთ; ყურადღება გაამახვილეთ არა იმაზე, რის გაკეთებასაც ვერ ასწრებთ, არამედ იმ მშვენიერ წუთებზე, რომელთა ერთად გატარებაც შეგიძლიათ.') WHERE id = 'd9001d20-5e18-461f-a3d5-cec998022416';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენს ბავშვთან ერთად კიდევ ერთი თვე გაიარეთ. კეთილი იყოს თქვენი მობრძანება 34-ე თვეში! 😊 თქვენი 34 თვის ბავშვის განვითარება ამ პერიოდში თითქმის ისეთივეა, როგორიც წინა თვეში იყო. ამ თვის ყველაზე მნიშვნელოვანი სიახლე ისაა, რომ თქვენი შვილი უკვე სრულად მზად არის სკოლამდელი განათლებისთვის. ასევე უნდა აღვნიშნოთ, რომ თქვენს ბავშვთან ერთად, რომელიც 3 წლის ასაკის სინდრომის ეტაპზე გადადის, გარკვეულწილად რთული, თუმცა საინტერესო პერიოდი გელით. ამ ეტაპზე, რომელსაც 3 წლის ასაკის კრიზისსაც უწოდებენ, თქვენი ბავშვი საკუთარ ეგოს აღმოაჩენს. ეგო პიროვნების სტრუქტურის ერთ-ერთი უმნიშვნელოვანესი ნაწილია. სტრუქტურა, რომელსაც პიროვნებას ვუწოდებთ, ერთმანეთთან დაკავშირებული სამი ძირითადი ნაწილისგან შედგება — იმპულსებისა და სურვილებისგან; ეგოსგან; ღირებულებების, რწმენისა და სინდისისგან. ეგო ამ სტრუქტურაში წონასწორობის შენარჩუნების როლს ასრულებს. ამ თვალსაზრისით აშკარაა, რომ ეგოს ჩვენს ფსიქიკურ ჯანმრთელობაში ძალიან მნიშვნელოვანი ადგილი უკავია. Anacan-ის ოჯახი ყოველთვის თქვენ გვერდითაა!') WHERE id = 'a8ffabb9-3040-4b25-bec5-5f9659629255';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ თქვენს შვილს 2 წლის ასაკში თვალების სრულყოფილი გამოკვლევა არ ჩაუტარდა, ძალიან მნიშვნელოვანია, ეს 3 წლის შესრულებამდე გააკეთოთ. სიელმის, ამბლიოპიისა და მხედველობის სხვადასხვა დარღვევის გამოსავლენად თვალების გამოკვლევა აუცილებლად 3 წლამდე უნდა ჩატარდეს. ბავშვებში მხედველობის სისტემა პირველი 9 წლის განმავლობაში სრულად ვითარდება, შემდეგ კი მნიშვნელოვანი ცვლილებები აღარ ხდება. ყველა ბავშვის მსგავსად, თქვენს პატარასაც, მაშინაც კი, თუ არანაირი პრობლემა არ აქვს, 3 წლის ასაკამდე აუცილებლად უნდა ჩაუტარდეს ოფთალმოლოგის გამოკვლევა. მხედველობის დარღვევებით გამოწვეული ამბლიოპია, თუ მას 9-10 წლამდე არ უმკურნალებენ, მოგვიანებით მკურნალობას აღარ ექვემდებარება. გარდა ამისა, მხედველობის დარღვევის მქონე ბავშვებს სკოლაში სწავლის სირთულეების განვითარების მაღალი ალბათობა აქვთ. ამიტომ, რაც უფრო ადრე გამოვლინდება პრობლემა, მით უფრო მაღალია მკურნალობის წარმატებით დასრულების შანსი.') WHERE id = 'e386827d-ad41-4c20-bd38-219ad4b81467';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ გსურთ, რომ თქვენმა შვილმა მთელი ღამე შეუწყვეტლად იძინოს, მას დამოუკიდებლად ჩაძინება უნდა ასწავლოთ. წინააღმდეგ შემთხვევაში, ყოველ ჯერზე, როცა გაიღვიძებს, მის ხელახლა დასაძინებლად თქვენც მოგიწევთ გაღვიძება. შესაძლოა, თქვენი შვილი ჩვილის საწოლში უკვე ვეღარ ეტევა. ამან შეიძლება მისი ძილის ხარისხზე უარყოფითად იმოქმედოს. ჯანსაღი ძილისთვის შეგიძლიათ ბავშვს მისთვის შესაფერისი საწოლი უყიდოთ. ნებისმიერ ასაკში ბავშვების ძილთან დაკავშირებული ორი ყველაზე გავრცელებული პრობლემაა ჩაძინების გაძნელება და ხშირი გაღვიძება. თუ გსურთ, რომ მან მთელი ღამე ისე იძინოს, რომ არ დაგიძახოთ, ყველაზე მნიშვნელოვანია, ისწავლოს სათამაშოს ან რაიმე ნივთის ჩახუტებით თავის დამშვიდება და ხელახლა ჩაძინება. არასწორია, თუ თქვენი შვილი ჩაძინებისთვის მუსიკას, სინათლეს ან საკვებს მიეჩვევა. ასეთი არასწორი ჩვევა გამოიწვევს იმას, რომ ღამით გაღვიძებისას ხელახლა დასაძინებლად იმავეს მოითხოვს.') WHERE id = '4ab036c3-4a94-40eb-b15f-cc5e03491b45';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი შვილის ძვლების განვითარებისთვის ამ პერიოდში ძალიან მნიშვნელოვანია კალციუმით მდიდარი საკვების მიღება. ამიტომ მან ყოველდღიურად 2 ჭიქა რძე ან მისი ეკვივალენტური რაოდენობის რძის პროდუქტი უნდა მიიღოს. რძის პროდუქტები შეგიძლიათ ბავშვის როგორც ძირითად კვებაში, ისე წასახემსებელ მენიუში შეიტანოთ. რძის შერჩევისას ყველაზე მნიშვნელოვანია, რომ ის ახალი და პასტერიზებული იყოს. ეცადეთ, იოგურტიც შეძლებისდაგვარად თავად მოამზადოთ სახლში პასტერიზებული რძისგან. თუ თქვენს შვილს რძის გემო არ მოსწონს და მისი დალევა არ სურს, მოერიდეთ მისთვის შაქრის ან სხვა ინგრედიენტების დამატებით გემოს შეცვლას. ამის ნაცვლად, შეგიძლიათ შესთავაზოთ რძის ალტერნატიული პროდუქტები, როგორიცაა იოგურტი, ხაჭო და ყველი.') WHERE id = 'eeb8003d-add3-422d-9fd8-3b5b9e6003eb';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი შვილის ცნობისმოყვარეობა იმდენად ძლიერია, რომ ზოგჯერ შეიძლება იმდენი შეკითხვა დაგისვათ, რომ დაგღალოთ. მეტყველების უნარის განვითარებასთან ერთად ხშირად მოისმენთ ისეთ შეკითხვებს, როგორიცაა: რატომ?, რატომ გვძინავს ღამით?, რატომ იზრდება ვაშლი ხეზე?, რატომ წვიმს? რა თქმა უნდა, ამ დაუსრულებელმა შეკითხვებმა, სხვა მშობლების მსგავსად, შესაძლოა თქვენც დაგღალოთ. თუმცა გახსოვდეთ, რომ შეკითხვების დასმა თქვენი შვილის შემეცნებითი განვითარებისა და სამყაროს აღმოჩენის მაჩვენებელია. ის შეკითხვების მეშვეობით სწავლობს. როცა დაიღლებით, უხეშად უარის თქმის ნაცვლად, მშვიდად უთხარით: შეიძლება შენს შეკითხვას ცოტა მოგვიანებით ვუპასუხო? რადგან ბავშვისთვის დამაბნეველ ან შემაშფოთებელ საკითხებზე მხოლოდ თქვენ მიერ გაცემულ პასუხებს შეუძლია მისი დამშვიდება.') WHERE id = '2fa7ea2e-a30f-47c2-aef5-ed3fe5788bde';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ თქვენი შვილი ბოსტნეულს არ ჭამს და ეს გაწუხებთ, იცოდეთ, რომ ამ პრობლემის წინაშე მარტო არ ხართ. ბოსტნეული, როგორც წესი, ბავშვებისთვის ყველაზე ნაკლებად საყვარელი, თუმცა მათთვის ერთ-ერთი ყველაზე მნიშვნელოვანი საკვებია. თითქმის ყველა ვიტამინი სხვადასხვა ბოსტნეულსა და ხილში გვხვდება. ამიტომ თქვენი შვილის კვების რაციონი მაქსიმალურად მრავალფეროვანი უნდა იყოს. თუ მას მომზადებული ბოსტნეული არ მოსწონს, შეგიძლიათ უმად საჭმელი ბოსტნეულისგან სალათი მოუმზადოთ. წახემსებისთვის კი საუკეთესო არჩევანი ხილია. ამგვარად, ბავშვს ზედმეტი შაქრისა და შოკოლადის მიღებასაც აარიდებთ. აუცილებელი არ არის, თქვენს შვილს ყველა ბოსტნეული ან ხილი მოსწონდეს. ზრდასრულების მსგავსად, მასაც საკუთარი გემოვნება აქვს. საკმარისია, თითოეული საკვები ჯგუფიდან 2-3 სახეობას მიირთმევდეს. ჭამის დაძალებამ შეიძლება საკვების მიმართ კიდევ უფრო უარყოფითი დამოკიდებულება გაუჩინოს.') WHERE id = '93e9401a-1194-4460-ab5a-1ff01deaad41';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ექსპერტების საერთო მოსაზრებით, ორიდან სამ წლამდე ასაკის ბავშვებს ღამით 11 საათი, დღისით კი დაახლოებით საათ-ნახევარი ან ორი საათი ძილი სჭირდებათ. ამ ასაკის ბავშვების უმეტესობა საღამოს 19:00-დან 21:00 საათამდე იძინებს, დილით კი 06:30-დან 08:00 საათამდე იღვიძებს. მიუხედავად იმისა, რომ თქვენი ბავშვის ძილის რეჟიმი თანდათან უფრო ემსგავსება თქვენსას, 4 წლამდე ის თქვენზე მეტ დროს გაატარებს მსუბუქი REM ძილის ფაზაში. ამის გამო ძილის ფაზებს შორის გადასვლა უფრო ხშირად ხდება და ბავშვიც ღამით თქვენზე ხშირად გაიღვიძებს. სწორედ ამიტომ, თუ გსურთ, რომ მან თქვენს გაღვიძების გარეშე მთელი ღამე უწყვეტად იძინოს, მნიშვნელოვანია, დამოუკიდებლად ხელახლა ჩაძინება ასწავლოთ. განსაკუთრებით ძილის წინ უნდა მოარიდოთ ტელევიზორს, პლანშეტსა და ტელეფონს, რომლებიც მის ქვეცნობიერზე ზემოქმედებს. ასეთმა მოწყობილობებმა შეიძლება ბავშვის ძილი ჩვეულებრივზე უფრო ხშირად დაარღვიოს.') WHERE id = '2c2d7b4a-f9e9-4546-9aa6-71036a012509';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ პერიოდში ბავშვს შეგიძლიათ უყიდოთ ფერადი ფანქრები, გასაფერადებელი და აქტივობების წიგნები, რომლებიც ნატიფი მოტორული უნარების განვითარებაში დაეხმარება. განსაკუთრებით ასაკის შესაბამისი აქტივობების წიგნებით ერთად მეცადინეობა დაგეხმარებათ, როგორც ხარისხიანად გაატაროთ დრო, ისე ბავშვს თამაშით სწავლის შესაძლებლობა მისცეთ. დღის განმავლობაში სულ მცირე 1-2 საათის განმავლობაში ერთად შემეცნებითი თამაშების თამაში თქვენი ბავშვის მომავალში ჩადებული ერთ-ერთი ყველაზე მნიშვნელოვანი ინვესტიციაა. მაგალითად, პატარა ნაწილებისგან მთლიანი ფიგურის აწყობა ამ პერიოდის ერთ-ერთი ყველაზე საინტერესო თამაშია. ამიტომ ფაზლები, ერთმანეთში ჩასასმელი სათამაშოები და ლეგოს ნაკრებები შეიძლება ენერგიით სავსე ბავშვისთვის ნამდვილი ხსნა აღმოჩნდეს. ასაკის მატებასთან ერთად ასეთი სათამაშოები რთულდება და თამაშისთვის უფრო განვითარებულ მოტორულ უნარებს მოითხოვს. ეს ბავშვს ახალი უნარების შეძენისა და წარმატების განცდის შესაძლებლობას აძლევს.') WHERE id = 'b66a0d11-0af2-4535-8154-1f619d2a0bfa';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ პერიოდში შეიძლება კითხვები გქონდეთ თქვენი ბავშვის კვების რეჟიმსა და ულუფების რაოდენობასთან დაკავშირებით. თქვენთვის ერთი დღის სანიმუშო მენიუ მოვამზადეთ! 😊 საუზმის დაწყება შესანიშნავი იქნება 1 ნაჭერი სრულმარცვლოვანი ხორბლის პურის ტოსტით, 1 ჩაის კოვზი არაქისის კარაქითა და ნახევარი ჭიქა რძით. წასახემსებლად შეგიძლიათ აირჩიოთ ნახევარი ჭიქა მარწყვი, ნახევარი ჭიქა იოგურტი ან ჯანსაღი სიმინდის ფანტელი (მიუსლი). სადილად შეგიძლიათ მრავალფეროვანი მენიუ შეადგინოთ 1 ნაჭერი ქატოს პურით, ცოტაოდენი თევზით, პატარა მოხარშული კარტოფილითა და 1 პატარა ფორთოხლით. შემდეგი წახემსებისთვის შეგიძლიათ მისცეთ სახლში მომზადებული 5 ცალი მარცვლოვანი კრეკერი, 5 ცალი უმი ნუში ან 1 ნაჭერი სრულმარცვლოვანი ხორბლის პური, რომელზეც ბაქმაზი/თაფლი იქნება წასმული. ვახშმად კი ნახევარი სტაფილო, 30 გრამი სხვა ბოსტნეული, დამატებით 30 გრამი საქონლის ან ქათმის ხორცი და ნახევარი ჯამი ბულგურის ფლავი ნოყიერიც იქნება და სასარგებლოც.') WHERE id = '443f9eda-baee-4eb9-a55b-b12c4d58ecb1';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'მიუხედავად იმისა, რომ ამ პერიოდში თქვენი ბავშვის ფიზიკური განვითარება ნელდება, გონებრივი განვითარება სწრაფად გრძელდება. ბავშვს უკვე თავისუფლად შეუძლია მოქმედებისა და საქმიანობის გამომხატველი სურათების დასახელება. თუ წინასწარ ასწავლეთ, მას გეომეტრიული ფიგურების შესაბამის სურათებთან დაკავშირება შეუძლია. მას ასევე შეუძლია ღერძზე თანმიმდევრულად ააცვას 5 რგოლი დიდიდან პატარამდე ან პატარიდან დიდამდე. შეუძლია გაარჩიოს, ნივთი მსუბუქია თუ მძიმე. შეგიძლიათ მასთან ერთად აკონტროლოთ კიდეც, რამდენ კილოგრამს იწონის — ეს ძალიან მოეწონება. თქვენს ბავშვს მთლიანი სურათის მისაღებად მისი ორი ნაწილის შეერთებაც შეუძლია. შეკითხვისას გიჩვენებთ გრძელ და მოკლე ნივთებს. ასევე შეუძლია ერთმანეთთან დაკავშირებული საგნების პოვნა, როგორიცაა კბილის პასტა და კბილის ჯაგრისი, თოჯინა და საბავშვო ბოთლი. ამ ყველაფრის მოკლე დროში სწავლა იმის დასტურია, თუ რამდენად მზად არის თქვენი ბავშვის ტვინი ახალი ცოდნის მისაღებად.') WHERE id = '7f5ccfc6-4475-4f0c-8f31-12479dd8da41';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ეს პერიოდი შესაფერისი დროა თქვენი ბავშვის საწოლის გამოსაცვლელად. თუ ჯერ კიდევ ჩვილის საწოლს იყენებთ, ბავშვს მასში მოთავსება თანდათან გაუჭირდება. ოჯახში ახალი წევრის შემომატებამაც შეიძლება ეს გადაწყვეტილება დააჩქაროს. თუ ორსულად ხართ ან ორსულობას გეგმავთ, უფროსი შვილი ახალ საწოლში ბავშვის დაბადებამდე სულ მცირე 6-8 კვირით ადრე უნდა გადაიყვანოთ. ფსიქოლოგიური თვალსაზრისით უმჯობესია, უფროსი შვილი ახალ საწოლს მანამდე შეეჩვიოს, სანამ ახალშობილი მის საწოლს „წაართმევს“. თუ მას ამ ცვლილებასთან შეგუება ძალიან გაუჭირდება, შეგიძლიათ ეს პროცესი ახალი ბავშვის 3-4 თვის შესრულებამდე გადადოთ. სანამ ახალი ბავშვი ამ თვეებს ნებისმიერ შესაფერის ადგილას ძილში გაატარებს, უფროსი შვილიც ოჯახის ახალ წევრს შეეჩვევა და საწოლის შეცვლა უფრო მარტივი გახდება. საწოლის შეცვლის კიდევ ერთი მიზეზი ტუალეტის ჩვევაა — ბავშვი უკვე უნდა მიეჩვიოს ღამით ტუალეტში ისე წასვლას, რომ არ გაგაღვიძოთ. ამ საკითხში მისი წახალისება ძალიან მნიშვნელოვანია, როგორც ამ ჩვევის ჩამოსაყალიბებლად, ისე თქვენი ძილის ხარისხის გასაუმჯობესებლად.') WHERE id = 'b162f1d9-6368-4367-b8db-fde84325b9ed';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი შვილის დაავადებებისგან დასაცავად, იმუნური სისტემის გასაძლიერებლად ან უბრალოდ მისთვის ენერგიის მისაცემად შეგიძლიათ სანელებლები გამოიყენოთ. ძლიერი ანტიოქსიდანტური მოქმედების გარდა, სანელებლებს ანთების საწინააღმდეგო მრავალი სასარგებლო თვისებაც აქვს. მათ შემადგენლობაში შემავალი ისეთი ანტიოქსიდანტები, როგორიცაა ბეტა-კაროტინი, სელენი და A, C და E ვიტამინები, თქვენს შვილს მრავალი პრობლემისგან — გულის დაავადებებიდან კიბომდე — იცავს. მაგალითად, კვლევები აჩვენებს, რომ კურკუმა დადებითად მოქმედებს ტვინის ჯანმრთელობასა და ასაკთან დაკავშირებულ კოგნიტიურ განვითარებაზე. სხვა კვლევის თანახმად კი, ერთი ჩაის კოვზი ჯანჯაფილის ანტიოქსიდანტური უნარი ერთი ჭიქა ისპანახისას უტოლდება. ამიტომ, ზომიერების დაცვითა და აუცილებლად ექიმთან კონსულტაციის შემდეგ, შეგიძლიათ თქვენი შვილის რაციონში სასარგებლო სანელებლები თამამად გამოიყენოთ.') WHERE id = 'c72aa2b5-e59d-4e6f-ad3f-c7a037c197ef';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი შვილის კითხვებზე პასუხის გაცემისას მნიშვნელოვანია, წაახალისოთ, რომ თავადაც გამოიკვლიოს საკითხი და დაფიქრდეს. მაგალითად, შეგიძლიათ აზროვნებისკენ უბიძგოთ ისეთი კითხვებით, როგორებიცაა: შენი აზრით, რატომ შეიძლება იყოს ასე?, შენ რას ფიქრობ?, რაიმე ვარაუდი გაქვს? ბავშვი, რომლის კითხვებსაც პასუხობთ, სკოლაშიც უფრო თავისუფლად სვამს კითხვებს მისთვის გაუგებარ საკითხებზე. დაკვირვებები აჩვენებს, რომ ბავშვები, რომლებიც მასწავლებელს მეტ კითხვას უსვამენ, სწავლაშიც უფრო წარმატებულები არიან. ამის საპირისპიროდ, ბავშვები, რომელთა კითხვებიც უპასუხოდ რჩება ან უგულებელყოფილია, თავს ნაკლებად ღირებულად გრძნობენ და სკოლაში კითხვების დასმას ერიდებიან. თქვენი შვილი, რომელიც მეტს ფიქრობს, კითხვებს სვამს და იკვლევს, მომავალშიც უფრო წარმატებული იქნება. ამიტომ ძალიან მნიშვნელოვანია, მის კითხვებს შეძლებისდაგვარად მოთმინებით უპასუხოთ.') WHERE id = '5b153890-626c-4f66-9895-e87a3626f96f';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'მაღაზიებში გაყიდული შეფუთული რძე თუ ძროხისგან ახლად მოწველილი უმი რძე? ეს კითხვა წლების განმავლობაში დედებისთვის ერთ-ერთი ყველაზე მნიშვნელოვანი საკითხია. ზოგი სახლში ადუღებულ უმ რძეს უფრო სასარგებლოდ მიიჩნევს, ზოგი კი პასტერიზებულ ან UHT რძედ წოდებულ პროდუქტებს ანიჭებს უპირატესობას. თუ უმი რძის წარმოშობა და ტრანსპორტირების პირობები ზუსტად ცნობილი არ არის, მისი მოხმარება საკმაოდ სარისკოა. მასში არსებულმა მავნე ბაქტერიებმა თქვენი შვილის ორგანიზმში სხვადასხვა რეაქცია შეიძლება გამოიწვიოს. გარდა ამისა, საფრთხეს წარმოადგენს ძროხისთვის ანტიბიოტიკების მიცემაც და რძის არაჰიგიენურ პირობებში შენახვაც. ამ თვალსაზრისით, არასანდო ადგილებში შეძენილი ჩამოსასხმელი რძის ნაცვლად, ყოველდღიური პასტერიზებული რძის არჩევა უფრო ჯანსაღი გადაწყვეტილება იქნება.') WHERE id = 'e3a23f3e-4fd8-4dbb-ac95-29d46ad09622';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი შვილი ადრეული ბავშვობის პერიოდის თითქმის დასასრულს მიუახლოვდა. ახლა ის უკვე სრულად თამაშის ასაკშია. შეუძლია მთელი დღე თამაშში გაატაროს, არასდროს მობეზრდეს და მუდმივად მოინდომოს თქვენი ჩართვაც. თამაში თქვენი შვილისთვის სამყაროს შეცნობისა და ახალი რამეების სწავლის ყველაზე ეფექტური საშუალებაა. ძალადობის წამახალისებელი სათამაშოების, მაგალითად, იარაღისა და პისტოლეტის ნაცვლად, სასურველია უფრო განმავითარებელი და შემოქმედებითი სათამაშოები შეურჩიოთ. რადგან თანდათან სკოლამდელ ასაკში შედის, შეგიძლიათ ასოებისა და ციფრების სწავლაში დაეხმაროთ. თუმცა ამ საკითხში ზედმეტად ნუ იჩქარებთ. თუ შეამჩნევთ, რომ ციფრებისა და ასოების მიმართ ინტერესს გამოხატავს, შეგიძლიათ ზეწოლის გარეშე ასწავლოთ. მოკლედ, თუ თავად სურს სწავლა, რა თქმა უნდა, მხარი უნდა დაუჭიროთ.') WHERE id = 'e878f726-41d1-4bee-844c-9a7d1fa53eaa';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'დღეს თითქმის ყველა ხილისა და ბოსტნეულის პოვნა წელიწადის ნებისმიერ დროს არის შესაძლებელი. თუმცა, როდესაც საქმე თქვენი შვილის კვებას ეხება, სეზონზე მოყვანილი პროდუქტები უფრო გემრიელიცაა და უფრო სასარგებლოც. ბუნებრივ პირობებში მოყვანის გამო ისინი ვიტამინებითა და მინერალებითაა მდიდარი. მაგალითად, დადგენილია, რომ ზამთარში და ზაფხულში მოკრეფილ ისპანახს შორის C ვიტამინის შემცველობის მხრივ სამმაგი განსხვავებაა. ამასთანავე, ადგილობრივი პროდუქტები შორიდან ჩამოტანილთან შედარებით უფრო ახალიცაა და უფრო სასარგებლოც. არ უნდა დაგავიწყდეთ, რომ ბუნებისა და კლიმატის სეზონურ ცვლილებებთან ერთად, როგორც თქვენს, ისე თქვენი შვილის ორგანიზმსაც განსხვავებული საჭიროებები უჩნდება. ამიტომ უმჯობესია, კვება ბუნების სრულყოფილ წესრიგს შეუსაბამოთ.') WHERE id = '00332087-6a8f-4e62-b2f8-03640f4bf4b5';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ თქვენი შვილის ცალკე საწოლში გადაყვანას გეგმავთ, შეგახსენებთ, რომ ამისთვის ახლა ყველაზე შესაფერისი პერიოდია. გარდამავალი ეტაპის გასამარტივებლად ხშირად შეაქეთ და გაამხნევეთ — ეს წარმატების მიღწევაში დაეხმარება. გაითვალისწინეთ, რომ ახალ საწოლთან შეგუების შემდეგ ბავშვი შეიძლება დიდი საწოლიდან მხოლოდ იმის საჩვენებლად გადმოვიდეს, რომ ეს შეუძლია. თუ ადგება, სიმშვიდე შეინარჩუნეთ, თუმცა მტკიცედ იმოქმედეთ. კვლავ საწოლში დააბრუნეთ, უბრალოდ უთხარით, რომ ძილის დროა, და მარტო დატოვეთ. თუ წინააღმდეგობას გაგიწევთ, შეგიძლიათ ძილის სპეციალისტების რეკომენდაციები გამოიყენოთ: ზურგზე მოეფერეთ და უთხარით, რომ ყველაფერი კარგადაა, თუმცა ძილის დრო მოვიდა. ხელში ნუ აიყვანთ და მის გვერდით ნუ დაწვებით; იყავით ალერსიანი, მაგრამ მტკიცე. ხუთი წუთი დაელოდეთ და შემდეგ კვლავ შეამოწმეთ. ეს პროცესი ჩაძინებამდე გაიმეორეთ და ლოდინის დრო ყოველ ჯერზე ოდნავ გაზარდეთ. თუ დაძინების დროს თანმიმდევრული და მტკიცე იქნებით, ღამით გაღვიძებები რამდენიმე კვირაში გაივლის.') WHERE id = '4078f349-ac2c-48e1-a276-0ec6e642a5ee';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენმა ბავშვმა, განსაკუთრებით თუ ამის შესახებ ვინმესგან გაიგებს, შეიძლება თანდათან დაიწყოს სიკვდილით დაინტერესება და კითხვების დასმა. მან შეიძლება იკითხოს: „რას ნიშნავს სიკვდილი?“, „სად მიდიან გარდაცვლილები?“, „მეც მოვკვდები?“. მიუხედავად იმისა, რომ ეს თემა ბევრ ოჯახში შფოთვას იწვევს, მნიშვნელოვანია, ასეთი კითხვები უპასუხოდ არ დატოვოთ. ბავშვებსაც, ისევე როგორც უფროსებს, იმის კი არ ეშინიათ, რაც იციან, არამედ იმის, რაც არ იციან, და ეს მათში შფოთვას იწვევს. ცოდნა გაგებისა და წუხილისგან გათავისუფლების გასაღებია. ამიტომ, შეგიძლიათ სიკვდილზე მანამდე ისაუბროთ, სანამ თქვენს ახლო გარემოცვაში ვინმე გარდაიცვლება — ყოველდღიური ცხოვრების ბუნებრივ კონტექსტში (მაგალითად, მკვდარი პეპლის, ცხოველების ან მცენარეების სიცოცხლის მაგალითზე) და ზედმეტი ემოციური დატვირთვის გარეშე. თუ შვილის დამწუხრებისა და მისი დაცვის სურვილით ამ თემას თავს აარიდებთ, რეალურ ცხოვრებაში ამ ფაქტის წინაშე აღმოჩენისას მას შეიძლება მძაფრი რეაქცია ჰქონდეს და საკუთარი გრძნობების მართვა გაუჭირდეს.') WHERE id = '89a84db5-00a0-4250-8e17-5337f74b7208';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი შვილისთვის ღამით 11 საათი, ხოლო დღისით 1,5-2 საათი ძილი საკმარისია. თუმცა ძილის საათების რეჟიმიც ძალიან მნიშვნელოვანია. ზოგიერთი მშობელი, დილით უფრო დიდხანს რომ ეძინოს, ბავშვს გვიანობამდე ფხიზლად ყოფნის უფლებას აძლევს. თუმცა ეს არასწორი მიდგომაა. იმისთვის, რომ ბავშვმა ზრდისთვის საჭირო ჰორმონებით სრულად ისარგებლოს, ის არაუგვიანეს 21:00 საათისა საწოლში უნდა იყოს. ამასთანავე, ძილის კარგი ჩვევის ჩამოსაყალიბებლად აუცილებელია, ეს რუტინად იქცეს. ძილის არასწორი განრიგის გამო ჰორმონების საჭირო რაოდენობით გამოუყოფლობამ გრძელვადიან პერიოდში შესაძლოა განვითარების შეფერხება გამოიწვიოს. გარდა ამისა, ბავშვის ტვინი ახალი ინფორმაციის მისაღებად სათანადოდ დასვენებული ვერ იქნება. ამიტომ ყურადღება უნდა მიაქციოთ, რომ თქვენი ბავშვის საღამოს ძილი 19:00-21:00 საათებს შორის დაიწყოს.') WHERE id = '9bac81bd-cded-4b25-9404-36ce1f5fe50c';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'როგორც ყველა ბავშვი, თქვენი ბავშვიც უნიკალური გენეტიკური და ფიზიოლოგიური თავისებურებებით დაიბადა. ამასთანავე, ადრეულ ბავშვობაში მიღებულ გამოცდილებას ბავშვის ჯანსაღი სოციალურ-ემოციური განვითარებისთვის უდიდესი მნიშვნელობა აქვს. კვლევები აჩვენებს, რომ მშობლების მიერ მაგალითის მიცემა და პოზიტიური კომუნიკაცია ბავშვის განვითარებაში მნიშვნელოვან როლს ასრულებს. სახლში განცდილი ემოციების შესახებ შვილთან საუბარი თქვენს ურთიერთობაზე დადებითად იმოქმედებს და მას გრძნობების ამოცნობის უნარს განუვითარებს. მაგალითად, თქვენ და თქვენმა პარტნიორმა შეგიძლიათ, ზედმეტი დეტალების გარეშე, ერთმანეთს გაუზიაროთ, როგორ ჩაიარა დღემ და რას გრძნობდით: „დღეს საცობმა ძალიან დამღალა“, „მანქანამ მოულოდნელად დაამუხრუჭა და შემაშინა“, „ჩემი უფროსი სამუშაოს დაგვიანებამ გააბრაზა და მეც გული დამწყდა“, „გზაში მეგობარი დავინახე და ამან ძალიან გამახარა“. ბავშვს, რომელიც იზრდება გარემოში, სადაც გრძნობებზე საუბრობენ, ემოციების გამოხატვისა და მართვის უნარი მნიშვნელოვნად განუვითარდება.') WHERE id = 'c1323801-3c49-4703-a7f2-cac086e9addc';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ თქვენი ბავშვი ასაკისთვის შეუფერებლად იქცევა, ხშირად ამის მიზეზი ის არის, რომ საკუთარი თავის გამოხატვა არ იცის. სხვა სიტყვებით რომ ვთქვათ, ის ასე რეაგირებს, რადგან შინაგანი დაძაბულობისა და პრობლემების სხვაგვარად გამოხატვა არ შეუძლია. მაგალითად, შეიძლება გაბრაზებისას მეგობარს დაარტყას, სასურველის ვერ მიღებისას იატაკზე დაეცეს და იფართხალოს, ვინმეს შეკითხვაზე ზედმეტად მორცხვად მოიქცეს ან მუდმივად შფოთავდეს. ასეთ შემთხვევაში თქვენი ყველაზე ეფექტური სტრატეგია, უპირველეს ყოვლისა, ბავშვისთვის იმის სწავლება იქნება, თუ რა ჰქვია მის მიერ განცდილ ემოციას. ბავშვებს, რომლებსაც საკუთარი ემოციების სიტყვებით სწორად გამოხატვა შეუძლიათ, ქცევითი პრობლემები ნაკლებად აქვთ. მაგალითად, თუ გაბრაზებისას შეძლებს თქვას, რომ ძალიან გაბრაზებულია, ბრაზის აფეთქებისა და ტირილის შეტევის ალბათობა შემცირდება. თუ თქვენს ბავშვს ხშირად ჰკითხავთ, რას გრძნობს, ეს მას ემოციების ამოცნობისა და გამოხატვის უნარს განუვითარებს და უარყოფით გრძნობებთან უფრო ჯანსაღად გამკლავებაში დაეხმარება.') WHERE id = 'c41a4ffe-aceb-49cc-a6db-32a8461961ac';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვის მიერ ბევრი კითხვის დასმა შეიძლება მიუთითებდეს როგორც მის გონიერებასა და ცნობისმოყვარეობაზე, ისე ძლიერ შფოთვაზე. ამის გასაგებად საუკეთესო გზა კითხვების შინაარსზე დაკვირვებაა. თუ კითხვები შიშით სავსე თემებს ეხება, მაგალითად: „ამ საჭმელს თუ შევჭამ, ავად გავხდები?“, „გული სწრაფად მიცემს, მოვკვდები?“, „ამაღამ სახლში ქურდი შემოვა?“, „მარცხენა ხელით თუ შევჭამ, რამე მოხდება?“, სასარგებლო იქნება სპეციალისტისთვის დახმარების თხოვნა. დროდადრო ყველა ბავშვმა შეიძლება ინერვიულოს და ასეთი კითხვები დასვას. თუმცა, თუ ეს ხშირად მეორდება, თქვენს ბავშვს ყურადღებით უნდა დააკვირდეთ. იმ სიტუაციების ამოცნობას, რომლებიც მას აშინებს და შფოთვას იწვევს, მისი ფსიქიკური ჯანმრთელობისთვის დიდი მნიშვნელობა აქვს. თუ პრობლემას თავად ვერ უმკლავდებით, ნუ მოგერიდებათ სპეციალისტისთვის მიმართვა. გახსოვდეთ, რომ დროული ჩარევა ყოველთვის ყველაზე ჯანსაღი არჩევანია.') WHERE id = 'd8d7160d-4daa-41aa-b77a-2dab3b64dfdc';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვის ცნობისმოყვარეობა მხოლოდ წიგნებსა და რვეულებთან არ ვითარდება. ადამიანის ბუნებრივი განვითარების პროცესში თეორიული სწავლების ფორმა 11-14 წლის ასაკამდე გრძელდება. ამ პერიოდამდე ბავშვი ნასწავლის დიდ ნაწილს პრაქტიკით, თამაშითა და ცნობისმოყვარეობის დახმარებით ითვისებს. ამიტომ არ უნდა ჩაახშოთ მისი ცნობისმოყვარეობა, რომელიც ყველაზე ხშირად კითხვების დასმით ვლინდება. ბავშვი, რომლის ცნობისმოყვარეობაც დათრგუნულია, შესაძლოა მოზარდობის პერიოდამდე ჯანსაღად ვერ განვითარდეს. ამიტომ თქვენი ბავშვის კითხვებს მოთმინებით უნდა უპასუხოთ და კითხვების დასმისკენაც კი წაახალისოთ. ხოლო კითხვებზე, რომელთა პასუხებიც არ იცით, შეგიძლიათ მასთან ერთად მოიძიოთ ინფორმაცია და თავადაც ახალი რამ ისწავლოთ.') WHERE id = 'c925eb18-ca4f-4e30-b127-cf5a2c698dac';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ თქვენი ბავშვის სკოლამდელი განათლების დაწესებულებაში მიყვანას გეგმავთ, რამდენიმე საკითხს უნდა მიაქციოთ ყურადღება. სკოლაში პირველად წასვლის პერიოდი ხომ ბავშვებისთვისაც და მშობლებისთვისაც ერთნაირად ამაღელვებელია. რაც უფრო მშვიდად იქნებით ოჯახში, მით უფრო ჯანსაღად გაივლის თქვენი ბავშვი ამ გარდამავალ პერიოდს. ამ დროს ძალიან მნიშვნელოვანია, შეინარჩუნოთ სიმშვიდე და ენდოთ სასწავლო დაწესებულებას. საბავშვო ბაღი ან მოსამზადებელი ჯგუფი იქნება პირველი ადგილი, სადაც თქვენი ბავშვი სახლიდან მოშორებით, ოჯახის წევრების გარეშე დარჩება. ამ პერიოდში თქვენი მხარდამჭერი დამოკიდებულება მას ახალ გარემოსთან შეგუებას გაუადვილებს. ამ პროცესის დასრულების შემდეგ თქვენი ბავშვი ჯგუფში დამოუკიდებელ პიროვნებად ჩამოყალიბებასა და სოციალიზაციას დაიწყებს. ამ ასაკში მისი აღქმა ძალიან აქტიურია, ამიტომ გარემოს სხვადასხვა სტიმულის დახმარებით ის სწრაფად და ეფექტურად შეიძენს ახალ ცოდნას.') WHERE id = '88e562a2-5445-4b67-bbd0-d77c240f5606';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი უკვე 35 თვისაა. სხვაგვარად რომ ვთქვათ, მის 3 წლის იუბილემდე სულ რამდენიმე დღე დარჩა! გილოცავთ! 😊 35 თვის ბავშვს უკვე შეუძლია საკუთარი გადაწყვეტილებების მიღება. ამიტომ ახლა მისი მხოლოდ თქვენი შეხედულებების მიხედვით წარმართვა უფრო რთული გახდება. ამ პერიოდში მან სხვადასხვა სიტუაციაში თქვენგან განსხვავებული რამ შეიძლება მოითხოვოს. მაგალითად: საჭმელი მამამ მოამზადოს, დედა კი მე მეთამაშოს. მიუხედავად იმისა, რომ თქვენი ბავშვი უფრო დამოუკიდებელი გახდა, მას შესაძლოა კვლავ ეშინოდეს რაიმეს თქვენ გარეშე გაკეთების. ამიტომ, დამოუკიდებლობის განსამტკიცებლად და საკუთარი თავის მართვის სასწავლად, ხელი უნდა შეუწყოთ, რომ მარტომ ითამაშოს. გახსოვდეთ, რომ ის ჯერ კიდევ თქვენი პატარა ბავშვია, რომელიც სამყაროს შეცნობას ცდილობს. პრობლემების გადაჭრის ყველაზე ეფექტური გზა კი მასთან საუბარი და ურთიერთობაა.') WHERE id = '209004b7-d29a-4345-ba5f-85059bbd8a7e';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ პერიოდში თქვენი ბავშვის სიმაღლისა და წონის საშუალო მაჩვენებლებში შესაძლოა მკვეთრი ცვლილებები არ აღინიშნებოდეს. 35 თვის ბიჭების წონა საშუალოდ 16 kq-ია, გოგონებისა კი დაახლოებით 15 kq. ამ ეტაპზე წონა სქესსა და გენეტიკაზე მეტად კვებით ჩვევებსა და მადას უკავშირდება. სიმაღლე კი უფრო მჭიდროდ არის დაკავშირებული გენეტიკურ მაჩვენებლებთან. კვლევები აჩვენებს, რომ სიმაღლის განმსაზღვრელი ფაქტორების 80% გენეტიკურ კოდს უკავშირდება. მოკლედ რომ ვთქვათ, თუ დედა და მამა მაღლები არიან, მოსალოდნელია, რომ თქვენი ბავშვიც თანატოლებზე მაღალი იქნება. მიუხედავად ამისა, სასარგებლოა, იცნობდეთ პერცენტილების ცხრილს. 35 თვის გოგონების სიმაღლე შეიძლება 87-102 sm-ის, ხოლო ბიჭების — 89-103 sm-ის ფარგლებში მერყეობდეს.') WHERE id = '8106725e-0710-4935-aa3f-544d3a83dba4';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ ასაკში თქვენს ბავშვს უკვე შეუძლია 10-მდე დათვლა და სწავლობს ისეთი კითხვების დასმას, როგორებიცაა: "რა, სად, ვინ?" ეს ყველაფერი მეტყველების განვითარების უკვე უფრო მაღალ დონეზე მიუთითებს. ის ცდილობს, უფრო გამართულად ისაუბროს, რადგან მისი ლექსიკური მარაგი იზრდება და გონებრივი შესაძლებლობების განვითარებასთან ერთად ენას უფრო სწორად იყენებს. ამ პერიოდში შესაძლოა იმის მოწმეც გახდეთ, როგორ გეხუმრებათ თქვენი ბავშვი. ზოგჯერ მას შეიძლება მოსწონდეს კიდეც ამ ხუმრობებით თქვენი გაბრაზება. თუ მის გარშემო იუმორის მოყვარული ადამიანები არიან, მათი მიბაძვით თქვენი გაცინება სიამოვნებას მიანიჭებს. ძალიან კარგია, რომ ამ ასაკში თქვენს ბავშვს იუმორის გრძნობა აქვს. თუმცა მნიშვნელოვანია ხუმრობის შინაარსი და ასაკთან შესაბამისობა. თუ სხვებისგან უარყოფით მაგალითებს იღებს და ასე ხუმრობს, სიცილის ნაცვლად მას უნდა გაესაუბროთ და აუხსნათ, რატომ არ არის ეს მისაღები.') WHERE id = 'b3f8428e-6bca-4e17-b06f-253ecc4381cb';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ თქვენი ბავშვის უმადობასთან დაკავშირებული პრობლემები გაწუხებთ, იძულების ნაცვლად უნდა დაელოდოთ, სანამ მოშივდება. ძალით კვებამ შეიძლება უარყოფითად იმოქმედოს როგორც მის ფსიქოლოგიურ მდგომარეობაზე, ისე ფიზიკურ ჯანმრთელობაზე. ამის ნაცვლად, უმჯობესია, მისთვის არასასურველი საკვები გარკვეული შუალედებით კვლავ შესთავაზოთ. კვებასთან დაკავშირებით ერთ-ერთი ყველაზე მნიშვნელოვანი საკითხი დასჯისა და დაჯილდოების მეთოდებია. არასწორია ბავშვის დასჯა იმის გამო, რომ არ ჭამს, ან დაჯილდოება იმისთვის, რომ ჭამა. გახსოვდეთ, რომ ისიც თქვენნაირი პიროვნებაა. როგორც ყველა ადამიანის, ისე თითოეული ბავშვისთვის საჭირო საკვების რაოდენობაც შეიძლება განსხვავებული იყოს. ამიტომ სასარგებლოა სპეციალისტთან კონსულტაცია. თქვენი ბავშვის დღიური კალორიული საჭიროება შეგიძლიათ ექიმთან ვიზიტისას გაარკვიოთ ან დიეტოლოგს მისთვის შესაფერისი კვების გეგმა შეადგენინოთ.') WHERE id = '64ea6bc8-7775-4535-9a1e-fa17c68ef78b';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენს 35 თვის ბავშვს გარეთ გასვლისას უკვე დამოუკიდებლად შეუძლია ფეხსაცმლის ჩაცმა და გახდა. თუმცა თასმების შესაკრავად მას ჯერ კიდევ ცოტა დრო სჭირდება. ამასთანავე, მას შეუძლია დამოუკიდებლად ჩაიცვას და გაიხადოს ტანსაცმელი, შეიკრას ღილები და ელვაშესაკრავიც კი. ეს ყველაფერი მისი ნატიფი მოტორული უნარების ყოველდღიური განვითარების შედეგია. ახლა ის უკვე თავისუფლად აკეთებს ბევრ რამეს, რაც ადრე არ შეეძლო: ზრუნავს პირად ჰიგიენაზე, ხტება ცალ ფეხზე, ლეგოს ნაწილებით აგებს კოშკებს, ფურცლავს წიგნს და ჭიქას ცალი ხელით იჭერს. ამ უნარების კიდევ უფრო გასაუმჯობესებლად მას შესაბამისი პირობები უნდა შეუქმნათ. მაგალითად, მაშინაც კი, თუ ფიქრობთ, რომ ტანსაცმელს სრულად სწორად ვერ იცვამს, ამის შესაძლებლობა უნდა მისცეთ და აუცილებლობის გარეშე არ ჩაერიოთ.') WHERE id = '163cc8b7-054e-465f-87c5-aa48d630b9cc';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ძილის რეჟიმი ყველა ასაკში მნიშვნელოვანია, მათ შორის ამ ეტაპზეც, როცა თქვენი ბავშვი 3 წლის ხდება. თუ საწოლი შეუცვალეთ, ბავშვი მას შეეჩვია და მთელი ღამე გაღვიძების გარეშე სძინავს, აუცილებლად შეაქეთ ამ წარმატებისთვის. თუ საწოლიდან დგება და თქვენთან მოსვლა სურს, მშვიდად და თბილად უთხარით, რომ თავის საწოლში უნდა დაბრუნდეს და დაიძინოს. თუ მიზეზს ვერ იგებს და ჯიუტობს, მოკლედ და მისთვის გასაგები ენით აუხსენით. მიუხედავად ამისა, შესაძლოა, სხვადასხვა მიზეზის მოფიქრებით კვლავ ეცადოს, არ დაიძინოს. თუმცა შეეცადეთ, ამ საკითხთან დაკავშირებულ წესებში გამონაკლისები არ დაუშვათ. მოთმინებითა და თანმიმდევრული მიდგომით ამ პრობლემის მოგვარებას შეძლებთ. თუ მაშინვე დაძინება არ სურს, თავის ოთახში წიგნის კითხვა ან მშვიდად დროის გატარება მოდუნებასა და ძილისთვის მომზადებაში დაეხმარება.') WHERE id = 'a45f03f4-7495-4f93-9e19-ea1e8ffa609b';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ თქვენს შვილს ტუალეტის გამოყენების სწავლა ჯერ კიდევ არ დაუსრულებია, ამ კვირებში შეგიძლიათ სწავლის დაწყებაზე იფიქროთ. თუ ბავშვს განვითარების შეფერხება არ აქვს, 3 წელი ტუალეტის გამოყენების სწავლის დასაწყებად რეკომენდებული პერიოდის ბოლო ეტაპად მიიჩნევა. თუ დღისით შარდის შეკავება უკვე შეუძლია, დაძინებამდე 1 საათით ადრე სითხის მიღება უნდა შეუზღუდოთ, ძილის წინ ტუალეტში წაიყვანოთ და ღამით დაძინებისას საფენი აღარ გაუკეთოთ. თუ ბავშვი დღისით შარდის გამოყოფას აკონტროლებს, ღამით მისთვის საფენის გაკეთება წინააღმდეგობრივი მიდგომა იქნება და შესაძლოა, წარმატების მიღწევა შეაფერხოს. ღრმა ძილის მქონე ბავშვებს ღამით შარდის შეკავება შეიძლება შედარებით გაუჭირდეთ. თუმცა, თუ გარკვეული დროით მოთმინებით შეხვდებით დასვრილ გარემოს, პროცესი დაჩქარდება და ბავშვსაც აღარ აერევა. დასუფთავების გასამარტივებლად შეგიძლიათ საწოლის დამცავი საფენები გამოიყენოთ.') WHERE id = '10d272f3-fd20-44b4-9b09-1b4398b61ba5';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ პერიოდში თქვენი შვილის საკვების მიმართ დამოკიდებულება შეიძლება ყოველდღიურად იცვლებოდეს: ერთ დღეს სიამოვნებით მიირთვას რომელიმე კერძი, მეორე დღეს კი უარი თქვას მასზე. მთავარია, სუფრაზე მრავალფეროვანი და ჯანსაღი საკვები შესთავაზოთ, ხოლო რა და რამდენი მიირთვას, თავად აირჩიოს. მისთვის ნაცნობ და საყვარელ კერძებთან ერთად, დროდადრო წაახალისეთ, რომ ახალი საკვების პატარა ნაჭერი გასინჯოს. თუმცა ძალიან მნიშვნელოვანია, არ დააძალოთ. ნუ მოელით, რომ ახლად გასინჯული საკვების სრულ ულუფას მაშინვე მიირთმევს. იმის გასაგებად, მოსწონს თუ არა ბავშვს კონკრეტული საკვები, ის სულ მცირე 6-7-ჯერ უნდა გაასინჯოთ. თქვენი შვილის ჯანმრთელობისთვის მნიშვნელოვანია, რომ თითოეული კვებისას ცილების, მარცვლეულისა და ბოსტნეულის ჯგუფის საკვები მიიღოს. კვებებს შორის შოკოლადისა და შაქრის შემცველი პროდუქტების ნაცვლად ხილის მიცემა უფრო სასარგებლო იქნება.') WHERE id = 'ac9f56dc-94bf-4adb-a7ed-1d15446f273b';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ თქვენს 3 წლის ბავშვს ასაკობრივი კრიზისი აქვს, იატაკზე წვება და ყვირის, საუკეთესო, რაც შეგიძლიათ გააკეთოთ, სიმშვიდის შენარჩუნებაა. რა თქმა უნდა, ამის თქმა ადვილია, გაკეთება კი რთული. თუმცა ბავშვები, როგორც წესი, თქვენს ქცევას იმეორებენ. თუ კრიზისის დროს სიმშვიდეს შეინარჩუნებთ, თქვენს შვილს ასწავლით, რომ მომავალში სირთულეების დროს საკუთარი ემოციების მართვა შეძლოს. 3 წლის ასაკს მიღწეულმა ბავშვმა დამოუკიდებლობის დასამტკიცებლად შეიძლება სხვადასხვა გზას მიმართოს. არასასურველი შედეგების თავიდან ასაცილებლად, იმ ქცევების შემთხვევაშიც კი, რომლებიც არ მოგწონთ, თუ ამის გადაუდებელი აუცილებლობა არ არსებობს, არ უნდა ჩაერიოთ და ბავშვს საშუალება უნდა მისცეთ, გარკვეული საქმეები დამოუკიდებლად გააკეთოს. ამ პერიოდში მშობლები ხშირად ჩივიან, რომ ბავშვებს ტანსაცმლის თავად შერჩევა სურთ. ასეთ შემთხვევებში სპეციალისტები გვირჩევენ, ბავშვს რამდენიმე ვარიანტი შევთავაზოთ და მათგან არჩევანის გაკეთების საშუალება მივცეთ. ნუ ღელავთ, ეს პერიოდი დიდხანს არ გაგრძელდება! 😊') WHERE id = '77d3682e-ed32-46fd-bdc5-b4fcebf4896e';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბოლო პერიოდში თქვენი შვილის მეტყველების განვითარებაში ახალი წინსვლა შეინიშნება. საუბრისას უკვე შეგიძლიათ შეამჩნიოთ, რომ მის მიერ შედგენილი წინადადებები გრამატიკულად ფორმირდება. მან ასევე დაიწყო აზრებს შორის მიზეზშედეგობრივი კავშირის დამყარება. მისი ლექსიკური მარაგი საშუალოდ 300 სხვადასხვა სიტყვისგან შედგება. მას შეუძლია დიდხანს ესაუბროს საკუთარ თავს, თქვენ, თავის სათამაშოებსა და მეგობრებს. ახალი სიტყვების მიმართ მისი ინტერესი გაიზარდა. ის იწყებს იმის აღმოჩენას, თუ რა მიზნით გამოიყენება წინადადებებში კავშირი „და“. აღიქვამს აწმყოსა და მომავალ დროს, ასევე ისეთ ნაცვალსახელებს, როგორიცაა „მე“ და „შენ“. მარტივ თანდებულებსა და ნაცვალსახელებს წინანდელთან შედარებით უფრო სწორად იყენებს. სწავლობს ფერების სახელებს, თუმცა შესაძლოა, ჯერ კიდევ ვერ ახერხებდეს ფერისა და მისი სახელწოდების ზუსტად დაკავშირებას. მაგალითად, შეიძლება ერთმანეთში აერიოს მსგავსი ფერები, როგორიცაა წითელი და ვარდისფერი ან ყვითელი და ნარინჯისფერი.') WHERE id = 'a7f6f0c5-f1b1-4f0e-b9c2-28b4975c766e';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'საქმიანობა, რომელიც თითქმის 3 წლის ბავშვს შეუძლია შეასრულოს და, სავარაუდოდ, ყველაზე მეტადაც მოეწონება, გაფერადებაა. გაფერადება არა მხოლოდ აუმჯობესებს თქვენი შვილის თვალისა და ხელის კოორდინაციას, არამედ საგნების აღქმისა და გააზრების უნარსაც აძლიერებს. რადგან ხატვა რთული და კომპლექსური პროცესია, მისთვის საინტერესო საღებავები უნდა შეარჩიოთ და თავისუფლად ხატვისთვის სივრცე შეუქმნათ. შეგიძლიათ უსაფრთხოდ გამოიყენოთ ცვილის ფანქრები; უმჯობესია, უფრო მსხვილი, jumbo ზომის ფანქრები შეარჩიოთ. ბავშვს შეიძლება მოსწონდეს გაფერადება, მაგრამ თუ შესაბამის ფანქრებს არ შეურჩევთ, ეს საქმიანობა მისთვის უინტერესო გახდება. თუ ფერადი ფანქრების შეძენას აპირებთ, ამ შემთხვევაშიც უპირატესობა მსხვილ (jumbo) ზომას მიანიჭეთ. გაფერადებისას თითების თავისუფლად მოძრაობის შესაძლებლობა თქვენი შვილისთვის ერთ-ერთი ყველაზე მნიშვნელოვანი პირობაა.') WHERE id = 'ce9d6e51-8832-4d9d-bbb8-766b28abc2e6';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ ამ პერიოდში თქვენს ბავშვს დღისით დაძინება არ სურს, საღამოს ძილის დრო უფრო ადრე უნდა გადაიტანოთ. შესაძლოა, მას ეშინოდეს, რომ კარადიდან ან საწოლის ქვემოდან ვინმე გამოვა, ან სიბნელის შიში ჰქონდეს. ასეთ დროს არ უნდა უპასუხოთ: არა, სისულელეა! ან რა უაზრო შიშია! ასეთი რეაქცია არა მხოლოდ ვერ გაუქრობს შიშს, არამედ შესაძლოა მის განვითარებასაც სერიოზული ზიანი მიაყენოს. გახსოვდეთ, რომ შიშის განცდა თქვენი ბავშვის განვითარების მნიშვნელოვანი ეტაპია. როცა მას ეშინია, შეგიძლიათ დამამშვიდებლად ესაუბროთ, წიგნი წაუკითხოთ, აუხსნათ განსხვავება რეალობასა და სიზმარს შორის და იმაზე დაელაპარაკოთ, რისიც ეშინია. ამგვარად, ბავშვს დაეხმარებით, სწორად გაიაზროს შიშის განცდა და ისწავლოს, როგორ მოიქცეს შიშის დროს.') WHERE id = '70f5b6ed-9e2c-4dc4-adbf-c9b127e85789';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'კეფირი ერთ-ერთი ყველაზე სასარგებლო სასმელია, რომელიც თქვენი ბავშვის კვების რაციონში უნდა შედიოდეს. ცივი ჩაის, გაზიანი და ყავის შემცველი სასმელების ნაცვლად, ბავშვს ისეთი ჯანსაღი ჩვევა უნდა გამოუმუშაოთ, როგორიც კეფირის დალევაა. ამასთანავე, მაღაზიაში გასაყიდი მზა პროდუქტის ნაცვლად, კეფირი სახლშიც მარტივად შეგიძლიათ მოამზადოთ. აფთიაქში ან სანელებლების მაღაზიაში შეძენილი კეფირის საფუარი ოთახის ტემპერატურის რძიან ჭურჭელში დაამატეთ და მსუბუქად შეანჯღრიეთ. შემდეგ ჭურჭელს დააფარეთ, რათა სინათლე არ მოხვდეს, და გააჩერეთ. ოთახის ტემპერატურაზე სულ მცირე 1 დღის გაჩერების შემდეგ საფუარი სითხისგან პლასტმასის საწურის საშუალებით შეგიძლიათ გამოყოთ. კეფირის მომზადებისას ასევე მნიშვნელოვანია, არ გამოიყენოთ ლითონის ჭურჭელი ან კოვზი, რადგან ლითონის ნივთებმა შესაძლოა საფუარს მოქმედების უნარი დაუკარგოს.') WHERE id = 'b9a410f0-fac4-4211-b529-90bd6f7038fb';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ პერიოდში შეიძლება შეამჩნიოთ, რომ თქვენი ბავშვი ზოგჯერ თქვენთვის მიუღებლად ან არასასურველად იქცევა. ასეთ შემთხვევებში უნდა აღიაროთ მისი იმჟამინდელი ემოცია, კონსტრუქციულად დაუწესოთ საზღვრები და აუცილებლად შესთავაზოთ ალტერნატივა. მაგალითად, შეგიძლიათ უთხრათ: დიახ, მესმის, რომ ახლა გაბრაზებული ხარ, მაგრამ სახლში ნივთები იატაკზე გადასაყრელად არ არის; ამის ნაცვლად, შეგიძლია შენი სათამაშოები ყუთში ჩაყარო. ასე ბავშვი მიხვდება, რომ მისი ემოცია გაიგეთ და თავადაც მიიღეთ, თუმცა კონკრეტული საქციელი არ იყო სწორი. თუ აკრძალვის დაწესებისას მის პიროვნებასაც გააკრიტიკებთ, ბავშვის თვითშეფასება დაზიანდება და მან შესაძლოა სიჯიუტის გამო იგივე ქცევა განაგრძოს. ამიტომ, იმის ნაცვლად, რომ სიტყვებით ცუდი ბავშვი ხარ მის პიროვნებას შეუტიოთ, უნდა აღიაროთ მისი გრძნობები, მკაფიოდ განუსაზღვროთ ქცევის საზღვრები და უფრო სასარგებლო საქმიანობა შესთავაზოთ. ძალიან მნიშვნელოვანია, ეს მეთოდი მშვიდად და თანმიმდევრულად გამოიყენოთ, რადგან თუ იმას, რასაც ერთ დღეს უკრძალავთ, მეორე დღეს ნებას დართავთ, ბავშვს გაურკვევლობის განცდა გაუჩნდება.') WHERE id = '4e533ab4-dd97-4697-9a7a-2763d84d0153';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბევრი სპეციალისტის აზრით, ბავშვები დამოუკიდებლობის ნიშნების გამოვლენას 18-24 თვის ასაკში იწყებენ. როდესაც თქვენი ბავშვი 3 წლის გახდება, ეს მოთხოვნილებები კიდევ უფრო გაძლიერდება და ის დაიწყებს იმის გამოხატვას, რომ "მე ცალკე პიროვნება ვარ". ამ პერიოდში ბავშვს სურს, აღიაროთ, რომ მას საკუთარი აზრები აქვს, და მათ პატივისცემით მოეკიდოთ. განვითარებულ ქვეყნებში 3 წლის ასაკის ამ ეტაპს "threenager"-ს უწოდებენ, რაც "პატარა მოზარდს" ნიშნავს. როგორც მშობელს, შეიძლება ზოგჯერ მოთმინება გამოგელიოთ, თუმცა გახსოვდეთ, რომ 3 წლის ასაკის სინდრომი სამუდამოდ არ გაგრძელდება! მშობლებს ისიც აინტერესებთ, რამდენ ხანს გრძელდება ეს პერიოდი. სხვა ეტაპების მსგავსად, 3 წლის ასაკის სინდრომსაც ზუსტი დროითი საზღვრები არ აქვს. თუმცა, გავრცელებული მოსაზრებით, ეს პერიოდი 2 წლის ასაკის სინდრომთან შედარებით უფრო მძაფრად, მაგრამ უფრო ხანმოკლედ მიმდინარეობს.') WHERE id = 'ad73d53b-9ddf-47dd-846f-bc47a9465bbe';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'შესაძლოა, ჯერ კიდევ თქვენი ბავშვის ნათქვამისა და მის მიერ შედგენილი წინადადებების ნახევარიც კი ვერ გაიგოთ. მის თანატოლებს შორის შეიძლება იყვნენ ბავშვები, რომლებიც უკეთ საუბრობენ, თუმცა მათი შედარება საჭირო არ არის. ბავშვის განვითარების სპეციალისტების აზრით, საშუალოდ 4 წლის ასაკამდე ნორმალურია, თუ ბავშვის ნათქვამი სრულად გასაგები არ არის. მოკლედ, ეს ბუნებრივი პროცესია. თუმცა, თუ ფიქრობთ, რომ თქვენი ბავშვი თანატოლებს მნიშვნელოვნად ჩამორჩება, შეგიძლიათ სპეციალისტს მიმართოთ. ამ ეტაპზე მას შეუძლია 3-4 სიტყვისგან შემდგარი მარტივი წინადადებების აგება და ორსაფეხურიანი მითითებების შესრულება, მაგალითად: "აიღე ჩემი სათამაშო და მომიტანე". ნაცვალსახელების გამოყენება მისთვის ჯერ კიდევ რთული შეიძლება იყოს, ამიტომ ნორმალურია ისეთი მოკლე, ნაცვალსახელის გარეშე ნათქვამი ფრაზების მოსმენა, როგორიცაა "ჭამე" ან "მშია". თუ ხშირად წაუკითხავთ წიგნებს ან ერთად მოიგონებთ ამბებს, ეს პროცესს უფრო სახალისოს გახდის და ბავშვის მეტყველების განვითარებასაც დააჩქარებს.') WHERE id = 'ec5bfd9e-b028-4a27-9161-19876bcbf319';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ პერიოდში შეიძლება შეამჩნიოთ, რომ თქვენს ბავშვს საჭმლის მომნელებელი სისტემის გარკვეული პრობლემები და აირებით გამოწვეული ტკივილი აქვს. ზოგიერთი სპეციალისტის აზრით, აირების პრობლემა უფრო ხშირად აქვთ ბავშვებს, რომლებიც ჭამისას დადიან, თამაშობენ ან ტელევიზორს უყურებენ. ამ მოსაზრების თანახმად, თამაშით აღგზნებული ბავშვები სწრაფად ჭამენ და ყლაპავენ, რის გამოც ბევრ ჰაერსაც ყლაპავენ და ეს საჭმლის მონელების პრობლემებს იწვევს. აირების პრობლემის თავიდან ასაცილებლად მნიშვნელოვანია, ბავშვმა ოჯახის წევრებთან ერთად სუფრასთან ნელა ჭამოს. საკვების საკმარისი რაოდენობითა და ნორმალურ დროში მიღება უფრო ჯანსაღია, ვიდრე სწრაფად ან საჭიროზე მეტი ჭამა. ამიტომ, თუ თქვენს ბავშვს სწრაფად ჭამის ჩვევა აქვს, ეცადეთ, ეს ჩვევა ჯერ კიდევ სკოლამდელ ასაკში გადააჩვიოთ. ამგვარად, მომავალში მას არც მსგავსი საჭმლის მომნელებელი პრობლემები შეაწუხებს და არც ჭარბი წონის პრობლემა შეექმნება.') WHERE id = '2a5e6072-b787-4135-92b2-5c7dcfe3dd8a';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბოლო დროს თქვენი ბავშვის მეტყველებაში მნიშვნელოვანი განვითარება უნდა შეგემჩნიათ. მაგალითად, მას უკვე შეუძლია ორ-სამწინადადებიანი საუბრის წარმართვა და წინადადებებში სუფიქსების გამოყენებას იწყებს. აწყობს გრამატიკულად გამართულ წინადადებებს, როგორიცაა „ეს სათამაშოა“; იყენებს ისეთ კატეგორიებს, როგორებიცაა სათამაშო, ცხოველი და საკვები. იყენებს სურვილისა და მომავალი დროის ფორმებს და შეუძლია საგნები აღწეროს, როგორც ღია ან დახურული. კითხვით წინადადებებში სათანადოდ იყენებს კითხვით ნაწილაკებს, ხოლო შეკითხვისას შეუძლია თავისი სახელისა და გვარის თქმა (თუმცა შეიძლება ყოველთვის არ სურდეს უცნობებისთვის საკუთარი სახელის გამხელა). მას ასევე შეუძლია ერთმანეთისგან დამოუკიდებელი ორი თანმიმდევრული დავალების შესრულება. მაგალითად, თუ ეტყვით: „შეგიძლია იატაკზე დაგდებული ქაღალდი აიღო და ნაგვის ურნაში ჩააგდო?“, ორივე მოქმედებას თანმიმდევრულად შეასრულებს. თუ ამ ყველაფრის მიუხედავად მისი მეტყველება ჯერ კიდევ ბოლომდე გასაგები არ არის, სასარგებლო იქნება მეტყველების სავარჯიშოების შესრულება.') WHERE id = '78c832c1-4c0d-4309-9e24-09ccab108546';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ თქვენს ბავშვს ხშირად აქვს დიარეა, უპირველესად ყურადღება უნდა მიაქციოთ მის საკვებს. მაგალითად, ბოსტნეულის კერძები ძალიან სასარგებლოა, თუმცა მათში სანელებლების ჭარბმა რაოდენობამ ბავშვში შესაძლოა დიარეა გამოიწვიოს. ცნობილია, რომ განსაკუთრებით ასეთი ეფექტი აქვს ცხარე წიწაკას. კიდევ ერთი მიზეზი შეიძლება იყოს შემწვარი საკვების ხშირი მიღება — ბავშვმა ასეთი საკვები კვირაში ერთხელზე ხშირად არ უნდა მიირთვას. დიარეამ ზრდასრულებშიც კი შეიძლება მოკლე დროში გამოიწვიოს დეჰიდრატაცია (გაუწყლოება), ბავშვებში კი მისი გავლენა გაცილებით მძიმე შეიძლება იყოს. ამიტომ მნიშვნელოვანია, გახსოვდეთ, რომ თითოეული საკვები, რომელსაც თქვენს ბავშვს აძლევთ, პირდაპირ მოქმედებს მის ჯანმრთელობაზე.') WHERE id = 'c8770cc7-96b4-4f44-abc5-fe4118707f16';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ პერიოდში რეკომენდებულია, თქვენი ბავშვი თანდათან მოამზადოთ სკოლამდელი განათლებისთვის. მიუხედავად იმისა, რომ ადრე სკოლამდელი განათლება უფრო მეტად მომუშავე დედებისთვის გამოსავლად მიიჩნეოდა, დღეს სპეციალისტები თანხმდებიან, რომ ის ყველა ბავშვმა უნდა მიიღოს. თქვენი ბავშვის განვითარებასა და საკუთარი აზრების გამოხატვის დაწყებასთან ერთად, მშობლისთვის სულ უფრო რთული ხდება მისი ყველა ინტერესისა და საჭიროების დამოუკიდებლად დაკმაყოფილება. თანამედროვე ბავშვები უფრო ცნობისმოყვარეები და სწავლისადმი მეტად გახსნილები არიან. სკოლამდელი განათლება ძალიან მნიშვნელოვანია თქვენი ბავშვის ჯანსაღი განვითარებისა და დამოუკიდებელ პიროვნებად ჩამოყალიბებისთვის. კვლევები აჩვენებს, რომ ამ პერიოდში ბავშვები ძალიან სწრაფად და ეფექტურად სწავლობენ. სათანადო ფიზიკურ და სოციალურ გარემოში თანატოლებთან ურთიერთობა მისი მომავალი წარმატებისთვის მყარ საფუძველს ქმნის.') WHERE id = '09cc45a6-5357-478d-806f-e921dc4066af';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ოდესმე გიფიქრიათ, რომ ამ ასაკში თქვენს შვილსაც, ისევე როგორც ზრდასრულებს, შეიძლება დეპრესია ჰქონდეს? მიუხედავად იმისა, რომ საზოგადოებაში ეს მოსაზრება ფართოდ მიღებული არ არის, სპეციალისტები აღნიშნავენ, რომ ბავშვებიც ხშირად განიცდიან სევდასა და დეპრესიას. ბავშვებში დეპრესიის ნიშნები ზრდასრულებისგან განსხვავებული, მრავალფეროვანი სიმპტომებით შეიძლება გამოვლინდეს. ზოგადად, ყურადღების გაფანტვა, ჰიპერაქტიურობა, სწავლის სირთულეები, ქცევითი დარღვევები ან მუდმივი პროტესტი შესაძლოა დეპრესიის მაჩვენებელი იყოს. განსაკუთრებით ოჯახში ახალი დის ან ძმის გაჩენა ბავშვის დეპრესიის ერთ-ერთი მთავარი მიზეზია. ამ დროს ბავშვი ღელავს: „ახლა მშობლებს აღარ ვეყვარები?“ ზოგჯერ ის ჩვილის მიმართ აგრესიულად იქცევა, ზოგჯერ კი, პირიქით, ზედმეტად დიდ სიყვარულს ავლენს. კლინიკური დაკვირვებების თანახმად, ბავშვი, რომელიც ამ შინაგან კონფლიქტს განიცდის, საკუთარ გრძნობებს ხშირად ფრაზით „ძალიან მოწყენილი ვარ“ გამოხატავს.') WHERE id = 'd5cee6e1-14a0-4774-a124-d29478e56e0b';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამჩნევთ, რამდენად განვითარდა თქვენი ბავშვის მოტორული უნარები ამ ეტაპზე? მან უკვე მიაღწია იმ დონეს, როდესაც ყოველდღიური საქმეების შესრულება — ჩაცმა, ჭამა, თამაშის შემდეგ სათამაშოების ალაგება და კბილების გახეხვა — თითქმის დაუხმარებლად შეუძლია. ალბათ მის თამაშებშიც შენიშნავდით ცვლილებებს. ბავშვმა უკვე დაიწყო თამაშების დამოუკიდებლად მოფიქრება და შესაძლოა იმასაც ამჩნევდეთ, რომ თავის მოფიქრებულ თამაშებში თქვენ და თანატოლებს დავალებებს გაძლევთ. ამასთანავე, თქვენმა ბავშვმა უკვე მიაღწია იმ ეტაპს, როდესაც თქვენი მეთვალყურეობის ქვეშ მაკრატლით სხვადასხვა ფორმის ამოჭრა შეუძლია. ეს აქტივობა დაეხმარება მას თითების უკეთ გამოყენებასა და, შესაბამისად, ნატიფი მოტორული უნარების განვითარებაში. თუმცა გახსოვდეთ, რომ მაკრატელი ბასრი და სახიფათო ხელსაწყოა, ამიტომ ბავშვს ყურადღებით უნდა აკონტროლოთ.') WHERE id = '52831199-fbe3-4b62-ad35-73e2e71edbc4';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'მიუხედავად იმისა, რომ ამ ეტაპზე თქვენი ბავშვი ზოგიერთი საქმის დამოუკიდებლად კეთებას სწავლობს, მას ჯერ არ აქვს ფიზიკური უნარი, ყველაფერი თავად გააკეთოს. ანალოგიურად, მიუხედავად იმისა, რომ უკვე მეტი სიტყვა იცის და შესაძლოა რამდენიმე წინადადების შედგენაც შეეძლოს, ჯერ კიდევ არ შეუძლია ყველა გრძნობისა და აზრის სრულად სიტყვიერად გამოხატვა. ამიტომ, როცა რაღაცის ისე გაკეთებას ვერ ახერხებს, როგორც სურს, ან საკუთარი სათქმელის გადმოცემა უჭირს, შესაძლოა ბრაზის შეტევები ჰქონდეს. ფიზიკური და მეტყველების უნარების შეზღუდულობის გამო საკუთარი თავის სრულად გამოხატვის შეუძლებლობა მასში დაძაბულობას იწვევს. გარდა ამისა, რადგან ყოველთვის ვერ ახერხებს სიტყვებით თქმას, რომ მოიწყინა, დაიღალა ან შია, შესაძლოა ყვირილით, ტირილით ან იატაკზე გაწოლით ცდილობდეს ამ საჭიროებების გამოხატვას და თქვენთვის გაგებინებას. მნიშვნელოვანია, იცოდეთ ეს ყველაფერი და გახსოვდეთ, რომ ასეთი ქცევა ამ ასაკის ბავშვისთვის ნორმალურია — ეს დიდ გავლენას ახდენს თქვენს დამოკიდებულებაზე ბავშვის მიმართ. ბრაზისა და ტირილის ეპიზოდების შესამცირებლად, ბავშვის გაბრაზების ნაცვლად, შეგიძლიათ სხვადასხვა ემოციური აქტივობის დახმარებით ასწავლოთ საკუთარი გრძნობების გაგება და ერთმანეთისგან გარჩევა, რათა მომავალში ემოციებისა და აზრების უფრო კონსტრუქციულად გამოხატვა შეძლოს.') WHERE id = 'bc00e9df-4632-4728-bd4b-cc292b91d13e';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'წესები და დისციპლინა ეფექტიანი აღზრდის განუყოფელი ნაწილია და ხელს უწყობს თქვენი ბავშვის მომავალ წარმატებას. გარემო, სადაც საზღვრები მკაფიოდ და მტკიცედ არის განსაზღვრული, ბავშვის განვითარებას საუკეთესოდ უწყობს ხელს. წესები ბავშვის თავისუფლებას კი არ ზღუდავს, არამედ ეხმარება, უსაფრთხო გარემოში გახდეს დამოუკიდებელი, გაარჩიოს კარგი და ცუდი, სწორი და არასწორი და გამოიმუშაოს თვითდისციპლინა. თუმცა ძალიან მნიშვნელოვანია, რომ წესები გარკვეულ სისტემას ეფუძნებოდეს და თანმიმდევრული იყოს. თუ ბავშვს ერთ დღეს რაღაცის უფლებას მისცემთ, მეორე დღეს კი აუკრძალავთ, ამან შესაძლოა წესებისადმი მისი პატივისცემა შეასუსტოს. ზედმეტმა შეზღუდვებმაც შეიძლება გამოიწვიოს ის, რომ ბავშვმა ვერ გაიგოს მათი მიზეზი და წინააღმდეგობა გაგიწიოთ. ბავშვისთვის უფრო რეალური და შესასრულებელია ის წესები, რომლებიც გასაგებ სიტუაციებს ეხება და რომელთა მიზეზის ახსნაც შესაძლებელია.') WHERE id = 'daec4206-a96e-46c2-8e87-38016160371c';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'შესაძლოა იცოდეთ, რამდენად სასარგებლოა თევზი, მაგრამ არ იცოდეთ, როგორ დაარწმუნოთ ბავშვი მის ჭამაში. პირველ რიგში, როგორც ყველა სხვა საკვების შემთხვევაში, იმისთვის, რომ ბავშვი კერძს შეეჩვიოს და შეიყვაროს, საჭიროა ეს საკვები 10-20-ჯერ ნახოს და ხშირად ხედავდეს, რომ მას ოჯახის წევრები საერთო სუფრასთან მიირთმევენ. რადგან უფროსებიც თევზს სხვა პროდუქტებთან შედარებით ნაკლებად მიირთმევენ, სრულიად ბუნებრივია, რომ ბავშვს მასთან შესაჩვევად უფრო მეტი დრო დასჭირდეს. გახსოვდეთ, რომ ახლა ისეთ პერიოდში ხართ, როდესაც ბავშვი განსაკუთრებით ჯიუტობს და მრავალი საკვების უარყოფისკენ არის მიდრეკილი. ამიტომ, კვებისადმი პრეტენზიულობის პერიოდში თევზზე უარის თქმა სულაც არ ნიშნავს, რომ ბავშვს მისი გემო არ მოსწონს ან არასდროს მოეწონება. სხვა სახის ხორცისგან განსხვავებით, თევზს ხშირად მთლიანად აჩვენებენ. ბავშვს შეიძლება აშინებდეს ან დისკომფორტს უქმნიდეს თევზის თავი, კუდი და მისკენ მიმართული თვალები. თუ თქვენი ბავშვის შემთხვევაშიც ასეა, უმჯობესია, თევზი სუფრაზე ფილეს ან ნაჭრების სახით მიიტანოთ.') WHERE id = '3ce2c11b-ecd0-47c6-af07-b3a6d4a2ed23';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'რადგან თქვენი ბავშვის მეტყველების უნარი კიდევ უფრო განვითარდა, ამ პერიოდში შესაძლოა მრავალი შეკითხვის დასმა დაიწყოს. ალბათ ხშირად გაიგონებთ შემეცნებით შეკითხვებს, როგორიცაა: „ფოთლები რატომ ცვივა?“, „მზე რატომ არის ყვითელი?“ ან „ზღვა რატომ არის ლურჯი?“. ამ პერიოდში ბავშვი ასევე იწყებს „მსგავსისა“ და „განსხვავებულის“ ცნებების გაგებას, საგნების ზომების, ფორმებისა და ფერების შედარებასა და გარჩევას. რადგან მისი წარმოსახვა აქტიურად ვითარდება, შესაძლოა შეამჩნიოთ, რომ მიბაძვით თამაშებს უკვე უფრო შემოქმედებითად თამაშობს. ამავე დროს, განვითარებული წარმოსახვის გამო შეიძლება ისეთი შიშები გაუჩნდეს, რომლებიც ადრე არ ჰქონია. მაგალითად, შეიძლება სჯეროდეს, რომ სახლში ურჩხული იმალება, ან ფიქრობდეს, რომ ღამით მასთან ერთად წარმოსახვით მეგობარს სძინავს. შესაძლოა იმასაც შეამჩნიოთ, რომ გარკვეული დროის შემდეგ თქვენ მიერ მოყოლილი ისტორიების ზოგიერთი ნაწილი ახსოვს და მეხსიერებაში დარჩენილ ფრაგმენტებს გიყვებათ.') WHERE id = 'd3b957d4-3ab1-417b-8bbe-00cb8a21a286';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, '2-6 წლის ასაკის ბავშვების დაახლოებით 5%-ს შეიძლება ჰქონდეს მეტყველების დარღვევა, რომელსაც ენაბორძიკობა ეწოდება. ამ ასაკობრივ ჯგუფში, განსაკუთრებით 3-4 წლის პერიოდში, შესაძლოა გამოვლინდეს მდგომარეობა, რომელსაც ფიზიოლოგიურ ენაბორძიკობას უწოდებენ. ბიჭებში ენაბორძიკობის პრობლემა გოგოებთან შედარებით თითქმის 2-ჯერ უფრო ხშირია. სპეციალისტების თქმით, ენაბორძიკობის მსგავსმა მეტყველების პრობლემებმა შეიძლება მნიშვნელოვანი სირთულეები გამოიწვიოს როგორც ოჯახში, ისე მის გარეთ და სხვადასხვა სახის ადაპტაციის პრობლემებიც შექმნას. ამ მხრივ, თუ ოჯახურ ანამნეზშიც არის მეტყველების დარღვევა, აუცილებლად მნიშვნელოვანია სპეციალისტის დახმარების მიღება. სპეციალისტთან დროული მიმართვისა და ადრეული ჩარევის შემთხვევაში, ენაბორძიკობის პრობლემა მოზარდობის ასაკამდე 80%-ით შეიძლება გამოსწორდეს. თუ თქვენს ბავშვს ასეთი პრობლემა აქვს, ამ პერიოდში ნუ დაადანაშაულებთ და ნუ მოახდენთ მასზე ზეწოლას.') WHERE id = '42f63232-fd9a-4cbc-b534-0404c45b38f0';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'პარკოსნები ბოჭკოს ყველაზე მაღალი შემცველობის მქონე საკვები ჯგუფია. ისინი ანელებს კუჭის დაცლის სიჩქარესა და წვრილი ნაწლავიდან გლუკოზის შეწოვას, რითაც სისხლში შაქრის დონის დაბალანსებას უწყობს ხელს. ამასთანავე, ხელს უწყობს სისხლში ქოლესტეროლისა და არტერიული წნევის სასურველ დონეზე შენარჩუნებას. კუჭში წყალთან ერთად გაფუებისას პარკოსნები დანაყრების შეგრძნებას იწვევს და თქვენს ბავშვს დღის განმავლობაში საჭირო ენერგიით უზრუნველყოფს. ამასთან, მუხუდოს, ხმელი ლობიოს, ბროკოლისა და ყვავილოვანი კომბოსტოს მსგავსი ზოგიერთი ბოსტნეული და ხმელი პროდუქტი სასარგებლოა, თუმცა აირების წარმოქმნაც შეუძლია. თქვენი ბავშვისთვის ამ პროდუქტების მიღება ძალიან სასარგებლოა! თუმცა უნდა დარწმუნდეთ, რომ ზედიზედ და დიდი რაოდენობით არ მიირთმევს. კერძის მომზადებისას პარკოსნების დასალბობად გამოყენებული წყალი აუცილებლად გადაღვარეთ, შემდეგ კი ისინი კარგად გარეცხეთ. კერძში ერთი კოვზი კამის ან მუსკატის კაკლის დამატებაც აირების წარმოქმნის თავიდან აცილებას შეუწყობს ხელს.') WHERE id = 'ef688bea-192e-4e4e-8e2b-89b299796329';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'იცოდით, რომ ბავშვის ცნობისმოყვარეობის სტიმულირებით შეგიძლიათ ხელი შეუწყოთ მისი ინტელექტის განვითარებას? ბავშვის ხასიათის შესაბამისი თამაშებისა და სცენარების მოფიქრებით მნიშვნელოვან წვლილს შეიტანთ მის ინტელექტუალურ განვითარებაში. მაგალითად, შეგიძლიათ დამალოთ სხვადასხვა ნივთი, სთხოვოთ ბავშვს მათი პოვნა და თქვას, რა ნივთია ეს. მიეცით საშუალება, შეხებისა და ცნობისმოყვარეობის დახმარებით გამოიცნოს ალუმინის ფოლგაში გახვეული სხვადასხვა ნივთი. ეს შეიძლება იყოს ნებისმიერი საყოფაცხოვრებო ნივთი — კოვზი, საყვარელი სათამაშო, პლასტმასის ჭიქა ან თუნდაც თქვენი კოსმეტიკური საშუალებები. ცნობისმოყვარეობით სავსე გარემოში ბავშვი აქტიურად ერთვება სწავლის პროცესში. ცნობისმოყვარეობით გაღვივებული სწავლის სურვილი არა მხოლოდ ხელს უწყობს ბავშვის ინტელექტის განვითარებას, არამედ ეხმარება მას, თანატოლებთან შედარებით უფრო ღრმად შეისწავლოს მისთვის საინტერესო საკითხი.') WHERE id = '6725b944-c3f1-499c-a21a-3bbbd23afe4b';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენს ბავშვს, რომელიც უკვე რამდენიმე თვეა დადის და გარემოს იკვლევს, მანძილისა და მიმართულების აღქმასთან ერთად მეხსიერებისა და შემეცნების უნარებიც განუვითარდა. ამ პერიოდში ის მიმართულებების შესწავლას იწყებს. თავდაპირველად შეუძლია აითვისოს ისეთი მარტივი ცნებები, როგორებიცაა წინ და უკან, მოგვიანებით კი — ზემოთ და ქვემოთ, შიგნით და გარეთ და სხვა საპირისპირო ცნებები. მას ასევე ესმის მსგავსებისა და განსხვავების ცნებები და შეუძლია საგნების ზომების, ფორმებისა და ფერების შედარება და გარჩევა. რადგან მისი წარმოსახვა სწრაფად ვითარდება, შეიძლება შეამჩნიოთ, რომ მიბაძვით თამაშებს უკვე უფრო შემოქმედებითად თამაშობს. თუ დასათვლელ საგნებს თვალით ვერ ხედავს, შესაძლოა ჯერ გონებაში დათვლა არ შეეძლოს. ამ უნარის განვითარებაში შეგიძლიათ დაეხმაროთ, თუ ასწავლით სათამაშო კუბების ერთმანეთზე დალაგებას და თან 1, 2, 3-ის დათვლას. ამასთან, მოერიდეთ მისი ასაკისთვის ზედმეტად რთული თამაშებისა და სათამაშოების შეძენას. ბავშვის შესაძლებლობებზე მუდმივად უფრო რთული ამოცანების შეთავაზებამ შეიძლება მის ფსიქოლოგიურ მდგომარეობაზე უარყოფითად იმოქმედოს; მისი ასაკისთვის შესაფერისი LEGO-ს კონსტრუქტორები და თამაშები განვითარებისთვის ბევრად უფრო სასარგებლო იქნება.') WHERE id = '41a7e71a-e46c-4110-ac09-a7e8357cae05';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, '[[თარგმანი ვერ შესრულდა]] ამ განყოფილების დამუშავებისას მოხდა შეცდომა. ორიგინალის დასაწყისი: "თქვენი ბავშვის მეტყველების უნარი ცოტა..."') WHERE id = 'aad2bc69-ad6a-413b-90fa-aefe2a168556';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, '[[თარგმანი ვერ შესრულდა]] ამ განყოფილების დამუშავებისას მოხდა შეცდომა. ორიგინალის დასაწყისი: 3 წლის ასაკიდან თქვენი ბავშვი...') WHERE id = '0d5b4196-e611-4d6d-85b3-4906d4cda8aa';
