UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, '[[თარგმანი ვერ შესრულდა]] ამ განყოფილების დამუშავებისას მოხდა შეცდომა. ორიგინალის დასაწყისი: თქვენი ბავშვის ინტელექტუალური განვითარების...') WHERE id = 'ab9bda44-8551-4efb-83a1-2cd1c1dbdb5b';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, '[[თარგმანი ვერ შესრულდა]] ამ განყოფილების დამუშავებისას მოხდა შეცდომა. ორიგინალის დასაწყისი: თქვენი ბავშვის წონისა და სიმაღლის საშუალო...') WHERE id = 'd8fbb3b8-bb5c-4edd-9483-cf983895ad96';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვის ზოგადი ჯანმრთელობის შესანარჩუნებლად საკმარისია, მან დღეში დაახლოებით 200 მლ, ანუ 1 ჭიქა კეფირი დალიოს. კეფირი იოგურტზე უფრო ნოყიერია. რძეში არსებული ყველა სასარგებლო ნივთიერების გარდა, კეფირის მარცვლებში შემავალი პრობიოტიკური ბაქტერიები მის კვებით ღირებულებას კიდევ უფრო ზრდის. ამასთანავე, ბავშვის ორგანიზმი კეფირს უფრო ადვილად ითვისებს. ცილების, აუცილებელი მინერალებისა და B ჯგუფის ვიტამინების მაღალი შემცველობა მას სხვა რძის პროდუქტებისგან გამოარჩევს. კეფირი განსაკუთრებით მდიდარია B12, B1 და K ვიტამინებით. იოგურტი საჭმლის მომნელებელი სისტემის გაწმენდასა და სასარგებლო ბაქტერიების კვებას უწყობს ხელს, კეფირი კი შეიცავს ბაქტერიებს, რომლებიც ნაწლავის მიკროფლორას აბალანსებს და აძლიერებს. მოკლედ, ბავშვის რაციონში იოგურტის მსგავსად კეფირიც უნდა შეიტანოთ. თუ თქვენს ბავშვს უბრალო კეფირის გემო არ მოსწონს, შეგიძლიათ სახლში არსებული ხილით შეაზავოთ და განსხვავებული გემოები შეუქმნათ.') WHERE id = 'd5d21407-1821-4172-9e4c-16f1330393d6';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'გასაფერადებელი და ხატვის აქტივობები, რომლებიც თქვენი ბავშვის წვრილი მოტორიკის განვითარებას უწყობს ხელს, მნიშვნელოვნად აუმჯობესებს ხელისა და თვალის კოორდინაციას. ამიტომ უმჯობესია, თვალი დახუჭოთ მცირეოდენ არეულობაზე და ბავშვს მოუწყოთ კუთხე, სადაც თავისუფლად შეძლებს ხატვას. გაფერადებისას ბავშვი საკუთარ ნამუშევრებს ქმნის, რაც მის თავდაჯერებასაც ზრდის. კვლევები აჩვენებს, რომ ხატვა და გაფერადება ბავშვის ყურადღების კონცენტრაციის უნარს ავითარებს. რადგან ეს აქტივობები მის წარმოსახვას ასახავს, ისინი შემოქმედებითი აზროვნების განვითარებაშიც მნიშვნელოვნად ეხმარება. გარდა ამისა, გაფერადების დასრულების შემდეგ ბავშვისთვის მის მიერ შექმნილ ნახატთან დაკავშირებით მარტივი კითხვების დასმა გააძლიერებს მის უნარს, აზრი მიანიჭოს ნანახსა და შექმნილს. ჰკითხეთ, რას ჰგავს ნახატი ან რატომ გამოიყენა ესა თუ ის ფერი — ეს ბავშვის თვითგამოხატვის უნარის განვითარებას შეუწყობს ხელს.') WHERE id = 'd90627d2-0af7-4088-8ea2-59eaa2ccc0b5';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, '3 წლის ასაკს თავისი უდავო სილამაზე აქვს! ოჰ, ეს რთული პერიოდები რომ არა… :) 2 წლის ასაკში დაწყებული დამოუკიდებლობისკენ სწრაფვა ამ პერიოდშიც გაგრძელდება. შესაძლოა, შეხვდეთ ისეთ ქცევებს, როგორებიცაა ყველაფრის დამოუკიდებლად გაკეთების სურვილი, ჩარევის მიუღებლობა და სიჯიუტე. ამ პერიოდში ბავშვმა, რომელსაც ზოგჯერ საკუთარი ემოციებისა და აზრების სრულად გამოხატვა ჯერ კიდევ უჭირს, შეიძლება იტიროს და ბრაზის შეტევებიც კი ჰქონდეს. იმის გაცნობიერება, რომ ამ ქცევით ის საკუთარი საჭიროებების გამოხატვას და თქვენგან გაგებას ცდილობს, მასთან სწორად ურთიერთობაში დაგეხმარებათ. ბრაზისა და ტირილის შეტევები ნაკლებად რომ განმეორდეს, ბავშვზე გაბრაზების ნაცვლად, სხვადასხვა ემოციური აქტივობის დახმარებით შეგიძლიათ ასწავლოთ გრძნობების გაგება და ერთმანეთისგან გარჩევა. მას შემდეგ, რაც ბავშვი საკუთარი გრძნობების ამოცნობას შეძლებს, შეგიძლიათ ერთად შეასრულოთ სავარჯიშოები, რომლებიც ამ ემოციების სიტყვიერად გამოხატვაში დაეხმარება.') WHERE id = 'fb8117d2-23da-46f7-96e8-b23a38bf77ec';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვის კვებითი არჩევანი შეიძლება დღიდან დღემდე იცვლებოდეს: შესაძლოა, ერთ დღეს რომელიმე კერძი სიამოვნებით მიირთვას, მეორე დღეს კი უარი თქვას მასზე. მთავარია, სუფრაზე მრავალფეროვანი და ჯანსაღი კერძები შესთავაზოთ, ხოლო თავად გადაწყვიტოს, რომელს და რამდენს შეჭამს. მისთვის ნაცნობი და საყვარელი კერძების გვერდით ზოგჯერ ახალი საკვების პატარა ნაჭერიც შეგიძლიათ შესთავაზოთ გასასინჯად, თუმცა ნუ დააძალებთ. ნუ მოელით, რომ ახლად გასინჯული საკვების სრულ პორციას მაშინვე შეჭამს. საკვები, რომელსაც პირველად სინჯავს, შეგიძლიათ ძირითად კერძებთან ერთად მიართვათ. ბავშვის ჯანმრთელობისთვის მნიშვნელოვანია, რომ ძირითადი კერძები ცილის, მარცვლეულისა და ბოსტნეულის ჯგუფების საკვებს შეიცავდეს. ფერადი და სახალისო გაფორმება, რომელიც მის ინტერესს მიიპყრობს, და დამოუკიდებლად ჭამის უფლება ბავშვს მადას კიდევ უფრო გაუღვიძებს.') WHERE id = '762fb583-ab88-4246-85a9-964005a3eff6';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ თქვენ და თქვენს ბავშვს ჯერ კიდევ ცალ-ცალკე ოთახებში არ გძინავთ, შესაძლოა, რთული პერიოდი გელოდეთ. ცალკე საწოლში დაძინების მიჩვევა თავისთავად რთული პროცესია. ყოველი წარუმატებელი მცდელობა მომდევნო ნაბიჯს ოდნავ ართულებს. ამიტომ საწოლის განცალკევება შესაფერის დროს უნდა დაიწყოთ და ამისთვის სათანადო ენერგიაც გამოყოთ. მართალია, ბავშვების გონება ჯერ ისე არ მუშაობს, როგორც ჩვენი, და მათ ბევრი რამის, განსაკუთრებით აბსტრაქტული ცნებების, აღქმა ჯერ არ შეუძლიათ, თუმცა სიახლეების წინ ახსნა მათაც სჭირდებათ. ბავშვის მოსამზადებლად მისი ოთახი და საწოლი უნდა მოაწყოთ და იზრუნოთ, რომ ისინი შეუყვარდეს. ყველა სათამაშო და ტანსაცმელი ოთახში სათანადო პირობებში და ბავშვისთვის ხელმისაწვდომად უნდა განათავსოთ. ოთახის დეკორისთვის ძილის ხელშემშლელი წითელი, ყვითელი და ყავისფერი ტონების ნაცვლად უპირატესობა მიანიჭეთ დამამშვიდებელი ფერების, მაგალითად, ლურჯისა და მწვანის ღია ტონებს. ყოველი დაძინების წინ არ დაგავიწყდეთ უთხრათ, რამდენად გიყვართ და რომ ყოველთვის მის გვერდით იქნებით, როცა დასჭირდება.') WHERE id = '843a47c0-4aff-4ff5-85ba-6031f15fc752';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თავის მოვლის სფერო ბავშვის პირად ჰიგიენასა და მოვლას მოიცავს. მასში შედის დამოუკიდებლად ჭამა, ჰიგიენის დაცვა, ტანსაცმლის ჩაცმა — ერთი სიტყვით, საკუთარი თავის დამოუკიდებლად მოვლა. ამ ასაკში ბავშვისგან მოსალოდნელია, რომ დახმარების გარეშე ჩაიცვამს თასმებისა და ღილების არმქონე ტანსაცმელს, გაარჩევს ტანსაცმლის წინა და უკანა მხარეებს და საჭიროებისას დამოუკიდებლად მივა ტუალეტში. თავის მოვლის უნარების განვითარების ხელშესაწყობად ბავშვი ყველაფერში უნდა წაახალისოთ, რისი გაკეთებაც თავად შეუძლია. ამაში დღის განმავლობაში ერთად შესრულებული მარტივი აქტივობებიც დაგეხმარებათ. მაგალითად, დილით გაღვიძებისას უთხარით, რომ ერთად წახვალთ სააბაზანოში ხელ-პირის დასაბანად. ჯერ თავად დაიბანეთ ხელ-პირი, შემდეგ აიღეთ პირსახოცი და აჩვენეთ, როგორ იმშრალებთ. უთხარით: „ნახე, ახლა ხელები და სახე დავიბანე და პირსახოცით ვიმშრალებ“, შემდეგ კი დაამატეთ: „ახლა შენი ჯერია“ და სთხოვეთ, იგივე გაიმეოროს.') WHERE id = 'f0bf3df0-c2a3-4852-8e59-7d26c9ec2d21';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი უკვე იმ ასაკშია, როდესაც სათამაშოებით უფრო დიდხანს თამაშობს და დამოუკიდებლად თამაშის მოფიქრება სიამოვნებს. ამიტომ სასარგებლოა, შეურჩიოთ ასაკის შესაბამისი სათამაშოები, რომლებიც მის ინტელექტუალურ განვითარებას შეუწყობს ხელს. რადგან ბავშვმა ფერების ერთმანეთისგან გარჩევა უკვე სრულად დაიწყო, შეგიძლიათ ფერებთან დაკავშირებული სათამაშოები შეარჩიოთ. ეს მას გაართობს და მიღწეული წარმატებითაც გააბედნიერებს. ხის კუბები, ყუთები, სათამაშო მატარებლები, თოჯინები, სხვადასხვა სამგანზომილებიანი გეომეტრიული ფიგურები და მსგავსი ნივთები კარგი არჩევანია. პატარა ნაწილებისგან მთლიანის აწყობა ამ პერიოდის ერთ-ერთი ყველაზე საინტერესო თამაშია. ამიტომ შეგიძლიათ ბავშვს ფაზლები, კონსტრუქტორები და ლეგოს ნაკრებები უყიდოთ. აუცილებელი არ არის, მან მხოლოდ ძვირადღირებული სათამაშოებით ითამაშოს. ბავშვისთვის თამაშების მოფიქრება სახლში არსებული სხვადასხვა ნივთითაც შეგიძლიათ. ამ პერიოდში მას განსაკუთრებით მოეწონება საკუთარი ფანტაზიით შექმნილი პერსონაჟებისა და ნივთების გამოყენებით სიმბოლური თამაშების თამაში.') WHERE id = 'eeac9ed5-495a-4af1-9154-9727dc9ff6ba';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენს ბავშვს უკვე შეუძლია კოვზისა და ჩანგლის დამოუკიდებლად გამოყენება, ამიტომ საკვების ჭამასაც თავისუფლად ახერხებს. სწორი კვების ჩვევის ჩამოსაყალიბებლად მნიშვნელოვანია, რომ ის თქვენთან ერთად დაჯდეს სუფრასთან და ჭამოს. საკვების რაოდენობა, რომელიც თქვენ მცირე გეჩვენებათ, სინამდვილეში მისი ასაკისთვის სავსებით ნორმალური და საკმარისია. თუ ფიქრობთ, რომ ბავშვი ვერ ნაყრდება და გამუდმებით ცდილობთ მისთვის საკვების მიცემას, ამან მომავალში შესაძლოა ჯანმრთელობის სერიოზული პრობლემები გამოიწვიოს. 3 წლის ბავშვის დღიური ენერგეტიკული მოთხოვნილება საშუალოდ დაახლოებით 1200 კალორიაა. ეს მაჩვენებელი ყველა ბავშვისთვის განსხვავებულია, ამიტომ შეგიძლიათ სპეციალისტთან კონსულტაციით თქვენი ბავშვის ინდივიდუალური კალორიული ნორმა განსაზღვროთ. დღიური კვების რეჟიმი უნდა მოიცავდეს 3 ძირითად კვებასა და 2-3 წახემსებას. მნიშვნელოვანია, აკონტროლოთ, რომ ბავშვი რეგულარულად და დაბალანსებულად იკვებებოდეს. დარწმუნდით, რომ არც ძირითად კვებას და არც წახემსებას არ ტოვებს.') WHERE id = '8f0a3b9b-c1b6-48d1-8194-b380ad4ebe6e';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ თქვენს ბავშვს დაძინება არ სურს, ამის ერთ-ერთი შესაძლო მიზეზი შეიძლება ის იყოს, რომ მას არ უნდა, დედა და მამა მარტო დატოვოს. 3-6 წლის ბავშვები ოიდიპოსის განვითარების ეტაპზე იმყოფებიან, ამიტომ მათ არც ძილის საათების მიღმა სიამოვნებთ მშობლების განმარტოებით დანახვა. მათი წარმოდგენით, საპირისპირო სქესის მშობელმა მთელი სიყვარული მხოლოდ მათ უნდა დაუთმოს; ამიტომ შეიძლება მშობლების ურთიერთობაზე იეჭვიანონ. არ ინერვიულოთ, ეს დროებითი ეტაპია. მიუხედავად ამისა, ამ პერიოდში სწორი არ არის ბავშვის ყველა სურვილს დაჰყვეთ და მასთან ერთად დაიძინოთ. ზოგჯერ მიზეზი შეიძლება განსხვავებული იყოს. ზოგიერთი ბავშვი გრძნობს, რომ მშობლებისგან საკმარის ყურადღებას ვერ იღებს და ძილის დროს მათთან ურთიერთობისთვის იყენებს. თუმცა ძილის დრო ბავშვის ამ მოთხოვნილების დასაკმაყოფილებლად გაცილებით ნაკლებად ეფექტურია, ვიდრე მშობლებთან აქტიურად გატარებული დრო. ამიტომ ეცადეთ, ბავშვს თქვენთან ემოციური კავშირის განმტკიცებაში დაეხმაროთ და ძილის მიღმა დარჩენილი დრო შეძლებისდაგვარად ნაყოფიერად გამოიყენოთ.') WHERE id = '09a880ca-a8b7-4625-9ae1-bbc95ae9f537';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'როდესაც თქვენი ბავშვი ყოველდღიურად ახალ გამოცდილებას იძენს, ძალიან მნიშვნელოვანია, ყოველი წარმატებული მცდელობის შემდეგ შეაქოთ. ეს შექება შეგიძლიათ კედელზე ჩამოსაკიდი ცხრილის დახმარებით ხელშესახებ ჯილდოდაც აქციოთ. შექმენით 7 დღის ცხრილი და, მაგალითად, ყოველი ღამის შემდეგ, როცა ბავშვი მოწესრიგებულად დაიძინებს, შესაბამის უჯრაში ერთად ჩააკარით მისთვის საყვარელი პერსონაჟის სტიკერი. თუ კვირის ბოლოს სტიკერების რაოდენობა თქვენ მიერ განსაზღვრულ ზღვარს გადააჭარბებს, შეგიძლიათ მცირე საჩუქარი უყიდოთ ან ერთად დაკავდეთ მისთვის საყვარელი საქმიანობით. ასევე მნიშვნელოვანია, სტუმრების თანდასწრებითაც შეაქოთ ბავშვის მონდომება. თუ თქვენი ბავშვი საბავშვო ბაღში ან სკოლაში დადის, ამ სისტემაში მისი მასწავლებელიც შეგიძლიათ ჩართოთ. ყოველი კარგად გატარებული ღამის შემდეგ აცნობეთ მასწავლებელს და სთხოვეთ, ბავშვი სასწავლო დაწესებულებაშიც შეაქოს — ეს ბავშვისთვის თავდაჯერებულობის მნიშვნელოვანი წყარო გახდება.') WHERE id = 'c2cf3063-80b7-4cce-b4a4-43230a67a805';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'მას შემდეგ, რაც თქვენმა ბავშვმა ფეხზე დგომა ისწავლა, მისი განვითარება სწრაფად გრძელდება. წონასწორობის შენარჩუნების დაუფლების შემდეგ მას სიამოვნებს სხვადასხვა სიმაღლიდან ჩამოხტომა, სირბილისას უეცრად გაჩერება და მიმართულების შეცვლა, ბურთით თამაში და ცოცვა. პარკში, ეზოში ან ტანვარჯიშის გაკვეთილებზე ყოველდღიურად ასეთი აქტივობებით დაკავება ბავშვის სხეულს აძლიერებს. მზიან ამინდში ჩატარებული აქტივობები მისი კუნთებისა და ძვლების გამაგრებასაც უწყობს ხელს. სახლშიც შეგიძლიათ მოუწყოთ დაბრკოლებებიანი გზა, სადაც ის მხიარულად გაატარებს დროს. დამალობანას თამაში, ცეკვა და კოტრიალი იმ სახალისო აქტივობებს შორისაა, რომელთა შესრულებაც სახლში ერთად შეგიძლიათ. ეს მარტივი მოძრაობები თქვენს ბავშვს გაართობს და მის ფიზიკურ განვითარებაზეც დადებითად იმოქმედებს.') WHERE id = 'ebe52971-5876-4787-8235-17c23e1fdb6f';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი უკვე იმ ასაკშია, როდესაც თანატოლებთან თამაშს იწყებს. სხვა ბავშვებთან ურთიერთობისას ის გაეცნობა ისეთ ცნებებს, როგორიცაა მოცდა, სურვილის გადადება, რიგის დაცვა და კონფლიქტების მოგვარება. ამ პერიოდში იწყებს განვითარებას ისეთი სოციალური უნარებიც, როგორიცაა თანამშრომლობა. სრულიად ნორმალურია, თუ ახალ გარემოში მოხვედრისას ან სახელის კითხვაზე ბავშვი თქვენ უკან დაიმალება და მოერიდება. მას დრო უნდა მისცეთ, რომ გარემოს შეეჩვიოს და თავი უსაფრთხოდ იგრძნოს. შესაძლოა, თქვენს ბავშვს უფრო მეტად იმავე სქესის თანატოლებთან თამაში ურჩევნოდეს. ძალიან მნიშვნელოვანია, არ ჩაერიოთ მის ურთიერთობებში თანატოლებთან და პატივი სცეთ მის არჩევანსა და თამაშებს.') WHERE id = '8455bcdc-fada-4c0f-a7dd-2a2412059239';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ვიცით, რამხელა ძალისხმევას დებთ თქვენი შვილის დასაცავად მისი დაბადების წამიდან და იმ მომენტიდანაც კი, როცა შეიტყვეთ, რომ ორსულად ხართ. გარკვეულ ასაკამდე ეს ძალისხმევა მისი ჯანმრთელობისთვის მეტად საჭირო და მნიშვნელოვანია. თუმცა, ამ ეტაპზე, სხვადასხვა უნარის განვითარებასთან ერთად, თქვენს შვილს უჩნდება სურვილი, გახდეს თქვენგან დამოუკიდებელი, თავად გააკეთოს თავისი საქმეები და თავისუფლად შეიცნოს სამყარო. ამის საშუალება უნდა მისცეთ და პატივი სცეთ მის დამოუკიდებლობასა და თავისუფლებას. მნიშვნელოვანია, საჭირო დროს, მისი ასაკისა და განვითარების შესაბამისი პასუხისმგებლობების დაკისრებით, ხელი შეუწყოთ მის დამოუკიდებლობასა და პასუხისმგებლობის გრძნობის ჩამოყალიბებას. ბავშვი, რომელსაც თავისუფლად მოქმედებისა და სამყაროს შეცნობის შესაძლებლობა ეძლევა, მომავალში თვითკმარი და თავდაჯერებული ადამიანი გახდება. ამიტომ, თუ რეალური აუცილებლობა არ არსებობს, ნუ შეაფერხებთ მას ისეთი ფრაზებით, როგორებიცაა: „ვაიმე, რამე არ დაგემართოს!“ ან „ვაიმე, რამე არ იტკინო!“') WHERE id = '26d3c54b-09eb-43e7-b3e6-8e1d6b9efa0a';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ ეტაპზე თამაშები ხელს უწყობს თქვენი ბავშვის განვითარებას და ამავდროულად ეხმარება, დრო მხიარულად გაატაროს. ამ ასაკში ბავშვი გაგაოცებთ უსაზღვრო ფანტაზიით, რომლის წყალობითაც ყველაფერს თამაშად აქცევს. ამიტომ სპეციალისტები ძვირადღირებული სათამაშოების ნაცვლად უპირატესობას ანიჭებენ თამაშებს, რომლებიც ბავშვის შემოქმედებით უნარებს ავითარებს. ძვირადღირებულმა სათამაშოებმა, რომლებიც შემოქმედებით განვითარებას არ უწყობს ხელს, შესაძლოა ბავშვის წარმოსახვა შეზღუდოს და დააქვეითოს. შეგიძლიათ ბავშვს შესთავაზოთ უფრო შემეცნებითი თამაშები, მაგალითად, მუყაოს ყუთისგან სახლის, თვითმფრინავის, მანქანის, გემის ან კოსმოსური ხომალდის გაკეთება. ორ სკამს შორის გადაფარებული უბრალო ზეწარიც კი ბავშვისთვის შეიძლება ნავსადგურად, კარვად, სახლად ან ნებისმიერ სხვა წარმოსახვით ადგილად იქცეს. როლური და „ვითომ“ თამაშებიც მნიშვნელოვნად უწყობს ხელს ბავშვის განვითარებას. ამიტომ შეძლებისდაგვარად უნდა შეუქმნათ ბავშვს თანატოლებთან ურთიერთობისა და მათთან ერთად თამაშის შესაძლებლობა.') WHERE id = 'a2a78f60-b8a2-4f4c-8094-c1ec1d443ca9';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'მიუხედავად იმისა, რომ ტუალეტის მოთხოვნილების კონტროლზე პასუხისმგებელი კუნთების განვითარება 18 თვის ასაკში სრულდება, სრულად კონტროლი შესაძლოა სამი წლის ასაკამდე ვერ მოხერხდეს. ამ პერიოდში, მიუხედავად იმისა, რომ თქვენი ბავშვი დღისით ტუალეტის მოთხოვნილებას აკონტროლებს, ღამით მას შესაძლოა ჯერ კიდევ სჭირდებოდეს დახმარება. გამოიჩინეთ მოთმინება, ნუ იჩქარებთ და მოერიდეთ გადაჭარბებულ რეაქციას. თუ ბავშვი ჩაისველებს, ნუ გაუბრაზდებით და ნუ გააკრიტიკებთ; აუხსენით, რომ ასეთი შემთხვევები დროდადრო შეიძლება მოხდეს. ასეთ დროს შეგიძლიათ მცირე პასუხისმგებლობებიც დააკისროთ, მაგალითად, სთხოვოთ, გაიხადოს შარვალი და ჭუჭყიანი ტანსაცმლის კალათაში ჩადოს. მიაჩვიეთ ტუალეტში შესვლა არა მხოლოდ ბუნებრივი მოთხოვნილების დასაკმაყოფილებლად, არამედ ხელების დაბანისა და კბილების გახეხვის ჩვევების გამოსამუშავებლადაც. იმის ნაცვლად, რომ ხშირად ჰკითხოთ: „ტუალეტი ხომ არ გინდა?“, აკონტროლეთ მიღებული სითხის რაოდენობა და უთხარით: „ახლა ტუალეტში წასვლის დროა“.') WHERE id = '127bfb16-6c2c-4ee2-8f0f-55e5671db200';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი, რომელიც უკვე თავად იგონებს თამაშებს და მეგობრებს იძენს, თანატოლებთან დროის გატარებით დიდ სიამოვნებას იღებს. თუმცა ზოგჯერ შესაძლოა მათ შორის გაუგებრობებსაც შეესწროთ. ბავშვმა შეიძლება მეგობრებთან თავი ყოვლისმცოდნედ წარმოაჩინოს, უფროსობა მოინდომოს, ხოლო თუ მის სურვილებს არ შეასრულებენ, გაჭირვეულდეს და პრობლემები შექმნას. თანატოლებთან კონფლიქტების მოგვარებისას მიეცით საკუთარი აზრის გამოთქმის საშუალება, ესაუბრეთ გადაჭრის გზებზე და სთხოვეთ, პრობლემა თავად მოაგვაროს. ხელი შეუწყვეთ, რომ დამოუკიდებელ პიროვნებად ჩამოყალიბდეს. მეგობრებთან მის ურთიერთობაში მუდმივმა ჩარევამ შესაძლოა უარყოფითად იმოქმედოს ბავშვის კომუნიკაციური უნარების განვითარებაზე. ამიტომ თამაშის დროს მიეცით თავისუფლება და, უსაფრთხო გარემოს შექმნისა და იმის უზრუნველყოფის შემდეგ, რომ ბავშვები ერთმანეთს ზიანს არ მიაყენებენ, უმჯობესია, შორიდან დააკვირდეთ. ამ პერიოდში გირჩევთ, ბავშვს შეძლებისდაგვარად ზრდასრულივით მოეპყროთ და დაეხმაროთ, რომ საკუთარი პრობლემები თავად მოაგვაროს.') WHERE id = 'ef337793-35af-4f64-93e3-376a6a149769';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'უნდა უზრუნველყოთ, რომ საკვების ყველა ჯგუფი თქვენი ბავშვის ყოველდღიურ რაციონში დაბალანსებულად იყოს წარმოდგენილი. რეკომენდებულია, მარცვლეულის ჯგუფიდან დღეში 6 პორცია მიიღოს. მარცვლეულის 1 პორცია უდრის 1 ნაჭერ კექსს, 1 ნაჭერ პურს, ნახევარ ჭიქა ფლავს ან მაკარონს. ხილისა და ბოსტნეულის ჯგუფიდან დღეში 5 პორცია უნდა მიიღოს; მაგალითად, 1 საშუალო ზომის ატამი, ვაშლი ან ნახევარი ჭიქა ბოსტნეული 1 პორციად ითვლება. ცხიმების ჯგუფიდან დღეში 3-5 პორციაა საჭირო; 1 ჩაის კოვზი კარაქი ან ზეითუნის ზეთი 1 პორციაა. ხორცის ჯგუფიდან დღეში 2 პორცია უნდა მიიღოს; 1-3 სუფრის კოვზი ქათმის ხორცი, წითელი ხორცი ან თევზი 1 პორციას უდრის. ასევე, 1 კვერცხი ან 4-5 სუფრის კოვზი პარკოსნები ხორცის 1 პორციას ანაცვლებს. რძის პროდუქტებიდან კი დღეში 3 პორციაა რეკომენდებული; ასანთის კოლოფის ზომის ყველი, 3/4 ჭიქა რძე ან იოგურტი 1 პორციად ითვლება. ამგვარად, დაბალანსებული კვებით შეგიძლიათ დაიცვათ ბავშვის ჯანმრთელობა და გააძლიეროთ მისი იმუნური სისტემა.') WHERE id = '4bf4b02c-af51-47f9-ba7a-47457d6c50de';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი, რომელიც „თამაშის პერიოდად“ ცნობილ ეტაპზე გადავიდა, იმდენად დიდი ენერგიითაა სავსე, რომ სახლში მისი სრულად დახარჯვა შეუძლებელია. ამ ენერგიის დასახარჯად ყველაზე შესაფერისი გარემო საბავშვო ბაღია. ბაღში სიარულის დასაწყებად იდეალურ ასაკად 3-3,5 წელი ითვლება. ბავშვები, რომლებსაც სახლში და-ძმა არ ჰყავთ, ბაღში ახალ მეგობრებს იძენენ, სწავლობენ გაზიარებას და უვითარდებათ პასუხისმგებლობის გრძნობა. შეიძლება ფიქრობდეთ: „ჩემი ბავშვი მორცხვია და ბაღში პრობლემები ექნება“. თუმცა სპეციალისტები აღნიშნავენ, რომ ბავშვები ხშირად სწორედ ბაღში სიარულის დაწყების შემდეგ ძლევენ მორცხვობას და იწყებენ სოციალიზაციას. თუ შეამჩნევთ, რომ თქვენს ბავშვს ახალ გარემოსთან შეგუების სერიოზული სირთულეები აქვს, ნუ აიძულებთ და დაელოდეთ, სანამ მზად იქნება.') WHERE id = 'ae372f82-277f-4b8f-b759-2dccdf242ba6';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენს ბავშვს უკვე შეუძლია 3-4 სიტყვისგან შემდგარი მარტივი წინადადებების შედგენა. მას შეუძლია შეასრულოს ორსაფეხურიანი დავალებები, მაგალითად: „აიღე პულტი და მომიტანე“. ნაცვალსახელები მისთვის შესაძლოა ჯერ კიდევ ცოტა რთული იყოს, ამიტომ ნორმალურია, თუ მისგან მოისმენთ მოკლე, ნაცვალსახელების გარეშე წინადადებებს, როგორიცაა „ჭამე საჭმელი“ ან „მოიტანე წყალი“. ამ თვეებში მას უკვე შეუძლია 10-მდე დათვლა და სწავლობს ისეთი კითხვების დასმას, როგორიცაა „რა?“, „სად?“ და „ვინ?“. ბავშვი, რომლის მეტყველებაც უკვე უკეთ არის განვითარებული, ცდილობს უფრო გამართულად ილაპარაკოს. მისი ლექსიკური მარაგი თანდათან იზრდება. გონებრივი შესაძლებლობების განვითარებასთან ერთად მან შეიძლება გაგეხუმროთ კიდეც და ზოგჯერ თქვენი გაღიზიანებითაც გაერთოს. მიუხედავად ამისა, შესაძლოა ჯერ კიდევ ვერ გაიგოთ ბავშვის ნათქვამის ნახევარიც კი. თუ შეამჩნევთ, რომ ამ მხრივ ის თანატოლებს მნიშვნელოვნად ჩამორჩება, შეგიძლიათ სპეციალისტს მიმართოთ.') WHERE id = '953823ad-cdcb-41ad-830e-fd7b2c088e70';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ პერიოდში მუსიკალური განათლება ბავშვებისთვის გარკვეული ცნებებისა და ღირებულებების შესასწავლად ძალიან ეფექტური საშუალებაა. მუსიკალური განათლება დადებით როლს ასრულებს ბავშვის ფსიქოლოგიურ განვითარებაში. ის ეხმარება თქვენს ბავშვს, სხვა ბავშვებთან ერთად ბედნიერი ცხოვრებისათვის საჭირო ჩვევები შეიძინოს. მუსიკალური აქტივობები ფსიქომოტორულ განვითარებაზეც მოქმედებს. მაგალითად, მუსიკალურ ინსტრუმენტებზე დაკვრა ხელს უწყობს ბავშვის მსხვილი და წვრილი მოტორული უნარების განვითარებას. თუ ბავშვები ადრეული ასაკიდან ხარისხიან მუსიკას მოუსმენენ, მომავალში, მუსიკოსები რომც არ გახდნენ, ჩამოყალიბდებიან ზრდასრულებად, რომლებსაც კარგი მუსიკის შერჩევა, სიყვარული და მისგან სიამოვნების მიღება შეუძლიათ. არ უნდა დაგვავიწყდეს, რომ ყველა ბავშვს შეიძლება მუსიკისადმი ერთნაირი ნიჭი არ ჰქონდეს, თუმცა მუსიკა ყველა ბავშვს უყვარს.') WHERE id = 'fedbb0d2-4a4b-4ba8-9970-6d8a02f5d453';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'როდესაც თქვენს ბავშვს აირების დაგროვებით გამოწვეული ტკივილი აწუხებს, უნდა გაიხსენოთ, რა ჭამა მან ბოლო რამდენიმე საათის განმავლობაში. დიდი ალბათობით, აირების დაგროვების მიზეზი მიღებული საკვებია. ზოგი ბავშვი ბოჭკოვანი და ცხიმიანი საკვების მიმართ სხვებზე უფრო მგრძნობიარეა. ასევე უნდა გახსოვდეთ, რომ მისი საჭმლის მომნელებელი სისტემა, ზრდასრულებისგან განსხვავებით, ჯერ კიდევ არ არის სრულად განვითარებული. ამიტომ საკვებმა, რომელიც თქვენთვის ადვილად მოსანელებელია, შესაძლოა ბავშვის საჭმლის მომნელებელი სისტემა მნიშვნელოვნად დატვირთოს. ასეთ შემთხვევებში სასარგებლოა ბავშვის მიერ მიღებული საკვების აღრიცხვა, საეჭვო პროდუქტების შეზღუდვა და აირების დაგროვებაზე დაკვირვება. დღეში ერთ ჭიქაზე მეტი ხილის წვენის დალევამაც შეიძლება აირების დაგროვება გამოიწვიოს. სხვა ბავშვების მსგავსად, თქვენს პატარასაც შეიძლება გაუჭირდეს ხილის წვენში ჭარბი რაოდენობით არსებული ფრუქტოზისა და საქაროზის მონელება. გარდა ამისა, დიდი რაოდენობით შაქრიანი სასმელების მიღება მისი კბილებისთვისაც საზიანოა.') WHERE id = 'e0542a27-8733-472b-8360-25ce6853ad56';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვის წიგნთან პირველი გაცნობა 0-6 წლის ასაკში ხდება. ბავშვს წიგნებისადმი ინტერესი რომ გაუჩნდეს და მათი აღმოჩენა შეძლოს, ამაში ხელშეწყობა თქვენი, როგორც მშობლის, მოვალეობაა. მისთვის წიგნის შეძენისას ასაკობრივი და განვითარების თავისებურებები უნდა გაითვალისწინოთ. ამ პერიოდში სასურველია შესთავაზოთ წიგნები, რომლებშიც მის გარშემო არსებული მოვლენები, ცოცხალი არსებები და საგნებია გამოსახული. ბავშვი დაათვალიერებს იმ წიგნების ილუსტრაციებს, რომლებსაც უკითხავთ, მიბაძავს ცოცხალი არსებებისა და საგნების ხმებს და შესაძლოა ნახატებთან დაკავშირებული კითხვებიც დაგისვათ. მას შეიძლება სურდეს, რომ ტექსტსა და ილუსტრაციებს შორის კავშირი აუხსნათ. ამ პერიოდში ბავშვის გარემო ფართოვდება, ინტერესები ვითარდება და ენობრივი უნარები უმჯობესდება. შეგიძლიათ შეარჩიოთ წიგნები, რომლებიც ხელს უწყობს მის შემოქმედებითობას, ყურადღებას ამახვილებს მოვლენების მიზეზებზე და ყოველდღიურ ცხოვრებასთან დაკავშირებულ ამბებს მოგვითხრობს. იმისთვის, რომ კითხვა ჩვევად იქცეს, როგორც მშობლების, ისე მასწავლებლების განსაკუთრებული ძალისხმევაა საჭირო. ყველაზე მნიშვნელოვანია, რჩევაზე „წიგნი წაიკითხე“ მეტად თავად მისცეთ ბავშვს მაგალითი.') WHERE id = '7afbe40c-9017-45b7-9741-68b1e5e44bb0';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი 2-3 წლიდან, ტუალეტის ჩვევების ათვისების პარალელურად, საკუთარი გენდერული იდენტობის გაცნობიერებას იწყებს. საპირისპირო სქესის და-ძმის ყოლა ან საბავშვო ბაღში საპირისპირო სქესის ბავშვებთან ურთიერთობა ამ პროცესს აჩქარებს. ბავშვებმა, რომლებიც საბავშვო ბაღში არ დადიან, და-ძმა არ ჰყავთ და შეზღუდული სოციალური გარემო აქვთ, შესაძლოა ეს განსხვავება უფრო გვიან გააცნობიერონ. თუმცა მნიშვნელოვანია, ბავშვმა არაუგვიანეს 5 წლის ასაკისა გააცნობიეროს საკუთარი სქესი და იცოდეს განსხვავებები სხვა გენდერულ იდენტობასთან მიმართებით. სასურველია, ეს საკითხები ოჯახში განიხილოთ, ბავშვს მათ გაგებაში დაეხმაროთ და მან შეძლოს საკუთარი თავის გოგოდ ან ბიჭად მოხსენიება. ამ პერიოდში ბავშვმა შეიძლება სექსუალობასთან დაკავშირებული კითხვების დასმა დაიწყოს და პასუხებს მისთვის ყველაზე ახლობელი და სანდო ადამიანებისგან — მშობლებისგან — ელოდება. მნიშვნელოვანია, რომ კითხვებით მოგმართოთ და ინტერესის გამოხატვა განაგრძოს. მიზანი უნდა იყოს, ბავშვმა კითხვები თავისუფლად დასვას და პასუხები ყოველგვარი ყოყმანის გარეშე მიიღოს იმ ადამიანებისგან, ვისაც ყველაზე მეტად ენდობა. თუ ასეთ დროს პასუხს გადადებთ ან ბავშვის მიმართ განმკითხავ დამოკიდებულებას გამოიჩენთ, გარკვეული დროის შემდეგ ის კითხვების დასმას შეწყვეტს და პასუხების ძებნას სხვაგან დაიწყებს. მისი ინტერესის დასაკმაყოფილებლად შეძლებისდაგვარად მკაფიო, მოკლე და კონკრეტული პასუხები უნდა გასცეთ.') WHERE id = 'df5565ed-acef-4630-91e5-3e94babb0601';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ ასაკში ზოგიერთმა ბავშვმა შეიძლება დღის ძილზე უარი თქვას. ასეთ შემთხვევაში შეგიძლიათ საღამოს დაძინების დრო უფრო ადრე გადმოწიოთ. გახსოვდეთ, რამდენად მნიშვნელოვანია ძილის რეჟიმი და ბავშვის ძილის მოთხოვნილების დაკმაყოფილება. თუ დაძინებას ეწინააღმდეგება, გაბრაზების გარეშე აუხსენით, რომ დაძინება და საწოლში წასვლა აუცილებელია. თუ კვლავ თავისას იჟინებს, შეგიძლიათ შესთავაზოთ, საკუთარ ოთახში გაატაროს დრო ან წიგნი დაათვალიეროს. ამასთანავე, შეგიძლიათ გამოიყენოთ ძილისთვის განკუთვნილი, მისთვის უკვე ნაცნობი სათამაშო. ოთახში სუსტი განათების მქონე ღამის სანათის დატოვებაც შეიძლება სასარგებლო იყოს. ყოველი დაძინების წინ დაარწმუნეთ, რომ თუ დაგიძახებთ, მაშინვე მის გვერდით იქნებით და არ დაგავიწყდეთ მისთვის კიდევ რამდენიმე კოცნის ჩუქება. 🙂') WHERE id = '4b759359-897f-442e-898f-e91b4d1f488e';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'არ უნდა დაგავიწყდეთ, რომ თქვენი ბავშვი უკვე დამოუკიდებელი პიროვნებაა. ბუნებრივია, მას საკუთარი მოწონებები და არ მოწონებები აქვს. ეს ნიშნავს, რომ ახლა უკვე რთული იქნება მისი მხოლოდ თქვენი შეხედულებების მიხედვით წარმართვა, როგორც ამას ადრე აკეთებდით. შესაძლოა, ხშირად შეხვდეთ მის წინააღმდეგობას. გარკვეულ სიტუაციებში გაბრაზება, ტირილი ან სიჯიუტე ნორმალურია. იმის ნაცვლად, რომ მას ისე უპასუხოთ, როგორც ზრდასრულ ადამიანს, ეცადეთ, დაელაპარაკოთ. უმეტეს შემთხვევაში ეს პრობლემის მოგვარებაში დაგეხმარებათ. როგორც თქვენ მოექცევით, ისიც იმავე დამოკიდებულებით გიპასუხებთ. მისი კომუნიკაციის უნარების განვითარებაში უდიდესი როლი თქვენ გეკისრებათ. პატივი უნდა სცეთ მის პირად სივრცეს და ისე მისცეთ მიმართულება, რომ მის აზრებში უხეშად არ ჩაერიოთ. ამგვარად, ბავშვს არ მოერიდება იმ მშობელთან ურთიერთობა, რომელიც უსმენს და პატივს სცემს. დროთა განმავლობაში კი ის ისწავლის საკუთარი თავის ტირილის გარეშე გამოხატვას და სიჯიუტესაც ნაკლებად გამოიჩენს.') WHERE id = '121d280d-108f-470d-8ec1-2acd91b6403d';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვის მეტყველება უკვე საგრძნობლად არის განვითარებული და მას შეუძლია არსებითი სახელების, ზმნების, ნაცვალსახელების, ზედსართავი სახელებისა და მრავლობითი რიცხვის ფორმების თავისუფლად გამოყენება. როცა მის გვერდით საუბრობთ, შესაძლოა ისიც ჩაერთოს განხილვაში. მას უკვე შეუძლია საკუთარი გრძნობების გამოხატვა არა მხოლოდ ფიზიკური მოქმედებებით, არამედ სიტყვებითაც. ამასთანავე, რადგან იუმორის გრძნობა უვითარდება, შესაძლოა სასაცილო სიტუაციებზე რეაგირება მოახდინოს. მას შეუძლია ზედიზედ ორი ან სამი დავალების შესრულება და ესმის, რისთვის გამოიყენება სხვადასხვა საგანი. მისი ნათქვამი უკვე უფრო გასაგებია. შეუძლია თავისთვის ენის გასატეხებისა და სიმღერების თქმა, ასევე მსგავსი და საპირისპირო ცნებების ერთმანეთისგან გარჩევა.') WHERE id = '38765ac8-4717-455f-8180-86f822819f07';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, '3 წლის ბავშვისთვის ძილის იდეალური ხანგრძლივობა 10-13 საათია. 14 საათზე მეტხანს ძილმა შესაძლოა მისი ემოციური და ფიზიკური განვითარება შეაფერხოს. ამ პერიოდში შეიძლება იფიქროთ, რომ ბავშვმა დღის ძილს თავი დაანებოს. თუმცა მშობლებს, რომლებსაც სურთ, მათი ბავშვი უფრო მშვიდი და გაწონასწორებული გაიზარდოს, ურჩევენ, დღის ძილი არ შეწყვიტონ. ბავშვებს, რომლებსაც დღის განმავლობაში საკმარისად სძინავთ, უფრო სწრაფი გონებრივი განვითარება აქვთ, ვიდრე მათ, ვინც დღისით არ იძინებს. კვლევები აჩვენებს, რომ ბავშვები, რომლებსაც დღისით სძინავთ, უფრო აქტიურები არიან აზროვნების, დამახსოვრებისა და პრობლემების გადაჭრის კუთხით. სანამ ძილის ოპტიმალურ რეჟიმს შეინარჩუნებთ, დღის ძილი მისთვის ყოველთვის სასარგებლო იქნება.') WHERE id = '494c995c-0f5f-468c-ac19-77cfd1a4b7f4';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ ბავშვისთვის ტუალეტის ჩვევების გამომუშავების პროცესში წარმატებას ვერ აღწევთ, შესაძლოა, გარკვეულ ნიუანსებზე ყურადღების გამახვილება დაგჭირდეთ. ასეთ შემთხვევებში სპეციალისტები არკვევენ, როდის შეძლო ბავშვმა ღამით შარდის შეკავების კონტროლი და ყოფილა თუ არა ოჯახში ღამის შარდის შეუკავებლობის პრობლემა. გარდა ამისა, წარუმატებლობის ერთ-ერთი მთავარი მიზეზი სწავლების პროცესში გამოვლენილი არასწორი მიდგომებია. მაგალითად, თუ ბავშვს უნებლიე შემთხვევის გამო გაუბრაზდებით, დაადანაშაულებთ ან სახის გამომეტყველებით აგრძნობინებთ, რომ იმედგაცრუებული ხართ, ამან შეიძლება სწავლების პროცესი შეაფერხოს. ასეთმა არასწორმა დამოკიდებულებამ შესაძლოა ბავშვი მორცხვ, უინიციატივო და საკუთარ თავში დაურწმუნებელ პიროვნებად ჩამოაყალიბოს. ამასთანავე, ბავშვმა შეიძლება ასეთი ქცევა საკუთარი სხეულის ხელყოფად აღიქვას, ადამიანების მიმართ ნდობა დაკარგოს და მუდმივად ეშინოდეს, რომ ზიანს მიაყენებენ. შედეგად, ის შეიძლება შფოთიან და ზედმეტად მოუსვენარ პიროვნებად ჩამოყალიბდეს და ქცევის სხვა პრობლემებიც განუვითარდეს. ამიტომ ძალიან მნიშვნელოვანია, რომ ამ პროცესისთვის, უპირველესად, თავად თქვენ იყოთ მზად.') WHERE id = 'a0e48404-d991-4429-b070-28474430ad64';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენ აცნობიერებთ, რომ ბავშვის განვითარებისა და ქცევის დადებითი მიმართულებით ჩამოყალიბებისთვის გარკვეული წესების დაწესებაა საჭირო. თუმცა, შესაძლოა, კითხვები გქონდეთ იმის შესახებ, თუ როგორ განსაზღვროთ და გამოიყენოთ ეს წესები. სპეციალისტები აღნიშნავენ, რომ არ არსებობს ყველა ოჯახისთვის შესაფერისი, ერთადერთი სწორი და ეფექტური აღზრდის ფორმულა. მშობელსა და შვილს შორის ეფექტური ურთიერთობა ოჯახის სტრუქტურის, თქვენი ღირებულებების, კულტურისა და ბავშვის ხასიათის მიხედვით განსხვავდება. ძალიან მნიშვნელოვანია, კარგად დააკვირდეთ თქვენს ბავშვს, რომელიც უკვე 3 წლის ხდება, და თქვენი ქცევა მის საჭიროებებსა და თავისებურებებს მოარგოთ. კეთილგანწყობილი და მხარდამჭერი მშობლობა ბავშვს საკუთარი უნარების აღმოჩენისა და შესაძლებლობების რეალიზების საშუალებას აძლევს. ამ ეტაპზე ყურადღება უნდა გაამახვილოთ იმაზე, რაც თქვენს ბავშვს შეუძლია, არასოდეს შეადაროთ ის თანატოლებს და არ შეზღუდოთ მრავალი ისეთი წესით, რომელთა შესრულებასაც ვერ შეძლებს.') WHERE id = '3da2acf8-a0e8-4a9b-bfd1-5a6c83e8b5da';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'რადგან თქვენს შვილს წინ ხანგრძლივი სასკოლო მარათონი ელის, ფორმალური განათლების დაწყება არ უნდა იჩქაროთ. ეცადეთ, ადრეული ბავშვობის წლები ბევრი თამაშითა და სიამოვნებით გაატაროს. მიუხედავად ამისა, ამ ასაკში ბევრი ბავშვი ასოებითა და რიცხვებით ინტერესდება. თუ თქვენი ბავშვიც მონდომებულია და ასოებსა და რიცხვებთან დაკავშირებული აქტივობები ართობს, შეგიძლიათ, საწყისი ცოდნა მისცეთ. როდესაც ასოების გარჩევას დაიწყებს, შეგიძლიათ უყიდოთ ანბანის წიგნები, რომლებშიც ასოები შესაბამის საგნებთანაა დაკავშირებული. სათამაშოების თაროებს მიაკარით წარწერები, მაგალითად, "თოჯინები", "წიგნები", "მანქანები", და თითოეულ სიტყვას შესაბამისი სურათიც დაურთეთ. ასე ის სიტყვასა და საგანს შორის კავშირს ადვილად დაინახავს.') WHERE id = '620dd0a6-5b3b-4996-884c-101ad6b8614b';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის ტვინის განვითარება დედის მუცელში იწყება და ზრდასრულობამდე გრძელდება. თუმცა, სპეციალისტების აზრით, ტვინის განვითარება ძირითადად 5 წლამდე სრულდება. ამ პერიოდში ბავშვის ჯანსაღი და დაბალანსებული კვება ძალიან მნიშვნელოვანია როგორც ფიზიკური, ისე გონებრივი განვითარებისთვის. გონებრივი განვითარების ხელშემწყობ საკვებს შორის, რა თქმა უნდა, კვერცხი ერთ-ერთ პირველ ადგილს იკავებს. საუზმის განუყოფელი ნაწილი — კვერცხი — ცილის მაღალი შემცველობის წყალობით ბავშვებში კონცენტრაციის უნარს აუმჯობესებს. ის მდიდარია მეხსიერებისთვის აუცილებელი ვიტამინებით. კვერცხი შეიცავს ტიროზინს, რომელიც ტვინს სიგნალების მისაღებად და გადასაცემად სჭირდება, და ორგანიზმს მხნეობის შესანარჩუნებლად საჭირო ენერგიით ამარაგებს.') WHERE id = '346378cf-c32a-4e3a-aa35-d7f1c6bfb93c';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენს შვილს მოძრაობის უნარები უკვე მნიშვნელოვნად აქვს განვითარებული. ის თავისუფლად დარბის სწორ ხაზზე და ხტომაც უკეთ გამოსდის. ფიზიკური განვითარების მხრივ დიდი პროგრესის წყალობით, თქვენი ბავშვის სათამაშო სივრცე და თამაშების მრავალფეროვნებაც გაიზარდა. ის დამოუკიდებლად იგონებს თამაშებს და იმ მეგობრებისთვისაც კი იწყებს დავალებების მიცემას, რომლებთან ერთადაც თამაშობს. მარტივად ახერხებს კოტრიალს, ხტომასა და კიბეზე ასვლას. გაგორებული ბურთისთვის ფეხის დარტყმა და ნასროლი ბურთის დაჭერა მისთვის ძალიან მარტივია. ეს პერიოდი შესანიშნავი შესაძლებლობაა, სწორად წარმართოთ მისი სპორტისადმი ინტერესი და კარგ შედეგებს მიაღწიოთ.') WHERE id = 'fac45c7d-fc32-4650-9898-0271871259d3';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, '3 წლის ბავშვების ენერგიისა და საკვები ნივთიერებების საჭიროება ისეთი მაღალი აღარ არის, როგორიც ჩვილობის პერიოდში იყო. თუმცა, რადგან ამ ასაკშიც გრძელდება სხეულის განვითარება, სწორი კვება, რა თქმა უნდა, ძალიან მნიშვნელოვანია. რეკომენდებულია, ამ პერიოდში მიღებული დღიური ენერგიის 45-50% ნახშირწყლებზე, 15-20% ცილებზე, ხოლო 35% ცხიმებზე მოდიოდეს. თქვენს შვილს უნდა ესაუბროთ ისეთ პროდუქტებზე, როგორიცაა შოკოლადი, შაქარი, გაზიანი სასმელები და ჩიფსები, და მათი მიღების შეზღუდვაზე დაითანხმოთ. აუხსენით, რომ ამ პროდუქტებმა მის ჯანმრთელობასა და განვითარებაზე შეიძლება უარყოფითად იმოქმედოს. ამასთან, ყურადღება მიაქციეთ იმასაც, თუ როგორ და როდის გაეცნობა ბავშვი ამ პროდუქტებს. რაც უფრო გვიან გასინჯავს პროდუქტებს, რომლებსაც ცხოვრების გარკვეულ ეტაპზე აუცილებლად შეხვდება, მით უკეთესი.') WHERE id = 'e0c4db2c-e5e7-44b0-acd7-3cd699b5d73e';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი შვილი უკვე დამოუკიდებელი გადაწყვეტილებების მიღების უნარის მქონე პიროვნებად ჩამოყალიბდა. ამიტომ მისი მხოლოდ თქვენი შეხედულებების მიხედვით წარმართვა ისე მარტივი აღარ იქნება, როგორც ადრე. სხვადასხვა სიტუაციაში მან შეიძლება დედისა და მამისგან განსხვავებული რამ მოისურვოს. მაგალითად: ‐დედამ წიგნი წამიკითხოს, მამამ კი ჩემთან ითამაშოს‐. მოუსმინეთ მის სურვილებს და გაგებით მოეკიდეთ მათ; მისაღები სურვილები შეუსრულეთ, ხოლო შეუსაბამო თხოვნებზე კეთილად აუხსენით უარის მიზეზი. ამ ასაკში ბავშვი ძალიან ცნობისმოყვარეა და მისმა მუდმივმა კითხვებმა შეიძლება დაგღალოთ, თუმცა მოთმინება გამოიჩინეთ. თუ წესების მიზეზს გააგებინებთ, მათი დაცვა გაუადვილდება. მთავარია, იყოთ თანმიმდევრული და მკაფიო. თავაზიანი და მოკლე შეხსენებები საუკეთესო მიდგომაა.') WHERE id = '5c814408-34ed-41f0-a49f-4e136c48eff6';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ ასაკში თქვენს შვილს უკვე შეუძლია განსაზღვრულ საზღვრებში მარტივი მონახაზების გაკეთება. ხატვასთან დაკავშირებული ახალი აღმოჩენებისას ბავშვს თანდათან მარტივი ფიგურების დახატვის უნარიც უვითარდება. თავის ნახატებში ის უფრო ხშირად იყენებს ვერტიკალურ, ჰორიზონტალურ, დახრილ და მრუდ ხაზებს. ადრე დახატული ფიგურებისგან შეუძლია შექმნას უფრო რთული სქემები ან ორნამენტები. ის იწყებს თავისა და სახის ნაკვთების ხატვას და შეუძლია საშუალოდ სამი ნაწილისგან შემდგარი ადამიანის გამოსახვა. მიუხედავად იმისა, რომ სხეულის დეტალები მის ნახატებში ჯერ ხშირად არ გვხვდება, მას შეუძლია სხეულის გამოსახულებას გამოტოვებული ნაწილები დაუმატოს. დღის განმავლობაში ხაზების გავლებაზე ორიენტირებული სავარჯიშოებით შეგიძლიათ დაეხმაროთ, რომ დრო სასიამოვნოდ გაატაროს და ახალი უნარებიც უფრო მარტივად აითვისოს.') WHERE id = 'c493c5fe-d48d-4e7c-91e0-fe08465a7aee';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვის 3 წლის დაბადების დღისთვის რამდენიმე რეკომენდაცია გვაქვს! თქვენი პატარა უკვე 3 წლის ხდება და ეს, დიდი ალბათობით, მისი პირველი დაბადების დღე იქნება, რომელიც ყველაზე კარგად დაამახსოვრდება. შეგიძლიათ, ეს დღე მისთვის დაუვიწყარი გახადოთ — მოაწყოთ თამაშები მეგობრებსა და თანატოლებთან ერთად, მისცეთ საშუალება ირბინოს და გაერთოს, ასევე დაგეგმოთ სხვადასხვა საინტერესო მასტერკლასი და აქტივობა. თუ ამინდი ხელს გიწყობთ, დაბადების დღის ღია ცის ქვეშ აღნიშვნა როგორც თქვენს პატარას, ისე სტუმრებს ძალიან გაახარებს! არ დაგავიწყდეთ, ამ შესანიშნავ დღეს ბევრი ფოტო გადაიღოთ, რადგან მომავალში ისინი ძვირფას მოგონებად დაგრჩებათ. და რაც მთავარია, გახსოვდეთ, რამდენი ძალისხმევა და შრომა ჩადეთ თქვენი ბავშვის აღზრდაში ამ ასაკამდე... ყველაზე დიდ აპლოდისმენტებს სწორედ თქვენ იმსახურებთ! არასოდეს დაგავიწყდეთ, რომ შესანიშნავი დედა ხართ! <3') WHERE id = '48bcf5cd-dbe3-4417-8aa0-e362136d2694';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ეს ის პერიოდია, როდესაც თქვენი ბავშვი შეიძლება განსაკუთრებით ინიციატივიანი იყოს. თუმცა მისი ინიციატივის გამოვლენის მცდელობების შეზღუდვა ან დასჯა მასზე უარყოფითად მოქმედებს. იმისთვის, რომ ბავშვმა ინიციატივიანობასა და ყოყმანს შორის ჯანსაღი ბალანსი იპოვოს, წახალისება სწორად და თანმიმდევრულად უნდა გამოიყენოთ. ასე ის გააცნობიერებს, რისი გაკეთება შეიძლება და რისი — არა, და თვითკონტროლის უნარსაც გამოიმუშავებს. თუ ბავშვს მუდმივად დასჯით და შეაკავებთ, მას დანაშაულის განცდა გაუჩნდება და ინიციატივის გამოჩენა გაუჭირდება. ამიტომ თქვენს ბავშვთან ჯანსაღი და თანმიმდევრული კომუნიკაცია და მისი მხარდაჭერა უაღრესად მნიშვნელოვანია იმ საკომუნიკაციო უნარებისთვის, რომლებსაც ის მთელი ცხოვრების განმავლობაში გამოიყენებს. ინიციატივიანობის განვითარებაში დახმარება ხელს შეუწყობს, რომ მომავალში ბავშვი საზოგადოების აქტიურ წევრად ჩამოყალიბდეს.') WHERE id = 'da3bc0fb-d618-4650-bd81-5423d3bc0091';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი ერთ-ერთი საუკეთესო დამკვირვებელია, ვისაც კი შეიძლება შეხვდეთ. ის სწავლობს გარშემო მყოფების მაგალითზე და მათი ქცევის მიბაძვით. როდესაც ბავშვი მისაბაძ ადამიანს აკვირდება, მნიშვნელოვანია, რომ მან მისი ქცევა სწორად აღიქვას. თუ დაინახავს, რომ დაკვირვებული ქცევა წახალისდა, მისი გამეორების სურვილი გაუძლიერდება. ხოლო თუ ამ ქცევას დასჯა მოჰყვება, ბავშვი შეეცდება, მას თავი აარიდოს და აღარ გაიმეოროს. ახალი ჩვევების შეძენისას უაღრესად მნიშვნელოვანია, რომ მისაბაძი ადამიანი სწორად იქცეოდეს. ამიტომ ბავშვის ყურადღება სწორ მაგალითებზე უნდა მიმართოთ და, როგორც მშობელმა, თავადაც ყოველთვის სანიმუშოდ უნდა მოიქცეთ.') WHERE id = '609dcb46-d1bd-4f1c-90ea-799e3c5e4531';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'სწორი და დაბალანსებული კვება სასიცოცხლოდ მნიშვნელოვანია თქვენი ბავშვის როგორც ფიზიკური, ისე გონებრივი განვითარებისთვის. თვალსაჩინო ზრდა, როგორიცაა სიმაღლეში მატება და წონის მომატება, მხოლოდ ჯანსაღი კვებით არის შესაძლებელი. ბავშვის სიმაღლისა და წონის რეგულარული მატება მიუთითებს, რომ ის საკმარის საკვებს იღებს. ჯანსაღი ზრდისთვის მან აუცილებლად უნდა მიიღოს საკვები ყველა ჯგუფიდან. რაციონში სხვადასხვა ბოსტნეულსა და ხილთან ერთად აუცილებლად უნდა შეიტანოთ ხორცი, რძის პროდუქტები, კვერცხი და პარკოსნები. გახსოვდეთ, რომ ბევრი ჭამა კარგ კვებას არ ნიშნავს. ბავშვის წონა შეიძლება ნორმალური ჩანდეს, თუ ის ყოველდღე დაბალი კვებითი ღირებულების მქონე საკვებს, მაგალითად, შემწვარ კერძებს ან მაკარონს მიირთმევს, თუმცა სასარგებლო ნივთიერებების ნაკლებობის გამო განვითარებაში შეიძლება ჩამორჩეს.') WHERE id = '056726bd-6460-4e68-8506-371ea64792ec';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ ბავშვს არ მისცემთ იმის გაკეთების შესაძლებლობას, რასაც თავადაც გაუმკლავდება, შეიძლება გარკვეული პრობლემები წარმოიშვას. თუ მის ყოველ სურვილს სხვა შეასრულებს, ზოგიერთი უნარი სათანადოდ ვერ განუვითარდება. ასეთ შემთხვევაში, ყველაფრის დამოუკიდებლად გაკეთების ნაცვლად, ის სხვების დახმარებას დაელოდება და პასუხისმგებლობას თავს აარიდებს. მშობლების სურვილი, დაიცვან საკუთარი ბავშვი, ბუნებრივია, თუმცა ზედმეტად მზრუნველმა დამოკიდებულებამ შეიძლება უარყოფითად იმოქმედოს ბავშვის პიროვნულ განვითარებაზე და ის ოჯახზე დამოკიდებული გახადოს. მაგალითად, ავად გახდომის შიშით ბავშვისთვის სოციალურ გარემოში ყოფნის შეზღუდვა მის თავდაჯერებას ამცირებს. ზედმეტი მეურვეობის ნაცვლად, მიეცით მას მცირე პასუხისმგებლობები, რომელთა შესრულებაც შეუძლია. ეს პასუხისმგებლობები დაეხმარება, დამოუკიდებელ პიროვნებად ჩამოყალიბდეს.') WHERE id = '35c295ce-6938-40be-bd01-33d29397e9d3';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, '3 წლის ასაკიდან ბავშვი თავდაპირველად საკუთარი სასქესო ორგანოების, შემდეგ კი მის გარშემო არსებული სექსუალური საკითხების მიმართ იწყებს ინტერესის გამოხატვას. ეს ფსიქოსოციალური განვითარების ნორმალური პროცესია. ამ პერიოდში ბავშვებმა მშობლებს შეიძლება სხვადასხვა კითხვა დაუსვან. ეცადეთ, ბავშვს მისთვის საინტერესო საკითხი ან ქცევა ასაკის შესაბამისი ენით აუხსნათ. არასოდეს მიმართოთ ტყუილს ან რთულ განმარტებებს; გამოიყენეთ მარტივი და გასაგები მაგალითები. არასრულმა ინფორმაციამ შეიძლება ბავშვს მცდარი წარმოდგენები და შიშები გაუჩინოს, მომავალში კი სქესობრივი განვითარების პრობლემები გამოიწვიოს. ეს კითხვები და ეტაპები თითოეულ ბავშვთან სხვადასხვა დროს და გარემო ფაქტორების გავლენით ვითარდება. მისი ინტერესის ბუნებრივად დაკმაყოფილება განვითარების ამ პროცესის ნაწილია.') WHERE id = '727f21dd-8b8d-4256-8326-d8a14decc7b4';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'მონტესორის მეთოდით სწავლებისას 3 წლის ბავშვებისთვის უნდა დაიგეგმოს წვრილი მოტორული უნარების განვითარებისთვის შესაფერისი აქტივობები, რომლებსაც დიდი მნიშვნელობა ენიჭება. წვრილი მოტორიკის განვითარება ხელს უწყობს როგორც წერის უნარის ჩამოყალიბებას, ისე ხელის მოქნილობას, რომელიც ინტელექტუალური განვითარების ერთ-ერთი მაჩვენებელია. ამიტომ ძალიან სასარგებლოა ისეთი აქტივობები, რომლებიც თქვენი ბავშვის პატარა თითებს ავარჯიშებს. რამდენიმე რჩევას გთავაზობთ: მაშით საგნების აღება და გადატანა სახალისოცაა და შემეცნებითიც. ყოველდღიურ ცხოვრებაში ისეთი მოქმედებები, როგორიცაა ღილების შეკვრა და ფეხსაცმლის თასმების შეკვრა, ამ უნარებსაც ავითარებს. თუ ბავშვი პირველივე ცდაზე ვერ შეძლებს დავალების შესრულებას, შეგიძლიათ გაამხნეოთ ისეთი ფრაზებით, როგორიცაა: „არაუშავს, კიდევ ერთხელ ვცადოთ?“ — და ამით მისი თავდაჯერება განამტკიცოთ.') WHERE id = 'b1b27ccb-a59d-4f78-b850-b6b85156fdf3';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვების ფიზიკური თავისებურებების გათვალისწინებით, სპორტის პირველი სახეობა, რომლითაც მათ შეუძლიათ დაკავდნენ, ტანვარჯიშია — ის სპორტის ყველა სახეობის საფუძვლად მიიჩნევა. ტანვარჯიში ის აქტივობაა, რომლითაც ბავშვები ადრეული ასაკიდანვე სიამოვნებით კავდებიან და რომლის სარგებელიც დადასტურებულია. დაკვირვებები აჩვენებს, რომ ბავშვები, რომლებიც ტანვარჯიშით არიან დაკავებული, ფსიქომოტორული, კოგნიტიური და ემოციური თვალსაზრისით უფრო სწრაფად ვითარდებიან. 3 წლიდან შეგიძლიათ, თამაშის ფორმის ტანვარჯიშული ვარჯიშებით გააცნოთ თქვენს შვილს ეს სფერო. ტანვარჯიში აძლიერებს ბავშვის ისეთ მოტორულ უნარებს, როგორებიცაა წონასწორობა, სისწრაფე, ძალა, სიმარჯვე, კოორდინაცია და მოქნილობა. ბავშვებს, რომლებიც ტანვარჯიშს ადრეულ ასაკში იწყებენ, მაქსიმალურად უვითარდებათ სირბილის, ხტომისა და ცოცვის უნარები. სპორტის ეს სახეობა თქვენს შვილს დაეხმარება, ენერგია სწორად დახარჯოს და, ამავდროულად, მნიშვნელოვან წვლილს შეიტანს მის ჯანმრთელობაში.') WHERE id = '3a71e453-dc05-444b-a5d5-f7d179a2c1b2';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, '3 წლის ასაკში მეორე ენის შესწავლის დაწყება ბავშვის ენობრივი აღქმის განვითარებისთვის ძალიან ეფექტურია. ბავშვი, რომელიც იზრდება გარემოში, სადაც მშობლიურ ენასთან ერთად სხვა ენაზეც საუბრობენ, ორივე ენას მარტივად ითვისებს. ამისთვის სასარგებლო იქნება, თუ თქვენი შვილი ინგლისურენოვან გარემოში აღმოჩნდება. ინგლისურ ენაზე მულტფილმებისა და იავნანების ხშირად მოსმენა ამ პროცესის საინტერესო და მარტივი მეთოდია. ასევე, როდესაც ბავშვი რაიმე პროგრამას უყურებს, უპირატესობა ინგლისურენოვან საბავშვო ფილმებს უნდა მიანიჭოთ. ამგვარად, დროთა განმავლობაში სიტყვები თქვენი შვილისთვის ნაცნობი გახდება. შეგიძლიათ, იმ სიტყვების ინგლისური შესატყვისებიც უთხრათ, რომელთა წარმოთქმაც მან უკვე დაიწყო. მაგალითად, როცა ის იტყვის „კატა“, თქვენ შეგიძლიათ უპასუხოთ „Cat“ და ამგვარად ახალი სიტყვა ასწავლოთ. მეტყველების განვითარების დაჩქარების მცდელობისას ბავშვმა ზეწოლა არ უნდა იგრძნოს — სწავლა სახალისო აქტივობებით წარმართეთ. მაგალითად, როდესაც ის საყვარელ თამაშს თამაშობს, შეგიძლიათ თამაშში შესრულებული მოქმედებები ინგლისურად გაახმოვანოთ.') WHERE id = '94749156-ac73-4e79-8936-22626911b701';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ პერიოდში თქვენი შვილის წარმოსახვის უნარი საგრძნობლად განვითარდა. წარმოსახვა, რომელიც ბავშვების ბუნების ნაწილია, სინამდვილეში რეალური ცხოვრების სიმბოლური მოდელია. თუ დააკვირდებით, როგორ თამაშობს თქვენი შვილი მეგობრებთან ერთად, მარტივად დაინახავთ, როგორ ასახავენ ისინი რეალურ ცხოვრებას სიმბოლურად. მისი წარმოსახვის სამყაროს მხარდაჭერით ბავშვს მომავლისთვის უკეთ ამზადებთ. ბავშვი, რომლის წარმოსახვასაც ხელს უწყობენ, შემოქმედებითობისადმი ღია პიროვნებად იზრდება. შეზღუდვებთან მუდმივად შეჯახება კი ბავშვს აღმოჩენისა და კვლევის სურვილს უკარგავს. თქვენი შვილის შინაგანი სამყაროს გასამდიდრებლად შეგიძლიათ, განსაკუთრებული ყურადღება დაუთმოთ ისეთ აქტივობებს, როგორებიცაა წიგნების კითხვა, ფაზლების აწყობა, ხატვა, კინოში სიარული, მეგობრებთან ურთიერთობა და მუსიკით დაკავება. გახსოვდეთ, რომ განვითარებული წარმოსახვის მქონე ბავშვმა თამაშისას შეიძლება ირგვლივ ნივთები მიმოფანტოს. ამას მკაცრად ნუ გამოეხმაურებით — გაგებით მოეკიდეთ არეულობას და მასთან ერთად სასიამოვნოდ და ნაყოფიერად გაატარეთ დრო.') WHERE id = '0d882b08-7404-48d9-97ab-a63d45290aad';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'გახსოვდეთ, რომ ბავშვის კვების ერთ-ერთი მთავარი წესი საკვების მიღების დროის დაცვაა. აუცილებლად უნდა იზრუნოთ, რომ თქვენმა შვილმა მიირთვას საუზმე, რომელიც დღის ყველაზე მნიშვნელოვანი კვებაა. ჯანსაღ წასახემსებლად შეგიძლიათ უპირატესობა მიანიჭოთ ჩირს, ფინიკსა და თხილეულს. ყურადღება მიაქციეთ, რომ ყოველდღიურ რაციონში შედიოდეს სასარგებლო თხილეული, როგორიცაა ნიგოზი, თხილი და ნუში, ასევე სრულმარცვლოვანი პროდუქტები. ეცადეთ, ხილი და ბოსტნეული ახალი და სეზონური შეარჩიოთ. პესტიციდების მოსაშორებლად ისინი ძალიან კარგად უნდა გარეცხოთ. უმჯობესია, ხილი ბავშვს მხოლოდ წვენის სახით კი არა, ბოჭკოსთან ერთად მისცეთ. კვლევები აჩვენებს, რომ თევზი ბავშვების იმუნურ სისტემაზე ძალიან დადებითად მოქმედებს და ორგანიზმის დაავადებებისადმი მდგრადობას ზრდის. ამიტომ კვირაში ერთხელ თევზის ჭამა ჩვევად უნდა აქციოთ.') WHERE id = 'e2ff4d89-6e44-49f2-8f66-9efbff6dfaad';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'საყოფაცხოვრებო უბედური შემთხვევები ხშირად ხდება. მათ შორის ყველაზე გავრცელებულია დაცემა და რაიმეზე შეჯახება, ჭრილობები, უცხო სხეულით სასუნთქი გზების დახშობა ან გაგუდვა, წყალში დახრჩობა, მოწამვლა, დამწვრობა და ელექტროდენით დაზიანება. თქვენი პასუხისმგებლობაა, რომ ბავშვმა უსაფრთხო გარემოში იცხოვროს და შესაბამისი დამცავი ზომები იყოს მიღებული. მსგავსი დაზიანებების თავიდან ასაცილებლად რამდენიმე მარტივად შესასრულებელ რეკომენდაციას გთავაზობთ: ღიად დარჩენილი აივნის კარი ან ფანჯარა უბედური შემთხვევის მიზეზი რომ არ გახდეს, გამოიყენეთ უსაფრთხოების საკეტები. ტელევიზორის მსგავსი დიდი მოწყობილობები მყარად დაამაგრეთ და დარწმუნდით, რომ ისინი არ გადაყირავდება. ბასრ და წვეტიან კუთხეებზე სპეციალური დამცავების დაყენებით შეგიძლიათ შეჯახებისას დაზიანება თავიდან აიცილოთ. სამზარეულოს კარადებსა და უჯრებზე დამცავი საკეტები გამოიყენეთ, რათა ბავშვი ვერ მისწვდეს ბასრ და წვეტიან ნივთებს, მაგალითად, დანასა და ჩანგალს. ეს მოწყობილობები ასევე შეამცირებს თითებისა და ხელის მოყოლის საფრთხეს. იმავე ფუნქციას ასრულებს კარის სახელურისა და თითების დამცავებიც. მედიკამენტები, საწმენდი საშუალებები და შხამიანი ნივთიერებები ბავშვებისთვის მიუწვდომელ ადგილას, შეძლებისდაგვარად ჩაკეტილ ან მაღალ კარადებში შეინახეთ.') WHERE id = 'da19983e-64ca-4ef1-be1d-d6b1b52c415f';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი შვილის პატარა ზრდასრული ადამიანივით ქცევამ შეიძლება საკმაოდ ბევრი სირთულე შეგიქმნათ. წარმოქმნილი პრობლემების მოგვარება ახალი წესების დაწესებით შეგიძლიათ. რა თქმა უნდა, წესების დაწესება რთულია — ზედმეტი სიმკაცრე ისეთივე საზიანოა, როგორც მეტისმეტი ლმობიერება. შეარჩიეთ თქვენი შვილისთვის შესაფერისი მიდგომა, ყოველდღიურად ნუ შეცვლით მას და იყავით თანმიმდევრული. გახსოვდეთ, რომ წესების დაწესება ბავშვის აღზრდის ნაწილია — ამ გზით მას ერთდროულად იცავთ და ზრდით. დროთა განმავლობაში თქვენი შვილი მიხვდება, რომ სწორად განსაზღვრული წესები მის სასარგებლოდ მოქმედებს და იგრძნობს, რომ ისინი თქვენი სიყვარულის ნაწილია. ამასთანავე, წესების დაწესება ბავშვისადმი თქვენი ნდობის გამოსახატავადაც ეფექტური გზაა.') WHERE id = '8821b078-f268-490e-aff6-43d6dec5162e';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ თქვენი შვილი ტელევიზორის ყურებისას ჭამს, პირველ რიგში, ის ვერც კი აცნობიერებს, რომ საკვებს მიირთმევს. მისთვის ეს უბრალოდ ტელევიზორის ყურებით გართობაა. რადგან ბავშვები გამოცდილებით სწავლობენ, ტელევიზორის წინ ჭამისას ისინი ჯანსაღი კვების ჩვევებს ვერ ითვისებენ. ბავშვს, რომელსაც ეს ჩვევა სათანადოდ არ ჩამოუყალიბდა, მომავალში შეიძლება ჰქონდეს არასრულფასოვანი კვების, სუფრასთან დაჯდომის სურვილის არქონის, საკვების მიმართ პრეტენზიულობისა და დამოუკიდებლად ჭამის უუნარობის პრობლემები. ტელევიზორის ან კომპიუტერის წინ ჭამისას ბავშვებმა შეიძლება დანაყრება ვერ იგრძნონ და თამაშის ან ფილმის დასრულებამდე განაგრძონ ჭამა. ეს კი თქვენს შვილს მომდევნო კვების დროს შიმშილის შეგრძნებასა და ყოველდღიურ კვებით ბალანსს დაურღვევს. ამგვარად, ხელს შეუშლით, ისწავლოს დანაყრების ამოცნობა და ჭამის დროულად შეწყვეტა.') WHERE id = 'a4f1d0bd-58eb-4370-bb57-6949cd1e1527';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, '3 წლის შემდეგ, როდესაც თქვენს შვილს უკვე შეუძლია კბილის პასტის გადმოფურთხება, შეგიძლიათ კბილები საბავშვო კბილის პასტით გაუხეხოთ. სამწუხაროდ, კბილის კარიესი იმ ბავშვებსაც უვითარდებათ, რომლებიც შოკოლადს, ტკბილეულსა და მსგავს პროდუქტებს არ მიირთმევენ. გავრცელებული მოსაზრების საპირისპიროდ, კარიესს იწვევს ყველაფერი, რაც კბილის ზედაპირს ეკვრის. ნახშირწყლებმა (მაგალითად, პურმა და მაკარონმა), რძემ (ლაქტოზამ) და მსგავსმა სასმელებმა შეიძლება კბილის კარიესი გამოიწვიოს. გადამუშავებული საკვების მოხმარების ზრდასთან ერთად, წლების განმავლობაში საკვებში შაქრის შემცველობაც გაიზარდა. ამის გამო ბავშვების კბილების დაცვა უფრო გართულდა. მთავარი მიზანია, კბილის ზედაპირზე საკვების ნარჩენების დარჩენა მინიმუმამდე შემცირდეს. კარიესის თავიდან ასაცილებლად მნიშვნელოვანი ნაბიჯების გადადგმა შეგიძლიათ, თუ თქვენს შვილს კბილებს დღეში 2-ჯერ, 2 წუთის განმავლობაში გაუხეხავთ და შუალედური კვების შემდეგ პირს წყლით გამოავლებინებთ. 3 წლის შემდეგ სტომატოლოგის მიერ ჩატარებული ფისურების ჰერმეტიზაციისა და ფტორირების პროცედურებიც ხელს შეუწყობს კარიესის თავიდან აცილებას.') WHERE id = '74588fea-3393-4777-9d52-b001b79cdfc6';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, '3 წლის ბავშვის ძილის რეჟიმზე მოქმედი ერთ-ერთი მთავარი ფაქტორი ტელევიზორისა და კომპიუტერული თამაშების წინ ხანგრძლივი დროის გატარებაა, განსაკუთრებით მაშინ, თუ ნანახმა შინაარსმა შეიძლება კოშმარები გამოიწვიოს. ამ ასაკში ბავშვებს აღქმის კარგი უნარი აქვთ. რადგან ისინი იაზრებენ, რა ხდება მათ გარშემო, ადვილად ექცევიან შთაბეჭდილების ქვეშ. ამან კი შეიძლება ძილის პრობლემები გამოიწვიოს. ბავშვს შეიძლება გარკვეული შიშები გაუჩნდეს იმ ისტორიების გამო, რომლებსაც უკითხავენ ან აყურებინებენ. აუცილებლად უნდა შეუზღუდოთ თქვენს შვილს ეკრანთან გატარებული დრო. მან დღეში მხოლოდ 30 წუთის განმავლობაში და მხოლოდ თქვენ მიერ შერჩეულ შინაარსს უნდა უყუროს. ამ დროს სასარგებლო იქნება, თუ მასთან ერთად იქნებით და დააკვირდებით, რათა მისი შიშები ამოიცნოთ.') WHERE id = '89c3ef7f-a4e3-4d2d-9a7f-42e0b75a36a6';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'შეიძლება ითქვას, რომ გააზრებულ სქესობრივ აღზრდასთან დაკავშირებული პირველი კითხვები დაახლოებით 3 წლის ასაკში ჩნდება. როდესაც ბავშვი სქესობრივ საკითხებთან დაკავშირებით პირველ კითხვას დაგისვამთ, შეიძლება დაიბნეთ ან შეშინდეთ. ეს კითხვები შეიძლება ეხებოდეს სასქესო ორგანოების ფუნქციებს, ქალისა და კაცის როლებს და იმას, თუ როგორ იბადებიან ადამიანები. თქვენი პასუხისმგებლობაა, ბავშვს პირველადი ინფორმაცია მიაწოდოთ, საკითხი სწორად გააცნოთ და აკონტროლოთ, რას იგებს სხვა წყაროებიდან. ამიტომ სქესობრივი აღზრდის საკითხებში ინფორმირებული უნდა იყოთ და სწორი მიდგომა აირჩიოთ. ნუ ისაუბრებთ თავდაცვითი ან ბოდიშის მომგვრელი ტონით. ესაუბრეთ იმავე ბუნებრივი ტონითა და ტემპით, რომლითაც ყოველდღიურ ცხოვრებაში საუბრობთ. თუ ჩვეულებრივ სწრაფად საუბრობთ, ამ თემაზე ზედმეტად ნელა საუბარი მის ყურადღებას მიიქცევს და აფიქრებინებს, რომ ეს საკითხი სხვებისგან განსხვავებული ან უცნაურია. მის კითხვებზე პასუხისას სახეზე შოკი ან შეშფოთება არ უნდა გეტყობოდეთ, რადგან ასეთმა გამომეტყველებამ შეიძლება აფიქრებინოს, რომ ამ თემაზე საუბარი არ შეიძლება.') WHERE id = 'df1bc0c0-a742-4c28-9bf6-e95185ce12cb';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვს არაჯანსაღი წასახემსებელი პროდუქტები რაც შეიძლება გვიან უნდა გააცნოთ. თუ ის საჭმელს არ ჭამს, ნუ მისცემთ საშუალებას იფიქროს, რომ ასეთი პროდუქტი ძირითადი საკვების შემცვლელია. სასურველი მცირე წასახემსებელი შეგიძლიათ მისცეთ არა ყოველთვის, როცა მოითხოვს, არამედ მხოლოდ მას შემდეგ, რაც ძირითად საკვებსა და ხილს შეჭამს, ჯანსაღად დანაყრდება და მომდევნო კვებამდე 1,5-2 საათი იქნება დარჩენილი. ამგვარად დარწმუნდებით, რომ ის მცირე რაოდენობას მიირთმევს. თუ ნაყინი სურს, შეგიძლიათ სახლში მომზადებული ჯანსაღი ნაყინი შესთავაზოთ. თუ ეს მეთოდი არ გაამართლებს, შეფუთული ნაყინის ნაცვლად შესთავაზეთ, სანდო ადგილას ხილისა და რძის ნაყინი უყიდოთ. ყოველთვის, როცა არაჯანსაღ წასახემსებელს მოითხოვს, შეეცადეთ საკითხი გადადოთ და მისი ყურადღება საყვარელ, საინტერესო აქტივობაზე გადაიტანოთ. არასოდეს გამოიყენოთ ასეთი საკვები გარიგების საგნად, რადგან თქვენი შვილი მალე დაიწყებს ამ მეთოდის თქვენს წინააღმდეგ გამოყენებას.') WHERE id = '50b63152-534e-4f39-95a9-aeba706b5baa';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენს ბავშვში ჯანსაღი თვითშეფასების ჩამოსაყალიბებლად რამდენიმე მნიშვნელოვან საკითხს უნდა მიაქციოთ ყურადღება. უპირველეს ყოვლისა, პატივი უნდა სცეთ თქვენი შვილის აზრებსა და მისწრაფებებს და მასთან ყოველთვის გულწრფელი უნდა იყოთ. მისი სურვილების სრულად უარყოფის ნაცვლად, ეცადეთ მისთვის გასაგები ენით აუხსნათ, რას ელით მისგან და რა არის მისაღები. ყურადღებით მოუსმინეთ თქვენს შვილს და აგრძნობინეთ, რამდენად ღირებულია თქვენთან ურთიერთობის დამყარების მისი მცდელობები. მისგან სრულყოფილ ქცევას ნუ მოელით — გქონდეთ რეალისტური მოლოდინები და დააწესეთ გარკვეული საზღვრები. მიეცით მას არჩევანის შესაძლებლობა. მაგალითად: "ახლა ძილის დროა. შენს სათამაშო დათუნიასთან ერთად გინდა დაძინება თუ ძაღლთან?" ან "წამლის მიღება ახლა გინდა თუ 10 წუთის შემდეგ?". ურთიერთობისას გამოიყენეთ "მე"-ფორმა და აუხსენით, როგორ მოქმედებს თქვენზე მისი მიუღებელი საქციელი. მაგალითად: "როცა კუბიკებს ისვრი, ვნერვიულობ, რომ ვინმე დაშავდება." მიეცით თქვენს შვილს შეცდომების დაშვების შესაძლებლობა, რათა მათგან გაკვეთილი ისწავლოს. ბავშვებს დრო სჭირდებათ საკუთარი გამოსავლის საპოვნელად — ამგვარად ისინი შეცდომების გამოსწორებასაც ისწავლიან.') WHERE id = 'af61b7a0-7776-4b9d-8393-d1e3bf0de875';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, '3 წლის ასაკიდან ბავშვები იწყებენ საკვების მნიშვნელობის გააზრებას ჩვენს ცხოვრებაში და რეკლამებისა და სათამაშოების გავლენის ქვეშ ექცევიან. ამ პერიოდში მიღებული შთაბეჭდილებები მათ მომავალ არჩევანს განსაზღვრავს. ჰამბურგერი, პიცა და კარტოფილი ფრი, რომლებსაც თქვენი ბავშვი ტელევიზორში ხედავს ან სათამაშოების სახით თამაშობს, დროთა განმავლობაში შესაძლოა მის საყვარელ საკვებად იქცეს. ასეთი საკვები მდიდარია ნაჯერი ცხიმებით, თუმცა ღარიბია ვიტამინებითა და მინერალებით. ამასთანავე, ის შეიცავს საღებავებს, კონსერვანტებსა და ჭარბი რაოდენობით მარილს. გაზიანი სასმელები კი დიდი რაოდენობით სიმინდის სიროფს შეიცავს. ჭარბი კალორიების გამო სწრაფი კვების პროდუქტები და გაზიანი სასმელები სიმსუქნის რისკს ზრდის, რამაც მომავალში შესაძლოა ტიპი 2 დიაბეტი, ასთმა და გულ-სისხლძარღვთა დაავადებები გამოიწვიოს. თქვენი ბავშვის ჯანსაღი კვებისთვის სწრაფი კვების პროდუქტები და ტკბილეული არასოდეს გამოიყენოთ ჯილდოდ. ეცადეთ, მოარიდოთ ის რეკლამებსა და მულტფილმებს, რომლებიც ასეთი საკვების მიღებისკენ უბიძგებს.') WHERE id = 'c9d496f4-cfe4-45b1-abe1-dd54922bd115';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი სხვადასხვა გარემოში შესაძლოა ვირუსებისა და ბაქტერიების ზემოქმედების ქვეშ აღმოჩნდეს. როდესაც მისი იმუნური სისტემა კარგად მუშაობს, ის მიკრობების მიმართ უფრო გამძლეა და ავად გახდომის რისკიც მცირდება. არასაკმარისი და არასწორი კვება, განსაკუთრებით სეზონების ცვლილებისას, იმუნიტეტის დასუსტებას იწვევს. დაახლოებით 3 წლის ბავშვებში იმუნიტეტის დაქვეითება ხშირად გვხვდება და მისი გამოვლენის შემთხვევაში მდგომარეობის გაუმჯობესება შესაბამისი მხარდაჭერით არის შესაძლებელი. მრავალფეროვანი საკვები ნივთიერებებით მდიდარი კვების რაციონი ხელს შეუწყობს როგორც თქვენი ბავშვის იმუნიტეტს, ისე მის ჯანსაღ ზრდას. განსაკუთრებით მნიშვნელოვანია, რომ საუზმეზე მან სულ მცირე 1 კვერცხი შეჭამოს და 1 ჭიქა რძე დალიოს. სხვა კვებებზე აუცილებლად უნდა მიიღოს წითელი და მწვანე წიწაკა, მწვანე ფოთლოვანი ბოსტნეული და, რაც მთავარია, ხახვი და ნიორი. საჭიროების შემთხვევაში ვიტამინები მხოლოდ ექიმის მეთვალყურეობით უნდა მიეცეს.') WHERE id = '1f040fd3-210e-465e-94b9-9cad5e55958d';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'განვითარების თითოეულ ეტაპს მისთვის დამახასიათებელი ქცევები აქვს, ამიტომ კარგად უნდა იცნობდეთ თქვენი ბავშვის ასაკობრივი პერიოდის თავისებურებებს. იმის დასადგენად, ითვლება თუ არა ქცევა დარღვევად, რამდენიმე კრიტერიუმი არსებობს. მაგალითად, 3 წლის ბავშვს ყურადღების ცენტრში ყოფნა სურს. მდიდარი წარმოსახვის გამო მან შეიძლება დაუჯერებელი ამბები მოყვეს. ამ ასაკში ბავშვებს ჯერ კიდევ არ შეუძლიათ სიცრუისა და სინამდვილის ერთმანეთისგან გარჩევა. ამიტომ ამ ასაკში მონაყოლი სიცრუედ არ ითვლება, თუმცა 11-14 წლის ბავშვთან იგივე შემთხვევა შესაძლოა ქცევის დარღვევად შეფასდეს. კიდევ ერთი კრიტერიუმია ინტენსივობა. 3 წლის ბავშვისთვის გაღიზიანება და სიჯიუტე ბუნებრივია, მაგრამ თუ ეს სხვისთვის ფიზიკური ზიანის მიყენებაში გადაიზრდება, უკვე ქცევის დარღვევის კატეგორიას მიეკუთვნება. მნიშვნელოვანი მაჩვენებელია ისიც, თუ ბავშვი გარკვეულ ქცევას დაჟინებით და ხანგრძლივი დროის განმავლობაში აგრძელებს.') WHERE id = 'e2e3a081-c2d4-43fa-9fb7-5fa0204ba1dc';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ ასაკიდან ბავშვის სოციალური გარემო იცვლება და თანატოლებთან მისი ურთიერთობა უფრო აქტიური ხდება. ამის წყალობით პატარები უფროსებზე დაკვირვებით მოთმინებასა და სწავლას ეჩვევიან, უფროსები კი უმცროსებისადმი სიყვარულით მოპყრობას სწავლობენ. 3 წლის ბავშვებში მხედველობა, სმენა, გემოვნება და შეხების შეგრძნება სწრაფად ვითარდება. უპირატესობა უნდა მიანიჭოთ აქტივობებს, რომლებიც თქვენი ბავშვის შეგრძნებებს განავითარებს და ამ შეგრძნებების საშუალებით მის გონებრივ განვითარებას შეუწყობს ხელს. 3 წლის ასაკიდან ბავშვებს მონტესორის საგანმანათლებლო დაწესებულებებში სიარულიც შეუძლიათ. მონტესორის მასალებს შორის მნიშვნელოვანი ადგილი უკავია სუნისა და გემოს ბოთლებს. ამ აქტივობის მომზადება სახლშიც მარტივად შეგიძლიათ. სხვადასხვა ბოთლში ჩასხმულ წყალს დაუმატეთ ლიმონის წვენი, მელასა ან შრატი და ასე შექმენით გემოს ბოთლები. შეხების შეგრძნების გასავითარებლად ასევე რეკომენდებულია სხვადასხვა ზედაპირის მომზადება, რომელთა ტექსტურასაც ბავშვი როგორც ხელებით, ისე ფეხებით შეიგრძნობს.') WHERE id = '2f2859f2-2f74-4d9b-8af7-2a5b021a62ab';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, '3 წლის ასაკში დაწყებული დაზიანებისა და გაქრობის შიში შესაძლოა სიზმრების, ნანგრევების ან ურჩხულების სახით გამოვლინდეს. თამაშის დროს თქვენი ბავშვი საკუთარ სამყაროში ამ შიშებს კონკრეტულ ფორმას აძლევს. როდესაც თამაშში გმირები და უარყოფითი პერსონაჟები ერთმანეთს ებრძვიან, სინამდვილეში ორივე მათგანი ბავშვის შინაგანი სამყაროს ანარეკლია. ამან შესაძლოა ოდნავ შეგაშფოთოთ, თუმცა საჭიროა სიმშვიდის შენარჩუნება. სიტყვები — «ურჩხული არ არსებობს!» — ბავშვს უჩენს განცდას, რომ მისი არ ესმით. უპირველეს ყოვლისა, მისი სამყაროს გაგება უნდა სცადოთ. ამის ყველაზე ეფექტური გზა მის თამაშში ჩართვაა. თუ თამაშის დროს უჩვეულო ქცევას შენიშნავთ, კითხვების დასმით შეძლებთ, უკეთ გაუგოთ და დადებითი როლების დახმარებით შიშების დაძლევაში დაეხმაროთ.') WHERE id = '9e9d2250-5512-46d4-b8e9-3d1a806c30dc';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვისთვის თამაშის მიზანი შესაძლოა მხოლოდ გართობა იყოს, თუმცა მშობლებისთვის თამაში შესანიშნავი შესაძლებლობაა, რომ ბავშვთან დრო გაატარონ და უკეთ გაიცნონ ის. სწავლისა და განვითარების პროცესი სულაც არ უნდა იყოს მოსაწყენი. სახალისო და შემეცნებითი თამაშებით შეგიძლიათ ხელი შეუწყოთ თქვენი ბავშვის ტვინის განვითარებას. დაუდეთ მას სხვადასხვა ფორმისა და ფერის ბლოკების ნაკრები (კუბიკები), დანარჩენი კი მის წარმოსახვას მიანდეთ. ეს თამაში ფორმებისა და ფერების გარჩევიდან დაწყებული, მრავალ სფეროში შეუწყობს ხელს მის გონებრივ განვითარებას და შემოქმედებით უნარებს გაუუმჯობესებს. სხვადასხვა მუსიკალური ინსტრუმენტის გაცნობა კი დადებითად მოქმედებს მის ემოციურ, სოციალურ და გონებრივ განვითარებაზე. მუსიკით დაკავება ერთ-ერთი ყველაზე შემეცნებითი და საინტერესო აქტივობაა.') WHERE id = '20a29436-fc37-4a8d-9225-4d47565f2992';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'სკოლამდელი განათლების მეშვეობით შესაძლებელია ბავშვის ინტერესების სფეროსა და გამორჩეული ნიჭის გამოვლენა. თითოეული ბავშვის ინდივიდუალური თავისებურებების გათვალისწინებით, მისი ფიზიკური და გონებრივი განვითარების ხელშეწყობა უფრო მარტივია. გონებრივი განვითარების 50% პირველი 4 წლის განმავლობაში, ხოლო 30% 8 წლამდე სრულდება. ამიტომ, როდესაც სკოლამდელ განათლებაზე ვსაუბრობთ, ვგულისხმობთ უმნიშვნელოვანეს პერიოდს, როდესაც თქვენს შვილს საკუთარი ინტელექტუალური პოტენციალის აღმოჩენა შეუძლია. ამ პერიოდში ბავშვს სხვადასხვა ტესტის საშუალებით ყურადღებით აკვირდებიან და მისი განვითარების პროცესს რეგულარულად აღრიცხავენ. გარდა ამისა, საბავშვო ბაღში თამაშებისა და ხელოვნებასთან დაკავშირებული აქტივობების მეშვეობით ბავშვის უნარებიც ვლინდება. ამგვარად, შესაძლებელია უფრო ადრე შეამჩნიოთ როგორც ბავშვის ძლიერი მხარეები, ისე ის უნარები, რომლებიც განვითარებას საჭიროებს.') WHERE id = 'fcdecd06-9935-451b-a2fa-d85e42defeda';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'მეტყველების უნარის შეძენა ბავშვის განვითარების პროცესში ძალიან მნიშვნელოვანი ეტაპია. თუ ბავშვი უკვე 3 წლისაა, მაგრამ ჯერ კიდევ არ დაუწყია ლაპარაკი და ნათქვამის გაგებაც უჭირს, აუცილებლად უნდა მიმართოთ სპეციალისტს. მიდგომამ, როგორიცაა „მამამისმაც გვიან დაიწყო ლაპარაკი“, შესაძლოა მომავალში ისეთი პრობლემები გამოიწვიოს, რომელთა გამოსწორებაც რთული იქნება. მეტყველების შეფერხებას მრავალი მიზეზი შეიძლება ჰქონდეს, მათ შორის სმენის დაქვეითება, სტიმულაციის ნაკლებობა, ინტელექტუალური განვითარების შეფერხება და აუტიზმი. თითოეული მათგანი განსხვავებულ მიდგომას საჭიროებს. ლოდინმა იმ იმედით, რომ „დროთა განმავლობაში გამოსწორდება“, შესაძლოა შეუქცევადი შედეგები გამოიწვიოს. ინტერნეტში ან წიგნებში წაკითხული ინფორმაციის საფუძველზე დიაგნოზის დასმა შეუძლებელია; აუცილებელია გამოცდილი სპეციალისტის მიერ ჩატარებული კლინიკური შეფასება.') WHERE id = '820eb790-8d69-449a-8be1-43f47a9dd95b';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'კვლევები აჩვენებს, რომ, სამწუხაროდ, ჩვენს ბავშვებს საკმარისად არ სძინავთ ან ძალიან გვიან იძინებენ. 3 წლის ბავშვისთვის 22:00 საათის შემდეგ დაძინება გვიანად ითვლება. ამ პერიოდში თქვენი შვილი უკვე გისოსების გარეშე საწოლში წევს და შეუძლია საკუთარი აზრების სიტყვიერად გამოხატვა, ამიტომ მის დაძინებას შესაძლოა მეტი დრო და მოთმინება დასჭირდეს. ყველაზე მნიშვნელოვანია, იყოთ მომთმენი და თანმიმდევრული. ბავშვმა კარგად იცის, რომელ თხოვნას შეუსრულებთ და სწორედ ამაზე ამახვილებს ყურადღებას. კიდევ ერთი ჭიქა წყალი მინდა, კიდევ ერთი ზღაპარი მომიყევი, დედა, შენ წადი და მამა მოვიდეს, საბანი დამაფარე, ტუალეტში მინდა, ზურგზე მომეფერე, კიდევ ერთი იავნანა მიმღერე... ნაცნობად ჟღერს ეს მიზეზები? შესაძლოა, ეს მთელი ღამე გაგრძელდეს და ძილი დაგიფრთხოთ. თანმიმდევრული და მტკიცე დამოკიდებულებით ამ პრობლემის დაძლევას შეძლებთ.') WHERE id = 'e9f80de9-ae84-478b-943d-e1b333c1b0f7';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი შვილის მიერ დამშვიდების სწავლა განვითარების ისეთივე ნაწილია, როგორიც ხოხვა, სიარული ან ფანქრის დაჭერა. თუ მას სათანადო მხარდაჭერას გაუწევთ, ის თვითრეგულაციის, ანუ საკუთარი თავის დამშვიდების უნარს შეიძენს. როდესაც ამ ამოცანას მობილურ ტელეფონს აკისრებთ, ბავშვი დამშვიდებას კი არ სწავლობს, არამედ სხვა გარეგანი ფაქტორით იღებს სტიმულაციას. ამის დასტურია ისიც, რომ ტელეფონის ჩამორთმევისას კვლავ იწყებს ტირილს. როდესაც მის სურვილებს ზღვარს უწესებთ, ტირილი ნორმალურია; სწორედ აქ იწყება მშობლობა. საზღვრების დაცვისას უთხარით, რომ გესმით მისი გრძნობები, თუმცა კამათისა და დაყოლიების მცდელობის გარეშე მშვიდად დაელოდეთ. თუ ბავშვის სწრაფად გაჩუმებას არ ეცდებით და სიმშვიდეს შეინარჩუნებთ, ეს მას დაეხმარება, დროთა განმავლობაში უფრო მარტივად დამშვიდდეს.') WHERE id = '9c23d639-ad9f-4e04-a46c-08501b1d3ab9';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, '3 წლის ასაკში განავლის შეკავების პრობლემას შესაძლოა ფსიქოლოგიური ფაქტორები ედოს საფუძვლად. ბავშვები, რომლებსაც ფიზიკური ჯანმრთელობის პრობლემა არ აქვთ, ზოგჯერ განავალს საკუთარი სხეულის ნაწილად აღიქვამენ და არ სურთ მისი დაკარგვა. ფსიქოლოგების აზრით, ბავშვები ამ გზით საკუთარი არსებობისა და დამოუკიდებლობის დამტკიცებას ცდილობენ. სხვა მიზეზები შეიძლება იყოს ძლიერი სტრესი, ოჯახური კონფლიქტები ან ტუალეტის ჩვევების ზედმეტად ადრე ან არასწორად სწავლება. ზოგიერთი ბავშვი კი კონტროლის საჭიროებას ამგვარად გამოხატავს. გარდა ამისა, უნიტაზის ან ჩარეცხვის ხმის შიშიც იმ შფოთვის გამომწვევ ფაქტორებს მიეკუთვნება, რომლებმაც შესაძლოა ბავშვს განავლის შეკავებისკენ უბიძგოს.') WHERE id = '11f77601-04b8-47b0-af21-9926fe8313e7';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი შვილის შემოქმედებითი უნარების განსავითარებლად თქვენი ფანტაზიაც უსაზღვრო უნდა იყოს. პლასტილინის, ფაზლების, ლეგოსა და გადასაყრელი მასალების გამოყენებით შეგიძლიათ განუვითაროთ როგორც შეხების შეგრძნება, ისე წარმოსახვის უნარი. პლასტილინით თამაში ბავშვს შემოქმედებით უნარებთან ერთად მოტორულ უნარებსაც უძლიერებს. ფაზლები პრობლემების გადაჭრის უნარს ავითარებს. ლეგო კი შესანიშნავი საშუალებაა როგორც ნატიფი მოტორიკის განსავითარებლად, ისე დიდი-პატარა და გრძელი-მოკლე ცნებებისა და ფერების სასწავლებლად. ასეთი აქტივობებისას დაინახავთ, რამდენად სასიამოვნოა რაიმეს ერთად შექმნა როგორც თქვენთვის, ისე თქვენი ბავშვისთვის.') WHERE id = 'bf87ac9e-0c8c-4b92-971a-12c295af60cc';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვების განვითარებაში პირადი საზღვრების დაცვასთან დაკავშირებულ აღზრდას მნიშვნელოვანი ადგილი უჭირავს. საკუთარი სხეულისა და პირადი სივრცის გაცნობა ბავშვს ეხმარება, გაიაზროს როგორც საკუთარი, ისე სხვების საზღვრები. ეს ასევე ძალიან მნიშვნელოვანია იმისთვის, რომ ბავშვმა საკუთარი თავი ფიზიკურად და ემოციურად დაიცვას. ამ საკითხზე საუბრისას უმჯობესია, სიტყვების «სირცხვილია» და «ცოდვაა» ნაცვლად გამოიყენოთ ცნებები «პირადი» ან «ინტიმური». პირადი საზღვრების დაცვა ბავშვს შიშის შექმნის გარეშე, ბუნებრივად, ყოველდღიური ცხოვრების ნაწილად უნდა ასწავლოთ. ბავშვს უნდა გააცნოთ სხეულის ინტიმური ნაწილები და აუხსნათ, რომ საჭიროების შემთხვევაში მათ შეიძლება შეეხონ მხოლოდ ისეთმა ახლობელმა ადამიანებმა, როგორებიც არიან დედა, ბებია ან მომვლელი. ადრეული ასაკიდან თავის მოვლის უნარების (დაბანა, ჩაცმა) გამომუშავებით შეგიძლიათ გაუადვილოთ საკუთარი პირადი სივრცის დაცვა. მოერიდეთ ბავშვის ინტიმურ ნაწილებზე ხუმრობას და ასწავლეთ, რომ მისი საზღვრების დარღვევის შემთხვევაში უნდა გააპროტესტოს, გაიქცეს ან დახმარებას მოუხმოს.') WHERE id = '553d9c23-e7d4-493a-b17a-3b250bd976ed';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ პერიოდში ბავშვთან საუბრისას მნიშვნელოვანია, სრული და გამართული წინადადებები გამოიყენოთ. ამასთანავე, უნდა გაითვალისწინოთ, რომ ის «კითხვების ასაკშია» და მის ყველა შეკითხვას მოთმინებით უპასუხოთ. თქვენი მიმართვის ფორმა და კომუნიკაციის სტილი მისთვის მისაბაძი მაგალითია. თქვენს ბავშვს სასაცილო ამბები მოსწონს, ზოგჯერ კი უხეში სიტყვები ან ჟარგონული გამოთქმები აინტერესებს და მის ყურადღებას იქცევს. დიდია ალბათობა, რომ ეს სიტყვები მან სხვა ბავშვებისგან ისწავლოს. თუ არ გსურთ, რომ ბავშვმა ასეთი გამოთქმები გამოიყენოს, უპირველეს ყოვლისა, მის გვერდით საკუთარ მეტყველებას უნდა მიაქციოთ ყურადღება. თუ ეს სიტყვები სხვისგან ისწავლა, სიცილის ან უგულებელყოფის ნაცვლად მშვიდად აუხსენით, რომ მათი გამოყენება არასწორი და უხეშია. ის აუცილებლად გაგიგებთ.') WHERE id = 'c0ccda10-853b-4577-bb20-e9b11dd89481';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ შეამჩნიეთ, რომ თქვენს ბავშვს წინანდელთან შედარებით მადა შეუმცირდა, ამის მიზეზი შეიძლება იყოს გადატანილი ავადმყოფობა, ყოველდღიური რეჟიმის ცვლილება ან მშობლების მიდგომა. ბავშვისადმი გადაჭარბებული ყურადღება ან, პირიქით, უყურადღებობა, კვების საკითხში ზედმეტი სიმკაცრე, მისი დაშინება ან ჭამის სანაცვლოდ დაჯილდოება უმადობის მთავარი მიზეზებია. დიდი შეცდომაა ბავშვისთვის საკვების მანამ ძალით მიცემა, სანამ არ აღებინებს, მისთვის იმ საკვების დაძალება, რომელიც არ უყვარს, ან კვებისას ისეთი ფრაზებით დაშინება, როგორებიცაა: «თუ საჭმელს არ შეჭამ, მგელი შეგჭამს» და «უკან ძაღლი გამოგეკიდება». უმადობის მქონე ბავშვებს, როგორც წესი, შეუძლიათ ერთი ულუფა კარგად მიირთვან. მათ საჭირო საკვები შეიძლება დღის განმავლობაში სამ მცირე ულუფადაც მიიღონ. თუმცა ამ დროს ბავშვს არ უნდა მისცეთ საშუალება, ხშირად მიირთვას ისეთი შაქრიანი და მაღალკალორიული პროდუქტები, როგორებიცაა ორცხობილა, კრეკერი, კოლა და შოკოლადი. ამგვარად თავიდან აიცილებთ ჯანსაღი საკვებისადმი ინტერესის დაკარგვას, ცარიელი კალორიების მიღებას, ჭარბი წონის განვითარებასა და კბილების დაზიანებას. ბავშვთან ერთად საჭმლის მომზადება მას უფრო დიდი მადით ჭამაში დაეხმარება. ბავშვი, რომელიც ფსიქოლოგიურ ზეწოლას არ განიცდის და დაბალანსებულად იკვებება, შეიძლება პერიოდულად კვლავ წააწყდეს ამ პრობლემას, თუმცა თქვენი მხარდაჭერით მას ადვილად გაუმკლავდება.') WHERE id = 'b3ccd641-2a40-4051-bdae-4ea45fc3c82d';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'მიეცით თქვენს ბავშვს ქვიშით, წყლითა და მიწით თამაშის შესაძლებლობა. ბუნებასთან ურთიერთობა ბავშვის გონებრივი განვითარებისთვის შესანიშნავი თერაპიაა! მიეცით მას სხვა ბავშვებთან ურთიერთობის, სხვადასხვა გარემოში ყოფნისა და ახალი მეგობრების შეძენის შესაძლებლობა. ბავშვი, რომელიც მუდმივად მარტოა, თავს უბედურად გრძნობს. ნება მიეცით ბავშვს, საოჯახო საქმეებში დაგეხმაროთ. ისეთი მარტივი საქმეები, როგორებიცაა სარეცხის გაფენისას სარჭების მოწოდება ან სუფრაზე კოვზების დალაგება, მისთვის ძალიან მნიშვნელოვანია. როდესაც დავალებებს აძლევთ და ის მათ ასრულებს, თავს უფრო ბედნიერად გრძნობს. მიანდეთ ისეთი მარტივი მოვალეობები, რომელთა შესრულებაც შეუძლია, მაგალითად, კბილების გახეხვა. ამგვარად ბავშვს ყოველდღიურ ცხოვრებაში ჩართავთ, გართობის შესაძლებლობას მისცემთ და დაეხმარებით იმის გაცნობიერებაში, რომ ის დამოუკიდებელი პიროვნებაა.') WHERE id = 'd9cbf0fb-de40-4e79-8907-e51a5d91c55d';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ თქვენი 3 წლის ბავშვი ღამითაც და დღისითაც ჯერ კიდევ საფენს(პამპერსს) იყენებს, ნუ დაადანაშაულებთ და ნუ შეარცხვენთ. საფენის გადაჩვევის ასაკი ყველა ბავშვისთვის განსხვავებულია. ბავშვს თავად უნდა გაუჩნდეს ტუალეტით სარგებლობის სურვილი და ამ ჩვევას თანდათან შეეგუოს. პროცესის გასამარტივებლად შეგიძლიათ განსაზღვრული დრო დააწესოთ. მაგალითად, მიაჩვიეთ ტუალეტში წასვლას სახლიდან გასვლამდე ან შუადღის ძილის წინ. გარკვეული დროის შემდეგ ბავშვი ტუალეტით სარგებლობას თქვენი შეხსენების გარეშეც მიეჩვევა. გარდა ამისა, იზრუნეთ, რომ გარემო, სადაც ბავშვი ტუალეტით ისარგებლებს, მშვიდი იყოს. ამ პროცესში ბავშვმა ზეწოლა არ უნდა იგრძნოს და სრულიად მშვიდად უნდა იყოს.') WHERE id = '4cd58449-48a3-4ba7-8d3b-5c017a035884';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ ბავშვი საკმარისად და დაბალანსებულად იკვებება, ეს ნიშნავს, რომ ის სწავლისთვის მზად არის. ჯანმრთელ და ენერგიულ ბავშვებს სწავლის უნარი, გამძლეობა და თავდაჯერებულობაც უფრო მაღალი აქვთ. რეგულარულ ფიზიკურ აქტივობასთან ერთად სწორი კვება ბავშვებს ჯანმრთელობის შენარჩუნებაში ეხმარება. კვების დროის მუდმივად გამოტოვება ბავშვის წარმატებებზე უარყოფითად მოქმედებს. მიუხედავად იმისა, რომ საუზმე ერთ-ერთი ყველაზე ხშირად უგულებელყოფილი კვებაა, მისი გამოტოვება დღის 1-0 ჩამორჩენით დაწყებას ჰგავს. კარგი საუზმე აუმჯობესებს თქვენი ბავშვის სწავლის შედეგებს და ეხმარება ენერგიის შენარჩუნებაში. არასოდეს დაგავიწყდეთ, რომ ახალი ცოდნის მისაღებად ბავშვებს, უპირველეს ყოვლისა, ენერგია სჭირდებათ.') WHERE id = '852b4ba3-0212-4567-91c1-bd38e389f59b';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ თქვენმა ბავშვმა საკვებით თამაში დაიწყო, ეს იმის ნიშანია, რომ დანაყრდა. ასეთ შემთხვევაში შეგიძლიათ მაგიდიდან წამოაყენოთ ან თეფში აიღოთ. ნუ აიძულებთ, თეფშზე დადებული ყველაფერი შეჭამოს, რადგან მომავალში ამ საკვების მიმართ ზიზღი შეიძლება გაუჩნდეს. ჭამამდე მცირე ფიზიკური აქტივობა ან თამაში თქვენს ბავშვს მადას გაუღვიძებს და კვების პროცესს უფრო სახალისოს გახდის. მიეცით საშუალება, მონაწილეობა მიიღოს კერძების დაგეგმვასა და მომზადებაში. კვების პროცესი უფრო საინტერესო რომ გახდეს, კერძები მისი გემოვნების შესაბამისად, ფერადად გააფორმეთ. თუ ბავშვი კვებით სიამოვნებას მიიღებს, თეფშის ბოლომდე დაცარიელების გამო სტრესს არ განიცდის და მისთვის არასასურველი პროდუქტების ჭამას არ აიძულებენ, ის ბედნიერი და ჯანმრთელი გაიზრდება.') WHERE id = 'c795e196-6a00-43c9-b36a-4c06f33e9796';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ ასაკში პატარა ჭრილობაც კი ბავშვისთვის დიდ მოვლენად შეიძლება იქცეს, რადგან სხეულის მთლიანობის შეგრძნება მისთვის ძალიან მნიშვნელოვანია. ბავშვი, რომელიც სერიოზული შემთხვევის დროს მამაცად გამოიყურება, მცირე სისხლდენამ შეიძლება ძალიან შეაშინოს. ისეთი სიტყვები, როგორიცაა: „ამის გამო ტირი? ეს ხომ პატარა ჭრილობაა! ნუ აზვიადებ!“, თქვენს ბავშვს ვერ დაამშვიდებს — პირიქით, უფრო გააღიზიანებს და შეაშინებს. ასეთ სიტუაციაში უმჯობესია, სიმშვიდე შეინარჩუნოთ და შეხებით დაამშვიდოთ. შეგიძლიათ უთხრათ: „მოდი, წავიდეთ და შენთვის ყველაზე საინტერესო პლასტირი ავარჩიოთ“, — და მისი ყურადღება პრობლემის გადაჭრაზე გადაიტანოთ. თუ პლასტირის დაკვრაზე უარს იტყვის, შეგიძლიათ სიტუაცია თამაშად აქციოთ და უთხრათ: „გინდა, ჯერ ჩემს ხელზე დააკრა?“') WHERE id = '1875f0d9-a30a-4320-bde4-1bf3b044e4f4';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, '3 წლის ასაკში ბავშვების სოციალური აქტივობა იზრდება და ამ პერიოდში სხვადასხვა საქმიანობამ შეიძლება ძილის რეჟიმზე იმოქმედოს. ახალ სათამაშო ჯგუფში სიარულის დაწყებამ, აქტივობების სახეობებმა და სხვა ბავშვებთან ურთიერთობამ შეიძლება სტრესი და უძილობა იმ ბავშვშიც კი გამოიწვიოს, რომელსაც მანამდე ძილის პრობლემა არ ჰქონია. ტელევიზორთან და კომპიუტერულ თამაშებთან დიდი დროის გატარებაც ამ პრობლემას ამწვავებს. პრობლემის მიზეზის დასადგენად თქვენი, როგორც მშობლის, დაკვირვება ძალიან მნიშვნელოვანია. თუ თვალს მიადევნებთ, რას აკეთებს თქვენი ბავშვი დღის განმავლობაში და რომელ გადაცემებს უყურებს, შეძლებთ გაარკვიოთ, რა ახდენს მასზე გავლენას. მიზეზის პოვნის შემდეგ გამოსავლის მოძებნა გაცილებით ადვილი იქნება. თუ მუშაობთ, სასარგებლოა ამ საკითხში იმ ადამიანთან თანამშრომლობა, რომელიც თქვენს ბავშვს უვლის.') WHERE id = '2c94cf91-454d-4e52-814d-caf33e7a8c00';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვებს მოძრაობა სჭირდებათ. ზრდასრულებისგან განსხვავებით, ბავშვებისთვის აქტიურობა განვითარებისთვის ძალიან მნიშვნელოვანია. თქვენს 3 წლის ბავშვს უკვე შეუძლია ცურვის გაკვეთილებზე სიარულის დაწყება. ცურვა მას წყლის შიშის დაძლევასა და დამშვიდებაში დაეხმარება. სამთვლიანი ველოსიპედით სეირნობა, სიარული, სირბილი და ხტომა ამ ასაკის ბავშვებისთვის შესანიშნავი არჩევანია. ბურთის სროლა ან დარტყმა 2 წლიდან ბავშვებისთვის განსაკუთრებით საინტერესო აქტივობაა და, რადგან ამ დროს სხეული მუდმივად მოძრაობს, ბავშვი საკმარის ენერგიას ხარჯავს. რიტმული ტანვარჯიში კი ერთდროულად მთელი სხეულის მუშაობას უზრუნველყოფს და რიტმის შეგრძნებასა და მოქნილობას ავითარებს. ამ აქტივობების სირთულის დონე შეიძლება თანდათან გაიზარდოს ბავშვის ზრდისა და ახალი უნარების შეძენის შესაბამისად.') WHERE id = 'b10de036-169f-413e-a171-34dd349200ac';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვებში ერთ-ერთი ყველაზე გავრცელებული რეგრესული ქცევა ჩვილივით ლაპარაკია. შეეცადეთ გაიგოთ, რა მიზეზი უდევს საფუძვლად ამ ქცევას. თუ თქვენს ბავშვს სურს, რომ მას პატარა ჩვილივით მოექცეთ, დაუკმაყოფილეთ ეს საჭიროება. შესაძლოა, უფრო ხშირად ჩახუტება, ფიზიკური კონტაქტი და სიყვარულის გამოხატვა დასჭირდეს. ამ პერიოდში უნდა მოერიდოთ ბავშვისთვის ჭამის დაძალებას ან მკაცრი წესების დაწესებას. შესაძლოა, შეგაშფოთოთ მისმა თქვენზე კვლავ დამოკიდებულმა ქცევამ, თუმცა მასთან ბრძოლა მდგომარეობას კიდევ უფრო გააუარესებს. მაქსიმალური გაგებით მოეკიდეთ და შეეცადეთ იპოვოთ სტრესის გამომწვევი ფაქტორი, რომელმაც ეს ქცევა განაპირობა. ამ რთული პერიოდის გავლის შემდეგ სწორი ჩვევების აღსადგენად საკმარისი დრო გექნებათ, ამიტომ ნუ ინერვიულებთ.') WHERE id = 'f90d33ac-0447-4870-8d96-71bc500d58eb';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'არაჯანსაღი საკვების რეგულარულად მიღებამ შეიძლება გამოიწვიოს სიმსუქნე, ემოციური პრობლემები, თვითშეფასების დაქვეითება და მომავალში ქრონიკული დაავადებები. სწრაფი კვების პროდუქტის მხოლოდ ერთხელ მიღებამაც კი, მცირეწლოვანი ბავშვის კალორიების დღიურ მოთხოვნილებასთან შედარებით, შეიძლება დამატებით 160-310 კილოკალორია შემატოს. მდგომარეობას კიდევ უფრო ართულებს სწრაფი კვების ბევრ პროდუქტში სახიფათო საკვები საღებავებისა და მავნე ტრანსცხიმების არსებობა, ასევე საკვების მომზადების უსაფრთხოებასთან დაკავშირებული კითხვები. კვირაში სამჯერ მეტჯერ სწრაფი კვების პროდუქტების მიღება ბავშვებში ზრდის ისეთი ატოპიური დარღვევების განვითარების ალბათობას, როგორებიცაა ასთმა, ეგზემა ან რინიტი. მცირეწლოვან ბავშვებში ასთმის გამწვავების მაჩვენებელი 25%-საც კი აღემატება. ამ საკვებში კალორიების, ცხიმისა და შაქრის ჭარბი რაოდენობა ბავშვის გემოვნებით არჩევანს ცვლის. შედეგად, თქვენმა ბავშვმა შეიძლება უარი თქვას ბოჭკოვან საკვებზე, ხილზე, რძესა და ბოსტნეულზე. ეს კი შეკრულობის პრობლემის უფრო ხშირ განვითარებას ნიშნავს. ბავშვობაში დიდი რაოდენობით სწრაფი კვების პროდუქტების მიღების ჩვევა მომავალში ჯანსაღ კვებაზე გადასვლას ართულებს, მაშინაც კი, თუ ჯანმრთელობის პრობლემები უკვე გამოვლინდა. სწრაფი კვების პროდუქტების დამოკიდებულების გამომწვევი გემოს გამო ბავშვს მომავალში შეიძლება აღარ მოეწონოს ჩვეულებრივი, ნაკლებად შეზავებული ბუნებრივი საკვები.') WHERE id = '10b4e0f2-9940-49f3-b88c-796456c2e129';